        /// <summary>
        /// while calling this function:: Please add LanguageId as parameter. If you don't need to use the languageId just keep it empty:For example SelectedPlantWiseCompany(sPlantID,"", out DataSet dsRef)
        /// </summary>
        /// <param name="sPlantID"></param>
        /// <param name="localLanguageId"></param>
        /// <param name="dsRef"></param>
        public void SelectedPlantWiseCompany(string sPlantID, string localLanguageId, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = "";

            try
            {
                strSql = @"SELECT p.UserName PlantName,ISNULL(LocLangplant.Name,p.UserName) PlantNameLocal,c.UserName CompanyName,c.Id CompanyId,ISNULL(LocLang.Name,c.UserName) CompanyNameLocal,ISNULL(LocLang.UtilityName,'') CompanyAddressLocal, ISNULL(a.Address1,'')+','+ ISNULL(a.Address2,'') CompanyAddress, a.Phone,a.Email
                                ,cm.Address1 cAddress1 ,cm.Address2 cAddress2
                                FROM org.Plant p
							LEFT OUTER JOIN org.Company c on c.Id=p.CompanyId
							LEFT OUTER JOIN mst.AddressMaster a on a.Id=p.AddressMasterId
							LEFT OUTER JOIN mst.AddressMaster cm on cm.Id=c.AddressMasterId
                            Left outer join HKP.LocalLanguage LocLang ON LocLang.CompanyId =  c.Id and LocLang.LanguageId = '" + localLanguageId + @"'
                            Left outer join HKP.LocalLanguage LocLangplant ON LocLangplant.PlantId =  p.Id and LocLangplant.LanguageId = '" + localLanguageId + @"'
							WHERE p.Id='" + sPlantID + "'";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//end of function



