        public void GetActiveBiometricDeviceAsAccessControllerInfoGrd(string sPlantID, string strKey, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;

            try
            {
                //strSql = @"SELECT [CheckBoxSelectEmp] = Convert(bit, 'True') , * FROM
                //               (SELECT SystemID, MachineID, MachineIP, Description, 'Access Controller' DeviceType
                //                    FROM dbo.BiometricDeviceAsAccessController
                //                 WHERE (PlantID = '" + sPlantID + @"') AND IsActive = 1) A ";

                strSql = @"SELECT [CheckBoxSelectEmp] = Convert(bit, 'True') , * FROM
                               (SELECT Id, MachineID, MachineIP, Description, 'Access Controller' DeviceType
                                    FROM MST.AccessControllerList
                                 WHERE (PlantID = '" + sPlantID + @"') AND IsActive = 1) A ";
