        public void GetEmpWiseDeviceAccessInfoWithInDateTime(string sPlantID, string strEmpCode, string sFromDateTime, string sToDateTime, string sAttdnProcBase, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;

            //// AND AR.PDate BETWEEN '" + FromDate + @"' AND '" + ToDate + @"'
            //// AND CONVERT(VARCHAR(5), AR.PTime, 108) BETWEEN '" + FromTime + @"' AND '" + ToTime + @"'

            try
            {
                if (sAttdnProcBase.Trim() == "EnrollmentID")
                {
                    strSql = @"SELECT A.DeviceID, A.EmployeeCode, A.EmployeeName, REPLACE(CONVERT(VARCHAR(11), A.DOJ, 113), ' ', '-') DOJ,
                                    A.Designation, A.Unit, A.Division, A.Department, A.Section, A.SubSection,
                                    REPLACE(CONVERT(VARCHAR(11), A.PDate, 113), ' ', '-') PDate, A.PType,
                                    CONVERT(VARCHAR(5), A.PTime, 108) PTime, BAC.Description FROM
                                (SELECT AR.DevSystemID, AR.DeviceID, E.EmployeeCode, E.EmployeeName, E.DOJ,
                                    D.DesignationName Designation, U.UnitName Unit, Dv.DivisionName Division, Dp.DepartmentName Department,
                                    S.SectionName Section, SB.SubSectionName SubSection, AR.PDate, AR.PType, AR.PTime
                                FROM dbo.EmployeeInformation E
                                                INNER JOIN (
			                                                 SELECT DevSystemID, DeviceID, LogDownLoadNum, PDate, PType, PTime,
					                                                CONVERT(DATETIME, (CONVERT(VARCHAR(101), PDate, 101) + ' ' + CONVERT(VARCHAR(8), PTime, 108))) PDateTime
			                                                 FROM dbo.AttdnRawData
			                                                ) AR ON E.EmployeeCode = AR.LogDownLoadNum
 LEFT JOIN MST.ManpowerBudget mb ON mb.Id = e.BudgetCode
                            LEFT JOIN ORG.Position PR ON MB.PositionId=PR.Id
                            LEFT JOIN ORG.Entity EN ON MB.EntityId=EN.Id
                                                LEFT JOIN dbo.Unit U ON EN.UnitID = U.SystemID
                                                LEFT JOIN dbo.Division Dv ON PR.DivisionID = Dv.SystemID
                                                LEFT JOIN dbo.Department Dp ON PR.DepartmentID = Dp.SystemID
                                                LEFT JOIN dbo.Section S ON PR.SectionID = S.SystemID
                                                LEFT JOIN dbo.SubSection SB ON PR.SubSectionID = SB.SystemID
                                                LEFT JOIN dbo.Designation D ON PR.DesignationID = D.SystemID
                                WHERE E.PlantID = '" + sPlantID + @"' AND E.SystemID IN ('" + strEmpCode + @"') AND
	                                   AR.PDateTime BETWEEN '" + sFromDateTime + @"' AND '" + sToDateTime + @"'
                                    ) A
                                LEFT JOIN dbo.BiometricDeviceAsAccessController BAC ON A.DevSystemID = BAC.SystemID
                                GROUP BY A.DeviceID, A.EmployeeCode, A.EmployeeName, A.DOJ, A.Designation, A.Unit, A.Division, A.Department,
                                    Section, SubSection, PDate, PType, PTime, BAC.Description
                                ORDER BY A.EmployeeCode, A.PDate, A.PTime, A.PType, A.DeviceID";
                }
                else
                {
                   
                    strSql = @"SELECT A.DeviceID, A.EmployeeCode, A.EmployeeName, REPLACE(CONVERT(VARCHAR(11), A.DOJ, 113), ' ', '-') DOJ,
                                    A.Designation, A.Unit, A.Division, A.Department, A.Section, A.SubSection,
                                    REPLACE(CONVERT(VARCHAR(11), A.PDate, 113), ' ', '-') PDate, A.PType,
                                    CONVERT(VARCHAR(5), A.PTime, 108) PTime, BAC.Description FROM
                                (SELECT AR.DevSystemID, AR.DeviceID, E.EmployeeCode, E.EmployeeName, E.DOJ, D.UserName Designation, U.UserName Unit,
                                    Dv.UserName Division, Dp.UserName Department, S.UserName Section,
                                    SB.UserName SubSection, AR.PDate, AR.PType, AR.PTime
                                FROM dbo.EmployeeInformation E
                                                INNER JOIN (
			                                                 SELECT DevSystemID, DeviceID, LogDownLoadNum, PDate, PType, PTime,
					                                                CONVERT(DATETIME, (CONVERT(VARCHAR(101), PDate, 101) + ' ' + CONVERT(VARCHAR(8), PTime, 108))) PDateTime
			                                                 FROM dbo.AttdnRawData
			                                                ) AR ON E.SystemId = AR.LogDownLoadNum
 LEFT JOIN MST.ManpowerBudget mb ON mb.Id = e.BudgetCode
                            LEFT JOIN ORG.Position PR ON MB.PositionId=PR.Id
                            LEFT JOIN ORG.Entity EN ON MB.EntityId=EN.Id
                                                LEFT JOIN ORG.Unit U ON EN.UnitID = U.Id
                                                LEFT JOIN ORG.Division Dv ON PR.DivisionID = Dv.Id
                                                LEFT JOIN ORG.Department Dp ON PR.DepartmentID = Dp.Id
                                                LEFT JOIN ORG.Section S ON PR.SectionID = S.Id
                                                LEFT JOIN ORG.SubSection SB ON PR.DepartmentID = SB.Id
                                                LEFT JOIN HKP.Designation D ON PR.DesignationID = D.Id
                                WHERE E.PlantID = '" + sPlantID + @"' AND E.SystemID IN (" + strEmpCode + @") AND
	                                  AR.PDateTime BETWEEN '" + sFromDateTime + @"' AND '" + sToDateTime + @"'
                                    ) A
                                LEFT JOIN MST.AccessControllerList BAC ON A.DevSystemID = BAC.Id
                                GROUP BY A.DeviceID, A.EmployeeCode, A.EmployeeName, A.DOJ, A.Designation, A.Unit, A.Division, A.Department,
                                    Section, SubSection, PDate, PType, PTime, BAC.Description
                                ORDER BY A.EmployeeCode, A.PDate, A.PTime, A.PType, A.DeviceID";
                }

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function

        public void GetVstWiseDeviceAccessInfoWithInDateTime(string sPlantID, string strVstCode, string FromDate, string ToDate, string FromTime, string ToTime, string CompAttdnProcBase, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;

            try
            {
                if (CompAttdnProcBase.Trim() == "EnrollmentID")
                {
                    strSql = @"SELECT A.*, BAC.Description FROM
                                (SELECT AR.DevSystemID, AR.DeviceID, V.VisitorID, V.VisitorName, VC.Category,
		                                V.VisitorStatue, REPLACE(CONVERT(VARCHAR(11), AR.PDate, 113), ' ', '-') PDate, AR.PType,
                                        CONVERT(VARCHAR(5), AR.PTime, 108) PTime
                                FROM dbo.VisitorEntry V
                                            INNER JOIN dbo.AttdnRawData AR ON V.VisitorID = AR.LogDownLoadNum
                                            LEFT JOIN dbo.VisitorCategory VC ON V.VisCatSystemID = VC.SystemID
                                WHERE V.PlantID = '" + sPlantID + @"' AND V.SystemID IN (" + strVstCode + @")
                                        AND AR.PDate BETWEEN '" + FromDate + @"' AND '" + ToDate + @"'
                                        AND CONVERT(VARCHAR(5), AR.PTime, 108) BETWEEN '" + FromTime + @"' AND '" + ToTime + @"') A
                                LEFT JOIN dbo.BiometricDeviceAsAccessController BAC ON A.DevSystemID = BAC.SystemID
                                GROUP BY A.DeviceID, A.VisitorID, A.VisitorName, A.Category, A.VisitorStatue, PDate, PType, PTime, BAC.Description
                                ORDER BY A.VisitorID, A.PDate, A.PTime, A.PType, A.DeviceID";
                }
                else
                {
                    strSql = @"SELECT A.*, BAC.Description FROM
                                (SELECT AR.DevSystemID, AR.DeviceID, V.VisitorID, V.VisitorName, VC.Category,
		                                V.VisitorStatue, REPLACE(CONVERT(VARCHAR(11), AR.PDate, 113), ' ', '-') PDate, AR.PType,
                                        CONVERT(VARCHAR(5), AR.PTime, 108) PTime
                                FROM dbo.VisitorEntry V
                                            INNER JOIN dbo.AttdnRawData AR ON V.CardNumber = AR.LogDownLoadNum
                                            LEFT JOIN dbo.VisitorCategory VC ON V.VisCatSystemID = VC.SystemID
                                      WHERE V.PlantID = '" + sPlantID + @"' AND V.SystemID IN (" + strVstCode + @")
                                            AND AR.PDate BETWEEN '" + FromDate + @"' AND '" + ToDate + @"'
                                            AND CONVERT(VARCHAR(5), AR.PTime, 108) BETWEEN '" + FromTime + @"' AND '" + ToTime + @"') A
                                                    LEFT JOIN dbo.BiometricDeviceAsAccessController BAC ON A.DevSystemID = BAC.SystemID
                                GROUP BY A.DeviceID, A.VisitorID, A.VisitorName, A.Category, A.VisitorStatue, PDate, PType, PTime, BAC.Description
                                ORDER BY A.VisitorID, A.PDate, A.PTime, A.PType, A.DeviceID";
                }

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function

        public void GetEmpJobCardInfoWithInDateTime(string strEmpCode, string FromDate, string ToDate, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;

            try
            {
                strSql = @"SELECT A.EmployeeCode
                            	,A.EmployeeName
                            	,A.DOJ
                            	,A.GivenDesignation
                                ,A.LegalDesignation
                            	,A.Unit
                            	,A.Division
                            	,A.Department
                            	,A.Section
                            	,A.SubSection
                            	,REPLACE(CONVERT(VARCHAR(11), A.PDate, 113), ' ', '-') PDate
                            	,A.DayStatus
                            	,A.InTime
                                ,CONVERT(VARCHAR(5), A.ShiftInTime, 108) ShiftInTime
                            	,A.InDeviceID
                            	,A.OutTime
                            	,A.OutDeviceID
                            	,A.IsManual
                            	,A.OTHr
                            	,A.LvShortName
                            	,A.Code
                            	,A.LvDescrip
                            	,A.LeaveType
                                ,dti,dto
                                ,InTimeShow
                                ,OutTimeShow
                                ,ShiftTime = CASE
                                    WHEN ShiftChangeInTime IS NULL
                                        THEN ShiftInTime
                                    ELSE ShiftChangeInTime
                                    END
                                ,ShiftName
                               ,CONVERT(VARCHAR(5), A.ShiftOutTime, 108) ShiftOutTime
                                ,A.IsManualDayStatus,A.IsManualInTime,A.IsManualOutTime, A.ShortLeave
                            FROM(
                                SELECT E.EmployeeCode
                                    , E.EmployeeName
                                    , REPLACE(CONVERT(VARCHAR(11), E.DOJ, 113), ' ', '-') DOJ
                                    , REPLACE(CONVERT(VARCHAR(11), E.DOS, 113), ' ', '-') DOS
                                    , D.UserName GivenDesignation
                                    , U.UserName Unit
                                    , Dv.UserName Division
                                    , Dp.UserName Department
                                    , S.UserName Section
                                    , SB.UserName SubSection
                                    , AR.WorkDate PDate
                                    , AR.DayStatus
                                    , CONVERT(VARCHAR(5), AR.InTime, 108) InTime
                                    , CONVERT(varchar(15), CAST(AR.InTime AS TIME), 100) InTimeShow
                                    --, ShiftInTime =case  when cs.InTime is null then sd.InTime else cs.InTime end
                                    , CONVERT(VARCHAR(5), SD.InTime, 108) ShiftInTime
                                    , ARIN.DeviceID InDeviceID
                                    , CONVERT(VARCHAR(5), AR.OutTime, 108) OutTime
                                    , CONVERT(varchar(15), CAST(AR.OutTime AS TIME), 100) OutTimeShow
                                    , AROUT.DeviceID OutDeviceID
                                    , AR.IsManualInTime IsManual
                                    , AR.OTHr
                                    , LT.UserName LvShortName
                                    , LT.Description LvDescrip
                                    , LT.LeaveType
                                    , LT.Code
                                    , Isnull(LG.UserName, '') LegalDesignation
                                    , AR.InTime dti, AR.OutTime dto
                                    , CONVERT(VARCHAR(5), SFCG.InTime, 108) ShiftChangeInTime
                                    , SD.ShiftDefinationName ShiftName
                                    , CONVERT(VARCHAR(5), SD.OutTime, 108) ShiftOutTime
                                    , AR.IsManualDayStatus, AR.IsManualInTime, AR.IsManualOutTime, ar.CountedShortLeave ShortLeave

                                FROM dbo.EmployeeInformation E
                                INNER JOIN dbo.AttdnProcessData AR ON E.SystemID = AR.EmpSystemID
                                LEFT JOIN(SELECT * FROM dbo.ShiftTimeChgMaster WHERE '" + FromDate + @"' BETWEEN FromDate AND ToDate) AS SFCG
                                                                                ON AR.ShiftSystemID = SFCG.ShiftDefinationID
 LEFT JOIN MST.ManpowerBudget mb ON mb.Id = e.BudgetCode
                            LEFT JOIN ORG.Position PR ON MB.PositionId=PR.Id
                            LEFT JOIN ORG.Entity EN ON MB.EntityId=EN.Id
                                LEFT JOIN dbo.AttdnRawData ARIN ON AR.InTimeRowID = ARIN.RowID
                                LEFT JOIN dbo.AttdnRawData AROUT ON AR.OutTimeRowID = AROUT.RowID
                                LEFT JOIN dbo.LeaveType LT ON AR.LTSystemID = LT.Id
                                LEFT JOIN ORG.Unit U ON EN.UnitID = U.Id
                                LEFT JOIN ORG.Division Dv ON PR.DivisionID = Dv.Id
                                LEFT JOIN ORG.Department Dp ON PR.DepartmentID = Dp.Id
                                LEFT JOIN ORG.Section S ON PR.SectionID = S.Id
                                LEFT JOIN ORG.SubSection SB ON PR.SubSectionID = SB.Id
                                LEFT JOIN HKP.LegalDesignation LG ON E.LegalDesignationId = LG.Id
                                left join EmpDateWiseShiftAssign es on es.EmpSystemID = E.SystemId
                                AND AR.WorkDate = ES.WorkDate
                                left join(
                                SELECT  m.ShiftDefinationID, c.ShiftDate, m.InTime, m.SystemID  FROM[ShiftTimeChgMaster] m
                                left join[ShiftTimeChgChild] c on m.SystemID = c.STCMasterSystemID
                                         ) CS on cs.ShiftDefinationID = es.ShiftSystemID and cs.ShiftDate = ar.WorkDate
                                left join[ShiftDefination] sd on sd.SystemID = es.ShiftSystemID
                                LEFT JOIN HKP.Designation D ON E.GivenDesignationId = D.Id
                                WHERE E.SystemID IN(" + strEmpCode + @")

                                    AND AR.WorkDate BETWEEN '" + FromDate + @"'

                                        AND '" + ToDate + @"' AND (EmployeeStatus = 'Active' OR COnvert(date,DOS) >= Convert(Date,'" + FromDate + @"'))
                                ) A
                            GROUP BY A.EmployeeCode
                            	,A.EmployeeName
                            	,A.DOJ
                                ,A.DOS
                            	,A.GivenDesignation
                                ,A.LegalDesignation
                            	,A.Unit
                            	,A.Division
                            	,A.Department
                            	,A.Section
                            	,A.SubSection
                            	,PDate
                            	,A.DayStatus
                            	,A.InTime
                                ,A.ShiftInTime
                            	,A.InDeviceID
                            	,A.OutTime
                            	,A.OutDeviceID
                            	,A.IsManual
                            	,A.OTHr
                            	,A.LvShortName
                            	,A.LvDescrip
                            	,A.LeaveType
                                ,A.Code
                                ,dti,dto
                                ,InTimeShow
                                ,OutTimeShow
                                ,ShiftChangeInTime
                                ,ShiftName
                                ,A.ShiftOutTime,A.IsManualDayStatus,A.IsManualInTime,A.IsManualOutTime, a.ShortLeave
                            ORDER BY EmployeeCodePreFix,EmployeeCodeNumeric
                            	,A.PDate";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function

             

        public void GetEEmpJobCardInfoWithInDateTimes(string EmpIdLoop, string FromDate, string ToDate, string plantId, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;

            try
            {
                strSql = @"   SELECT A.EmployeeCode
                            	,A.EmployeeName
                                ,A.EmployeeStatus
                            	,A.DOJ
                            	,A.GivenDesignation
                                ,A.LegalDesignation
                            	,A.Unit
                            	,A.Division
                            	,A.Department
                            	,A.Section
                            	,A.SubSection
                            	,REPLACE(CONVERT(VARCHAR(11), A.PDate, 113), ' ', '-') PDate
                                ,PDay
                            	,A.DayStatus
                                ,A.IsHalfDayLeave
                            	,A.InTime
                                ,ShiftInTimeShow
								 ,ShiftInTime
                            	,A.InDeviceID
                            	,A.OutTime
                            	,A.OutDeviceID
                            	,A.IsManual
                            	,A.OTHr OverStay
                                ,A.TotalOTHr FinalOT
                            	,A.LvShortName
                            	,A.Code
                            	,A.LvDescrip
                            	,A.LeaveType
                                ,dti,dto
                                ,InTimeShow
                                ,OutTimeShow
                                ,A.OTConsiderOn
                                ,ShiftTime = CASE WHEN ShiftChangeInTime IS NULL THEN ShiftInTime ELSE ShiftChangeInTime END
                                ,ShiftName
								,ShiftType
							    ,ShiftOutTime
                                ,A.IsManualDayStatus,A.IsManualInTime,A.IsManualOutTime, A.ShortLeave,A.IsOTEntitled,A.IsOTComfirm,A.WorkDate,
                                ReConfirm = CASE  WHEN A.IsOTComfirm=0 AND A.WorkDate IS NOT NULL  THEN 1   ELSE 0  END,A.DayCategory
                                ,A.InTimelate,A.OutTimelate
                                ,A.ShiftInTimeLate
                                ,A.GradeCode
	                            ,A.LeaveDuration                               
								,A.DurationInMin

	                                ,A.EO 
									,A.LIN
									,A.LO
                                    ,A.Line,A.ExtraOT
                            FROM(
                                SELECT E.EmployeeCode
                                    , E.EmployeeName
                                    ,E.EmployeeStatus
                                    , REPLACE(CONVERT(VARCHAR(11), E.DOJ, 113), ' ', '-') DOJ
                                    , REPLACE(CONVERT(VARCHAR(11), E.DOS, 113), ' ', '-') DOS
                                    , D.UserName GivenDesignation
                                    , U.UserName Unit
                                    , Dv.UserName Division
                                    , Dp.UserName Department
                                    , S.UserName Section
                                    ,ar.IsHalfDayLeave
                                    , SB.UserName SubSection
                                    ,datename(dw,AR.WorkDate) as PDay
                                    , AR.WorkDate PDate
                                    , AR.DayStatus
                                    , LSalGr.Code GradeCode
                                    , HR.OTConsiderOn
                                    ---, AR.InTime InTime
                                    ,  InTime=case when dt.OriginalDayType='W' and ar.IsOTEntitled=0 and  ma.InTime IS NOT NUll then ma.InTime 
									               when dt.OriginalDayType='H' and ar.IsOTEntitled=0  and ma.InTime IS NOT NUll  then ma.InTime 
												   when dt.OriginalDayType='W' and ar.IsOTEntitled=1  and  EOT.FromDate IS NOT NUll  then EOT.FromDate 
												   when dt.OriginalDayType='H' and ar.IsOTEntitled=1  and  EOT.FromDate IS NOT NUll  then EOT.FromDate                                                    
									else   ISNULL(ar.InTime,ar.PunchInTime) end

                                    , AR.InTime InTimeShow
                                   	,l.UserName as Line
                            ,ShiftInTimeLate=CASE
							 WHEN cs.InTime IS NULL
							 THEN CONVERT(varchar(15),CAST(SD.InTime AS TIME),108)
							 ELSE CONVERT(VARCHAR(15), CAST(cs.InTime AS TIME), 108)
						     END
                                    , CONVERT(VARCHAR(5), AR.InTime, 108) InTimelate
                             ,ShiftInTimeShow = CASE
							 WHEN cs.InTime IS NULL
							 THEN CONVERT(varchar(15),CAST(SD.InTime AS TIME),100)
							 ELSE CONVERT(VARCHAR(15), CAST(cs.InTime AS TIME), 100)
						     END
                                    , ARIN.DeviceID InDeviceID
                                    ---, AR.OutTime OutTime
                                    , OutTime=case when dt.OriginalDayType='W' and ar.IsOTEntitled=0 and ma.OutTime IS NOT NUll  then ma.OutTime 
									               when dt.OriginalDayType='H' and ar.IsOTEntitled=0 and ma.OutTime IS NOT NUll then ma.OutTime 
												   when dt.OriginalDayType='W' and ar.IsOTEntitled=1 and EOT.ToDate IS NOT NUll  then EOT.ToDate 
												   when dt.OriginalDayType='H' and ar.IsOTEntitled=1 and EOT.ToDate IS NOT NUll  then EOT.ToDate 
                                                   when dt.OriginalDayType='NW' and ar.IsOTEntitled=1 and EOT.ToDate IS NOT NUll then EOT.ToDate 
									else  ISNULL(ar.OutTime,ar.PunchOutTime) end



                                    , AR.OutTime OutTimeShow
                                    , CONVERT(VARCHAR(5), AR.OutTime, 108) OutTimelate
                                    , AROUT.DeviceID OutDeviceID
                                    , AR.IsManualInTime IsManual
                                    ---, AR.OTHr 
                                    , ISNULL( AR.OTHr,0) +ISNULL( EOT.Duration,0) OTHr
                                    ,OT.TotalOTHr
                                    , LT.UserName LvShortName
                                    , LT.Description LvDescrip
                                    , LT.LeaveType
                                    , LT.Code
                                    , Isnull(LG.UserName, '') LegalDesignation
                                    , AR.InTime dti, AR.OutTime dto
                                    , CONVERT(VARCHAR(5), cs.InTime, 108) ShiftChangeInTime
                                    , SD.ShiftDefinationName ShiftName
									,sd.ShiftType
                                    ,LEAVE.LeaveDuration	                            
									,HODD.DurationInMin

		                            ,EO.OffDuration AS EO
									,EIN.OffDuration AS LIN
									,LO= Case when LO.InfoType='LUNCHOUT' THEN 'YES' ELSE 'NO' END,ISNULL( EOT.Duration,0)ExtraOT

						   ,ShiftOutTime = CASE                                   
                           WHEN cs.OutTime IS NULL
                           THEN CONVERT(varchar(15),CAST(SD.OutTime AS TIME),100)
                           ELSE CONVERT(VARCHAR(15), CASt(cs.OutTime AS TIME), 100)
                           END
                                     ,ShiftInTime = Format(AR.InTime, 'yyyy-MM-dd') + ' ' + CASE 
			                         WHEN cs.InTime IS NULL
			                         	THEN CONVERT(VARCHAR(15), CAST(SD.InTime AS TIME), 100)
			                         ELSE CONVERT(VARCHAR(15), CASt(cs.InTime AS TIME), 100)
			                         END
                                    , AR.IsManualDayStatus, AR.IsManualInTime, AR.IsManualOutTime, ar.CountedShortLeave ShortLeave,AR.IsOTEntitled,AR.IsOTComfirm,OT.WorkDate,dt.Category DayCategory
                                FROM dbo.EmployeeInformation E

                                    LEFT OUTER JOIN MST.ManpowerBudget mpb on mpb.Id=e.BudgetCode
									LEFT OUTER JOIN ORG.Position PO ON mpb.PositionId=PO.Id
                                    LEFT OUTER JOIN ORG.Entity EN ON mpb.EntityId=EN.Id

                                INNER JOIN dbo.AttdnProcessData AR ON E.SystemID = AR.EmpSystemID
	                           LEFT JOIN (select LET.SystemID,LTD.LeaveDuration,LTD.WorkDate,LET.EmpSystemID from  LeaveTransaction LET 
										    left join LeaveTransactionDetails LTD ON LTD.LvTrnsSystemID=LET.SystemID	
                                        where ltd.WorkDate Between '" + FromDate + @"' and '" + ToDate + @"'
								         ) LEAVE ON LEAVE.EmpSystemID=E.SystemId and LEAVE.WorkDate= AR.WorkDate

                                left join (select EmpSystemID,WorkDate,SUM(DurationInMin)AS DurationInMin
		                    From  [dbo].[HourlyOffDuty] 
	                        WHERE  ApproveType='Deducation' AND WorkDate Between '" + FromDate + @"' and '" + ToDate + @"'
		                    Group BY  EmpSystemID,WorkDate)as HODD on HODD.EmpSystemID=E.SystemId and HODD.WorkDate=AR.WorkDate

                                LEFT JOIN(SELECT * FROM dbo.ShiftTimeChgMaster WHERE '" + FromDate + @"' BETWEEN FromDate AND ToDate) AS SFCG
                                ON AR.ShiftSystemID = SFCG.ShiftDefinationID
                                LEFT JOIN dbo.AttdnRawData ARIN ON AR.InTimeRowID = ARIN.RowID
                                LEFT JOIN dbo.AttdnRawData AROUT ON AR.OutTimeRowID = AROUT.RowID
                                LEFT JOIN dbo.LeaveType LT ON AR.LTSystemID = LT.Id
                                LEFT JOIN ORG.Unit U ON EN.UnitID = U.Id
                                LEFT JOIN ORG.Division Dv ON PO.DivisionID = Dv.Id
                                LEFT JOIN ORG.Department Dp ON PO.DepartmentID = Dp.Id

                                  LEFT JOIN ORG.Section S ON PO.SectionID = S.Id
                                LEFT JOIN ORG.SubSection SB ON PO.SubSectionID = SB.Id
								left join org.Line l on l.Id=mpb.LineId

                                LEFT JOIN HKP.LegalDesignation LG ON E.LegalDesignationId = LG.Id
                                LEFT JOIN MST.LegalSalaryGradeDesignation LSGD ON LSGD.LegalDesignationId = LG.Id and LSGD.PlantId='" + plantId + @"'
                                LEFT JOIN SCS.LegalSalaryGrade LSalGr ON LSalGr.Id = LSGD.LegalSalaryGradeId
                                left join EmpDateWiseShiftAssign es on es.EmpSystemID = E.SystemId
                                AND AR.WorkDate = ES.WorkDate
                                left join(
                                SELECT  m.ShiftDefinationID, c.ShiftDate, m.InTime, m.SystemID,m.OutTime  FROM[ShiftTimeChgMaster] m
                                left join[ShiftTimeChgChild] c on m.SystemID = c.STCMasterSystemID
                                         ) CS on cs.ShiftDefinationID = es.ShiftSystemID and cs.ShiftDate = ar.WorkDate
                                left join[ShiftDefination] sd on sd.SystemID = es.ShiftSystemID
                                LEFT JOIN HKP.Designation D ON E.GivenDesignationId = D.Id
                                LEFT JOIN FinalOT OT ON E.SystemId = OT.EmpSystemID and ot.WorkDate=ar.WorkDate
                                LEFT JOIN PlantWiseHRMSSetting hr on HR.PlantID=E.PlantId
                                LEFT JOIN DayType dt on dt.Daytype=AR.DayStatus

                                left join AttendanceInfoExtra LO on LO.EmpSystemId=e.SystemId and LO.WorkDate=ar.WorkDate and LO.InfoType='LUNCHOUT'
								left join AttendanceInfoExtra EO on EO.EmpSystemId=e.SystemId and EO.WorkDate=ar.WorkDate and EO.InfoType='EARLUOUT'
								left join AttendanceInfoExtra EIN on EIN.EmpSystemId=e.SystemId and EIN.WorkDate=ar.WorkDate and EIN.InfoType='EARLUIN'


								left join (
								SELECT EmpSystemId,FromDate,ToDate,Duration,WorkDate FROM HourlyOT where  OTType='EXTRAOT' 
								
								) EOT on EOT.EmpSystemId=AR.EmpSystemID and EOT.WorkDate=ar.WorkDate

								left join AttdnManualData MA on MA.EmpSystemID=ar.EmpSystemID and MA.WorkDate=ar.WorkDate



                                WHERE E.SystemID in (" + EmpIdLoop + @")
                                    AND AR.WorkDate BETWEEN '" + FromDate + @"'
                                        AND '" + ToDate + @"' AND (EmployeeStatus = 'Active' OR COnvert(date,DOS) >= Convert(Date,'" + FromDate + @"'))
                                ) A
                            GROUP BY A.EmployeeCode
                            	,A.EmployeeName
                            	,A.DOJ
                                ,A.DOS
                            	,A.GivenDesignation
                                ,A.LegalDesignation
                            	,A.Unit
                            	,A.Division
                            	,A.Department
                            	,A.Section
                            	,A.SubSection
                            	,PDate
                                ,PDay	
                            	,A.DayStatus
                                ,a.IsHalfDayLeave
                            	,A.InTime
                                ,A.ShiftInTime
                                ,A.ShiftInTimeShow
                            	,A.InDeviceID
                            	,A.OutTime
                            	,A.OutDeviceID
                            	,A.IsManual
                            	,A.OTHr
                                ,A.TotalOTHr
                            	,A.LvShortName
                            	,A.LvDescrip
                            	,A.LeaveType
                                ,A.Code
                                ,dti,dto
                                ,InTimeShow
                                ,OutTimeShow
                                ,A.OTConsiderOn
                                ,ShiftChangeInTime
                                ,ShiftName
								,ShiftType
                                ,A.ShiftInTimeLate
                                ,A.GradeCode
                                ,A.EmployeeStatus
                                ,A.ShiftOutTime
                                ,A.IsManualDayStatus
                                ,A.IsManualInTime
                                ,A.IsManualOutTime
                                , a.ShortLeave
                                ,A.IsOTEntitled
                                ,A.IsOTComfirm
                                ,A.WorkDate
                                ,A.DayCategory
                                ,A.InTimelate
                                ,A.OutTimelate
	                            ,A.LeaveDuration                       
								,A.DurationInMin
                                ,A.EO 
								,A.LIN
								,A.LO
,A.Line,A.ExtraOT
                            ORDER BY A.EmployeeCode
                            	,A.PDate ";


                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function
        public void GetEmpJobCardInfoWithInDateTimes(string EmpIdLoop, string FromDate, string ToDate, string plantId, out DataSet dsRef)
        {

            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;
            try
            {
                strSql = @"SELECT A.EmployeeCode,A.EmployeeCodeNumeric
                            	,A.EmployeeName,A.OutTime punchTime--,A.firstSlab
                                ,A.EmployeeStatus
                            	,A.DOJ
                            	,A.GivenDesignation
                                ,A.LegalDesignation
                            	,A.Unit
                            	,A.Division
                            	,A.Department
                            	,A.Section
                            	,A.SubSection
                            	,REPLACE(CONVERT(VARCHAR(11), A.PDate, 113), ' ', '-') PDate
                                ,PDay
                            	,DayStatus
                                
                                ,A.IsHalfDayLeave
                            	,A.InTime
                                ,ShiftInTimeShow
								 ,ShiftInTime
                            	,A.InDeviceID
                            	,A.OutTime
                            	,A.OutDeviceID
                            	,A.IsManual
                            	,OverStay
                                ,A.TotalOTHr FinalOT
                            	,A.LvShortName
                            	,A.Code
                            	,A.LvDescrip
                            	,A.LeaveType
                                ,dti,dto
                                ,InTimeShow
                                ,OutTimeShow
                                ,A.OTConsiderOn
                                ,ShiftTime = CASE WHEN ShiftChangeInTime IS NULL THEN ShiftInTime ELSE ShiftChangeInTime END
                                ,ShiftInTimeC = CASE WHEN ShiftChangeInTime IS NULL THEN ShiftInTimecc ELSE ShiftChangeInTime END
                                ,ShiftName
								,ShiftType
							    ,ShiftOutTime
                                ,A.IsManualDayStatus,A.IsManualInTime,A.IsManualOutTime, A.ShortLeave,A.IsOTEntitled,A.IsOTComfirm,A.pdate  WorkDate,
                                ReConfirm = CASE  WHEN A.IsOTComfirm=0 AND A.WorkDate IS NOT NULL  THEN 1   ELSE 0  END,A.DayCategory
                                ,A.InTimelate,A.OutTimelate
                                ,A.ShiftInTimeLate
                                ,A.GradeCode
	                            ,A.LeaveDuration                               
								,A.DurationInMin

	                                ,A.EO 
									,A.LIN
									,A.LO
                                    ,A.Line
                            FROM(
                                SELECT E.EmployeeCode,e.EmployeeCodeNumeric--,g.firstSlab
                                    , E.EmployeeName
                                    ,E.EmployeeStatus
                                    , REPLACE(CONVERT(VARCHAR(11), E.DOJ, 113), ' ', '-') DOJ
                                    , REPLACE(CONVERT(VARCHAR(11), E.DOS, 113), ' ', '-') DOS
                                    , D.UserName GivenDesignation
                                    , U.UserName Unit
                                    , Dv.UserName Division
                                    , Dp.UserName Department
                                    , S.UserName Section
                                    ,ar.IsHalfDayLeave
                                    , SB.UserName SubSection
                                    ,datename(dw,AR.WorkDate) as PDay
                                    , AR.WorkDate PDate
                                    --, AR.DayStatus
                                    , LSalGr.Code GradeCode
                                    , HR.OTConsiderOn
                                    , AR.InTime InTime
                                    --, AR.InTime InTimeShow
                                   	,l.UserName as Line
                                    ,OverStay = case when hr.NoPunchOnHoliday = 1 and dt.OriginalDayType = 'H' then 0.00
									when hr.NoPunchOnWeekoff = 1 and dt.OriginalDayType = 'W' then 0.00 else AR.OTHr end
                                    ,DayStatus = case when hr.NoPunchOnHoliday = 1 and dt.OriginalDayType = 'H' then 'H' 
									when hr.NoPunchOnWeekoff = 1 and dt.OriginalDayType = 'W' then 'W'
									else AR.DayStatus end
									,InTimeShow = case when hr.NoPunchOnHoliday = 1 and dt.OriginalDayType = 'H' then null
									 when hr.NoPunchOnWeekoff = 1 and dt.OriginalDayType = 'W' then null else AR.InTime end
									,OutTimeShow = case when hr.NoPunchOnHoliday = 1 and dt.OriginalDayType = 'H' then Null
								 when hr.NoPunchOnWeekoff = 1 and dt.OriginalDayType = 'W' then Null	else AR.OutTime end
                            ,ShiftInTimeLate=CASE
							 WHEN cs.InTime IS NULL
							 THEN CONVERT(varchar(15),CAST(SD.InTime AS TIME),108)
							 ELSE CONVERT(VARCHAR(15), CAST(cs.InTime AS TIME), 108)
						     END
                                    , CONVERT(VARCHAR(5), AR.InTime, 108) InTimelate
                             ,ShiftInTimeShow = CASE
							 WHEN cs.InTime IS NULL
							 THEN CONVERT(varchar(15),CAST(SD.InTime AS TIME),100)
							 ELSE CONVERT(VARCHAR(15), CAST(cs.InTime AS TIME), 100)
						     END
                                    , ARIN.DeviceID InDeviceID
                                    , AR.OutTime OutTime
                                    --, AR.OutTime OutTimeShow
                                    , CONVERT(VARCHAR(5), AR.OutTime, 108) OutTimelate
                                    , AROUT.DeviceID OutDeviceID
                                    , AR.IsManualInTime IsManual
                                    --, AR.OTHr 
                                    ,OT.TotalOTHr
                                    , LT.UserName LvShortName
                                    , LT.Description LvDescrip
                                    , LT.LeaveType
                                    , LT.Code
                                    , Isnull(LG.UserName, '') LegalDesignation
                                    , AR.InTime dti, AR.OutTime dto
                                    , CONVERT(VARCHAR(5), cs.InTime, 108) ShiftChangeInTime
                                    , SD.ShiftDefinationName ShiftName
									,sd.ShiftType
                                    ,LEAVE.LeaveDuration	                            
									,HODD.DurationInMin

		                            ,EO.OffDuration AS EO
									,EIN.OffDuration AS LIN
									,LO= Case when LO.InfoType='LUNCHOUT' THEN 'YES' ELSE 'NO' END

						   ,ShiftOutTime = CASE                                   
                           WHEN cs.OutTime IS NULL
                           THEN CONVERT(varchar(15),CAST(SD.OutTime AS TIME),100)
                           ELSE CONVERT(VARCHAR(15), CASt(cs.OutTime AS TIME), 100)
                           END
                                     ,ShiftInTime = Format(AR.InTime, 'yyyy-MM-dd') + ' ' + CASE 
			                         WHEN cs.InTime IS NULL
			                         	THEN CONVERT(VARCHAR(15), CAST(SD.InTime AS TIME), 100)
			                         ELSE CONVERT(VARCHAR(15), CASt(cs.InTime AS TIME), 100)
			                         END

                                    ,ShiftInTimecc = Format(AR.WorkDate, 'yyyy-MM-dd') + ' ' + CASE 
			                         WHEN cs.InTime IS NULL
			                         	THEN CONVERT(VARCHAR(15), CAST(SD.InTime AS TIME), 100)
			                         ELSE CONVERT(VARCHAR(15), CASt(cs.InTime AS TIME), 100)
			                         END

                                    , AR.IsManualDayStatus, AR.IsManualInTime, AR.IsManualOutTime, ar.CountedShortLeave ShortLeave,AR.IsOTEntitled,AR.IsOTComfirm,OT.WorkDate,dt.Category DayCategory
                                FROM dbo.EmployeeInformation E

                                    LEFT OUTER JOIN MST.ManpowerBudget mpb on mpb.Id=e.BudgetCode
									LEFT OUTER JOIN ORG.Position PO ON mpb.PositionId=PO.Id
                                    LEFT OUTER JOIN ORG.Entity EN ON mpb.EntityId=EN.Id

                                INNER JOIN dbo.AttdnProcessData AR ON E.SystemID = AR.EmpSystemID
	                           LEFT JOIN (select LET.SystemID,LTD.LeaveDuration,LTD.WorkDate,LET.EmpSystemID from  LeaveTransaction LET 
										    left join LeaveTransactionDetails LTD ON LTD.LvTrnsSystemID=LET.SystemID	
                                        where ltd.WorkDate Between '" + FromDate + @"' and '" + ToDate + @"'
								         ) LEAVE ON LEAVE.EmpSystemID=E.SystemId and LEAVE.WorkDate= AR.WorkDate

                                left join (select EmpSystemID,WorkDate,SUM(DurationInMin)AS DurationInMin
		                    From  [dbo].[HourlyOffDuty] 
	                        WHERE  ApproveType='Deducation' AND WorkDate Between '" + FromDate + @"' and '" + ToDate + @"'
		                    Group BY  EmpSystemID,WorkDate)as HODD on HODD.EmpSystemID=E.SystemId and HODD.WorkDate=AR.WorkDate

                                LEFT JOIN(SELECT * FROM dbo.ShiftTimeChgMaster WHERE '" + FromDate + @"' BETWEEN FromDate AND ToDate) AS SFCG
                                ON AR.ShiftSystemID = SFCG.ShiftDefinationID
                                LEFT JOIN dbo.AttdnRawData ARIN ON AR.InTimeRowID = ARIN.RowID
                                LEFT JOIN dbo.AttdnRawData AROUT ON AR.OutTimeRowID = AROUT.RowID
                                LEFT JOIN dbo.LeaveType LT ON AR.LTSystemID = LT.Id
                                LEFT JOIN ORG.Unit U ON EN.UnitID = U.Id
                                LEFT JOIN ORG.Division Dv ON PO.DivisionID = Dv.Id
                                LEFT JOIN ORG.Department Dp ON PO.DepartmentID = Dp.Id

                                  LEFT JOIN ORG.Section S ON PO.SectionID = S.Id
                                LEFT JOIN ORG.SubSection SB ON PO.SubSectionID = SB.Id
								left join org.Line l on l.Id=mpb.LineId

                                LEFT JOIN HKP.LegalDesignation LG ON E.LegalDesignationId = LG.Id
                                LEFT JOIN MST.LegalSalaryGradeDesignation LSGD ON LSGD.LegalDesignationId = LG.Id and LSGD.PlantId='" + plantId + @"' and LSGD.LegalSalaryGradeId is not null
                                LEFT JOIN SCS.LegalSalaryGrade LSalGr ON LSalGr.Id = LSGD.LegalSalaryGradeId
                                left join EmpDateWiseShiftAssign es on es.EmpSystemID = E.SystemId
                                AND AR.WorkDate = ES.WorkDate
                                left join(
                                SELECT  m.ShiftDefinationID, c.ShiftDate, m.InTime, m.SystemID,m.OutTime  FROM[ShiftTimeChgMaster] m
                                left join[ShiftTimeChgChild] c on m.SystemID = c.STCMasterSystemID
                                         ) CS on cs.ShiftDefinationID = es.ShiftSystemID and cs.ShiftDate = ar.WorkDate
                                left join[ShiftDefination] sd on sd.SystemID = es.ShiftSystemID
                                LEFT JOIN HKP.Designation D ON E.GivenDesignationId = D.Id
                                LEFT JOIN FinalOT OT ON E.SystemId = OT.EmpSystemID and ot.WorkDate=ar.WorkDate
                                LEFT JOIN PlantWiseHRMSSetting hr on HR.PlantID=E.PlantId
                                LEFT JOIN DayType dt on dt.Daytype=AR.DayStatus
                            
							--inner join OTSlabDefineGeneral g on 
							--'" + ToDate + @"' between g.FromDate and g.ToDate 
							--and g.PlantID=ar.PlantID 
							--and g.DayType=dt.OriginalDayType

                                left join AttendanceInfoExtra LO on LO.EmpSystemId=e.SystemId and LO.WorkDate=ar.WorkDate and LO.InfoType='LUNCHOUT'
								left join AttendanceInfoExtra EO on EO.EmpSystemId=e.SystemId and EO.WorkDate=ar.WorkDate and EO.InfoType='EARLYOUT'
								left join AttendanceInfoExtra EIN on EIN.EmpSystemId=e.SystemId and EIN.WorkDate=ar.WorkDate and EIN.InfoType='EARLYIN'

                                WHERE E.SystemID in (" + EmpIdLoop + @")
                                    AND AR.WorkDate BETWEEN '" + FromDate + @"'
                                        AND '" + ToDate + @"' AND (EmployeeStatus = 'Active' OR COnvert(date,DOS) >= Convert(Date,'" + FromDate + @"'))
                                ) A
                            
                            ORDER BY A.EmployeeCode
                            	,A.PDate
                                ";


                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.BeginTransaction();
                objCon.getDataSet(strSql, out dsRef);
                objCon.CommitTransaction();
                //objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function

        public void GetMaintenanceSchedulePlannedConsumableDetails(string PlannedId,string plantId, out DataSet dsRef)
        {

            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;
            try
            {
                strSql = @"select distinct 'Consumable' type, E.UserName Entity,MS.UserName ScheduleName,APD.Id as PlannedId,MS.ScheduleCode,
MM.UserName MachineName,MA.AssetName,MM.MachineMake Make,MM.MachineModel Model,MS.ScheduleDays,Case when isnull((SELECT TOP 1 format(MPD.ActualDate,'dd-MMM-yyyy') from [TRN].[MachineAssetPlannedDetails] MPD where MPD.Id=APD.Id
ORDER BY MPD.Id DESC),'')='' then DATEDIFF(day, GETDATE(), GETDATE()) else DATEDIFF(day, GETDATE(), (MS.ScheduleDays+GETDATE())) end DueDays,
Format(APD.PlannedDate,'dd-MMM-yyyy') as PlannedDate,Format(APD.FromDate,'dd-MMM-yyyy') as FromDate,Format(APD.ActualDate,'dd-MMM-yyyy') as ActualDate,MS.StandardScheduleMinutes as StandardTime,MS.MaxScheduleMinutes as Maximumtime,
format(APD.FromTime,'hh:mm tt') as FromTime,format(APD.ToTime,'hh:mm tt') as ToTime,APD.Minute as [Minute],MA.AssetCode,WC.UserName WorkCenter,
Reverse(stuff(Reverse((Select EmployeeName + ',' from EmployeeInformation where 
SystemId in (select ResponsiblePersonId from [TRN].[ResponsiblePlannedDetails] where PlannedId=APD.Id and IsActive=1) for xml PATH(''))),1,1,'')) as ResponsiblePerson,
'' as [Item Name],'' as ItemSNO,'' CriticalLevel,'' ItemRemarks,
'' as CheckPoints, 
MSC.SNO as StoresSNO,MSC.ItemName as StoreItemName,
(select UserName from SCS.UnitOfMeasurement where Active=1 and Id=MSC.UOMId) as UOM,
(select StandardName from MST.MaterialMasterArticle where Id=MSC.ArticleId) as Article,
MSC.EstimatedQty,
MSC.Category,MSC.CostType,MSC.EstimationLevel,MSC.Remarks as StoresRemarks,
isnull((SELECT TOP 1 format(ActualDate,'dd-MMM-yyyy') from [TRN].[MachineAssetPlannedDetails] where Id=APD.Id
 ORDER BY Id DESC),'') as LastMaintenanceDate,
Case when isnull((SELECT TOP 1 format(MPD.ActualDate,'dd-MMM-yyyy') from [TRN].[MachineAssetPlannedDetails] MPD where MPD.Id=APD.Id
ORDER BY MPD.Id DESC),'')='' then Format(GETDATE(),'dd-MMM-yyyy') else format(MS.ScheduleDays+APD.ActualDate,'dd-MMM-yyyy') end CurrentMaintanceDate,
MA.AssetReference,Y.Closing as StockQty
from TRN.Maintenancescheduling MS
--left Join MST.MachineMaster MM ON MM.id=MS.MachineMasterId
left join TRN.MaintenanceMachineAsset MMA ON MMA.MaintenanceSchedulingId=MS.Id and MMA.IsActive=1
left join MachineMasterAsset MA ON MA.Id=MMA.AssetId
left join MST.MachineMaster MM  ON MM.Id=MA.MachineMasterId
left join ORG.Entity E ON E.Id=MMA.EntityId
left Join [TRN].[MachineAssetPlannedDetails] APD ON APD.AssetId=MMA.Id
left join SCS.WorkCenterMaster WC ON WC.Id=MMA.WorkCenterMasterId
left join TRN.MaintenanceStoresConsumable MSC ON MSC.MaintenanceSchedulingId=MS.Id 
left join (SELECT X.Closing,X.ArticleId FROM (
                        SELECT Distinct 
                               ROW_NUMBER() Over(Order by  IM.Id) As[S.N]             
                              , isnull(MT.UserName,'') MaterialType
                              , isnull(MGM.UserName,'') AS MaterialGroup                        
                             ,isnull(MM.UserName,'') MaterialMasterName    
                             ,MM.Id    MaterialMasterId    
                            ,HSNC.Code HSNCode
                            ,isnull( ART.StandardName,'') ArticleName    
                             ,ART.Id ArticleId        
                            , ISNULL(FCV.UserName,'') AS FirstCharacteristicsValue
                            , ISNULL(SCV.UserName,'') AS SecondCharacteristicsValue
                            , ISNULL(TCV.UserName,'') AS ThirdCharacteristicsValue --,MS.UserName MaterialStorageLocation    
                            ,TUoM.UserName UOM,  opbal.IsAsset
                            ,(((((((isnull(opbal.TransactionQty,0) + isnull(opbal2.TransactionQty,0))-isnull(IFD1.IssueQty,0)-isnull(PurchaseReturnData.Qty,0))-isnull(AdjustmentData.Qty,0))+isnull(IssueReturnData.Qty,0))-isnull(InventorySalesData.Qty,0))-isnull(InventoryScrapData.Qty,0))-isnull(InventoryTransferData.Qty,0)) Closing 



                        from TRN.InventoryMaterial AS IM
                        left JOIN MST.MaterialMaster AS MM ON IM.MaterialMasterId=MM.Id
                        LEFT JOIN [HKP].[HSNCode] AS HSNC ON HSNC.ID=MM.HSNCodeId
                        LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId=MGM.Id
                        LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId=ART.Id
                        LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId=FC.Id
                        LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId=SC.Id
                        LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId=TC.Id
                        LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId=FCV.Id
                        LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId=SCV.Id
                        LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId=TCV.Id
                        left join( 
                                    SELECT IRD.InventoryMaterialId--, IRD.MaterialStorageId
                                    ,IRD.IsAsset,Sum(IRD.BaseQty) AS TransactionQty, Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
                                    FROM [TRN].[InventoryReceiveDetail] IRD
                                    LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
                                    where convert(Date,IR.GRNDate) <= Format(GETDATE(),'dd-MMM-yyyy') AND IR.OpeningBalanceId IS NOT NULL  
                                    group By IRD.InventoryMaterialId--,IRD.MaterialStorageId
                            ,IRD.IsAsset
                                    
                                    ) AS opbal ON opbal.InventoryMaterialId=IM.Id AND IM.PlantId='" + plantId + @"'
                                    -- left join[HKP].[MaterialStorage] MS on ms.id = opbal.MaterialStorageId 
                                    LEFT JOIN[HKP].[MaterialType] AS MT On MGM.MaterialTypeId = MT.Id 
                                    left JOIN[SCS].[UnitOfMeasurement] AS TUoM ON MM.BaseUOMId = TUoM.Id 
                                    left join(SELECT IRD.InventoryMaterialId, Sum(IRD.BaseQty) AS TransactionQty , Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
FROM[TRN].[InventoryReceiveDetail] IRD
LEFT JOIN[TRN].[InventoryReceive] IR ON IR.Id= IRD.InventoryReceiveId
where convert(Date, IR.GRNDate) > Format(GETDATE(), 'dd-MMM-yyyy') group By IRD.InventoryMaterialId--) AS opbal1 ON opbal1.InventoryMaterialId = IM.Id AND IM.PlantId = '"+plantId+@"'
UNION ALL
SELECT IRD.InventoryMaterialId, Sum(IRD.BaseQty) AS TransactionQty, Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
FROM[TRN].[InventoryReceiveDetail] IRD
LEFT JOIN[TRN].[InventoryReceive] IR ON IR.Id = IRD.InventoryReceiveId
where convert(Date, IR.GRNDate) = Format(GETDATE(), 'dd-MMM-yyyy') group By IRD.InventoryMaterialId) AS opbal1 ON opbal1.InventoryMaterialId = IM.Id AND IM.PlantId = '"+plantId+ @"'
left join(SELECT IRD.InventoryMaterialId, Sum(IRD.BaseQty) AS TransactionQty , Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
FROM[TRN].[InventoryReceiveDetail] IRD
LEFT JOIN[TRN].[InventoryReceive] IR ON IR.Id= IRD.InventoryReceiveId
where convert(Date, IR.GRNDate) <= Format(GETDATE(), 'dd-MMM-yyyy') AND IR.OpeningBalanceId IS NULL
  --AND(ISNULL(IR.AuthorizedByStatus, '') != 'Reject') AND ISNULL(IR.CheckedByStatus,'')!= 'Reject'
GROUP BY IRD.InventoryMaterialId
                                    ) AS opbal2 ON opbal2.InventoryMaterialId = IM.Id AND IM.PlantId = '" + plantId+ @"'
left join(select IID.InventoryMaterialId, Sum(IH.Qty) IssueQty, Sum(IID.PolicyAmount) PolicyAmount
FROM TRN.InventoryIssueDetail IID
LEFT JOIN TRN.InventoryIssue II ON IID.InventoryIssueId= II.Id
LEFT JOIN TRN.InventoryIssueHistory IH On IH.InventoryIssueDetailId= IID.Id
WHERE convert(Date, II.IssueDate) <= Format(GETDATE(), 'dd-MMM-yyyy') AND II.PlantId = '" + plantId+ @"' GROUP BY IID.InventoryMaterialId
                                    ) IFD On IFD.InventoryMaterialId = IM.Id
 left join(select IID.InventoryMaterialId, Sum(IH.Qty) IssueQty, Sum(IH.TotalAmount) PolicyAmount
FROM TRN.InventoryIssueDetail IID
LEFT JOIN TRN.InventoryIssue II ON IID.InventoryIssueId= II.Id
LEFT JOIN TRN.InventoryIssueHistory IH On IH.InventoryIssueDetailId= IID.Id
WHERE convert(Date, II.IssueDate) <= Format(GETDATE(), 'dd-MMM-yyyy') AND II.PlantId = '" + plantId+ @"' GROUP BY IID.InventoryMaterialId
                                ) IFD1 On IFD1.InventoryMaterialId = IM.Id
--Issue Return
Left join(select IH.InventoryMaterialId, sum(IH.Qty) Qty, sum(IRD.MaterialTranRate) MaterialTranRate, (sum(IH.Qty)* sum(IRD.MaterialTranRate)) IssueReturnAmount from trn.InventoryIssueReturnHistory IH
Left join trn.InventoryIssueReturn II ON II.Id = IH.InventoryIssueReturnId
Left join trn.InventoryReceiveDetail IRD ON IRD.Id = IH.InventoryReceiveDetailId
WHERE convert(Date, II.IssueDate) <= Format(GETDATE(), 'dd-MMM-yyyy') AND II.PlantId = '" + plantId+ @"' GROUP BY IH.InventoryMaterialId
                                 )IssueReturnData ON IssueReturnData.InventoryMaterialId = IM.Id
--Purchase return
Left join(select IH.InventoryMaterialId, sum(IH.TransactionQty) Qty, sum(IRD.MaterialTranRate) MaterialTranRate, (sum(IH.TransactionQty * IRD.MaterialTranRate)) PurchaseReturnAmount
from trn.PurchaseReturnDetail IH
Left join trn.PurchaseReturn II ON II.Id = IH.PurchaseReturnId
Left join trn.InventoryReceiveDetail IRD ON IRD.Id = IH.InventoryReceiveDetailId
WHERE convert(Date, II.[POReturnDate]) <= Format(GETDATE(), 'dd-MMM-yyyy') AND II.PlantId = '" + plantId+ @"' GROUP BY IH.InventoryMaterialId
)PurchaseReturnData ON PurchaseReturnData.InventoryMaterialId = IM.Id

-- Adjustment
Left join(select psad.InventoryMaterialId, sum(IH.Qty) Qty, sum(IH.Rate) Rate, (sum(IH.Qty) * sum(IH.Rate)) AdjustmentAmount
from trn.PhysicalStockAdjustmentHistory IH
Left JOIN TRN.PhysicalStockAdjustmentDetail psad on psad.Id = IH.PhysicalStockAdjustmentDetailId
Left join trn.PhysicalStockAdjustmentMaster II ON II.Id = psad.PhysicalStockAdjustmentMasterID
--Left join trn.InventoryReceiveDetail IRD ON IRD.Id = IH.InventoryReceiveDetailId
WHERE convert(Date, II.IssueDate) <= Format(GETDATE(), 'dd-MMM-yyyy') AND II.PlantId = '" + plantId+ @"' GROUP BY psad.InventoryMaterialId
)AdjustmentData ON AdjustmentData.InventoryMaterialId = IM.Id
-- where opbal.IsAsset = 0 AND IM.PlantId = '" + plantId+ @"' AND MM.UserName is not null

-- InventorySales
    Left join(select ISD.InventoryMaterialId, sum(ISH.Qty) Qty, sum(ISH.BaseRate) Rate, (sum(ISH.Qty * ISH.BaseRate)) InventorySalesAmount
    from[TRN].[InventorySalesHistory] ISH
    Left JOIN[TRN].[InventorySalesDetail] ISD on ISD.Id = ISH.InventorySalesDetailId
    Left join[TRN].[InventorySales] Ins on Ins.Id = ISD.InventorySalesId
    --Left join trn.InventoryReceiveDetail IRD ON IRD.Id = IH.InventoryReceiveDetailId
   WHERE convert(Date, Ins.SalesDate) <= Format(GETDATE(), 'dd-MMM-yyyy') AND Ins.PlantId = '" + plantId+ @"' GROUP BY ISD.InventoryMaterialId
    )InventorySalesData ON InventorySalesData.InventoryMaterialId = IM.Id
    -- where IM.PlantId = '" + plantId+ @"' AND MM.UserName is not null--AND MM.UserName like '%Bed Sheet%'

   --InventoryScrap
     Left join(select ISCD.InventoryMaterialId, sum(ISCH.Qty) Qty, sum(ISCH.Rate) Rate, (sum(ISCH.Qty * ISCH.Rate)) InventoryScrapAmount
 from[TRN].[InventoryScrapHistory] ISCH
  Left JOIN[TRN].[InventoryScrapDetail] ISCD on ISCD.Id = ISCH.InventoryScrapDetailId
Left join[TRN].[InventoryScrap] ISC on ISC.Id = ISCD.InventoryScrapId
     --Left join trn.InventoryReceiveDetail IRD ON IRD.Id = IH.InventoryReceiveDetailId
  WHERE convert(Date, ISC.ScrapDate) <= Format(GETDATE(), 'dd-MMM-yyyy') AND ISC.PlantId = '"+plantId+@"' GROUP BY ISCD.InventoryMaterialId
     )InventoryScrapData ON InventoryScrapData.InventoryMaterialId = IM.Id
     --InventoryTransfer
     Left join(select IRD.InventoryMaterialId, sum(IRD.InventoryTransferQty) Qty, sum(IRD.MaterialTranRate) Rate, (sum(IRD.InventoryTransferQty) * sum(IRD.MaterialTranRate)) InventoryTransferAmount
 from[TRN].[InventoryTransferHistory] ITH
  Left JOIN[TRN].[InventoryReceiveDetail] IRD on IRD.Id = ITH.InventoryReceiveDetailId
  Left join[TRN].[InventoryReceive] IR on IR.Id = IRD.InventoryReceiveId
 WHERE convert(Date, IR.GRNDate) <= Format(GETDATE(), 'dd-MMM-yyyy') AND IR.PlantId = '" + plantId+ @"'
 GROUP BY IRD.InventoryMaterialId
     )InventoryTransferData ON InventoryTransferData.InventoryMaterialId = IM.Id
where IM.PlantId = '" + plantId+ @"' AND MM.UserName is not null ) X )  Y ON Y.ArticleId = MSC.ArticleId
where APD.Id='" + PlannedId + @"' order by MSC.SNO";


                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.BeginTransaction();
                objCon.getDataSet(strSql, out dsRef);
                objCon.CommitTransaction();
                //objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function

        public void GetSkillManagemenetPlannedDetails(string PlannedId, string plantId, out DataSet dsRef)
        {

            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;
            try
            {
                strSql = @"select  E.UserName Entity,SM.UserName ScheduleName,APD.Id as PlannedId,SM.ScheduleCode,SM.ScheduleDays,EI.SystemId as EmployeeId,EI.EmployeeName,
P.Code as PositionCode,DIV.UserName Division,DEP.UserName EmpDepartment,S.UserName Section,SS.UserName SubSection,EB.Code as BudgetCode,P.Activity,DEG.UserName Designation,P.UserName as Process,
Case when isnull((SELECT TOP 1 format(MPD.ActualDate,'dd-MMM-yyyy') from TRN.EmployeePlannedDetails MPD where MPD.Id=APD.Id
ORDER BY MPD.Id DESC),'')='' then DATEDIFF(day, GETDATE(), GETDATE()) else DATEDIFF(day, GETDATE(), (SM.ScheduleDays+GETDATE())) end DueDays,
Format(APD.PlannedDate,'dd-MMM-yyyy') as PlannedDate,Format(APD.FromDate,'dd-MMM-yyyy') as FromDate,Format(APD.ActualDate,'dd-MMM-yyyy') as ActualDate,SM.StandardScheduleMinutes as StandardTime,SM.MaxScheduleMinutes as Maximumtime,
format(APD.FromTime,'hh:mm tt') as FromTime,format(APD.ToTime,'hh:mm tt') as ToTime,APD.Minute as [Minute],
Reverse(stuff(Reverse((Select EmployeeName + ',' from EmployeeInformation where 
SystemId in (select ResponsiblePersonId from [TRN].[SkillResponsiblePlannedDetails] where PlannedId=APD.Id and IsActive=1) for xml PATH(''))),1,1,'')) as ResponsiblePerson,
isnull((SELECT TOP 1 format(ActualDate,'dd-MMM-yyyy') from TRN.EmployeePlannedDetails where Id=APD.Id
 ORDER BY Id DESC),'') as LastMaintenanceDate,
Case when isnull((SELECT TOP 1 format(MPD.ActualDate,'dd-MMM-yyyy') from TRN.EmployeePlannedDetails MPD where MPD.Id=APD.Id
ORDER BY MPD.Id DESC),'')='' then Format(GETDATE(),'dd-MMM-yyyy') else Format((SM.ScheduleDays+GETDATE()),'dd-MMM-yyyy') end CurrentMaintanceDate,
APD.Grade,APD.GradeRemark
from TRN.SkillManagement SM
left join HKP.Process PRO ON PRO.Id=SM.ProcessId
left join TRN.SkillManagementPositionCode SPC ON SPC.SMID=SM.Id
 left join EmployeeInformation EI ON EI.EmployeeStatus='Active' and EI.PositionID=SPC.PositionCodeId 
 left join TRN.SkillManagementEntity SPE ON SPE.SMID=SM.Id
 left Join TRN.EmployeePlannedDetails APD ON APD.PositionCodeId=SPC.Id and APD.Id=(select top 1 Id from TRN.EmployeePlannedDetails MAPD where MAPD.PositionCodeId=SPC.Id and MAPD.EmployeeId=EI.SystemId and MAPD.EntityId=SPE.Id order by MAPD.ActualDate desc)
 left join MST.ManpowerBudget EB ON EB.Id=EI.BudgetCode
LEFT JOIN ORG.Position PR ON MB.PositionId=PR.Id
 left Join Org.Entity E ON E.Id=SPE.EntityId
 left Join ORG.Position P ON P.Id=pr.PositionID
 left join org.Division DIV ON DIV.Id=pr.DivisionId
 left join Org.Department DEP ON DEP.Id=pr.DepartmentId
 left join Org.Section S ON S.Id=pr.SectionId
 left join Org.SubSection SS ON SS.Id=pr.SubSectionId
 left join HKP.Designation DEG ON DEG.Id=EI.GivenDesignationId
where APD.Id='" + PlannedId + @"'";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.BeginTransaction();
                objCon.getDataSet(strSql, out dsRef);
                objCon.CommitTransaction();
                //objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }

