        #region Late Attendance Posting Report
        public void GetLateAttendancePostingData(string plantId, string EffectiveDate, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;

            try
            {
                string fd = "01-" + Convert.ToDateTime(EffectiveDate).ToString("MMM") + "-" + Convert.ToDateTime(EffectiveDate).ToString("yyyy");
                string endDate = Convert.ToDateTime(fd).AddMonths(1).AddDays(-1).ToString("dd-MMM-yyyy");

                strSql = @" 
                            SELECT 
                            format(apd.WorkDate,'dd-MMM-yyy')WorkDate,FORMAT(apd.InTime,'hh:mm tt')InTime ,Format(apd.OutTime,'hh:mm tt')OutTime, DATEDIFF(DAY, apd.WorkDate, amd.DateAdded) AS datedifference,ei.EmployeeName,
                            apd.DayStatus, EI.EmployeeCode,EI.EmployeeName,FORMAT(EI.DOJ, 'dd-MMM-yyyy') DOJ,DSG.UserName Designation,se.UserName Section,FORMAT(amd.DateAdded,'dd-MMM-yyy') DateAdded
                            ,Sus.UserName SubSection,L.UserName Line,DP.UserName Department,ei.EmployeeCurrentStatus
                            , apd.IsManualDayStatus, apd.IsManualInTime, apd.IsManualOutTime,amd.AddedBy
                            from AttdnProcessData apd
                            left join EmployeeInformation ei on ei.SystemId=apd.EmpSystemID
                            LEFT JOIN MST.ManpowerBudget PMB ON EI.BudgetCode = PMB.Id
                            LEFT JOIN ORG.Position PR ON PMB.PositionId = PR.Id
                            LEFT JOIN ORG.Entity E ON PMB.EntityId = E.Id    
                            LEFT JOIN HKP.Designation DSG ON PR.DesignationId = DSG.Id     
                            LEFT JOIN HKP.Designation DeG ON DeG.Id = EI.GivenDesignationId
                            LEFT JOIN ORG.Department DP ON DP.Id = PR.DepartmentId
                            LEFT JOIN HKP.LegalDesignation LGD ON LGD.Id = EI.LegalDesignationId
                            LEFT JOIN ORG.Section AS Se ON Se.Id = PR.SectionID
                            LEFT JOIN ORG.SubSection AS SuS ON SuS.Id = PR.SubSectionID
                            LEFT JOIN ORG.Line AS L ON L.Id= PMB.LineId
                            left join [dbo].[DayType] dt on dt.DayType=apd.DayStatus
                            left join [dbo].[AttdnManualData] amd on amd.EmpSystemID=apd.EmpSystemID and amd.WorkDate=apd.WorkDate
                            where
                              (apd.IsManualInTime=1
                            or apd.IsManualDayStatus=1 )
                            and 
                            DATEDIFF(DAY, apd.WorkDate, amd.DateAdded) > 3
                            and apd.WorkDate Between '" + fd + @"' and '" + endDate + @"'
                            and apd.DayStatus in (select daytype from daytype where category='Present' OR  category='Late')
                            order by apd.WorkDate,apd.DateAdded, EI.EmployeeCode";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function

        public void GetLateAttendancePostingForOtEntitleData(string plantId, string EffectiveDate, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;

            try
            {
