        public void GetShiftNotAssign(string FromDate, string ToDate, string plantId, string companyId, string companyGroupId, out DataSet dsRef)
        {
            ConnectionManager.clsConnectionManager con = new clsConnectionManager(120);
            string strSql = string.Empty;
            string fd = "01-" + Convert.ToDateTime(ToDate).ToString("MMM") + "-" + Convert.ToDateTime(ToDate).ToString("yyyy");
            string endDate = Convert.ToDateTime(fd).AddMonths(1).AddDays(-1).ToString("dd-MMM-yyyy");
            try
            {
                strSql = @"select x.* ,LG.UserName Designation,dep.UserName Department,sec.UserName Section,ssec.UserName SubSection
                                    ,ec.UserName EmpCategory,E.UserName Entity
                                    from org.Position p
                                    left join mst.ManpowerBudget mpb on mpb.PositionId = p.Id
                                    left join org.Entity e on e.Id = mpb.EntityId
                                    left join org.Section sec on sec.id = p.SectionId
                                    left join org.SubSection ssec on ssec.Id = p.SubSectionId
                                    left join org.Department dep on dep.Id = p.DepartmentId
                                    left join 
                                    
                                    (	select  e.EmployeeCode,e.EmployeeName,e.PlantId
									,FORMAT( EffectiveDate,'dd-MMM-yyyy')EffectiveDate
									,FORMAT(e.DOJ,'dd-MMM-yyyy')DOJ
									,FORMAT(c.CutOffDate,'dd-MMM-yyyy')CutOffDate
									,e.BudgetCode,e.LegalDesignationId
									,flag= case when isnull(es.EmpSystemID,'')='' then 'Shift Not Assign'
									when e.DOJ<es.EffectiveDate and c.CutOffDate<es.EffectiveDate then 'Wrong Effective Date'
									else ''									end
									from EmployeeInformation e
									left join SCS.OpeningBalanceCutOffDate c on c.PlantId=e.PlantId and c.ModuleName='HR'
									left join (select MIN(EffectiveDate)EffectiveDate,EmpSystemID from EmployeeShiftAssign where IsSingleDayShift=0
									group by EmpSystemID
									) es on es.EmpSystemID = e.SystemId
									
									) x on x.BudgetCode = mpb.Id
									
									left join mst.DesignationMasterLegalDesignation m on m.LegalDesignationId=x.LegalDesignationId
									left join mst.DesignationMaster dm on dm.id=m.DesignationMasterId
									left join hkp.EmployeeCategory ec on ec.Id = dm.EmployeeCategoryId
									left join hkp.LegalDesignation LG on LG.Id = x.LegalDesignationId
									LEFT JOIN org.Line L ON L.Id = MPB.LineId
									
									where x.flag != '' and isnull(EmployeeCode,'') != ''
									and x.EffectiveDate >= '" + FromDate + @"' and x.PlantId = '" + plantId + "'";

                con.getDataSet(strSql, out dsRef);

            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                con = null;
            }
        }//End Function

        public void GetShortDurationAbsentReports(string FromDate, string ToDate, string plantId, string companyId, string companyGroupId, out DataSet dsRef)
        {
            ConnectionManager.clsConnectionManager con = new clsConnectionManager(120);
            string strSql = string.Empty;

            try
            {
                strSql = @"SELECT FORMAT(AP.WorkDate, 'dd-MMM-yyyy') WorkDate
                        	,EI.SystemId 
                           ";
                strSql += columnName();
                strSql += @"

                            ,AP.DayStatus
                            ,AP.IsManualDayStatus, AP.IsManualInTime, AP.IsManualOutTime
                        	,FORMAT(EI.DOJ, 'dd-MMM-yyyy') DOJ
                        	,SD.ShiftDefinationName ShiftName
                        	,sd.ShiftType
                        	,ShiftOutTime = CASE 
                        		WHEN cs.OutTime IS NULL
                        			THEN CONVERT(VARCHAR(15), CAST(SD.OutTime AS TIME), 100)
                        		ELSE CONVERT(VARCHAR(15), CASt(cs.OutTime AS TIME), 100)
                        		END
                        	,ShiftInTime = CASE 
                        		WHEN cs.InTime IS NULL
                        			THEN CONVERT(VARCHAR(15), CAST(SD.InTime AS TIME), 100)
                        		ELSE CONVERT(VARCHAR(15), CASt(cs.InTime AS TIME), 100)
                        		END
                        	,AP.InTime InTime
                        	,AP.OutTime OutTime
                             ,DateDiff(minute, AP.PunchOutTime,AP.OutTime) OutTimeDifferent 
                        	,ISNULL(MA.UpdatedBy, MA.AddedBy) ManualAttdnUser
                        	,ISNULL(ISNULL(MA.DateUpdated, MA.DateAdded), '') ManualAttdnDate
                        	,AP.IsOTComfirm
                        	,OTF.NormalOTHr ComfirmedOT
                        	,AP.OTHr CalOT
                        	,ISNULL(AP.PunchInTime, '') PunchInTime
                        	,AP.PunchOutTime PunchOutTime
                            ,DateDiff(minute, AP.PunchOutTime,AP.OutTime) OutTimeDifferent
                             ,AP.OTHr OverStay
                            ,OTF.TotalOTHr
							,(isnull(AP.OTHr,0) - isnull(OTF.TotalOTHr,0)) OTDifference
                        FROM AttdnProcessData AP
                        LEFT JOIN AttdnManualData MA ON AP.EmpSystemID = MA.EmpSystemID
                        	AND AP.WorkDate = MA.WorkDate                       
                        LEFT JOIN FinalOT OTF ON AP.EmpSystemID = OTF.EmpSystemID
                        	AND AP.WorkDate = OTF.WorkDate
                        LEFT JOIN EmployeeInformation EI ON AP.EmpSystemID = EI.SystemId
                        LEFT JOIN EmpDateWiseShiftAssign es ON es.EmpSystemID = EI.SystemId
                        	AND AP.WorkDate = ES.WorkDate
                        Left join DayType DT ON DT.DayType = AP.DayStatus
                        LEFT JOIN (
                        	SELECT m.ShiftDefinationID
                        		,c.ShiftDate
                        		,m.InTime
                        		,m.SystemID
                        		,m.OutTime
                        	FROM [ShiftTimeChgMaster] m
                        	LEFT JOIN [ShiftTimeChgChild] c ON m.SystemID = c.STCMasterSystemID
                        	) CS ON cs.ShiftDefinationID = es.ShiftSystemID
                        	AND cs.ShiftDate = AP.WorkDate
                        LEFT JOIN [ShiftDefination] sd ON sd.SystemID = es.ShiftSystemID";
                strSql += tableName();
                strSql += @"WHERE  
                                AP.DayStatus ='A'  
                        	AND AP.WorkDate between '" + FromDate + @"' and  '" + ToDate + @"'   
                           and ei.PlantId='" + plantId + @"' and ei.CompanyId='" + companyId + @"' and ei.GroupID='" + companyGroupId + @"'                             
							and  AP.InTime IS not NULL	AND AP.OutTime IS not  NULL								
                        ORDER BY 
                        	EmployeeCodePreFix,EmployeeCodeNumeric
                               ,AP.WorkDate";
                con.getDataSet(strSql, out dsRef);
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                con = null;
            }
        }//End Function
        public void GetLeaveWithPunchReports(string FromDate, string ToDate, string plantId, string companyId, string companyGroupId, out DataSet dsRef)
        {
            ConnectionManager.clsConnectionManager con = new clsConnectionManager(120);
