        public void GetTBS(string FromDate, string ToDate, string plantId, string companyId, string companyGroupId, out DataSet dsRef)
        {
            ConnectionManager.clsConnectionManager con = new clsConnectionManager(120);
            string strSql = string.Empty;

            try
            {
                strSql = @"SELECT
                format(ap.WorkDate,'dd-MMM-yyy') WorkDate ";
                strSql += columnName();
                strSql += @"
                ,FORMAT(EI.EmployeeCurrentStatusEffectiveDate,'dd-MMM-yyyy') EmployeeCurrentStatusEffectiveDate
                ,ssd.DayStatus
                ,ssdc.c PresentFromEffectiveDate
                ,TotalAbsent.c NumberOfAbsentDays

                FROM EmployeeInformation EI
                left join AttdnProcessData AP ON AP.EmpSystemID = EI.SystemId";
                strSql += tableName();
                strSql += @"
                left join AttdnProcessData ssd ON ssd.EmpSystemID = EI.SystemId and ssd.WorkDate='" + ToDate + @"'
                left join (
                select EmpSystemID,count(WorkDate) c from AttdnProcessData a
                left join EmployeeInformation ee on ee.SystemId=a.EmpSystemID
                left join DayType d on d.DayType=a.DayStatus
                where WorkDate between ee.EmployeeCurrentStatusEffectiveDate and '" + ToDate + @"' and d.Category in ('Present','Late')
                group by EmpSystemID
                ) ssdc ON ssdc.EmpSystemID = EI.SystemId
                
                left join (
                select EmpSystemID,count(WorkDate) c from AttdnProcessData a
                left join EmployeeInformation ee on ee.SystemId=a.EmpSystemID
                left join DayType d on d.DayType=a.DayStatus
                where WorkDate between ee.EmployeeCurrentStatusEffectiveDate and '" + ToDate + @"' and d.Category in ('Absent')
                group by EmpSystemID
                ) TotalAbsent ON TotalAbsent.EmpSystemID = EI.SystemId


                WHERE
                AP.WorkDate='" + ToDate + @"'
                and ei.PlantId='" + plantId + @"' and ei.CompanyId='" + companyId + @"' and ei.GroupID='" + companyGroupId + @"'
                and ei.DOJ<='" + ToDate + @"' AND (ei.DOS is null OR ei.DOS>= '" + FromDate + @"')
                AND EI.EmployeeCurrentStatus='TBS'
                
                ORDER BY
                EmployeeCodePreFix,EmployeeCodeNumeric,ap.WorkDate";
                con.getDataSet(strSql, out dsRef);

            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                con = null;
            }
        }//End Function
        public void GetMaternityLeave(string FromDate, string ToDate, string plantId, string companyId, string companyGroupId, out DataSet dsRef)
        {
            ConnectionManager.clsConnectionManager con = new clsConnectionManager(120);
            string strSql = string.Empty;

            try
            {
                strSql = @" select format(APD.WorkDate,'dd-MMM-yyyy')WorkDate,mlp.ChildNo
                          ";
                strSql += columnName();
                strSql += @"
                            ,APD.DayStatus,let.LeaveType,let.UserName LeaveName
                                ,APD.MaternityStatus 

							,format(DateAdd(DAY,-mlp.MaternityStartDay,LT.FromDate),'dd-MMM-yyyy') as FollowUpStartDay
							,format(DateAdd(DAY,mlp.MaternityEndDay,LT.ToDate-1),'dd-MMM-yyyy') as FollowUpEndDay
							,Format(LT.FromDate,'dd-MMM-yyyy') MaternityLeaveStartDay
							,Format(LT.ToDate,'dd-MMM-yyyy') MaternityLeaveEndDay
							,EC.UserName as EmployeeCategory

                             from  dbo.AttdnProcessData APD 
                             left join EmployeeInformation ei on ei.SystemId=APD.EmpSystemID
                            ";
                strSql += tableName();

                strSql += @"
                             left join (select * from [dbo].[LeaveTransaction]
							 where  ('" + FromDate + @"' Between FromDate and ToDate) or 
							 ('" + ToDate + @"' Between FromDate and ToDate)
							 ) LT on LT.EmpSystemID=ei.SystemId and APD.LTSystemID=LT.LTSystemID
                              left join [dbo].[LeaveType] lET on  lET.Id = APD.LTSystemId  
                               left join [MST].[MaternityLeavePolicy] mlp on mlp.Id=LT.MaternityLeavePolicyId
                             where let.LeaveType='Maternity'
                             AND APD.WorkDate between '" + FromDate + @"' and  '" + ToDate + @"'   
                             and ei.PlantId='" + plantId + @"' and ei.CompanyId='" + companyId + @"' and ei.GroupID='" + companyGroupId + @"'
                            
                             order by mlp.MaternityLeaveStartDay,EmployeeCodePreFix,EmployeeCodeNumeric,APD.WorkDate";
