            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                con = null;
            }
        }//End Function
        public void GetBankRemark(string FromDate, string ToDate, string plantId, string companyId, string companyGroupId, out DataSet dsRef)
        {
            ConnectionManager.clsConnectionManager con = new clsConnectionManager(120);
            string strSql = string.Empty;

            try
            {
                strSql = @"  select distinct EI.systemid,EI.PaymentMode 
                            ,b.EmpSystemID,b.BankAccNo,b.IsApproved,EI.EmployeeStatus
                            ,Remark=case when isnull(EI.PaymentMode,'')='Bank' and ISNULL(b.BankAccNo,'')='' then 'Bank Acc is required'
                            when (isnull(EI.PaymentMode,'')<>'Bank' and isnull(EI.PaymentMode,'')<>'Transfer') and ISNULL(b.BankAccNo,'')<>'' then 'Payment mode is not valid'
                            when (isnull(EI.PaymentMode,'')='Bank' or isnull(EI.PaymentMode,'')='Transfer') and ISNULL(b.BankAccNo,'')<>'' and b.IsApproved=0 then 'Bank Acc Approval required'
                            else 'OK' end
                            ";
                strSql += columnName();
                strSql += @"
                                ,b.IsApproved
							
                            from EmployeeInformation EI
                           ";
                strSql += tableName();
                strSql += @"
                            left join EmployeeBankInfo b on ei.SystemId=b.EmpSystemID
                            where 
	                    	 EI.DOJ<='" + ToDate + @"' AND (EI.DOS is null OR EI.DOS>= '" + ToDate + @"') 
                         and EI.PlantId='" + plantId + @"' AND EI.CompanyId='" + companyId + @"' and EI.GroupID='" + companyGroupId + @"'
                         and EI.DOJ<='" + ToDate + @"' AND (EI.DOS is null OR EI.DOS>= '" + FromDate + @"')
                            and                          
                            (--plant
                            (isnull(EI.PaymentMode,'')='Bank' and ISNULL(b.BankAccNo,'')='') 
                            or (isnull(EI.PaymentMode,'')='Cash' and ISNULL(b.BankAccNo,'')<>'') 
                            or (isnull(EI.PaymentMode,'')='Transfer' and ISNULL(b.BankAccNo,'')='') 
                            --or (isnull(EI.PaymentMode,'')='Bank' and ISNULL(b.BankAccNo,'')<>'' 
                            or b.IsApproved=0)--plant 
                            ";
                con.getDataSet(strSql, out dsRef);

            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                con = null;
            }
        }//End Function

