        #region Attendance Summary Status report

        public void GetAttendanceSummaryStatusReport(string FromDate, string ToDate, string plantId, string companyId, string companyGroupId, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;

            try
            {
                strSql = @"   SELECT EmpSystemID, MIN(FORMAT(WorkDate,'dd-MMM-yyy')) FromDate, MAX(Format(WorkDate,'dd-MMM-yyy')) ToDate,					
		                            SUM(ISNULL(TotalPresent, 0)) TotalPresent, SUM(ISNULL(TotalLate, 0)) TotalLate, 
		                            SUM(ISNULL(TotalAbsent, 0)) TotalAbsent, SUM(ISNULL(TotalLv, 0)) TotalLv, 
		                            SUM(ISNULL(Other, 0)) Other, SUM(ISNULL(TotalWeekOff, 0)) TotalWeekOff,								
		                            SUM(ISNULL(TotalHoliDay, 0)) TotalHoliDay,EmployeeName,EmployeeCode,Designation,DOJ,

	                                  LineSection = CASE WHEN Line is null THEN SubSection   
									                                                 
                                                       ELSE Line END

                            FROM (							
							SELECT EmpSystemID, WorkDate,EEI.EmployeeName,EEI.EmployeeCode,dg.UserName Designation,format(EEI.DOJ,'dd-MMM-yyyy')DOJ,
                                S.UserName Section,l.UserName Line,ss.UserName SubSection,
			                            TotalPresent = CASE WHEN d.Category = 'Present' THEN 1                                                       
                                                       ELSE 0 END,
			                            TotalLate = CASE WHEN d.Category = 'Late' THEN 1                                                       
                                                       ELSE 0 END,
			                            TotalAbsent = CASE WHEN d.Category = 'Absent' THEN 1                                                       
                                                       ELSE 0 END,
			                            TotalLv = CASE WHEN d.Category = 'Leave' THEN 1 						                               
						                               ELSE 0 END,
			                            Other = CASE WHEN d.Category not in( 'Leave','Present','Late','Absent','Leave','Weekend','Holiday') THEN 1 
						                            ELSE 0 END,
			                            TotalWeekOff = CASE WHEN d.Category = 'Weekend' THEN 1 
						                                ELSE 0 END,
			                            TotalHoliDay = CASE WHEN d.Category = 'Holiday' THEN 1 
						                               ELSE 0 END,
                                        OTHr
	                             FROM   (select * from dbo.AttdnProcessData where WorkDate between '" + FromDate + @"' and  '" + ToDate + @"') z 
                            left join DayType d on d.DayType=z.DayStatus
							LEFT join EmployeeInformation  EEI on EEI.SystemId=z.EmpSystemID
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = eei.BudgetCode
                            LEFT JOIN ORG.Position PR ON MB.PositionId=PR.Id
							left join hkp.LegalDesignation dg on dg.id=EEI.LegalDesignationId 	
	                        left join [ORG].[Section] s on s.Id=pr.SectionId	
							left join [ORG].[SubSection] ss on ss.Id=pr.SubSectionId
							left join [ORG].[Line] l on l.Id=mb.LineId	
                                WHERE z.WorkDate between '" + FromDate + @"' and  '" + ToDate + @"'
								and EmpSystemID in
								(--t
								
								SELECT 
                            AB.EmpSystemID 
       --                     ,format(apd.WorkDate,'dd-MMM-yyyy') as FD
							--,format(ab.WorkDate,'dd-MMM-yyyy')TD
							--,ei.EmployeeName,format(ei.DOJ,'dd-MMM-yyyy')DOJ
       --                     ,apd.daystatus as [Status],ei.EmployeeCode
                            FROM AttdnProcessData AS apd
                            INNER JOIN EmployeeInformation AS ei ON ei.SystemId=apd.EmpSystemID                          
                            INNER JOIN (select* from (SELECT apd.EmpSystemID, apd.WorkDate,apd.DayStatus, dense_rank() OVER (PARTITION BY apd.EmpSystemID ORDER BY apd.WorkDate DESC) AS RNK
                            FROM AttdnProcessData AS apd WHERE apd.DayStatus NOT IN (
                            SELECT dt.DayType FROM DayType AS dt WHERE dt.Category IN ('Holiday','Weekend')
                            ) AND apd.WorkDate<'" + ToDate + @"'
                            )AS K WHERE k.RNK=1) AB ON ab.EmpSystemID=apd.EmpSystemID
                            
                            WHERE apd.WorkDate ='" + ToDate + @"'

                             AND apd.DayStatus IN (SELECT dt.DayType FROM DayType AS dt WHERE dt.Category IN ('Present','Late')) 
                            AND AB.DayStatus='A'--he was present flags								
								)--t							
								) A
                            GROUP BY EmpSystemID,EmployeeName,EmployeeCode,Designation,DOJ
                                   ,Line,Section,SubSection
                                    ";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function
