        #region  Hourly Ot report

        public void GetHourotReport(string FromDate, string ToDate, string plantId, string companyId, string companyGroupId, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;

            try
            {
                strSql = @"       select ei.EmployeeName,ei.EmployeeCode,format(ei.DOJ,'dd-MMM-yyyy')DOJ,FORMAT(ho.WorkDate,'dd-MMM-yyyy')WorkDate,s.UserName as Section,sb.UserName as SubSection,ld.UserName Designation
                                      ,d.UserName Department,ap.DayStatus,ei.GenderID,HO.Duration,
                                      HO.EmpSystemId,HO.EmpSystemId,FORMAT(HO.FromDate,'dd-MMM-yyyy hh:mm tt') FromDate,format(HO.ToDate,'dd-MMM-yyyy hh:mm tt')ToDate,l.UserName as Line
                                      ,(cast(ho.Duration as decimal(18,2) )/60)as DurationH,hr.OTConsiderOn
                                        ,HO.OTType 
                                      From HourlyOT  HO 
                                      LEFT JOIN EmployeeInformation ei on ei.SystemId=HO.EmpSystemId
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = ei.BudgetCode
                            LEFT JOIN ORG.Position PR ON MB.PositionId=PR.Id
                                      LEFT JOIN AttdnProcessData ap on  ho.EmpSystemId=ap.EmpSystemID and HO.WorkDate=ap.WorkDate
                                      LEFT JOIN [ORG].[Section] s on s.Id=pr.SectionId
                                      LEFT JOIN [ORG].[SubSection] sb on sb.Id=pr.SubSectionId
                                      LEFT JOIN [HKP].[LegalDesignation] ld on ld.Id=ei.LegalDesignationId
                                      LEFT JOIN [ORG].[Department] d on d.Id=pr.DepartmentId
                                      LEFT JOIN [ORG].[Line] l on l.Id=mb.LineId
                                      LEFT JOIN PlantWiseHRMSSetting hr on hr.PlantID=HO.PlantId     
                                    where HO.WorkDate between '" + FromDate + "' and '" + ToDate + @"'  and ei.PlantId='" + plantId + @"'
                                    order by ei.EmployeeCode,ho.WorkDate
                                    ";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function
