        #region Individual Daily OT Report Compliance
        public DataTable GetCIndividualDailyOT(string FromDate, string ToDate, string OTDuration, string OTfinal, string plantId, string companyId, string companyGroupId)
        {
            string strSql = string.Empty;//789
            try
            {
                if (OTfinal == "ConfirmOT")
                {
                    strSql = @"SELECT ei.EmployeeName,ei.systemid
                            ,ei.EmployeeCode
                            ,FORMAT(ot.WorkDate,'dd-MMM-yyyy') WorkDate
                            ,FORMAT(ei.DOJ,'dd-MMM-yyyy') DOJ
                            --,s.UserName as Section,S.Sequence SectionSequence,S.ID SectionId,sb.UserName as SubSection,ld.UserName Designation,d.UserName Department,d.Id DepartmentId,d.Sequence DepartmentSequence
                                                        ---,s.UserName as Section,S.Sequence SectionSequence,S.ID SectionId,sb.UserName as SubSection,ld.UserName Designation,d.UserName Department,d.Id DepartmentId,d.Sequence DepartmentSequence
                            ,Section.UserName as Section,Section.Sequence SectionSequence,Section.ID SectionId,SubSection.UserName as SubSection,ld.UserName Designation,Department.UserName Department,Department.Id DepartmentId,Department.Sequence DepartmentSequence
                            
,sum(ot.TotalOTHr) AS TotalOT
                            ,sum(ot.TotalOTHr)/60 AS TotalOTH
                            ,pwhr.OTConsiderOn
                            ,l.UserName Line
                            --,DayType=case when dt.Category ='Holiday' then 'H'
							--when dt.Category ='Weekend' then 'W'
							--else 'NW' end
                            ,dt.OriginalDayType DayType
                        ,ssd.InTime,ssd.OutTime
                             FROM FinalOT ot 
                            left join AttdnProcessData ssd on ssd.EmpSystemID=ot.EmpSystemID and ot.WorkDate=ssd.WorkDate and ssd.IsOTComfirm=1 and ssd.IsOTEntitled=1
							 left join DayType dt on dt.DayType=ssd.DayStatus
                             left join EmployeeInformation ei on ei.SystemId=ot.EmpSystemID
                             LEFT JOIN [MST].[ManpowerBudget] AS MB  on MB.Id = ei.BudgetCode
								                LEFT JOIN ORG.Entity AS ENT ON ENT.Id = MB.EntityId
  
									LEFT OUTER JOIN ORG.Position PO ON MB.PositionId=PO.Id
                                    LEFT OUTER JOIN ORG.Entity EN ON MB.EntityId=EN.Id
                                    LEFT JOIN [ORG].[Department] ON Department.Id = PO.DepartmentId
                                    LEFT JOIN [ORG].[Division] ON Division.Id = EN.DivisionId
                                    LEFT JOIN [ORG].[Plant] ON Plant.Id = EN.PlantId
                                    LEFT JOIN [ORG].[Section] ON Section.Id = PO.SectionId
                                    LEFT JOIN [ORG].[SubSection] ON SubSection.Id = PO.SubSectionId
                                    LEFT JOIN [ORG].[Unit] ON Unit.Id = EN.UnitId
                                    Left join org.Line L on L.Id = MB.LineId
                            LEFT JOIN [HKP].[LegalDesignation] ld ON ld.Id=ei.LegalDesignationId
                            LEFT JOIN [dbo].[PlantWiseHRMSSetting] pwhr ON pwhr.PlantID=ot.PlantID
                            WHERE ot.WorkDate BETWEEN '" + FromDate + @"' AND '" + ToDate + @"'  AND ot.plantid='" + plantId + @"'
                            AND ssd.IsOTComfirm=1 AND ssd.IsOTEntitled=1
                            GROUP BY EI.EmployeeName,EI.EmployeeCode,ot.WorkDate,ei.DOJ,Section.UserName,Section.ID,SubSection.UserName
							,Department.Sequence,Section.Sequence
                            ,ld.UserName ,Department.UserName,Department.Id,pwhr.OTConsiderOn,l.UserName ,EmployeeCodePreFix,ei.systemid
							 ,EmployeeCodeNumeric,dt.OriginalDayType,ssd.InTime,ssd.OutTime
                            having  sum(isnull(ot.TotalOTHr,0))/60 > '" + OTDuration + @"'
                            order by TotalOT desc,EmployeeCodePreFix,EmployeeCodeNumeric,WorkDate";

                }
                else
                {
                    strSql = @"SELECT ei.EmployeeName,ei.systemid,ei.EmployeeCodeNumeric
                            ,ei.EmployeeCode
                            ,FORMAT(ssd.WorkDate,'dd-MMM-yyyy') WorkDate
                            ,format(ei.DOJ,'dd-MMM-yyyy')DOJ
 ,Section.UserName as Section,Section.Sequence SectionSequence,Section.ID SectionId
 ,SubSection.UserName as SubSection,ld.UserName Designation,Department.UserName Department,Department.Id DepartmentId
 ,Department.Sequence DepartmentSequence
                            ,sum(ssd.OTHr) AS TotalOT
                            ,sum(ssd.OTHr)/60 AS TotalOTH
                            ,pwhr.OTConsiderOn
                            ,l.UserName Line
                            ,ssd.IsOTEntitled
                            ,ssd.DayStatus

                            ,ssd.InTime InTimeShow
							,ssd.OutTime  OutTimeShow
							,ShiftInTimeLate=CASE
							 WHEN cs.InTime IS NULL
							 THEN CONVERT(varchar(15),CAST(ssd.InTime AS TIME),108)
							 ELSE CONVERT(VARCHAR(15), CAST(cs.InTime AS TIME), 108)
						     END
                                    , CONVERT(VARCHAR(5), ssd.InTime, 108) InTimelate
                             ,ShiftInTimeShow = CASE
							 WHEN cs.InTime IS NULL
							 THEN CONVERT(varchar(15),CAST(SD.InTime AS TIME),100)
							 ELSE CONVERT(VARCHAR(15), CAST(cs.InTime AS TIME), 100)
						     END
                            ,datename(dw,ssd.WorkDate) as PDay
                            --,DayType=case when dt.Category ='Holiday' then 'H'
							--when dt.Category ='Weekend' then 'W'
							--else 'NW' end
                          ,ShiftOutTime = CASE                                   
                           WHEN cs.OutTime IS NULL
                           THEN CONVERT(varchar(15),CAST(SD.OutTime AS TIME),100)
                           ELSE CONVERT(VARCHAR(15), CASt(cs.OutTime AS TIME), 100)
                           END
                                     ,ShiftInTime = Format(SD.InTime, 'yyyy-MM-dd') + ' ' + CASE 
			                         WHEN cs.InTime IS NULL
			                         	THEN CONVERT(VARCHAR(15), CAST(SD.InTime AS TIME), 100)
			                         ELSE CONVERT(VARCHAR(15), CASt(cs.InTime AS TIME), 100)
			                         END
                            ,dt.OriginalDayType DayType
							,ISNULL(CAS.MaxOTPerDay,'') MaxOTPerDay, ISNULL(CAS.MaxExtraOTPerDay,'') MaxExtraOTPerDay,CAS.IsNoPunchOnHolidayForOTEntitle,CAS.IsNoPunchOnHolidayForOTNotEntitle,CAS.IsNoPunchOnWeekOffForOTEntitle,CAS.IsNoPunchOnWeekOffForOTNotEntitle
                             FROM AttdnProcessData ssd 
                            left join DayType dt on dt.DayType=ssd.DayStatus
                             left join EmployeeInformation ei on ei.SystemId=ssd.EmpSystemID
                             LEFT JOIN [MST].[ManpowerBudget] AS MB  on MB.Id = ei.BudgetCode
								                LEFT JOIN ORG.Entity AS ENT ON ENT.Id = MB.EntityId
  
									LEFT OUTER JOIN ORG.Position PO ON MB.PositionId=PO.Id
                                    LEFT OUTER JOIN ORG.Entity EN ON MB.EntityId=EN.Id
                                    LEFT JOIN [ORG].[Department] ON Department.Id = PO.DepartmentId
                                    LEFT JOIN [ORG].[Division] ON Division.Id = EN.DivisionId
                                    LEFT JOIN [ORG].[Plant] ON Plant.Id = EN.PlantId
                                    LEFT JOIN [ORG].[Section] ON Section.Id = PO.SectionId
                                    LEFT JOIN [ORG].[SubSection] ON SubSection.Id = PO.SubSectionId
                                    LEFT JOIN [ORG].[Unit] ON Unit.Id = EN.UnitId
                                    Left join org.Line L on L.Id = MB.LineId
                                    LEFT JOIN HKP.LegalDesignation Ld on LD.Id = ei.LegalDesignationId
									
                                    LEFT JOIN [dbo].[ComplianceAttendanceSetting] CAS ON CAS.CompanyGroupId=MB.CompanyGroupId and cas.PlantId=ei.PlantId

                                    LEFT join [dbo].[PlantWiseHRMSSetting] pwhr ON pwhr.PlantID=ssd.PlantID
                                    LEFT JOIN EmpDateWiseShiftAssign es on es.EmpSystemID = EI.SystemId AND  es.WorkDate = ssd.WorkDate

							 left join(
                                SELECT  m.ShiftDefinationID, c.ShiftDate, m.InTime, m.SystemID,m.OutTime  FROM[ShiftTimeChgMaster] m
                                left join[ShiftTimeChgChild] c on m.SystemID = c.STCMasterSystemID
                                         ) CS on cs.ShiftDefinationID = es.ShiftSystemID and cs.ShiftDate = ssd.WorkDate
                                left join[ShiftDefination] sd on sd.SystemID = es.ShiftSystemID

                            WHERE SSD.WorkDate BETWEEN '" + FromDate + @"' AND '" + ToDate + @"' AND SSD.IsOTEntitled=1 AND SSD.plantid='" + plantId + @"'
                             GROUP BY EI.EmployeeName,EI.EmployeeCode,ei.DOJ,Section.UserName,Section.ID,SubSection.UserName
							,Department.Sequence,Section.Sequence,SSD.WorkDate,SSD.InTime,SSD.OutTime
                            ,ld.UserName ,Department.UserName,Department.Id,pwhr.OTConsiderOn,l.UserName ,EmployeeCodePreFix,ei.systemid
							 ,EmployeeCodeNumeric,dt.OriginalDayType,cs.InTime,SD.InTime,cs.OutTime,SD.OutTime,CAS.MaxExtraOTPerDay
							 ,CAS.MaxOTPerDay,CAS.IsNoPunchOnHolidayForOTEntitle,CAS.IsNoPunchOnHolidayForOTNotEntitle,CAS.IsNoPunchOnWeekOffForOTEntitle,CAS.IsNoPunchOnWeekOffForOTNotEntitle
                            ,ssd.IsOTEntitled,ssd.DayStatus
                            HAVING  SUM(ISNULL(SSD.OTHr,0))/60 > '" + OTDuration + @"'
                            ORDER BY TotalOT desc,ISNULL(EmployeeCodePreFix,''),EmployeeCodeNumeric,WorkDate";
                }


                return _sqlRepository.GetDataTable(strSql);
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
            }
        }//End Function


