        #region  Hourly Ot report month

        public void GetEncashReport(string YearNo, string plantId, string companyId, string companyGroupId, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;
            var identity = (CustomIdentity)Thread.CurrentPrincipal.Identity;

            try
            {
                strSql = @"select yc.YearNo,Format(EncashmentDate,'dd-MMM-yyyy')EncashmentDate,let.EmpSystemId,let.Days,let.Rate
                            ,lt.LeaveType, let.LeaveEncashmentType,e.EmployeeName,e.EmployeeCode,
                            Disbus=case when let.Isdisburse='1' then 'Yes' else 'No' End ,format(e.DOJ,'dd-MMM-yyyy')DOJ,hr.OTConsiderOn,
                            ld.UserName [Designation],se.UserName [Section],ss.UserName [SubSection],l.UserName [Line],d.UserName [Department],format(e.DOS,'dd-MMM-yyyy')DOS
                            ------------------------------------------------------------------------------------------------------------------------------------
                            ,let.BasicAmmount, let.GrossAmmount, let.BankAccNo, let.PaymentMode,b.UserName BankName,bb.UserName BankBranchName
                            ,let.BroughtForward
                            ,let.DaysCanBeSanctioned
                            ,let.AvailedLeave
                            ,Balance=ISNULL(let.BroughtForward,0)+ISNULL(let.DaysCanBeSanctioned,0)-ISNULL(let.AvailedLeave,0)-ISNULL(let.Days,0)-ISNULL(let.YearEndLapse,0)
                            ,let.CarryForward
                            ,let.YearEndLapse
                            From
                            [dbo].[LeaveEncashmentTransaction] as let
                            left join EmployeeInformation as e on e.SystemId=let.EmpSystemId
                            
                            LEFT JOIN MST.ManpowerBudget PMB ON e.BudgetCode=PMB.Id
                            LEFT JOIN ORG.Position PR ON PMB.PositionId=PR.Id
                            LEFT JOIN ORG.Entity En ON PMB.EntityId=En.Id
                            
                            left join [ORG].[Department] d on d.Id=PR.DepartmentId
                            left join [HKP].[LegalDesignation] ld on ld.Id=let.LegalDesignationId
                            left join [ORG].[Section] se on se.Id=PR.SectionId---------
                            left join [ORG].[SubSection] ss on ss.Id=PR.SectionId
                            
                            left join [ORG].[Line] as l on l.Id = PMB.LineId
                            
                            left join [dbo].[YearlyCalendar] as yc on yc.Id=let.YearlyCalendarId
                            left join [dbo].[LeaveType] lt ON lt.Id =let.LeaveTypeSystemId
                            LEFT JOIN PlantWiseHRMSSetting hr on hr.PlantID=let.PlantId
                            -------------------------------------------------------------------------------------------------------
                            left join [HKP].[Bank] b ON b.Id=let.BankSystemID
                            left join [HKP].[BankBranch] bb ON bb.Id=let.BankBranchId
                            left join TRN.EmployeeLeaveSummary S ON S.EmployeeId=let.EmpSystemId AND s.CalanderYearId=let.YearlyCalendarId
                            INNER JOIN LeaveType t on s.LeaveTypeId=t.Id AND t.LeaveType='Earn'
                            
                            where yc.YearNo='" + YearNo + @"' 
                            order by EmployeeCodePreFix ,EmployeeCodeNumeric
                                                                ";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function

        public void GetEarnLeaveReport(string YearNo, string plantId, string companyId, string companyGroupId, bool isActive, bool isSeperated, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;
            var identity = (CustomIdentity)Thread.CurrentPrincipal.Identity;


            try
            {
                strSql = @"SELECT [CheckBoxSelect] = Convert(bit, 'False'),yc.YearNo,FORMAT(s.FromDate,'dd-MMM-yyyy')FromDate,FORMAT(s.ToDate,'dd-MMM-yyyy')Todate,
                            E.SystemId, e.EmployeeCode,e.EmployeeName,e.FatherName,t.UserName LeaveType ,FORMAT(e.DOB,'dd-MMM-yyyy') DOB,FORMAT(e.DOJ,'dd-MMM-yyyy') DOJ,format(e.DOS,'dd-MMM-yyyy')DOS
                            , EC.UserName EmpCategoryName
                            ,ld.UserName Designation
                            ,U.UserName Unit
                            ,Dv.UserName Division
                            ,Dp.UserName Department
                            ,Se.UserName Section
                            ,SB.UserName SubSection
                            ,L.UserName Line
                            ,isnull(s.YearEndLapse,0)as YearEndLapse ,isnull(s.EncashedInbetween,0) as EncashedInbetween
                            ,BroughtForward=CASE WHEN s.IsEncashed =1 THEN ISNULL(s.CarryForward, 0)+ISNULL(s.EncashedInbetween, 0) ELSE ISNULL(s.BroughtForward, 0)+isnull(s.CarryForwardOpeningBalance,0) END
                            ,s.DaysCanBeSanctioned
                            
                            ,isnull(kk.LeaveDuration,0) AvailedLeave
                            
                            -----------------------------------Is Brought Forward Add to balance -----------------------------------------------------------
                            ,Balance=CASE WHEN t.LeaveType='Earn' THEN
                            CASE WHEN
                            -----------------------------------DOJorDOC start -----------------------------------------------------------
                            CASE WHEN ltd.LvAvailedOnDOJ=1 THEN
                            CASE WHEN ltd.CanAvailUOM='Year' THEN DateAdd(YEAR,LvCanAvailAfter, e.DOJ )
                            WHEN ltd.CanAvailUOM='Month' THEN DateAdd(MONTH,LvCanAvailAfter, e.DOJ )
                            WHEN ltd.CanAvailUOM='Day' THEN DateAdd(DAY,LvCanAvailAfter, e.DOJ ) END
                            WHEN ltd.LvAvailedOnDOC=1 THEN
                            CASE WHEN ltd.CanAvailUOM='Year' THEN DateAdd(YEAR,LvCanAvailAfter, e.DOC )
                            WHEN ltd.CanAvailUOM='Month' THEN DateAdd(MONTH,LvCanAvailAfter, e.DOC )
                            WHEN ltd.CanAvailUOM='Day' THEN DateAdd(DAY,LvCanAvailAfter, e.DOC )
                            END
                            END
                            ---------------------------------------DOJorDOC start end-------------------------------------------------------
                            
                            > GETDATE() then
                            (CASE WHEN s.IsEncashed =1 THEN ISNULL(s.CarryForward, 0)+ISNULL(s.EncashedInbetween, 0) ELSE ISNULL(s.BroughtForward, 0)+isnull(s.CarryForwardOpeningBalance,0) END)+isnull(s.DaysCanBeSanctioned,0)-isnull(kk.LeaveDuration,0)-isnull(s.EncashedInbetween,0)------No
                            ELSE (CASE WHEN s.IsEncashed =1 THEN ISNULL(s.CarryForward, 0)+ISNULL(s.EncashedInbetween, 0) ELSE ISNULL(s.BroughtForward, 0)+isnull(s.CarryForwardOpeningBalance,0) END)+isnull(s.DaysCanBeSanctioned,0)-isnull(kk.LeaveDuration,0)-isnull(s.EncashedInbetween,0) END---Yes
                            ELSE (CASE WHEN s.IsEncashed =1 THEN ISNULL(s.CarryForward, 0)+ISNULL(s.EncashedInbetween, 0) ELSE ISNULL(s.BroughtForward, 0)+isnull(s.CarryForwardOpeningBalance,0) END)+isnull(s.DaysCanBeSanctioned,0)-isnull(kk.LeaveDuration,0)-isnull(s.EncashedInbetween,0) END ---No
                            
                            ,ISNULL(ltd.PolicyName,'') PolicyName
                            ,YY.BASIC
							,YY.GROSS
                           ,isnull(ltd.LvEncashmentFormulaDesID,0)as LvEncashmentFormulaDesID
                           
                            from TRN.EmployeeLeaveSummary S
                            JOIN trn.EmployeeLeaveSummary AS SX ON sx.Id=s.Id AND sx.Id=(SELECT TOP 1 Id FROM trn.EmployeeLeaveSummary AS X 
                            WHERE x.EmployeeId=s.EmployeeId AND s.LeaveTypeId=x.LeaveTypeId AND x.PlantId=s.PlantId AND x.fromdate<='" + YearNo + @"' ORDER BY X.ToDate DESC)
                            INNER JOIN LeaveType t on s.LeaveTypeId=t.Id AND t.LeaveType='Earn'
                            INNER JOIN EmployeeInformation e on e.SystemId=s.EmployeeId
                            
                             LEFT JOIN MST.ManpowerBudget PMB ON e.BudgetCode=PMB.Id
                             LEFT JOIN ORG.Position PR ON PMB.PositionId=PR.Id
                             LEFT JOIN ORG.Entity En ON PMB.EntityId=En.Id
                             left join [dbo].[YearlyCalendar] as yc on yc.Id=S.CalanderYearId
                            
                            LEFT JOIN (
                            select
                            tt.UserName LeaveType,t.EmpSystemID,t.LTSystemID, sum(isnull(d.LeaveDuration,0)) LeaveDuration
                            from
                            LeaveTransaction t
                            left join
                            (--detail
                            select SUM(LeaveDuration) LeaveDuration, LvTrnsSystemID from LeaveTransactionDetails
                            where IsAvailed=1
                            and WorkDate <='" + YearNo + @"'
                            group by LvTrnsSystemID
                            )--detail
                            d on t.SystemID=d.LvTrnsSystemID
                            
                            left join LeaveType tt on tt.id=t.LTSystemID
                            where t.IsApproved=1
                            group by tt.UserName ,t.EmpSystemID,t.LTSystemID
                            ) kk on kk.LTSystemID=s.LeaveTypeId and kk.EmpSystemID=s.EmployeeId
                            left outer join (
                            --***********LV**********************
                            
                             SELECT DC.LeavePolicyMasterId ,lpm.PolicyName ,e.SystemId EmpId,d.*
                            FROM
                            EmployeeInformation e
				LEFT JOIN HKP.LegalDesignation LD ON LD.Id = e.LegalDesignationId
				LEFT JOIN MSt.DesignationMasterLegalDesignation DMLD ON LD.ID = DMLD.LegalDesignationId
                            LEFT join MST.DesignationMaster DM ON  DM.Id = DMLD.DesignationMasterId
                            LEFT JOIN SCS.DesignationMasterConfiguration DC
                            ON DM.Id=DC.DesignationMasterId AND dc.plantid=e.plantid
                            LEFT JOIN LeavePolicyDetail d ON d.LPMSystemID=dc.LeavePolicyMasterId
                            LEFT JOIN LeavePolicyMaster AS lpm ON lpm.SystemID=dc.LeavePolicyMasterId
                            where dc.plantid='" + identity.PlantId + @"'
                            --*******************LV***********************
                            ) ltd on ltd.LTSystemID = t.Id AND ltd.EmpId=e.SystemId
                            
                            
                            LEFT JOIN HKP.EmployeeCategory AS EC ON E.EmployeeCategorySystemID = EC.Id
                            LEFT JOIN ORG.Unit U ON E.UnitID = U.Id
                            LEFT JOIN ORG.Division Dv ON PR.DivisionID = Dv.Id
                            LEFT JOIN ORG.Department Dp ON PR.DepartmentID = Dp.Id
                            LEFT JOIN ORG.Section Se ON PR.SectionID = Se.Id
                            LEFT JOIN ORG.SubSection SB ON PR.SubSectionID = SB.Id
                            LEFT JOIN ORG.Line L ON PMB.LineID = L.Id
                            LEFT JOIN HKP.Designation D ON E.DesignationSystemID = D.Id
                            LEFT JOIN HKP.LegalDesignation AS ld ON e.LegalDesignationId = ld.Id
                            LEFT JOIN MST.DesignationMaster dm ON E.GivenDesignationId = dm.DesignationId
                                     
                                left join (									  
									SELECT
                                        max(case when SalaryHead = 'Basic' then D.EntryAmount end) [BASIC],
                                         max(case when SalaryHead = 'Gross' then D.EntryAmount end) [GROSS]

                                        ,EmpInfoSystemID
FROM ( SELECT x.EffectiveDate EffectiveDate,m.SystemID,x.EmpInfoSystemID
										from (
										SELECT max(y.EffectiveDate) EffectiveDate ,EmpInfoSystemID FROM (
										SELECT max(EffectiveDate) EffectiveDate ,EmpInfoSystemID FROM SalaryInfoDefineMaster WHERE IsApproved =1 AND EffectiveDate<=GETDATE() GROUP BY EmpInfoSystemID
										union
										SELECT Max(EffectiveDate) EffectiveDate ,EmpInfoSystemID FROM SalaryInfoBackMaster WHERE IsApproved =1 AND EffectiveDate<=GETDATE() GROUP BY EmpInfoSystemID
										) AS y GROUP BY y.EmpInfoSystemID
										) x										
										INNER JOIN (
										SELECT EffectiveDate,SystemID,EmpInfoSystemID FROM SalaryInfoDefineMaster WHERE IsApproved =1
										union
										SELECT EffectiveDate,SystemID,EmpInfoSystemID FROM SalaryInfoBackMaster WHERE IsApproved =1
										) m ON m.EffectiveDate=x.EffectiveDate AND m.EmpInfoSystemID=x.EmpInfoSystemID ) mas
										   INNER JOIN (
                                            	SELECT SystemID, SalaryID, side.SalaryHeadID,SalaryHead, EntryCurrencyID, EntryAmount, DefineCurrencyID, DefineAmount, AmtDefinitionCurrencyID, AmtDefinitionRate, SequenceNo, SalaryCategory
                                            	FROM SalaryInfoDefine side inner join 
                                            	SalaryHead SHb On SHb.SalaryHeadID =side.SalaryHeadID and SHb.HeadCategory IN ('Basic','GROSS')
                                            	
                                            	UNION
                                            	
                                            	SELECT SystemID, SalaryID, sib.SalaryHeadID,SalaryHead, EntryCurrencyID, EntryAmount, DefineCurrencyID, DefineAmount, AmtDefinitionCurrencyID, AmtDefinitionRate, SequenceNo, SalaryCategory
                                            	FROM SalaryInfoBack  sib Inner join 
                                            	SalaryHead SH On SH.SalaryHeadID =sib.SalaryHeadID and SH.HeadCategory IN ('Basic','GROSS')
                                            	
												) d ON mas.SystemID = d.SalaryID

	                                        Group by EmpInfoSystemID	

									  )YY on YY.EmpInfoSystemID=e.SystemId	

                            where --s.CalanderYearId='" + YearNo + @"' AND 
                            s.EmployeeId IN (SELECT SystemId FROM EmployeeInformation WHERE PlantId='" + identity.PlantId + @"'";
                if ((isSeperated && isActive) || (!isSeperated && !isActive))
                {
                    strSql += @"AND ( EmployeeStatus = 'Active' OR  (EmployeeStatus = 'Separated' AND DOS <='" + YearNo + @"'))";
                }
                else
                {
                    if (isActive)
                    {
                        strSql += @"AND EmployeeStatus = 'Active'";
                    }
                    if (isSeperated)
                    {
                        strSql += @"AND (EmployeeStatus = 'Separated' AND DOS <='" + YearNo + @"')";
                    }
                }


                strSql += @")ORDER BY e.EmployeeCodePreFix,e.EmployeeCodeNumeric";

                ConnectionManager.clsConnectionManager con = new ConnectionManager.clsConnectionManager(600);
                con.getDataSet(strSql, out dsRef);
                //objCon = new ConnectionManager.DAL.ConManager("1");
                //objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function
        #endregion

        #region AttendanceOnDayStatus
        public void GetAttendanceOnDayStatus(string fromDate, string toDate, string DateStatus, string EmpIdLoop, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;
            var identity = (CustomIdentity)Thread.CurrentPrincipal.Identity;
            var DayTypeAndCatagory = "";
            if (DateStatus == "TotalPresent")
            {
                DayTypeAndCatagory = "AND  DT.Category in( 'Present','Late') ";
            }
            if (DateStatus == "Absent")
            {
                DayTypeAndCatagory = "AND  DT.Category = 'Absent'";
            }
            if (DateStatus == "LatePresent")
            {
                DayTypeAndCatagory = "AND  DT.Category = 'Late'";
            }
            if (DateStatus == "Leave")
            {
                DayTypeAndCatagory = "AND  DT.Category = 'Leave'";
            }
            if (DateStatus == "OnTimePresent")
            {
                DayTypeAndCatagory = "AND  DT.Category = 'Present'";
            }
            try
            {
                strSql = @"SELECT e.SystemId,DT.DayType,e.EmployeeCode,mpb.Code BudgetCode,e.EmployeeName
                                    ,REPLACE(CONVERT(VARCHAR(11), e.DOJ, 106), ' ', '-') DOJ
                                    ,REPLACE(CONVERT(VARCHAR(11), e.DOS, 106), ' ', '-') DOS
								    ,format( APD.WorkDate,'dd-MMM-yyyy') as WorkDate 
                                    ,ld.UserName LegalDesignation
									,Section.UserName as Section
									,Subsection.UserName as Subsection
									,Line.UserName as Line
									,edept.UserName as Department
									,LT.UserName LeaveType
                                    ,Division.UserName as Division
			                        ,format(APD.InTime,'dd-MMM-yyyy hh:mm tt')as InTime
									,format(APD.OutTime,'dd-MMM-yyyy hh:mm tt')as OutTime
                                    ,s.ShiftDefinationName
                                        ,ShiftOutTime= CASE                                   
                                   WHEN cs.OutTime IS NULL
                                   THEN CONVERT(varchar(15),CAST(S.OutTime AS TIME),100)
                                   ELSE CONVERT(VARCHAR(15), CASt(cs.OutTime AS TIME), 100)
                                   END
                                       ,ShiftInTime= CASE 
			                         WHEN cs.InTime IS NULL
			                         	THEN CONVERT(VARCHAR(15), CAST(S.InTime AS TIME), 100)
			                         ELSE CONVERT(VARCHAR(15), CASt(cs.InTime AS TIME), 100)
			                         END

                                    FROM EmployeeInformation e
								    LEFT OUTER JOIN MST.ManpowerBudget mpb on mpb.Id=e.BudgetCode
									LEFT OUTER JOIN ORG.Position PO ON mpb.PositionId=PO.Id
                                    LEFT OUTER JOIN ORG.Entity EN ON mpb.EntityId=EN.Id
                                    LEFT OUTER JOIN ORG.Department edept on edept.id=PO.DepartmentId
                                    LEFT OUTER JOIN HKP.LegalDesignation  ld on ld.Id=e.LegalDesignationId
									LEFT JOIN [ORG].[Section] ON Section.Id = PO.SectionId
									LEFT JOIN [ORG].[Subsection] ON Subsection.Id = PO.SubsectionId
									LEFT JOIN [ORG].[Line] ON Line.Id = MPB.LineId
                                    

                                    LEFT JOIN [MST].DesignationMaster DesM ON DesM.DesignationId = E.GivenDesignationId
								    LEFT JOIN [HKP].EmployeeCategory EmpC ON EmpC.Id = DesM.EmployeeCategoryId                                
                                    LEFT OUTER JOIN HKP.EmployeeLocation ELoc on mpb.EmployeeLocationId=ELoc.Id
			                        LEFT JOIN [ORG].[Plant] ON Plant.Id = EN.PlantId
									LEFT JOIN [ORG].[Division] ON Division.Id = EN.DivisionId
									LEFT JOIN [ORG].[Unit] ON Unit.Id = EN.UnitId
                                    LEFT OUTER JOIN PlantWiseHRMSSetting hs on hs.PlantID=e.PlantId
                                   --LEFT OUTER JOIN TRN.Resignation rsg on rsg.EmployeeId=e.SystemId
                                   --LEFT OUTER JOIN dbo.PreRecruitmentEmployee pre on pre.Id=e.PreRecruitmentEmployeeId
			                        LEFT OUTER JOIN AttdnProcessData APD ON APD.EmpSystemID = E.SystemId                                    
									LEFT OUTER JOIN LeaveType LT ON LT.Id = APD.LTSystemID
									LEFT OUTER JOIN DayType DT ON DT.DayType = APD.DayStatus

                                    LEFT JOIN ShiftDefination s on s.SystemID=APD.ShiftSystemID  
									LEFT JOIN EmpDateWiseShiftAssign ES on es.EmpSystemID = E.SystemId AND APD.WorkDate = ES.WorkDate
									LEFT JOIN(
                                SELECT  m.ShiftDefinationID, c.ShiftDate, m.InTime, m.SystemID,m.OutTime ,m.BreakStratTime,m.BreakEndTime
								 FROM[ShiftTimeChgMaster] m
                                left join[ShiftTimeChgChild] c on m.SystemID = c.STCMasterSystemID
                                         ) CS on cs.ShiftDefinationID = es.ShiftSystemID and cs.ShiftDate = APD.WorkDate

                                    WHERE 
									  E.GroupID='" + identity.CompanyGroupId + @"' 
									 AND E.PlantId='" + identity.PlantId + @"' 
									 " + DayTypeAndCatagory + @"
									 AND CONVERT(DATE, APD.WorkDate) 
									 between CONVERT(DATE,'" + fromDate + @"') 
									 and CONVERT(DATE,'" + toDate + @"') 
                                      and  E.SystemID in (" + EmpIdLoop + @")
									ORDER BY EmployeeCodePreFix,EmployeeCodeNumeric ASC";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function

        public void GetDailyAllowance(string fromDate, string toDate, string AllowanceDailyId, string EmpIdLoop, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;
            var identity = (CustomIdentity)Thread.CurrentPrincipal.Identity;

            try
            {
                strSql = @"  select format(dat.WorkDate,'dd-MMM-yyyy') as WorkDate,dat.Quantity,dat.Rate,dat.Amount,e.EmployeeCode,e.EmployeeName
                            ,ld.UserName as Designation, d.UserName as Department,se.UserName as Section,ss.UserName as SubSection,l.UserName AS Line
                            ,ad.UserName as AllowanceType,format(e.DOJ,'dd-MMM-yyyy')as DOJ,format(e.DOC,'dd-MMM-yyyy')as DOC,format(e.DOS,'dd-MMM-yyyy')as DOS  ,eu.UserName AS Unit
                            from [dbo].[DailyAllowanceTransaction] as dat 
                            inner join EmployeeInformation as e on e.SystemId=dat.EmpSystemId
                            left join [HKP].[AllowanceDaily] as ad on ad.Id=dat.AllowanceDailyId
                            LEFT JOIN MST.ManpowerBudget PMB ON e.BudgetCode=PMB.Id
                            LEFT JOIN ORG.Position PR ON PMB.PositionId=PR.Id
                            LEFT JOIN ORG.Entity En ON PMB.EntityId=En.Id
                            LEFT JOIN [ORG].[Department] d on d.Id=PR.DepartmentId
                            LEFT JOIN [HKP].[LegalDesignation] ld on ld.Id=e.LegalDesignationId
                            LEFT JOIN [ORG].[Section] se on se.Id=PR.SectionId
                            LEFT JOIN [ORG].[SubSection] ss on ss.Id=PR.SectionId
                            LEFT JOIN [ORG].[Line] as l on l.Id = PMB.LineId
                            LEFT OUTER JOIN ORG.Unit eu on eu.id=EN.UnitId
                            where dat.WorkDate between '" + fromDate + @"' and '" + toDate + @"'
                            and e.PlantId='" + identity.PlantId + @"' and dat.AllowanceDailyId='" + AllowanceDailyId + @"'  and  E.SystemID in (" + EmpIdLoop + @") ";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function

        public void GetDailyAllowanceSummary(string fromDate, string toDate, string AllowanceDailyId, string EmpIdLoop, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;
            var identity = (CustomIdentity)Thread.CurrentPrincipal.Identity;

            try
            {
                strSql = @"  select 
                            e.EmployeeCode,e.EmployeeName
                            ,ld.UserName as Designation, d.UserName as Department,se.UserName as Section,ss.UserName as SubSection,l.UserName AS Line
                            ,ad.UserName as AllowanceType,format(e.DOJ,'dd-MMM-yyyy')as DOJ,format(e.DOC,'dd-MMM-yyyy')as DOC
                            ,format(e.DOS,'dd-MMM-yyyy')as DOS  ,eu.UserName AS Unit
                            ,x.Quantity,x.Amount
                            from EmployeeInformation as e 
                            inner join (select sum(dat.Quantity) as Quantity,sum(dat.Amount) as Amount
							,dat.EmpSystemId,dat.AllowanceDailyId
							from [dbo].[DailyAllowanceTransaction] as dat 
							where dat.WorkDate between '" + fromDate + @"' and '" + toDate + @"'
							Group by  EmpSystemId,AllowanceDailyId) x on e.SystemId=x.EmpSystemId
                            left join [HKP].[AllowanceDaily] as ad on ad.Id=x.AllowanceDailyId
                            LEFT JOIN MST.ManpowerBudget PMB ON e.BudgetCode=PMB.Id
                            LEFT JOIN ORG.Position PR ON PMB.PositionId=PR.Id
                            LEFT JOIN ORG.Entity En ON PMB.EntityId=En.Id
                            LEFT JOIN [ORG].[Department] d on d.Id=PR.DepartmentId
                            LEFT JOIN [HKP].[LegalDesignation] ld on ld.Id=e.LegalDesignationId
                            LEFT JOIN [ORG].[Section] se on se.Id=PR.SectionId
                            LEFT JOIN [ORG].[SubSection] ss on ss.Id=PR.SectionId
                            LEFT JOIN [ORG].[Line] as l on l.Id = PMB.LineId
                            LEFT OUTER JOIN ORG.Unit eu on eu.id=EN.UnitId
                            where
                             e.PlantId='" + identity.PlantId + @"' and x.AllowanceDailyId='" + AllowanceDailyId + @"' 
							and  E.SystemID in (" + EmpIdLoop + @") ";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function


        #endregion

        #region  Hourly Leave report

        public void GetHourLeaveReport(string FromDate, string ToDate, string plantId, string companyId, string companyGroupId, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;

            try
            {
                strSql = @"     select ho.EmpSystemId,Format(ho.WorkDate,'dd-MMM-yyyy')WorkDate,FORMAT(HO.ToDate,'dd-MMM-yyyy hh:mm tt')ToDate,HO.DurationInMin,
                                Approve=case when ho.IsApprove=1 then 'Yes' else 'No' end,ho.ApproveType,format(ho.FromDate,'dd-MMM-yyyy hh:mm tt')FromDate,ho.DurationInHours,
                                ei.EmployeeCode,ei.EmployeeName,ei.GenderID,s.UserName [Section],sb.UserName [SubSection],ld.UserName [Designation],d.UserName [Department]
                                ,l.UserName [Line],FORMAT(ei.DOJ,'dd-MMM-yyyy')DOJ,AP.DayStatus,hlr.UserName as Reason
                                From [dbo].[HourlyOffDuty] as ho
                                LEFT JOIN EmployeeInformation as ei on ei.SystemId=ho.EmpSystemId
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = ei.BudgetCode
                            LEFT JOIN ORG.Position PR ON MB.PositionId=PR.Id
                                LEFT JOIN AttdnProcessData ap on  ho.EmpSystemId=ap.EmpSystemID and HO.WorkDate=ap.WorkDate
                                LEFT JOIN [ORG].[Section] s on s.Id=pr.SectionId
                                LEFT JOIN [ORG].[SubSection] sb on sb.Id=pr.SubSectionId
                                LEFT JOIN [HKP].[LegalDesignation] ld on ld.Id=ei.LegalDesignationId
                                LEFT JOIN [ORG].[Department] d on d.Id=pr.DepartmentId
                                LEFT JOIN [ORG].[Line] l on l.Id=mb.LineId
LEFT JOIN [HKP].[HourlyLeaveReason]  hlr on hlr.Id=ho.HourlyLeaveReasonId
                                    where HO.WorkDate between '" + FromDate + "' and '" + ToDate + @"'  
                                    order by ho.WorkDate,ei.EmployeeCode
                                    ";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function
        #endregion


        #region Worker Late Status report

        public void GetWorkerLateStatusReport(string WorkDate, string EntityId, string EntityUserName, string plantId, string companyId, string companyGroupId, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;

            //string FirstDayOfTheMonth = "01-" + Convert.ToDateTime(WorkDate).ToString("MMM") + "-" + Convert.ToDateTime(WorkDate).ToString("yyyy");
            //string LastDayOfTheMonth = Convert.ToDateTime(FirstDayOfTheMonth).AddMonths(1).AddDays(-1).ToString("dd-MMM-yyyy");

            try
            {
                strSql = @" SELECT count(a.daystatus) Counts,a.EmpSystemID,e.EmployeeName
                                ,e.EmployeeCode,ld.UserName Designation,s.UserName Section,l.UserName Line
                                ,EN.UserName Entity,u.UserName Unit,cd.IsManualInTime
                                ,FORMAT(CD.InTime,'hh:mm tt')InTime
                                FROM AttdnProcessData a
                                left join DayType d on d.DayType=a.DayStatus 
                                left join EmployeeInformation e on e.SystemId=a.EmpSystemID
                                LEFT JOIN [HKP].[LegalDesignation] ld on ld.Id=e.LegalDesignationId
                                left join [ORG].[Section] s on s.Id=e.SectionId
                                left join [ORG].[Unit] u on u.Id=e.UnitId
                                left join [ORG].[Line] l on l.Id=e.LineId
                                LEFT JOIN AttdnProcessData CD ON CD.EmpSystemID=A.EmpSystemID and CD.WorkDate='" + WorkDate + @"'
                                LEFT JOIN MST.ManpowerBudget MB ON MB.Id=E.BudgetCode
                                LEFT JOIN ORG.Entity EN ON EN.Id=MB.EntityId
                                --**********************************************************
                                where month(a.WorkDate)=month('" + WorkDate + @"')  and
                                year(a.WorkDate)=year('" + WorkDate + @"') 
                                And d.Category='Late'                            
                                and a.EmpSystemID in
                                (
                                SELECT a.EmpSystemID
                                FROM AttdnProcessData a
                                left join DayType d on d.DayType=a.DayStatus
                                 WHERE 
                                 WorkDate ='" + WorkDate + @"' 
                                 And d.Category='Late'
                                )
                                --********************************************************
                                group by a.EmpSystemID,e.EmployeeName,e.EmployeeCode,ld.UserName,s.UserName,l.UserName 
                                ,CD.InTime,EN.UserName,U.UserName,cd.IsManualInTime
                                    order by  EN.UserName
                                    ";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function
        #endregion   Worker Late Status report

        #region PreallocatedOTReport Query

        public void GetPreallocatedOTReport(string WorkDate, string plantId, string companyId, string companyGroupId, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;

            try
            {
                strSql = @"SELECT 
                                        Emp.SystemID EmpSystemID,EMP.EmployeeName, EMP.EmployeeCode,EMP.EmpPicPath,EMP.BudgetCode,E.UserName EntityName,D.UserName Designation,
                                        PR.UserName PositionName,DEG.UserName GivenDesignation,DEPT.UserName Department,S.UserName Section,SS.UserName SubSection									
                                        ,PL.UserName Plant,LDEG.UserName LegalDesignation, L.UserName Line,							
										isnull(POT.PreallocatedOTHr,0) * 60 as PreallocatedOTHr,EMP.EmployeeCodePreFix,EMP.EmployeeCodeNumeric,hr.OTConsiderOn								
                                        FROM EmployeeInformation EMP
                                        LEFT JOIN MST.ManpowerBudget PMB ON EMP.BudgetCode=PMB.Id
                                        LEFT JOIN ORG.Position PR ON PMB.PositionId=PR.Id
                                        LEFT JOIN ORG.Entity E ON PMB.EntityId=E.Id
                                        LEFT JOIN ORG.Section S ON S.Id=PR.SectionId
                                        LEFT JOIN ORG.SubSection SS ON SS.Id=PR.SubSectionId
                                        LEFT JOIN HKP.Designation D ON PR.DesignationId=D.Id
                                        LEFT JOIN ORG.Department DEPT ON PR.DepartmentId=DEPT.Id
                                        LEFT JOIN ORG.Plant PL ON PL.Id=EMP.PlantId
                                        LEFT JOIN PlantWiseHRMSSetting hr on hr.PlantID=PL.Id 
                                        LEFT JOIN ORG.Line L ON L.Id=PMB.LineId
                                        LEFT JOIN HKP.Designation DEG ON EMP.GivenDesignationId=DEG.Id
                                        LEFT JOIN HKP.LegalDesignation LDEG ON EMP.LegalDesignationId=LDEG.Id								
                                        LEFT JOIN [dbo].[PreallocatedOT] POT ON POT.EmpSystemID=EMP.SystemId 
                                        WHERE emp.PlantID='" + plantId + @"'  and EMP.CompanyId='" + companyId + @"' AND POT.WorkDate ='" + WorkDate + @"'										
										ORDER BY EmployeeCodePreFix,EmployeeCodeNumeric";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function


        public void GetPreallocatedOTReportDepartmentSection(string WorkDate, string plantId, string companyId, string companyGroupId, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
