        #region Actual OT AND Plan Report Query

        public void GetActualOTAndPlanReport(string WorkDate, string plantId, string companyId, string companyGroupId, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;

            try
            {
                strSql = @"SELECT 
                            Emp.SystemID EmpSystemID,EMP.EmployeeName, EMP.EmployeeCode,EMP.EmployeeCodePreFix,EMP.EmployeeCodeNumeric	
                            ,DEPT.UserName Department,S.UserName Section,SS.UserName SubSection,apd.DayStatus	
                            ,LDEG.UserName LegalDesignation
                            ,ISNULL(POT.PreallocatedOTHr*60,0) as PlanOT,ISNULL(FT.TotalOTHr,0)TotalOTHr
                            ,case when POT.PreallocatedOTHr*60 -FT.TotalOTHr>0 then POT.PreallocatedOTHr*60 -FT.TotalOTHr else 0 end [LessThanPlanned]
                            ,case when FT.TotalOTHr-POT.PreallocatedOTHr*60>0 then FT.TotalOTHr-POT.PreallocatedOTHr*60 else 0 end [MoreThanPlanned]
                            ,case when FT.EmpSystemID is null then POT.PreallocatedOTHr*60 else 0 end [NotInActual]
                            ,case when pot.EmpSystemID is null then ft.TotalOTHr else 0 end [NotInPlan],hr.OTConsiderOn,L.UserName AS Line
                            ,Format(apd.InTime,'hh:mm tt')InTime,format(apd.OutTime,'hh:mm tt')OutTime,sd.ShiftDefinationName,apd.IsManualDayStatus,apd.IsManualInTime,apd.IsManualOutTime
                            FROM EmployeeInformation EMP

                             LEFT JOIN MST.ManpowerBudget PMB ON EMP.BudgetCode=PMB.Id
                             LEFT JOIN ORG.Position PR ON PMB.PositionId=PR.Id
                             LEFT JOIN ORG.Entity En ON PMB.EntityId=En.Id
							 
                            LEFT JOIN [dbo].[PreallocatedOT] POT ON POT.EmpSystemID=EMP.SystemId AND POT.WorkDate ='" + WorkDate + @"'
                            left join AttdnProcessData apd on apd.EmpSystemID=EMP.SystemID and apd.WorkDate ='" + WorkDate + @"'
                            left join [dbo].[ShiftDefination] as sd on sd.SystemID=apd.ShiftSystemID
                            LEFT JOIN ORG.Section S ON S.Id=PR.SectionId
                            LEFT JOIN ORG.SubSection SS ON SS.Id=PR.SubSectionId
                            LEFT JOIN ORG.Department DEPT ON PR.DepartmentId=DEPT.Id
                            LEFT JOIN ORG.Plant PL ON PL.Id=EMP.PlantId

                             LEFT JOIN PlantWiseHRMSSetting hr on hr.PlantId=PL.Id   

                            LEFT JOIN ORG.Line L ON L.Id=PMB.LineId
                            LEFT JOIN HKP.Designation DEG ON EMP.GivenDesignationId=DEG.Id
                            LEFT JOIN HKP.LegalDesignation LDEG ON EMP.LegalDesignationId=LDEG.Id	
                            left join FinalOT FT ON FT.WorkDate='" + WorkDate + @"' AND FT.EmpSystemID=EMP.SystemId
                            WHERE emp.PlantID='" + plantId + @"' 
                            and POT.EmpSystemID is not null or FT.EmpSystemID is not null 
                            ORDER BY EmployeeCodePreFix,EmployeeCodeNumeric";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function

        #endregion

        #region Actual OT AND Plan Report Query

        public void GetTiffineBillLatestReport(string WorkDate, string DailyAllowance, string plantId, string companyId, string companyGroupId, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;
            try
            {
                strSql = @"select FORMAT(dat.WorkDate,'dd-MMM-yyyy')WorkDate,e.EmployeeName					
							,dar.Rate,S.UserName [Section],dat.Quantity
                            ,ss.UserName as [SubSection],DEPT.UserName [Department],L.UserName [Line], DEG.UserName [Designation],LDEG.UserName as [Legal Designation]
                            ,isnull((convert(int,dat.Quantity)*dar.Rate),0) [TotalRate],e.EmployeeCode,apd.DayStatus,apd.InTime,apd.OutTime
                            ,apd.IsManualInTime,apd.IsManualOutTime,apd.IsManualDayStatus,sd.ShiftDefinationName
                            from DailyAllowanceTransaction dat                       
                            left join EmployeeInformation e on e.SystemId=dat.EmpSystemId
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = e.BudgetCode
                            LEFT JOIN ORG.Position P ON MB.PositionId=P.Id
                            left join AttdnProcessData apd on apd.EmpSystemId=dat.EmpSystemId and apd.WorkDate=dat.WorkDate
                            left join [dbo].[ShiftDefination] sd on sd.SystemID=apd.ShiftSystemID
                            left join (
							select d.Rate,d.PlantID,m.DesignationId,d.DailyAllowanceId  from DailyAllowanceRate d
							inner join mst.DesignationMaster m on m.EmployeeCategoryId=d.EmployeeCategoryId
							left join scs.DesignationMasterConfiguration c on c.DesignationMasterId=m.id and c.PlantId='" + plantId + @"'
							) dar on dar.DailyAllowanceId=dat.AllowanceDailyId and dar.PlantId=e.PlantId and dar.DesignationId=e.GivenDesignationId
                            LEFT JOIN ORG.Section S ON S.Id=p.SectionId
                            LEFT JOIN ORG.SubSection SS ON SS.Id=p.SubSectionId
                            LEFT JOIN ORG.Department DEPT ON p.DepartmentId=DEPT.Id
                            LEFT JOIN ORG.Plant PL ON PL.Id=e.PlantId
                            LEFT JOIN ORG.Line L ON L.Id=mb.LineId
                            LEFT JOIN HKP.Designation DEG ON e.GivenDesignationId=DEG.Id
                            LEFT JOIN HKP.LegalDesignation LDEG ON e.LegalDesignationId=LDEG.Id		
                            where dat.PlantId='" + plantId + @"' and DAT.AllowanceDailyId='" + DailyAllowance + @"' and dat.WorkDate='" + WorkDate + @"'";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function
        #endregion    Tiffine Bill Query

        #region Tiffine Bill Summary Query

        public void GetTiffineBillLatestSummaryReport(string FromDate, string ToDate, string DailyAllowance, string plantId, string companyId, string companyGroupId, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;
            try
            {
                strSql = @"select e.EmployeeCode
                            ,sum(isnull(dat.Quantity*dar.Rate,0)) [TotalAmount]
                            ,sum(isnull(dat.Quantity,0)) [Quantity]
                            from DailyAllowanceTransaction dat
                            left join EmployeeInformation e on e.SystemId=dat.EmpSystemId
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = e.BudgetCode
                            LEFT JOIN ORG.Position P ON MB.PositionId=P.Id
                            left join (
                            select d.Rate,d.PlantID,m.DesignationId,d.DailyAllowanceId from DailyAllowanceRate d
                            inner join mst.DesignationMaster m on m.EmployeeCategoryId=d.EmployeeCategoryId
                            left join scs.DesignationMasterConfiguration c on c.DesignationMasterId=m.id and c.PlantId='" + plantId + @"'
                            ) dar on dar.DailyAllowanceId=dat.AllowanceDailyId and dar.PlantId=e.PlantId and dar.DesignationId=e.GivenDesignationId
                            left join [HKP].[AllowanceDaily] AD ON AD.Id=dat.AllowanceDailyId
                            LEFT JOIN ORG.Section S ON S.Id=p.SectionId
                            LEFT JOIN ORG.SubSection SS ON SS.Id=p.SubSectionId
                            LEFT JOIN ORG.Department DEPT ON p.DepartmentId=DEPT.Id
                            LEFT JOIN ORG.Plant PL ON PL.Id=e.PlantId
                            LEFT JOIN ORG.Line L ON L.Id=mb.LineId
                            LEFT JOIN HKP.Designation DEG ON e.GivenDesignationId=DEG.Id
                            LEFT JOIN HKP.LegalDesignation LDEG ON e.LegalDesignationId=LDEG.Id	
                            where dat.PlantId='" + plantId + @"' and DAT.AllowanceDailyId='" + DailyAllowance + @"'
                            and dat.WorkDate between '" + FromDate + "' and '" + ToDate + @"'
                            group by e.EmployeeCode";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function
        #endregion    Tiffine Bill Summary Query


        #region AttendanceRawData

        public void GetAttRawDataReport(string WorkDate, string plantId, string companyId, string companyGroupId, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;

            try
            {
                strSql = @"select  ei.EmployeeName ,ei.EmployeeCode, format(ard.PTime,'dd-MMM-yyyy hh:mm tt')PTime, ard.PType,acl.MachineID,acl.Remarks DeviceDescription
                            ,FORMAT(EI.DOJ, 'dd-MMM-yyyy') DOJ ,DSG.UserName Designation ,se.UserName Section,Sus.UserName SubSection,L.UserName Line,DP.UserName Department
                            ,p.UserName as Plant,format(ard.DateAdded,'dd-MMM-yyyy hh:mm tt')DateAdded,
							E.UserName Entity,''Remarks ,SD.username ShiftName,ec.UserName as EmployeeCategory 
                            from [dbo].[AttdnRawData] ard
                            left join [MST].[AccessControllerList] acl on acl.Id=ard.DevSystemID
                            inner join EmployeeInformation ei on ei.SystemId=ard.LogDownLoadNum
							left join EmpDateWiseShiftAssign DS on DS.EmpSystemID=EI.SystemId	and DS.WorkDate = '" + WorkDate + @"'
							LEFT JOIN dbo.ShiftDefination SD ON DS.ShiftSystemID = SD.SystemID
                            LEFT OUTER JOIN ShiftTimeChgMaster AS cs ON DS.WorkDate BETWEEN cs.FromDate AND cs.ToDate AND sd.SystemID=cs.ShiftDefinationID
							left join org.Plant p on p.Id=ei.PlantId
                            LEFT JOIN MST.ManpowerBudget PMB ON EI.BudgetCode = PMB.Id
                            LEFT JOIN ORG.Position PR ON PMB.PositionId = PR.Id
                            LEFT JOIN ORG.Entity E ON PMB.EntityId = E.Id    
                            LEFT JOIN HKP.Designation DSG ON PR.DesignationId = DSG.Id     
                            LEFT JOIN HKP.Designation DeG ON DeG.Id = EI.GivenDesignationId
                            LEFT JOIN ORG.Department DP ON DP.Id = PR.DepartmentId
                            LEFT JOIN HKP.LegalDesignation LGD ON LGD.Id = EI.LegalDesignationId
                            left join mst.DesignationMasterLegalDesignation ddm on ddm.LegalDesignationId = 
							ei.LegalDesignationId
							left join mst.DesignationMaster dm on dm.Id = ddm.DesignationMasterId
							left join scs.DesignationMasterConfiguration dxc on dxc.DesignationMasterId=dm.Id
							and dxc.PlantId=ei.PlantId
							left join hkp.EmployeeCategory ec on ec.Id=Dm.EmployeeCategoryId
                            LEFT JOIN ORG.Section AS Se ON Se.Id = PR.SectionID
                            LEFT JOIN ORG.SubSection AS SuS ON SuS.Id = PR.SubSectionID
                            LEFT JOIN ORG.Line AS L ON L.Id= PMB.LineId
                           where ard.PDate = '" + WorkDate + @"' and ei.PlantId='" + plantId + @"'
                            order by ei.EmployeeCode,ard.PDate";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function

