        public void GetEmpShiftInfo(string strEmpCode, string FromDate, string ToDate, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;

            try
            {
                strSql = @"select d.EmpSystemID,e.EmployeeCode,e.EmployeeName
                                ,deg.UserName GivenDesignation
                                --,d.WorkDate
                                ,REPLACE(CONVERT(VARCHAR(11), d.WorkDate, 113), ' ', '-') WorkDate
                                ,REPLACE(CONVERT(VARCHAR(11), e.DOJ, 113), ' ', '-') DOJ
                                 ,d.IsManuallyChanged
                                ,isnull(saf.ShiftDefinationName,'') +isnull(sar.ShiftDefinationName,'') PlannedShift
                                ,r.ShiftRosterName
                                ,sd.ShiftDefinationName DateWiseShift
                                ,a.IsFix
                                ,u.UserName Unit
                                ,dept.UserName Department
                                from EmpDateWiseShiftAssign d
                                left join EmployeeShiftAssign a on d.EmpSftAssiSystemID=a.SystemID
                                left join EmployeeInformation e on e.SystemId=d.EmpSystemID
                                left join ShiftDefination saf on saf.SystemID=a.FixSystemID
                                left join ShiftDefination sar on sar.SystemID=a.RosterStartShiftID
                                left join ShiftRosterMaster r on r.SystemID=a.RosterSystemID
                                left join ShiftDefination sd on sd.SystemID=d.ShiftSystemID
                                left join hkp.Designation deg on deg.id=e.GivenDesignationId
                                left join org.Unit u on u.id=e.UnitId
                                left join org.Department dept on dept.id=e.DepartmentId

                                where d.WorkDate between '" + FromDate + @"' and '" + ToDate + @"'
                                and d.EmpSystemID in (" + strEmpCode + @")
                                order by d.WorkDate";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function
        public void GetManualAttendance(string EmpSysId, string WorkDate, string sPlantID, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;


            string _wc = "";

            if (EmpSysId != "")
            {
                _wc = "and E.EmployeeCode in (" + EmpSysId + @")";
            }

            try
            {
                strSql = @"Select Convert(int,e.EmployeeCode ) EmployeeCode, EmployeeName,SB.UserName Designation,u.UserName Unit,D.StandardName Department, 
                                            s.UserName Section,sb.UserName Sub_section, 
											A.DayStatus, 
											CONVERT(varchar(15),CAST(A.InTime AS TIME),100) InTime,
											CONVERT(varchar(15),CAST(A.OutTime AS TIME),100) OutTime
                                            from EmployeeInformation E
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = e.BudgetCode
                            LEFT JOIN ORG.Position PR ON MB.PositionId=PR.Id
                            LEFT JOIN ORG.Entity EN ON MB.EntityId=EN.Id
                                            Left Join ORG.Department D on D.Id = PR.DepartmentId 
                                            Left Join AttdnProcessData A on A.EmpSystemID = E.SystemId
                                            LEFT JOIN ORG.Section S ON PR.SectionID = S.Id
                                            LEFT JOIN ORG.SubSection SB ON PR.SubSectionID = SB.Id
                                            left join ORG.Unit u on u.Id=en.UnitId
											
                                            where  (IsManualDayStatus=1 or IsManualInTime=1 or IsManualOutTime=1) and WorkDate ='" + WorkDate + @"' AND A.PlantID = '" + sPlantID + @"' 
                                            " + _wc + @" 
										    ORDER BY EmployeeCode";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }

        public void GetDailyDayStatus(string WorkDate, string PrevWorkDate, string sPlantID, string DepartmentId, string SectionId, string SubsectionId, string LineId, string dayStatus, string employeeCategory, string shift, string entity, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;
            var ToDates = Convert.ToDateTime(WorkDate);  //PrevWorkDate
            var PrvDate = Convert.ToDateTime(PrevWorkDate);
            //var PrvDate = ToDates.AddDays(-1);


            string _wc = "";

            if (DepartmentId.ToUpper() != "ALL" && DepartmentId != "null" && DepartmentId != "")
            {
                _wc += " and EI.DepartmentId in (" + DepartmentId + ")";
            }
            if (dayStatus != null)
            {
                if (dayStatus.ToUpper() != "ALL" && dayStatus != "null" && dayStatus != "" && dayStatus != "''")
                {
                    if (dayStatus == "'Other'")
                    {
                        _wc += " and AD.Category not in( 'Present','Late','Absent','Leave','Weekend')";
                    }
                    else
                    {
                        _wc += " and AD.Category in (" + dayStatus + ")";
                    }
                }
            }

            if (SectionId.ToUpper() != "ALL" && SectionId != "null" && SectionId != "")
            {
                _wc += " and pr.SectionId in (" + SectionId + ")";
            }
            if (SubsectionId.ToUpper() != "ALL" && SubsectionId != "null" && SubsectionId != "")
            {
                _wc += " and pr.SubSectionId in (" + SubsectionId + ")";
            }
            if (LineId.ToUpper() != "ALL" && LineId != "null" && LineId != "")
            {
                _wc += "and  isnull(m.LineID,'')  in (" + LineId + ")";
            }
            if (employeeCategory.ToUpper() != "ALL" && employeeCategory != "null" && employeeCategory != "")
            {
                _wc += "and ec.Id in (" + employeeCategory + ")";
            }
            if (shift.ToUpper() != "ALL" && shift != "null" && shift != "" && shift.ToUpper() != "'ALL'")
            {
                _wc += "and sd.SystemID in (" + shift + " )";
            }
            if (entity.ToUpper() != "ALL" && entity != "null" && entity != "")
            {
                _wc += "and en.Id in (" + entity + " )";
            }


            try
            {
                strSql = @"Select   ei.FatherName,ec.UserName as EmployeeCategory,FORMAT(CAST(AD.intime AS datetime2), N'hh:mm tt')intime,FORMAT(CAST(AD.outtime AS datetime2), N'hh:mm tt')outtime,sd.UserName as ShiftName,en.UserName as Entity,
Dp.UserName Department, ad.seq,ad.ds,FORMAT(CAST(sd.InTime AS datetime2), N'hh:mm tt') ShiftIntime,FORMAT(CAST(sd.OutTime AS datetime2), N'hh:mm tt') ShiftOuttime,
                                    S.UserName Section,
                                    SS.UserName SubSection,                                   
									L.UserName Line,
                                    ISNULL(LG.UserName,'') Designation, 
                                    EI.SystemId EmpSystemId,
                                    EI.EmployeeCode, EI.EmployeeName , CONVERT(VARCHAR(5), AD.InTime, 108) IInTime,CONVERT(VARCHAR(5), SD.InTime, 108) ShiftIn,
                                    CONVERT(VARCHAR(5), SD.InTime, 108) iShiftIn,CONVERT(VARCHAR(5), SD.OutTime, 108) ShiftOut,
                                    TodayStatus=case 
									when  AD.SEQ=1 THEN AD.DS when isnull(EI.EmployeeCurrentStatus,'') <>'' then EI.EmployeeCurrentStatus else AD.DayStatus 																		
									END,
									PrvDayStatus=case
									when   ADp.DayStatus='LV' THEN ADp.DS when isnull(EI.EmployeeCurrentStatus,'') <>'' then EI.EmployeeCurrentStatus else ADp.DayStatus 	
									end,
	                               -- AD.DayStatus TodayStatus
									 AD.NormalOTHr OTHr,
	                                ADP.DayStatus PrvDayStatus, 
                                    ---isnull(ADP.NormalOTHr,0) YesterdayOTHr,
                                    ADP.NormalOTHr YesterdayOTHr,
                                    ISNULL(M.LineID,'') LineID,
									PR.SubSectionId,l.Sequence,hr.OTConsiderOn
                                    ,AD.IsOTEntitled IsOTEntitledToday, ADP.IsOTEntitled IsOTEntitledYesterday, ISNULL(ADP.IsOTComfirm,0) IsTodayOTComfirm, ISNULL(AD.IsOTComfirm,0) IsYesterDayOTComfirm
                                    ,ToDayReConfirm = CASE WHEN AD.IsOTComfirm=0 AND AD.FIOTWorkDate IS NOT NULL THEN 1 ELSE 0  END
                                    ,YesterDayReConfirm= CASE WHEN ADP.IsOTComfirm=0 AND ADP.FOTWorkDate IS NOT NULL THEN 1 ELSE 0  END,ADP.YesterDayDayCategory,AD.ToDayDayCategory
					        FROM (select *
							,TBSSEQ=case when isnull(EmployeeCurrentStatus,'')='LONG ABSENTEEISM' then 2 when isnull(EmployeeCurrentStatus,'')='TBS' then 3 else 0 end
							 from EmployeeInformation							
							) EI
							
							left outer join MST.ManpowerBudget as m on m.Id=ei.BudgetCode
                            LEFT JOIN ORG.Position PR ON M.PositionId=PR.Id
                            left outer join ORG.Entity  as en on en.Id=m.EntityId
                            LEFT JOIN PlantWiseHRMSSetting hr on HR.PlantID=ei.PlantId
					        LEFT JOIN HKP.LegalDesignation LG on EI.LegalDesignationId = LG.Id
                            LEFT JOIN HKP.Designation GD on GD.Id = EI.GivenDesignationId
                            LEFT JOIN ORG.Section S ON S.Id = PR.SectionId
                            LEFT JOIN ORG.SubSection SS ON SS.ID = PR.SubSectionId
							LEFT JOIN (select dm.EmployeeCategoryId,d.LegalDesignationId from mst.DesignationMasterLegalDesignation d
							 left join MST.DesignationMaster as dm on dm.Id=d.DesignationMasterId
							 ) kk on kk.LegalDesignationId=ei.LegalDesignationId
							LEFT JOIN ORG.Line L ON L.Id = M.LineId
							left join HKP.EmployeeCategory as EC on ec.Id=kk.EmployeeCategoryId
                            LEFT JOIN  EmployeeOTEntitle OT ON OT.EmpSystemID=EI.SystemId
					        INNER JOIN (SELECT APD.*, FIOT.NormalOTHr, FIOT.WorkDate FIOTWorkDate,dt.Category ToDayDayCategory,Dt.Category
                                            ,SEQ=case when  LTSystemid in (select  id from leavetype where LeaveType='Maternity') then 1
													 when isnull(MaternityStatus,'')<>''  then 1 else 0 end
											--,DS=(select  code from leavetype where LeaveType='Maternity' and id=LTSystemid)
											,DS=case when LTSystemid in (select  id from leavetype where LeaveType='Maternity') then (select  code from leavetype where LeaveType='Maternity' and id=LTSystemid)
											when isnull(MaternityStatus,'')<>'' then MaternityStatus else null end 
                             from dbo.AttdnProcessData APD
							LEFT JOIN FINALOT FIOT on FIOT.EmpSystemID = APD.EmpSystemID AND FIOT.WorkDate=APD.WorkDate
							LEFT JOIN DayType dt on dt.Daytype=APD.DayStatus
							WHERE APD.WorkDate  = '" + ToDates.ToString("dd-MMM-yyyy") + @"' 
							) AD ON AD.EmpSystemID = EI.SystemID
							left outer join dbo.ShiftDefination as sd on sd.SystemID=AD.ShiftSystemID
					        LEFT JOIN (select a.*, fot.NormalOTHr, FOT.WorkDate FOTWorkDate,dty.Category YesterDayDayCategory 
                            ,DS=case when LTSystemid in (select  id from leavetype where LeaveType='Maternity') then (select  code from leavetype where LeaveType='Maternity' and id=LTSystemid)
											when isnull(MaternityStatus,'')<>'' then MaternityStatus else null end
                            from dbo.AttdnProcessData a 
							LEFT JOIN FINALOT FOT on FOT.EmpSystemID = a.EmpSystemID AND FOT.WorkDate=a.WorkDate
                            LEFT JOIN DayType dty on dty.Daytype=a.DayStatus
                                    WHERE a.WorkDate  = '" + PrvDate.ToString("dd-MMM-yyyy") + @"'
									) ADP ON ADP.EmpSystemID = EI.SystemID 
                                    LEFT JOIN ORG.Department DP on Dp.Id = PR.DepartmentId
                            
                                    WHERE   (EI.EmployeeStatus = 'Active' OR Convert(date,DOS) >= '" + ToDates.ToString("dd-MMM-yyyy") + @"') AND  EI.Plantid='" + sPlantID + "' " + _wc + @" 
                            ORDER BY EI.TBSSEQ,AD.SEQ,EmployeeCodePreFix,EmployeeCodeNumeric";
                objCon = new ConnectionManager.DAL.ConManager("1");

                objCon.BeginTransaction();
                objCon.getDataSet(strSql, out dsRef);
                objCon.CommitTransaction();

                //objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function

