        public void GetDailyStatusCount(/*ParaAttendanceReport op,*/ string companyGroupId, string companyId, string plantId, string workDate, string shift, string Entity, string Dept, string Ydate, string Sec, string SSec, string designationList, string empCategoryList, string LineId, string Dstatus, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;
            string xxy = string.Empty;
            clsStaticInfo obs = null;
            string ShiftIds_WC = "";
            try
            {
                if (shift.Length > 0)
                {
                    ShiftIds_WC = " where ShiftSystemID in (" + shift + ") ";
                }

                if (Dstatus != null)
                {
                    if (Dstatus.ToUpper() != "ALL" && Dstatus != "null" && Dstatus != "" && Dstatus != "''")
                    {
                        if (Dstatus == "'Other'")
                        {
                            xxy = " and dt.Category not in( 'Present','Late','Absent','Leave','Weekend')";
                        }
                        else
                        {
                            xxy = " and dt.Category in (" + Dstatus + ")";
                        }
                    }
                }

                obs = new clsStaticInfo();
                strSql = @"SELECT EmpSystemId,EmployeeCode,FatherName
								,Department
	                            , EmployeeName
	                            , DOJ
                                ,dti,dto
	                            , PDate
	                            , DayStatus
	                            , InTime
                                ,ShiftName
                                ,ShiftInTimeShow
								,ShiftOutTimeShow
                                ,InTimeShow
                                ,OutTimeShow
	                            , InDeviceID
	                            , OutTime
	                            , OutDeviceID
	                            , OTHr
	                            , ShiftInTime = CASE
		                            WHEN ShiftChangeInTime IS NULL
			                            THEN ShiftInTime
		                            ELSE ShiftChangeInTime
		                            END
	                            , PlantID
                                ,'0' Duration
                                ,'0' LateBy,ShortLeave,LeaveType,IsManualDayStatus,IsManualInTime,IsManualOutTime
	                    , Designation
		                , EmpCategory
		                , Line
		                , SubSection
		                , Section
		                , Department
                                ,JobLocation,Entity,PrvDayStatus,YesterdayOTHr,OTConsiderOn,TodaysOT
                        ,TodayStatus
			                FROM
                            (
                              SELECT E.SystemId EmpSystemId,E.EmployeeCode
                                    ,E.FatherName                                    
	                                , E.EmployeeName
	                                , REPLACE(CONVERT(VARCHAR(11), E.DOJ, 113), ' ', '-') DOJ	                                
	                                , dep.Id DepartmentID
	                                , s.id SectionID
	                                , ss.Id SubSectionID
	                                , L.id LineID
                                    ,AD.InTime dti,AD.OutTime dto
	                                , REPLACE(CONVERT(VARCHAR(11), AD.WorkDate, 113), ' ', '-') PDate
	                                , E.EmployeeCategorySystemID EmpCategoryID
	                                , AD.DayStatus
	                                , CONVERT(VARCHAR(5), AD.InTime, 108) InTime
                                    ,CONVERT(varchar(15),CAST(AD.InTime AS TIME),100) InTimeShow
	                                , ARIN.DeviceID InDeviceID
	                                , CONVERT(VARCHAR(5), AD.OutTime, 108) OutTime
                                    ,CONVERT(varchar(15),CAST(AD.OutTime AS TIME),100) OutTimeShow
	                                , AROUT.DeviceID OutDeviceID
	                                , AD.OTHr
	                                , CONVERT(VARCHAR(5), SFCG.InTime, 108) ShiftChangeInTime
	                                , CONVERT(VARCHAR(5), SD.InTime, 108) ShiftInTime

                                    , ShiftInTimeShow = CASE
		                            WHEN SFCG.InTime IS NULL
			                            THEN CONVERT(varchar(15),CAST(SD.InTime AS TIME),100)
		                            ELSE CONVERT(VARCHAR(15), CAST(SFCG.InTime  AS TIME), 100)
		                            END
                                    ,AD.OTHr TodaysOT
                                    , ShiftOutTimeShow = CASE
		                            WHEN SFCG.OutTime IS NULL
			                            THEN CONVERT(varchar(15),CAST(SD.OutTime AS TIME),100)
		                            ELSE CONVERT(VARCHAR(15), CAST(SFCG.OutTime AS TIME), 100)
		                            END
                                    , SD.ShiftDefinationName ShiftName
	                                , AD.PlantID,LG.Id Designation
									, AD.CountedShortLeave ShortLeave ,lt.Code LeaveType
                                    ,ad.IsManualDayStatus,ad.IsManualInTime,ad.IsManualOutTime		                           
		                            , L.UserName Line
		                            , dep.UserName Department
		                            , S.UserName Section
		                            , ss.UserName SubSection
		                            , EC.UserName AS EmpCategory
                                    ,PrvDayStatus=ADp.DayStatus 
									,ADP.NormalOTHr YesterdayOTHr
                                    ,hr.OTConsiderOn
                                    ,TodayStatus=xx.DayStatus
                                    ,jl.JobLocation,
									e.JobLocationID,en.UserName Entity,mp.EntityId,E.EmployeeCodeNumeric

                                FROM dbo.EmployeeInformation E
							                INNER JOIN (select * from dbo.AttdnProcessData  " + ShiftIds_WC + @" )AD ON E.SystemID = AD.EmpSystemID
							                LEFT JOIN (SELECT * FROM dbo.ShiftTimeChgMaster WHERE '" + workDate + @"' BETWEEN FromDate AND ToDate) AS SFCG
											ON AD.ShiftSystemID = SFCG.ShiftDefinationID
							                LEFT JOIN dbo.ShiftDefination SD ON AD.ShiftSystemID = SD.SystemID
							                LEFT JOIN dbo.AttdnRawData ARIN ON AD.InTimeRowID = ARIN.RowID
							                LEFT JOIN dbo.AttdnRawData AROUT ON AD.OutTimeRowID = AROUT.RowID 
                                            left join JobLocation jl on jl.SystemID=e.JobLocationID

											left join mst.ManpowerBudget mp on mp.id=e.BudgetCode
											left join org.Entity en on en.id=mp.EntityId    
											left join ORG.Position p on p.Id = mp.PositionId
											left join org.Department dep on dep.Id = p.DepartmentId
											left join org.Section s on s.Id = p.SectionId
											left join org.SubSection ss on ss.Id = p.SubSectionId
											LEFT JOIN PlantWiseHRMSSetting hr on HR.PlantID=e.PlantId
											left join LeaveType lt on lt.Id=ad.LTSystemID                                            
                                            LEFT JOIN org.Line L ON L.Id = En.LineId
                                            LEFT JOIN hkp.LegalDesignation LG ON e.LegalDesignationId = LG.Id
                                            
                                            LEFT JOIN
                                            (
                                            SELECT ECT.Id, ECT.UserName, DM.DesignationId FROM [HKP].[EmployeeCategory] ECT
											LEFT JOIN MST.DesignationMaster DM ON ECT.Id=DM.EmployeeCategoryId
											)EC ON EC.DesignationId=E.GivenDesignationId
                                            left JOIN (SELECT APD.EmpSystemID,APD.DayStatus
                             from dbo.AttdnProcessData APD
							LEFT JOIN DayType dt on dt.Daytype=APD.DayStatus
							WHERE APD.WorkDate  = '" + workDate + @"'
							) xx ON xx.EmpSystemID = E.SystemID
                            LEFT JOIN (select  a.EmpSystemID,a.DayStatus, fot.NormalOTHr, FOT.WorkDate FOTWorkDate,dty.Category YesterDayDayCategory
                            from dbo.AttdnProcessData a 
							LEFT JOIN FINALOT FOT on FOT.EmpSystemID = a.EmpSystemID AND FOT.WorkDate=a.WorkDate
                            LEFT JOIN DayType dty on dty.Daytype=a.DayStatus
                                    WHERE a.WorkDate  = '" + Ydate + @"'
									) ADP ON ADP.EmpSystemID = E.SystemID 

			                    WHERE LG.Id in (" + designationList + ") and AD.WorkDate  = '" + workDate + @"' 
                                AND (ISNULL(E.EmployeeCurrentStatus,'') != 'TBS' or (ISNULL(E.EmployeeCurrentStatus,'') = 'TBS' AND EmployeeCurrentStatusEffectiveDate > '" + workDate + @"')))
                                A  WHERE PlantID  = '" + plantId + @"'";


                if (Dept != "ALL")
                {
                    strSql = strSql + @" AND DepartmentID in ( " + Dept + ")";
                }
                if (Sec != "ALL")
                {
                    strSql = strSql + @" AND SectionID in (" + Sec + ")";
                }
                if (SSec != "ALL")
                {
                    strSql = strSql + @" AND SubSectionID in (" + SSec + ")";
                }

                if (empCategoryList != "ALL")
                {
                    strSql = strSql + @" AND EmpCategoryID in (" + empCategoryList + ")";
                }

                if (Entity != "ALL")
                {
                    strSql = strSql + @" AND EntityId in (" + Entity + ")";
                }
                if (LineId != "ALL" && LineId != "''")
                {
                    strSql = strSql + @" AND isnull(LineId,'') in (" + LineId + ")";
                }



                objCon = new ConnectionManager.DAL.ConManager("1");
                //objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");

                objCon.BeginTransaction();
                objCon.getDataSet(strSql, out dsRef);
                objCon.CommitTransaction();
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function


       
