        public void GetDailyAttnRptForVisitor(string sPlantID, string WDate, string sVisCatSysID, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;

            try
            {
                strSql = @"SELECT * FROM
                            (
                              SELECT A.VisitorID, A.VisitorName, A.Category, REPLACE(CONVERT(VARCHAR(11), A.PDate, 113), ' ', '-') PDate,
		                            CONVERT(VARCHAR(5), A.InTime, 108) InTime, A.OutTime,
		                            DayStatus = CASE WHEN A.PDate IS NULL THEN 'A'
					                            WHEN (DATEDIFF(MINUTE, A.InTime, (A.PDate + ' 09:00:00.000'))) < -15 THEN 'L'
					                            ELSE 'P'
					                            END,
		                            LateBy = CASE WHEN (DATEDIFF(MINUTE, A.InTime, (A.PDate + ' 09:00:00.000'))) < -15 THEN (DATEDIFF(MINUTE, (A.PDate + ' 09:00:00.000'), A.InTime))
					                            ELSE 0 END
	                            FROM
                                    (SELECT V.VisitorID, V.VisitorName, VC.Category, ADIN.PDate,
                                        ADIN.PTime InTime, CONVERT(VARCHAR(5), ADOUT.PTime, 108) OutTime
                                    FROM dbo.VisitorEntry V
                                        LEFT JOIN (
						                            SELECT LogDownLoadNum, PDate, PType, MIN(PTime) PTime FROM dbo.AttdnRawData
								                            WHERE PDate = '" + WDate + @"' AND PType = 'IN' AND PlantID = '" + sPlantID + @"'
							                            GROUP BY LogDownLoadNum, PDate, PType
						                            ) ADIN ON V.VisitorID = ADIN.LogDownLoadNum
                                        LEFT JOIN (
						                            SELECT LogDownLoadNum, PDate, PType, MAX(PTime) PTime FROM dbo.AttdnRawData
								                            WHERE PDate = '" + WDate + @"' AND PType = 'OUT' AND PlantID = '" + sPlantID + @"'
							                            GROUP BY LogDownLoadNum, PDate, PType
						                            ) ADOUT ON V.VisitorID = ADOUT.LogDownLoadNum AND ADIN.PDate = ADOUT.PDate
                                        LEFT JOIN dbo.VisitorCategory VC ON V.VisCatSystemID = VC.SystemID ";

                if (sVisCatSysID != "ALL")
                {
                    strSql = strSql + @" WHERE V.VisCatSystemID = '" + sVisCatSysID + @"'";
                }

                strSql = strSql + @"
                                ) A
                            GROUP BY A.VisitorID, A.VisitorName, A.Category, A.PDate, A.InTime, A.OutTime
                            ) B
                        ORDER BY DayStatus, Category, VisitorID";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function

        public void GetMonthlyAttnSummaryRptForDetails(ParaMontlyAttendance objm, Dictionary<string, string> empParameters, out DataSet dsRef, bool isActive, bool isSeperated, bool isMaternity)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;

            try
            {
                string wcEmpStatus = " Where (1=0 ";

                if (isActive == true && isSeperated == true && isMaternity == true)
                {
                    wcEmpStatus = " Where (1=1 ";
                }
                else
                {
                    if (isActive == true)
                    {
                        wcEmpStatus += " OR CurrentMonthEmployeeStatus ='Regular'";
                    }
                    if (isSeperated == true)
                    {
                        wcEmpStatus += " OR CurrentMonthEmployeeStatus ='Separated'";
                    }
                    if (isMaternity == true)
                    {
                        wcEmpStatus += " OR CurrentMonthEmployeeStatus ='MLV_PRE'";
                    }
                }
                wcEmpStatus += ")";

                strSql = @"SELECT A.* FROM
                                    (SELECT E.SystemId EmployeePK,E.GenderID,E.EmployeeCode,  ISNULL(E.EmployeeCodeNumeric,0) EmployeeCodeNumeric
									,ISNULL(E.EmployeeCodePreFix,0) EmployeeCodePreFix,E.EmployeeName, REPLACE(CONVERT(VARCHAR(11), E.DOJ, 113), ' ', '-') DOJ, REPLACE(CONVERT(VARCHAR(11), E.DOS, 113), ' ', '-') DOS, E.EmpType
                                           ,ISNULL( Ld.UserName, '') LegalDG, Unit.UserName Unit, Division.UserName Division, Department.UserName Department,
                                             ISNULL(EmpC.UserName,'') EmployeeCategory,ISNULL(EmpC.WorkingDaysInAMonth,'') WorkingDaysInAMonth,Section.UserName Section, SubSection.UserName SubSection, Line.UserName Line, REPLACE(CONVERT(VARCHAR(11), ADM.FromDate, 113), ' ', '-') FromDate,
                                            REPLACE(CONVERT(VARCHAR(11), ADM.ToDate, 113), ' ', '-') ToDate, ADM.MonthNo, ADM.YearNo
											, CASE WHEN MONTH(DOS) =  MONTH('" + objm.FDate + @"')  AND YEAR(DOS) = YEAR('" + objm.FDate + @"') then 'Separated' else 'Regular' end CurrentMonthEmployeeStatus

                                            ,ADM.TotalProcDate, ADM.TotalPresent, ADM.TotalLate, ADM.TotalAbsent, ADM.TotalLv, ADM.TotalLWP, ADM.TotalMLv, ADM.TotalOTHr,
                                            ADM.TotalNormalOTHr, ADM.TotalExtraOTHr, ADM.TotalHoliDay, isnull(ADM.TotalWeekOffHoliDay,0) + isnull(ADM.TotalWeekOff,0) TotalWeekOff, ADM.TotalWeekOffHoliDay,SLeave.ShortLeave,Plant.UserName PlantName
                                    FROM dbo.EmployeeInformation E
                                                INNER JOIN 
                                    
                                    dbo.AttdnDataMonthlySummary ADM ON E.SystemID = ADM.EmpSystemID        
                                    LEFT OUTER JOIN MST.ManpowerBudget mpb on mpb.Id=e.BudgetCode
									LEFT OUTER JOIN ORG.Position PO ON mpb.PositionId=PO.Id
                                    LEFT OUTER JOIN ORG.Entity EN ON mpb.EntityId=EN.Id
                                    LEFT JOIN [ORG].[Department] ON Department.Id = PO.DepartmentId
                                    LEFT JOIN [ORG].[Division] ON Division.Id = EN.DivisionId
                                    LEFT JOIN [ORG].[Plant] ON Plant.Id = EN.PlantId
                                    LEFT JOIN [ORG].[Section] ON Section.Id = PO.SectionId
                                    LEFT JOIN [ORG].[SubSection] ON SubSection.Id = PO.SubSectionId
                                    LEFT JOIN [ORG].[Unit] ON Unit.Id = EN.UnitId
                                    LEFT JOIN [ORG].[Line] ON Line.Id = mpb.LineId
						            LEFT JOIN [HKP].[LegalDesignation] as Ld on Ld.Id=E.LegalDesignationId
			                        LEFT JOIN [MST].DesignationMasterLegalDesignation LDM ON LDM.LegalDesignationId=E.LegalDesignationId
			                        LEFT JOIN [MST].DesignationMaster DesM ON DesM.Id = LDM.DesignationMasterId
                                    LEFT JOIN [HKP].EmployeeCategory EmpC ON EmpC.Id = DesM.EmployeeCategoryId
                                    LEFT OUTER JOIN hkp.Designation dsg on dsg.id=PO.DesignationId
                             
                                             LEFT JOIN (
													SELECT EmpSystemID,sum(CountedShortLeave) ShortLeave,DATEPART(year,workdate) _year,DATEPART(month,workdate) _month
												 FROM AttdnProcessData  adm
												 left join dbo.EmployeeInformation E on e.SystemId = adm.EmpSystemID
													where E.PlantID = '" + objm.PlantId + @"'  AND DATEPART(year,workdate)= Year('" + objm.TDate + @"')  AND DATEPART(month,workdate) = Month('" + objm.TDate + @"') 
													group by EmpSystemID,DATEPART(year,workdate),DATEPART(month,workdate)
													
												) SLeave on adm.MonthNo=SLeave._month and adm.YearNo=SLeave._year and e.SystemId=SLeave.EmpSystemID

                                    WHERE --E.PlantID = '" + objm.PlantId + @"' AND 
                                        ADM.MonthNo = Month( '" + objm.TDate + @"') AND ADM.YearNo = Year('" + objm.TDate + @"')
                                    --AND (ISNULL(E.EmployeeCurrentStatus,'') != 'TBS' or (ISNULL(E.EmployeeCurrentStatus,'') = 'TBS' AND EmployeeCurrentStatusEffectiveDate >='" + objm.FDate + @"'))
                                    AND (DOS IS NULL  OR DOS >= '" + objm.FDate + @"') AND E.DOJ <= '" + objm.TDate + @"'";

                if (objm.UnitId != "ALL")
                {
                    strSql = strSql + @" AND EN.UnitID = '" + objm.UnitId + "'";
                }
                if (objm.DivisionId != "ALL")
                {
                    strSql = strSql + @" AND EN.DivisionID = '" + objm.DivisionId + "'";
                }
                if (objm.DepartmentId != "ALL")
                {
                    strSql = strSql + @" AND PO.DepartmentID = '" + objm.DepartmentId + "'";
                }
                if (objm.SectionId != "ALL")
                {
                    strSql = strSql + @" AND PO.SectionID = '" + objm.SectionId + "'";
                }
                if (objm.SubsectionId != "ALL")
                {
                    strSql = strSql + @" AND PO.SubSectionID = '" + objm.SubsectionId + "'";
                }
                if (objm.LineId != "ALL")
                {
                    strSql = strSql + @" AND mpb.LineID = '" + objm.LineId + "'";
                }

                if (objm.EmpCat != "ALL")
                {
                    strSql = strSql + @" AND EmpC.Id = '" + objm.EmpCat + "'";
                }
                if (objm.DesignationGroupId != "ALL")
                {
                    strSql = strSql + @" AND DesM.DesignationGroupID = '" + objm.DesignationGroupId + "'";
                }
                if (objm.JoblocationName.ToUpper() != "ALL")
                {
                    strSql = strSql + @" AND E.JobLocationID = '" + objm.JoblocationName + "'";
                }
                if (objm.DesignationId != "ALL")
                {
                    strSql = strSql + @" AND PO.DesignationID = '" + objm.DesignationId + "'";
                }
                try
                {
                    if (empParameters.Count > 0)
                    {
                        if (empParameters.Keys.ElementAt(0) != "")
                        {
                            strSql += @" AND E.SystemId IN(" + empParameters["EmpSystemId"] + ")";
                        }
                    }
                }
                catch (Exception)
                {
                }


                strSql = strSql + @") A " + wcEmpStatus + @"
                        ORDER BY  A.EmployeeCodePreFix,A.EmployeeCodeNumeric";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function

        public void GetMonthlyDailyAttendanceDicCom(ParaMontlyAttendance objm, Dictionary<string, string> parameters, out DataSet dsRef)
        {
            try
            {
                ConnectionManager.DAL.ConManager objCon;
                string strSql = string.Empty;
                 strSql = @"SELECT A.* FROM
	                                (SELECT E.systemId EmpSystemId,E.EmployeeCode, E.EmployeeName, REPLACE(CONVERT(VARCHAR(11), E.DOJ, 113), ' ', '-') DOJ,
                                            D.UserName Designation, U.UserName Unit, Dv.UserName Division, Dp.UserName Department,
                                            S.UserName Section, SB.UserName SubSection, L.UserName Line,  REPLACE(CONVERT(VARCHAR(11), AD.WorkDate, 113), ' ', '-') PDate,
                                            AD.DayStatus, FORMAT(AD.InTime, 'hh.mm tt') InTime, ARIN.DeviceID InDeviceID, FORMAT(AD.OutTime, 'hh.mm tt') OutTime,
                                            AROUT.DeviceID OutDeviceID,CONVERT(VARCHAR(10),CONVERT(DECIMAL(18,2),AD.OTHr/60), 108) OTHr,FinalOT.TotalOTHr, LT.UserName LvShortName
											,AD.WorkDate, DD.UserName GivenDesignation,DATEPART(day,ad.WorkDate) AS D,DT.Category DayCategory

                                            ,CAS.MaxOTPerDay,CAS.IsNoPunchOnHolidayForOTEntitle,CAS.IsNoPunchOnHolidayForOTNotEntitle,CAS.IsNoPunchOnWeekOffForOTEntitle,CAS.IsNoPunchOnWeekOffForOTNotEntitle
											,AD.IsOTEntitled,ShiftOutTime = CASE WHEN cs.OutTime IS NULL THEN CONVERT(varchar(15),CAST(SD.OutTime AS TIME),100) ELSE CONVERT(VARCHAR(15), CASt(cs.OutTime AS TIME), 100)END 
											,ShiftInTime = Format(AD.WorkDate, 'yyyy-MM-dd') + ' ' + CASE WHEN cs.InTime IS NULL THEN CONVERT(VARCHAR(15), CAST(SD.InTime AS TIME), 100)  ELSE CONVERT(VARCHAR(15), CASt(cs.InTime AS TIME), 100) END
											, AD.InTime InTimeShow, AD.OutTime as OutTimeShow,AD.WorkDate WDate,E.EmployeeCodeNumeric,AD.IsManualOutTime, HR.OTConsiderOn, dt.OriginalDayType,E.SystemId,AD.OTHr OverStay

                                    FROM dbo.EmployeeInformation E
                                                LEFT OUTER JOIN MST.ManpowerBudget mpb on mpb.Id=e.BudgetCode
                                                left join ORG.Position p on p.Id = mpb.PositionId
                                                left join org.Entity en on en.id=mpb.EntityId
                                                INNER JOIN dbo.AttdnProcessData AD ON E.SystemID = AD.EmpSystemID
                                                Left JOIN dbo.DayType DT ON DT.DayType = AD.DayStatus
                                                LEFT JOIN dbo.AttdnRawData ARIN ON AD.InTimeRowID = ARIN.RowID
                                                LEFT JOIN dbo.AttdnRawData AROUT ON AD.OutTimeRowID = AROUT.RowID
											    LEFT JOIN dbo.FinalOT FinalOT ON  FinalOT.EmpSystemID = E.SystemId AND AD.WorkDate = FinalOT.WorkDate                                                
                                                LEFT JOIN dbo.LeaveType LT ON AD.LTSystemID = LT.Id
                                                LEFT JOIN ORG.Unit U ON EN.UnitID = U.Id
                                                LEFT JOIN ORG.Division Dv ON p.DivisionID = Dv.Id
                                                LEFT JOIN ORG.Department Dp ON p.DepartmentID = Dp.Id
                                                LEFT JOIN ORG.Section S ON p.SectionID = S.Id
                                                LEFT JOIN ORG.SubSection SB ON p.SubSectionID = SB.Id
                                                LEFT JOIN ORG.Line L ON mpb.LineID = L.Id
                                                LEFT JOIN HKP.Designation D ON p.DesignationID = D.Id
												LEFT JOIN HKP.Designation DD ON E.GivenDesignationId = DD.Id

												left join [dbo].[ComplianceAttendanceSetting] CAS ON CAS.CompanyGroupId=mpb.CompanyGroupId and cas.PlantId=e.PlantId
												left join EmpDateWiseShiftAssign es on es.EmpSystemID = E.SystemId AND AD.WorkDate = ES.WorkDate
												left join(
                                SELECT  m.ShiftDefinationID, c.ShiftDate, m.InTime, m.SystemID,m.OutTime  FROM[ShiftTimeChgMaster] m
                                left join[ShiftTimeChgChild] c on m.SystemID = c.STCMasterSystemID
                                         ) CS on cs.ShiftDefinationID = es.ShiftSystemID and cs.ShiftDate = AD.WorkDate
										 left join[ShiftDefination] sd on sd.SystemID = es.ShiftSystemID
                                        LEFT JOIN PlantWiseHRMSSetting hr on HR.PlantID=E.PlantId
                                        --LEFT JOIN DayType dt on dt.Daytype=AD.DayStatus

                                    WHERE AD.PlantID = '" + objm.PlantId + @"' AND AD.WorkDate BETWEEN '" + objm.FDate + @"' AND '" + objm.TDate + @"' 
                                    AND (E.DOS is null or E.DOS >= '" + objm.FDate + @"')									
									";
                if (parameters.Count > 0)
                {
                    if (parameters.Keys.ElementAt(0) != "")
                    {
                        strSql += @" AND E.SystemID IN(" + parameters["EmpSystemId"] + ")";
                    }
                }
                strSql += ") A ORDER BY EmpSystemId";
                DataTable dt = _sqlRepository.GetDataTable(strSql);

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {

                throw ex;
            }
        }

        public void GetComplianceMonthlyAttnSummaryRptForDetails(string plantId, string month, string year, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;

            try
            {
                
                strSql = @"SELECT A.* FROM
                                    (SELECT E.SystemId EmployeePK,CONVERT (int,E.EmployeeCode) EmployeeCode, E.EmployeeName, REPLACE(CONVERT(VARCHAR(11), E.DOJ, 113), ' ', '-') DOJ, REPLACE(CONVERT(VARCHAR(11), E.DOS, 113), ' ', '-') DOS, E.EmpType,
                                            D.UserName Designation, DG.UserName GivenDesignation, U.UserName Unit, Dv.UserName Division, Dp.UserName Department,
                                            S.UserName Section, SB.UserName SubSection, L.UserName Line, REPLACE(CONVERT(VARCHAR(11), ADM.FromDate, 113), ' ', '-') FromDate,
                                            REPLACE(CONVERT(VARCHAR(11), ADM.ToDate, 113), ' ', '-') ToDate, ADM.MonthNo, ADM.YearNo,
                                            ADM.TotalProcDate, ADM.TotalPresent, ADM.TotalLate, ADM.TotalAbsent, ADM.TotalLv, ADM.TotalLWP, ADM.TotalMLv, ADM.TotalOTHr,
                                            ADM.TotalNormalOTHr, ADM.TotalExtraOTHr, ADM.TotalHoliDay, ADM.TotalWeekOff, ADM.TotalWeekOffHoliDay,SLeave.ShortLeave
                                    FROM dbo.EmployeeInformation E
left join mst.ManpowerBudget mp on mp.id=e.BudgetCode
											left join org.Entity en on en.id=mp.EntityId    
											left join ORG.Position p on p.Id = mp.PositionId
                                                INNER JOIN dbo.AttdnDataMonthlySummary ADM ON E.SystemID = ADM.EmpSystemID
                                                LEFT JOIN ORG.Unit U ON EN.UnitID = U.Id
                                                LEFT JOIN ORG.Division Dv ON P.DivisionID = Dv.Id
                                                LEFT JOIN ORG.Department Dp ON P.DepartmentID = Dp.Id
                                                LEFT JOIN ORG.Section S ON P.SectionID = S.Id
                                                LEFT JOIN ORG.SubSection SB ON P.SubSectionID = SB.Id
                                                LEFT JOIN ORG.Line L ON mp.LineID = L.Id
                                                LEFT JOIN HKP.Designation D ON P.DesignationID = D.Id
                                                LEFT JOIN HKP.Designation DG ON DG.Id=E.GivenDesignationId
                                            left join (
												select EmpSystemID,sum(CountedShortLeave) ShortLeave,DATEPART(year,workdate) _year,DATEPART(month,workdate) _month
												 from AttdnProcessData
													where PlantID='" + plantId + @"' --and DATEPART(year,workdate)=2018 and DATEPART(month,workdate)=9
													group by EmpSystemID,DATEPART(year,workdate),DATEPART(month,workdate)
													--having sum(CountedShortLeave)>2
												) SLeave on adm.MonthNo=SLeave._month and adm.YearNo=SLeave._year and e.SystemId=SLeave.EmpSystemID

                                    WHERE ADM.PlantID = '" + plantId + @"' AND ADM.MonthNo = '" + month + @"' AND ADM.YearNo = '" + year + @"'
                                    AND (E.EmployeeStatus='Active' OR Year(DOS) >= '" + year + @"' AND MONTH(DOS) >= '" + month + @"')";


                strSql = strSql + @") A
                        GROUP BY A.EmployeeCode, A.EmployeeName, A.DOJ,A.DOS, A.EmpType, A.Designation, A.GivenDesignation,A.Unit, A.Division, A.Department,
		                            A.Section, A.SubSection, A.Line, A.FromDate, A.ToDate, A.MonthNo, A.YearNo,
                                    A.TotalProcDate, A.TotalPresent, A.TotalLate, A.TotalAbsent, A.TotalLv,A.TotalLWP, A.TotalMLv, A.TotalOTHr,
                                    A.TotalNormalOTHr, A.TotalExtraOTHr, A.TotalHoliDay, A.TotalWeekOff, A.TotalWeekOffHoliDay,A.EmployeePK,A.ShortLeave
                        ORDER BY  A.EmployeeCode";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function

