        public void GetMonthlyIntimeOutTimeRaw(string IsDayStatus, Dictionary<string, string> empParameters, ParaMontlyAttendance objm, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;
            string _show_col = " isnull(DayStatus, '') ";
            string _show_man = " AD.DayStatus, ";
            try
            {


                if (IsDayStatus == "INRAW")
                {
                    _show_col = " isnull(InTime, '') ";
                }
                else if (IsDayStatus == "OUTRAW")
                {
                    _show_col = " isnull(OutTime, '') ";
                }
                else
                {
                    _show_col = " isnull(InTime, '') ";
                }


                if (IsDayStatus == "MANUAL")
                {
                    _show_man = @" DayStatus= case when  AD.IsManualDayStatus=1 then 'MANUAL'

                                            when AD.IsManualInTime = 1 then 'MANUAL'

                                            when AD.IsManualOutTime = 1 then 'MANUAL'
											else '' end, ";
                }

                strSql = @"DECLARE @sql_ nvarchar(max)

                                    select  EmployeePK,WorkDate," + _show_col + @" Duration
                                    
                                    INTO #tempOT
                                    from 
                                    (
                                    SELECT A.EmployeePK,A.EmployeeCode,A.EmployeeName,A.DOJ,A.Designation,A.Unit,A.Division,A.Department,A.Section,A.SubSection,A.Line,A.PDate,Min(A.InTime) InTime,MAx(A.OutTime) OutTime,WorkDate,A.GivenDesignation FROM
	                                (SELECT E.systemId EmployeePK,E.EmployeeCode, E.EmployeeName, 
									        REPLACE(CONVERT(VARCHAR(11), E.DOJ, 113), ' ', '-') DOJ,
                                            D.UserName Designation, U.UserName Unit, 
											Dv.UserName Division, Dp.UserName Department,
                                            S.UserName Section, 
											SB.UserName SubSection, 
											L.UserName Line,  
											REPLACE(CONVERT(VARCHAR(11), x.attanDate, 113), ' ', '-') PDate,                                             
											CONVERT(VARCHAR(5), X.IntimeResult, 108) InTime,											
											CONVERT(VARCHAR(5), X.OuttimeResult, 108) OutTime,                                            
										    x.attanDate WorkDate, 
										    DD.UserName GivenDesignation
                                    FROM dbo.EmployeeInformation E    
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = e.BudgetCode
                            LEFT JOIN ORG.Position P ON MB.PositionId=P.Id
                            LEFT JOIN ORG.Entity EN ON MB.EntityId=EN.Id
                                                LEFT JOIN ORG.Unit U ON EN.UnitID = U.Id
                                                LEFT JOIN ORG.Division Dv ON P.DivisionID = Dv.Id
                                                LEFT JOIN ORG.Department Dp ON P.DepartmentID = Dp.Id
                                                LEFT JOIN ORG.Section S ON P.SectionID = S.Id
                                                LEFT JOIN ORG.SubSection SB ON P.SubSectionID = SB.Id
                                                LEFT JOIN ORG.Line L ON MB.LineID = L.Id
                                                LEFT JOIN HKP.Designation D ON P.DesignationID = D.Id
												LEFT JOIN HKP.Designation DD ON E.GivenDesignationId = DD.Id
LEFT JOIN MST.DesignationMaster dm ON E.GivenDesignationId = dm.DesignationId
                            LEFT JOIN HKP.EmployeeCategory EC ON EC.Id=DM.EmployeeCategoryId
												--start Rawdata
												LEFT JOIN
												(   
												select
												a.LogDownLoadNum, a.PDate attanDate,a.PlantID ,
												IntimeResult=i.PTime ,
												OuttimeResultTemp=case when i.PTime > t.PTime   then nt.PTime else t.PTime end,												
												OuttimeResult=case when i.PTime is null   then null else (case when i.PTime > t.PTime   then nt.PTime else t.PTime end) end  
												from (select * from AttdnRawData )a
												left join (select * from AttdnRawData where PType='IN'  ) i on a.LogDownLoadNum=i.LogDownLoadNum and a.PDate=i.PDate
												left join (select * from AttdnRawData where PType='OUT') t on a.LogDownLoadNum=t.LogDownLoadNum and a.PDate=t.PDate
												left join (select * from AttdnRawData where PType='OUT' ) nt on a.LogDownLoadNum=nt.LogDownLoadNum and nt.PDate=  DATEADD(day,1,a.PDate)   
												--where  a.LogDownLoadNum='1800450'
												group by a.LogDownLoadNum, i.PTime ,t.PTime,nt.PTime ,a.PDate,a.PlantID) x 
												ON x.LogDownLoadNum=E.SystemID --AND x.attanDate=ad.WorkDate
											    --end Rawdata
                                    WHERE E.PlantID = '" + objm.PlantId + @"' AND x.attanDate BETWEEN '" + objm.FDate + @"' AND '" + objm.TDate + @"' 
									--and E.SystemID='1800450'---change
                                    AND (E.EmployeeStatus='Active' or E.dos>'" + objm.FDate + "' or e.dos is null)   ";

                if (objm.UnitId != "ALL")
                {
                    strSql = strSql + @" AND EN.UnitID = '" + objm.UnitId + "'";
                }
                if (objm.DivisionId != "ALL")
                {
                    strSql = strSql + @" AND P.DivisionID = '" + objm.DivisionId + "'";
                }
                if (objm.DepartmentId != "ALL")
                {
                    strSql = strSql + @" AND P.DepartmentID = '" + objm.DepartmentId + "'";
                }
                if (objm.SectionId != "ALL")
                {
                    strSql = strSql + @" AND P.SectionID = '" + objm.SectionId + "'";
                }
                if (objm.SubsectionId != "ALL")
                {
                    strSql = strSql + @" AND P.SubSectionID = '" + objm.SubsectionId + "'";
                }
                if (objm.LineId != "ALL")
                {
                    strSql = strSql + @" AND MB.LineID = '" + objm.LineId + "'";
                }
                //if (sSbSeStr != "ALL")
                //{
                //    strSql = strSql + @" AND E.SubSecStrucSystemID = '" + sSbSeStr + "'";
                //}
                if (objm.EmpCat != "ALL")
                {
                    strSql = strSql + @" AND EC.ID = '" + objm.EmpCat + "'";
                }
                if (objm.DesignationGroupId != "ALL")
                {
                    strSql = strSql + @" AND DM.DesignationGroupID = '" + objm.DesignationGroupId + "'";
                }
                if (objm.DesignationId != "ALL")
                {
                    strSql = strSql + @" AND DM.DesignationSystemID = '" + objm.DesignationId + "'";
                }
                if (empParameters.Count > 0)
                {
                    if (empParameters.Keys.ElementAt(0) != "")
                    {
                        strSql += @" AND E.SystemId IN(" + empParameters["EmpSystemId"] + ")";
                    }
                }


                strSql = strSql + @") A
                         GROUP BY A.EmployeeCode, A.EmployeeName, A.DOJ, A.Designation, A.Unit, A.Division, A.Department,
		                            A.Section, A.SubSection, A.Line, A.PDate, 
                                    WorkDate,GivenDesignation ,A.EmployeePK 


                            ) TT
	                            DECLARE @sql nvarchar(max),
                                    @col nvarchar(max)

                            SELECT @col = (
                                SELECT DISTINCT ','+QUOTENAME(REPLACE(CONVERT(VARCHAR(11), WorkDate, 113), ' ', '-'))	
                                FROM #tempOT 
                                FOR XML PATH ('')
                            )

                            SELECT @sql = N'
                            (SELECT *
                            FROM #tempOT
                            PIVOT (
                                MAX([Duration]) FOR [WorkDate] IN ('+STUFF(@col,1,1,'')+')
                            ) as pvt)'

                            EXEC sp_executesql @sql
                            drop table #tempOT
                            ";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function

        public void GetMonthlyDailyShift(string shiftCode, ParaMontlyAttendance objm, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;
            string _show_col = " isnull(ShiftCode, '') ";
            string _show_man = " AD.DayStatus, ";
            try
            {

                //if (IsDayStatus == "OUTTIME")
                //{
                //    _show_col = " isnull(OutTime, '') ";
                //}
                //else if (IsDayStatus == "INTIME")
                //{
                //    _show_col = " isnull(InTime, '') ";
                //}
                //else
                //{
                //    _show_col = " isnull(DayStatus, '') ";
                //}


                //     if (IsDayStatus == "MANUAL")
                //     {
                //         _show_man = @" DayStatus= case when  AD.IsManualDayStatus=1 then 'MANUAL'

                //                                 when AD.IsManualInTime = 1 then 'MANUAL'

                //                                 when AD.IsManualOutTime = 1 then 'MANUAL'
                //else '' end, ";
                //     }

                strSql = @"DECLARE @sql_ nvarchar(max)

                                    select  EmployeePK,WorkDate, isnull(ShiftCode, '')  ShiftCode 
                                    INTO #tempOT
                                    from 
                                    (
                                    SELECT A.* FROM
	                                (SELECT E.systemId EmployeePK,E.EmployeeCode, E.EmployeeName, REPLACE(CONVERT(VARCHAR(11), E.DOJ, 113), ' ', '-') DOJ,
                                            D.UserName Designation, U.UserName Unit, Dv.UserName Division, Dp.UserName Department,
                                            S.UserName Section, SB.UserName SubSection, L.UserName Line,  REPLACE(CONVERT(VARCHAR(11), AD.WorkDate, 113), ' ', '-') PDate,
                                             AD.DayStatus, CS.Code ShiftCode,  CONVERT(VARCHAR(5), AD.InTime, 108) InTime, ARIN.DeviceID InDeviceID, CONVERT(VARCHAR(5), AD.OutTime, 108) OutTime,
                                            AROUT.DeviceID OutDeviceID,  LT.UserName LvShortName
											,AD.WorkDate, DD.UserName GivenDesignation
                                    FROM dbo.EmployeeInformation E
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = e.BudgetCode
                            LEFT JOIN ORG.Position P ON MB.PositionId=P.Id
                            LEFT JOIN ORG.Entity EN ON MB.EntityId=EN.Id
                                                INNER JOIN AttdnProcessFinalData AD ON E.SystemID = AD.EmpSystemID
                                                LEFT JOIN dbo.AttdnRawData ARIN ON AD.ShiftID = ARIN.RowID

                                                LEFT JOIN HKP.CompliedShift CS ON AD.ShiftID = CS.Id
                                                LEFT JOIN dbo.AttdnRawData AROUT ON AD.ShiftID = AROUT.RowID
                                                LEFT JOIN dbo.LeaveType LT ON AD.ShiftID = LT.Id
                                                LEFT JOIN ORG.Unit U ON EN.UnitID = U.Id
                                                LEFT JOIN ORG.Division Dv ON P.DivisionID = Dv.Id
                                                LEFT JOIN ORG.Department Dp ON P.DepartmentID = Dp.Id
                                                LEFT JOIN ORG.Section S ON P.SectionID = S.Id
                                                LEFT JOIN ORG.SubSection SB ON P.SubSectionID = SB.Id
                                                LEFT JOIN ORG.Line L ON MB.LineID = L.Id
                                                LEFT JOIN HKP.Designation D ON P.DesignationID = D.Id
												LEFT JOIN HKP.Designation DD ON E.GivenDesignationId = DD.Id
LEFT JOIN MST.DesignationMaster dm ON E.GivenDesignationId = dm.DesignationId
                            LEFT JOIN HKP.EmployeeCategory EC ON EC.Id=DM.EmployeeCategoryId
                                    WHERE E.PlantID = '" + objm.PlantId + @"' AND AD.WorkDate BETWEEN '" + objm.FDate + @"' AND '" + objm.TDate + @"' 
                                    AND (E.EmployeeStatus='Active' or E.dos>'" + objm.FDate + @"' or e.dos is null) ";

                if (objm.UnitId != "ALL")
                {
                    strSql = strSql + @" AND EN.UnitID = '" + objm.UnitId + "'";
                }
                if (objm.DepartmentId != "ALL")
                {
                    strSql = strSql + @" AND P.DepartmentID = '" + objm.DepartmentId + "'";
                }
                if (objm.DivisionId != "ALL")
                {
                    strSql = strSql + @" AND P.DivisionID = '" + objm.DivisionId + "'";
                }

                if (objm.SectionId != "ALL")
                {
                    strSql = strSql + @" AND P.SectionID = '" + objm.SectionId + "'";
                }
                if (objm.SubsectionId != "ALL")
                {
                    strSql = strSql + @" AND P.SubSectionID = '" + objm.SubsectionId + "'";
                }
                if (objm.LineId != "ALL")
                {
                    strSql = strSql + @" AND MB.LineID = '" + objm.LineId + "'";
                }
                //if (sSbSeStr != "ALL")
                //{
                //    strSql = strSql + @" AND E.SubSecStrucSystemID = '" + sSbSeStr + "'";
                //}
                if (objm.EmpCat != "ALL")
                {
                    strSql = strSql + @" AND EC.ID = '" + objm.EmpCat + "'";
                }
                if (objm.DesignationGroupId != "ALL")
                {
                    strSql = strSql + @" AND DM.DesignationGroupID = '" + objm.DesignationGroupId + "'";
                }
                if (objm.DesignationId != "ALL")
                {
                    strSql = strSql + @" AND P.DesignationID = '" + objm.DesignationId + "'";
                }

                strSql = strSql + @") A
                         GROUP BY A.EmployeeCode, A.EmployeeName, A.DOJ, A.Designation, A.Unit, A.Division, A.Department,
		                            A.Section, A.SubSection, A.Line, A.PDate, A.DayStatus, A.InTime, A.InDeviceID, A.OutTime,
                                    A.OutDeviceID, A.LvShortName, WorkDate, GivenDesignation, A.EmployeePK,A.ShiftCode 


                            ) TT
	                            DECLARE @sql nvarchar(max),
                                    @col nvarchar(max)

                            SELECT @col = (
                                SELECT DISTINCT ','+QUOTENAME(REPLACE(CONVERT(VARCHAR(11), WorkDate, 113), ' ', '-'))	
                                FROM #tempOT 
                                FOR XML PATH ('')
                            )

                            SELECT @sql = N'
                            (SELECT *
                            FROM #tempOT
                            PIVOT (
                                MAX([ShiftCode]) FOR [WorkDate] IN ('+STUFF(@col,1,1,'')+')
                            ) as pvt)'

