        public void GetOTFinalRpt(string sPlantID, string frmDate, string toDate, string sUnit, string sDevi, string sDept, string sSect, string sSbSe, string sLine, string sEmpC, string sDeGr, string sDesi, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;

            try
            {
                strSql = @"SELECT A.* FROM
                                    (SELECT E.EmployeeCode, E.EmployeeName, REPLACE(CONVERT(VARCHAR(11), E.DOJ, 113), ' ', '-') DOJ,
                                            D.UserName Designation,ISNULL( LG.UserName, '') LegalDG, U.UserName Unit, Dv.UserName Division, Dp.UserName Department,
                                            S.UserName Section, SB.UserName SubSection, L.UserName Line
                                            ,ARIN.WorkDate,ARIN.TotalOTHr, ARIN.NormalOTHr, ARIN.ExtraOTHr,DD.UserName GivenDesignation,hr.OTConsiderOn,E.EmployeeCodeNumeric
                                    FROM dbo.EmployeeInformation E
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = e.BudgetCode
                            LEFT JOIN ORG.Position P ON MB.PositionId=P.Id
                            LEFT JOIN ORG.Entity EN ON MB.EntityId=EN.Id
                                                LEFT JOIN dbo.FinalOT ARIN ON E.SystemId = ARIN.EmpSystemID
                                                LEFT JOIN ORG.Unit U ON EN.UnitID = U.Id
                                                LEFT JOIN ORG.Division Dv ON P.DivisionID = Dv.Id
                                                LEFT JOIN ORG.Department Dp ON P.DepartmentID = Dp.Id
                                                LEFT JOIN ORG.Section S ON P.SectionID = S.Id
                                                LEFT JOIN ORG.SubSection SB ON P.SubSectionID = SB.Id
                                                LEFT JOIN ORG.Line L ON MB.LineID = L.Id
                                                LEFT JOIN HKP.LegalDesignation D ON E.LegalDesignationId = D.Id
                                                LEFT JOIN HKP.Designation DD ON E.GivenDesignationId = DD.Id
                                                LEFT join PlantWiseHRMSSetting hr on hr.PlantID=e.PlantId
                                                LEFT JOIN HKP.LegalDesignation LG ON LG.Id = E.LegalDesignationId
                                    WHERE E.PlantID = '" + sPlantID + @"' AND ARIN.WorkDate BETWEEN '" + frmDate + @"' AND '" + toDate + @"' AND ARIN.TotalOTHr > 0
AND (E.EmployeeStatus<>'Separated' OR DOS >= '" + frmDate + @"')
";

             

                strSql = strSql + @") A
                        GROUP BY A.EmployeeCode, A.EmployeeName, A.DOJ, A.Designation,A.LegalDG, A.Unit, A.Division, A.Department,
		                            A.Section, A.SubSection, A.Line, A.WorkDate, A.TotalOTHr, A.NormalOTHr, A.ExtraOTHr, A.GivenDesignation,OTConsiderOn,A.EmployeeCodeNumeric
                        ORDER BY A.Unit, A.EmployeeCodeNumeric, A.Section, A.SubSection";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Fu
        public void GetMonthlyLunchOutRpt(string sPlantID, string frmDate, string toDate, string sUnit, string sDevi, string sDept, string sSect, string sSbSe, string sLine, string sEmpC, string sDeGr, string sDesi, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;

            try
            {
                strSql = @"SELECT E.EmployeeCode, E.EmployeeName, REPLACE(CONVERT(VARCHAR(11), E.DOJ, 113), ' ', '-') DOJ,
                                            D.UserName Designation,ISNULL( LG.UserName, '') LegalDG, U.UserName Unit, Dv.UserName Division, Dp.UserName Department,
                                            S.UserName Section, SB.UserName SubSection, L.UserName Line
                                            ,DD.UserName GivenDesignation,hr.OTConsiderOn,ec.UserName EmployeeCategory,
											E.EmployeeCodeNumeric,
											atd.WorkDate ,atd.EmpSystemId
											,[Status]=case
											when infotype = 'LUNCHOUT' and ARIN.InTime is null and ARIN.OutTime is null then 'NOP'
											when infotype = 'LUNCHOUT' and ARIN.InTime is not null and ARIN.OutTime is not null then 'VLD'
											when infotype = 'LUNCHOUT' and ARIN.InTime is null and ARIN.OutTime is not null then 'LO'
											when infotype = 'LUNCHOUT' and ARIN.InTime is not null and ARIN.OutTime is null then 'NOO'
											when infotype = 'LUNCHOUT_OM'  then 'OM'
											else 'OTH'
											end,atd.DayStatus
                                                                        FROM dbo.EmployeeInformation E
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = e.BudgetCode
                            LEFT JOIN ORG.Position P ON MB.PositionId=P.Id
                            LEFT JOIN ORG.Entity EN ON MB.EntityId=EN.Id
                                                LEFT JOIN AttdnProcessData atd ON E.SystemId = atd.EmpSystemID 
                                                LEFT JOIN AttendanceInfoExtra ARIN ON atd.EmpSystemID = ARIN.EmpSystemID and atd.workdate = ARIN.WorkDate and  (ARIN.InfoType in ('LUNCHOUT','LUNCHOUT_OM'))
                                                LEFT JOIN ORG.Unit U ON EN.UnitID = U.Id
                                                LEFT JOIN ORG.Division Dv ON P.DivisionID = Dv.Id
                                                LEFT JOIN ORG.Department Dp ON P.DepartmentID = Dp.Id
                                                LEFT JOIN ORG.Section S ON P.SectionID = S.Id
                                                LEFT JOIN ORG.SubSection SB ON P.SubSectionID = SB.Id
                                                LEFT JOIN ORG.Line L ON MB.LineID = L.Id
                                                LEFT JOIN HKP.LegalDesignation D ON E.LegalDesignationId = D.Id
                                                LEFT JOIN HKP.Designation DD ON E.GivenDesignationId = DD.Id
