                }
                if (sDesi.ToUpper() != "ALL")
                {
                    strSql = strSql + @" AND P.DesignationID = '" + sDesi + "'";
                }

                strSql = strSql + @") A
                        GROUP BY A.EmployeeCode, A.EmployeeName, A.DOJ, A.Designation,A.LegalDesign, A.Unit, A.Division, A.Department,
		                            A.Section, A.SubSection, A.Line, A.WorkDate, A.TotalOTHr, A.NormalOTHr, A.ExtraOTHr, A.GivenDesignation,OTConsiderOn
                        ORDER BY A.Unit, A.EmployeeCode, A.Section, A.SubSection";

