        public void GetShortLeaveAvailedDateRange(string sPlantID, string FromDate, string ToDate, string IncludingFromTime, string IncludingToTime, string ExcludingFromTime, string ExcludingToTime, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSQL = string.Empty;
            try
            {
                strSQL = @"SELECT EmployeeCode, EmployeeName, DOJ, Unit, Division, Department, Section, SubSection, Designation,
	                               EmpCategoryName, REPLACE(CONVERT(VARCHAR(11), SlvDate, 113), ' ', '-') AS SlvDate, OutTime, InTime, ReqInterval, Availed
                            FROM (";

                if (IncludingFromTime.Trim() != "" & IncludingToTime.Trim() != "" & ExcludingFromTime.Trim() != "" & ExcludingToTime.Trim() != "")
                {
                    strSQL = strSQL + @"
                            SELECT SLV.SystemID, E.EmployeeCode,
                                  E.EmployeeName, REPLACE(CONVERT(VARCHAR(11), E.DOJ, 113), ' ', '-') AS DOJ,
	                              U.UnitName AS Unit, Dv.DivisionName AS Division, De.DepartmentName AS Department, Se.SectionName AS Section,
                                  SuS.SubSectionName SubSection, Dsg.DesignationName AS Designation, EC.EmpCategoryName,
                                  SLV.SlvDate, CONVERT(Varchar(5), SLV.OutTime, 108) AS OutTime, CONVERT(Varchar(5), SLV.InTime, 108) AS InTime,
                                  ISNULL(SLV.TimeDuration,0) AS ReqInterval, ISNULL(DATEDIFF(MI, SLV.OutTime, SLV.InTime),0) AS Availed
                            FROM dbo.EmployeeInformation E
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = e.BudgetCode
                            LEFT JOIN ORG.Position P ON MB.PositionId=P.Id
                            LEFT JOIN ORG.Entity EN ON MB.EntityId=EN.Id
			                            INNER JOIN ShortLeaveAllocation AS SLV ON E.SystemID = SLV.EmpSystemID AND SLV.PlantID = '" + sPlantID + @"'
			                            LEFT OUTER JOIN
							                        Gender AS G ON E.GenderID  = G.SystemID
				                       
				                        LEFT OUTER JOIN
							                        Unit AS U ON U.SystemID = EN.UnitID
				                        LEFT OUTER JOIN
							                        Division AS Dv ON Dv.SystemID = P.DivisionID
				                        LEFT OUTER JOIN
							                        Department AS De ON De.SystemID = P.DepartmentID
				                        LEFT OUTER JOIN
							                        Designation AS Dsg ON Dsg.SystemID = P.DesignationID
				                        LEFT OUTER JOIN
							                        Section AS Se ON Se.SystemID = P.SectionID
				                        LEFT OUTER JOIN
							                        SubSection AS SuS ON SuS.SystemID = P.SubSectionID
LEFT JOIN MST.DesignationMaster dm ON E.GivenDesignationId = dm.DesignationId
                            LEFT JOIN HKP.EmployeeCategory EC ON EC.Id=DM.EmployeeCategoryId
                            WHERE ((SLV.OutTime IS NOT NULL) OR (SLV.InTime IS NOT NULL) OR (SLV.IsHalfDayLeave = 1))
                                    AND SLV.SlvDate BETWEEN '" + FromDate + @"' AND '" + ToDate + @"'
                                    AND ((CONVERT(VARCHAR(5), SLV.OutTime, 108) BETWEEN '" + IncludingFromTime + @"' AND '" + IncludingToTime + @"')
                                    OR (CONVERT(VARCHAR(8), SLV.InTime, 108) BETWEEN '" + IncludingFromTime + @"' AND '" + IncludingToTime + @"'))
                                    AND SLV.SystemID NOT IN (
															 SELECT SystemID FROM ShortLeaveAllocation
															  WHERE SLV.SlvDate BETWEEN '" + FromDate + @"' AND '" + ToDate + @"'
																	AND CONVERT(VARCHAR(8), SLV.OutTime, 108) BETWEEN '" + ExcludingFromTime + @"' AND '" + ExcludingToTime + @"'
															)
                          ";
                }
                else if (IncludingFromTime.Trim() != "" & IncludingToTime.Trim() != "" & ExcludingFromTime.Trim() == "" & ExcludingToTime.Trim() == "")
                {
                    strSQL = strSQL + @"
                            SELECT SLV.SystemID, E.EmployeeCode,
                                  E.EmployeeName, REPLACE(CONVERT(VARCHAR(11), E.DOJ, 113), ' ', '-') AS DOJ,
	                              U.UnitName AS Unit, Dv.DivisionName AS Division, De.DepartmentName AS Department, Se.SectionName AS Section,
                                  SuS.SubSectionName SubSection, Dsg.DesignationName AS Designation, EC.EmpCategoryName,
                                  SLV.SlvDate, CONVERT(Varchar(5), SLV.OutTime, 108) AS OutTime, CONVERT(Varchar(5), SLV.InTime, 108) AS InTime,
                                  ISNULL(SLV.TimeDuration,0) AS ReqInterval, ISNULL(DATEDIFF(MI, SLV.OutTime, SLV.InTime),0) AS Availed
                            FROM dbo.EmployeeInformation E
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = e.BudgetCode
                            LEFT JOIN ORG.Position P ON MB.PositionId=P.Id
                            LEFT JOIN ORG.Entity EN ON MB.EntityId=EN.Id
			                            INNER JOIN ShortLeaveAllocation AS SLV ON E.SystemID = SLV.EmpSystemID AND SLV.PlantID = '" + sPlantID + @"'
			                            LEFT OUTER JOIN
							                        Gender AS G ON E.GenderID  = G.SystemID
				                       
				                        LEFT OUTER JOIN
							                        Unit AS U ON U.SystemID = EN.UnitID
				                        LEFT OUTER JOIN
							                        Division AS Dv ON Dv.SystemID = P.DivisionID
				                        LEFT OUTER JOIN
							                        Department AS De ON De.SystemID = P.DepartmentID
				                        LEFT OUTER JOIN
							                        Designation AS Dsg ON Dsg.SystemID = P.DesignationID
				                        LEFT OUTER JOIN
							                        Section AS Se ON Se.SystemID = P.SectionID
				                        LEFT OUTER JOIN
							                        SubSection AS SuS ON SuS.SystemID = P.SubSectionID
LEFT JOIN MST.DesignationMaster dm ON E.GivenDesignationId = dm.DesignationId
                            LEFT JOIN HKP.EmployeeCategory EC ON EC.Id=DM.EmployeeCategoryId
                            WHERE ((SLV.OutTime IS NOT NULL) OR (SLV.InTime IS NOT NULL) OR (SLV.IsHalfDayLeave = 1))
                                    AND SLV.SlvDate BETWEEN '" + FromDate + @"' AND '" + ToDate + @"'
                                    AND ((CONVERT(VARCHAR(5), SLV.OutTime, 108) BETWEEN '" + IncludingFromTime + @"' AND '" + IncludingToTime + @"')
                                    OR (CONVERT(VARCHAR(8), SLV.InTime, 108) BETWEEN '" + IncludingFromTime + @"' AND '" + IncludingToTime + @"'))
                          ";
                }
                else if (IncludingFromTime.Trim() == "" & IncludingToTime.Trim() == "" & ExcludingFromTime.Trim() != "" & ExcludingToTime.Trim() != "")
                {
                    strSQL = strSQL + @"
                            SELECT SLV.SystemID, E.EmployeeCode,
                                  E.EmployeeName, REPLACE(CONVERT(VARCHAR(11), E.DOJ, 113), ' ', '-') AS DOJ,
	                              U.UnitName AS Unit, Dv.DivisionName AS Division, De.DepartmentName AS Department, Se.SectionName AS Section,
                                  SuS.SubSectionName SubSection, Dsg.DesignationName AS Designation, EC.EmpCategoryName,
                                  SLV.SlvDate, CONVERT(Varchar(5), SLV.OutTime, 108) AS OutTime, CONVERT(Varchar(5), SLV.InTime, 108) AS InTime,
                                  ISNULL(SLV.TimeDuration,0) AS ReqInterval, ISNULL(DATEDIFF(MI, SLV.OutTime, SLV.InTime),0) AS Availed
                            FROM dbo.EmployeeInformation E
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = e.BudgetCode
                            LEFT JOIN ORG.Position P ON MB.PositionId=P.Id
                            LEFT JOIN ORG.Entity EN ON MB.EntityId=EN.Id
			                            INNER JOIN ShortLeaveAllocation AS SLV ON E.SystemID = SLV.EmpSystemID AND SLV.PlantID = '" + sPlantID + @"'
			                            LEFT OUTER JOIN
							                        Gender AS G ON E.GenderID  = G.SystemID
				                        
				                        LEFT OUTER JOIN
							                        Unit AS U ON U.SystemID = EN.UnitID
				                        LEFT OUTER JOIN
							                        Division AS Dv ON Dv.SystemID = P.DivisionID
				                        LEFT OUTER JOIN
							                        Department AS De ON De.SystemID = P.DepartmentID
				                        LEFT OUTER JOIN
							                        Designation AS Dsg ON Dsg.SystemID = P.DesignationID
				                        LEFT OUTER JOIN
							                        Section AS Se ON Se.SystemID = P.SectionID
				                        LEFT OUTER JOIN
							                        SubSection AS SuS ON SuS.SystemID = P.SubSectionID
LEFT JOIN MST.DesignationMaster dm ON E.GivenDesignationId = dm.DesignationId
                            LEFT JOIN HKP.EmployeeCategory EC ON EC.Id=DM.EmployeeCategoryId
                            WHERE ((SLV.OutTime IS NOT NULL) OR (SLV.InTime IS NOT NULL) OR (SLV.IsHalfDayLeave = 1))
                                    AND SLV.SlvDate BETWEEN '" + FromDate + @"' AND '" + ToDate + @"'
                                    AND SLV.SystemID NOT IN (
															 SELECT SystemID FROM ShortLeaveAllocation
															  WHERE SLV.SlvDate BETWEEN '" + FromDate + @"' AND '" + ToDate + @"'
																	AND CONVERT(VARCHAR(8), SLV.OutTime, 108) BETWEEN '" + ExcludingFromTime + @"' AND '" + ExcludingToTime + @"'
															)
                          ";
                }
                else
                {
                    strSQL = strSQL + @"
                            SELECT SLV.SystemID, E.EmployeeCode,
                                  E.EmployeeName, REPLACE(CONVERT(VARCHAR(11), E.DOJ, 113), ' ', '-') AS DOJ,
	                              U.UnitName AS Unit, Dv.DivisionName AS Division, De.DepartmentName AS Department, Se.SectionName AS Section,
                                  SuS.SubSectionName SubSection, Dsg.DesignationName AS Designation, EC.EmpCategoryName,
                                  SLV.SlvDate, CONVERT(Varchar(5), SLV.OutTime, 108) AS OutTime, CONVERT(Varchar(5), SLV.InTime, 108) AS InTime,
                                  ISNULL(SLV.TimeDuration,0) AS ReqInterval, ISNULL(DATEDIFF(MI, SLV.OutTime, SLV.InTime),0) AS Availed
                            FROM dbo.EmployeeInformation E
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = e.BudgetCode
                            LEFT JOIN ORG.Position P ON MB.PositionId=P.Id
                            LEFT JOIN ORG.Entity EN ON MB.EntityId=EN.Id
			                            INNER JOIN ShortLeaveAllocation AS SLV ON E.SystemID = SLV.EmpSystemID AND SLV.PlantID = '" + sPlantID + @"'
			                            LEFT OUTER JOIN
							                        Gender AS G ON E.GenderID  = G.SystemID
				                       
				                        LEFT OUTER JOIN
							                        Unit AS U ON U.SystemID = EN.UnitID
				                        LEFT OUTER JOIN
							                        Division AS Dv ON Dv.SystemID = P.DivisionID
				                        LEFT OUTER JOIN
							                        Department AS De ON De.SystemID = P.DepartmentID
				                        LEFT OUTER JOIN
							                        Designation AS Dsg ON Dsg.SystemID = P.DesignationID
				                        LEFT OUTER JOIN
							                        Section AS Se ON Se.SystemID = P.SectionID
				                        LEFT OUTER JOIN
							                        SubSection AS SuS ON SuS.SystemID = P.SubSectionID
LEFT JOIN MST.DesignationMaster dm ON E.GivenDesignationId = dm.DesignationId
                            LEFT JOIN HKP.EmployeeCategory EC ON EC.Id=DM.EmployeeCategoryId
                            WHERE ((SLV.OutTime IS NOT NULL) OR (SLV.InTime IS NOT NULL) OR (SLV.IsHalfDayLeave = 1))
                                    AND SLV.SlvDate BETWEEN '" + FromDate + @"' AND '" + ToDate + @"'
                          ";
                }

                strSQL = strSQL + @" ) A
							GROUP BY EmployeeCode, EmployeeName, DOJ, Unit, Division, Department, Section, SubSection, Designation,
									 EmpCategoryName, SlvDate, OutTime, InTime, ReqInterval, Availed
                            ORDER BY A.SlvDate, EmployeeCode, OutTime, InTime";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function

        public void GetShortLeaveNotAvailedDateRange(string sPlantID, string FromDate, string ToDate, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSQL = string.Empty;
            try
            {
                strSQL = @"SELECT E.EmployeeCode, E.EmployeeName, REPLACE(CONVERT(VARCHAR(11), E.DOJ, 113), ' ', '-') AS DOJ,
                                U.FactoryUnitDesc Unit, Dv.DivisionName Division, Dpt.DepartmentDesc Department,
                                S.SectionName Section, SS.SubSection, Desg.DesignationDesc Designation,
                                CONVERT(VARCHAR(11), SLV.SlvDate, 113) AS ReqDate, ISNULL(SLV.TimeDuration,0) AS ReqInterval
                            FROM dbo.EmployeeInformation E
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = e.BudgetCode
                            LEFT JOIN ORG.Position P ON MB.PositionId=P.Id
                            LEFT JOIN ORG.Entity EN ON MB.EntityId=EN.Id
                                INNER JOIN ShortLeaveAllocation AS SLV ON E.SystemID = SLV.EmpSystemID
								                                AND SLV.PlantID = '" + sPlantID + @"'
                                LEFT JOIN Unit U ON EN.UnitID = U.SystemID
                                LEFT JOIN Division Dv ON P.DivisionID = Dv.SystemID
                                LEFT JOIN Department Dpt ON P.DepartmentID = Dpt.SystemID
                                LEFT JOIN Section S ON P.SectionID = S.SystemID
                                LEFT JOIN SubSection SS ON P.SubSectionID = SS.SystemID
                                LEFT JOIN Designation Desg ON P.DesignationID = Desg.SystemID
                             WHERE ((SLV.OutTime IS Null) AND (SLV.InTime IS Null) AND (SLV.IsHalfDayLeave = 0))
							                                AND SLV.SlvDate Between '" + FromDate + @"' AND '" + ToDate + @"'
                             ORDER BY SLV.SlvDate, E.EmployeeCodeNumeric";

