        public void xGetSalaryInfoSlrProcIDWise(string strSlrProcID, string sPlantID, string strStatus, string sEmpSysID, out DataSet dsRef)
        {
            string strSQL;
            ConnectionManager.DAL.ConManager objCon;
            try
            {
                strSQL = @"SELECT EmpSlr.EmpInfoSystemID, EmpBasic.EmployeeCode, EmpBasic.EmployeeName, Replace(Convert(varchar(11),EmpBasic.DOJ,106),' ','-') DOJ,
                                EmpBasic.EmployeeStatus, EmpBasic.UnitID, EmpBasic.UnitName, EmpBasic.DivisionID, EmpBasic.DivisionName,
                                EmpBasic.DepartmentID, EmpBasic.DepartmentName, EmpBasic.SectionID, EmpBasic.SectionName, EmpBasic.SubSectionID,
                                EmpBasic.SubSectionName, EmpBasic.EmployeeCategorySystemID, EmpBasic.EmpCategoryName, EmpBasic.DesignationGroupName,
                                EmpBasic.DesignationSystemID, EmpBasic.DesignationName,EmpBasic.GivenDesignationName,EmpBasic.GivenDesignationGroup, EmpBasic.PlantName,
								--EmpBasic.BankName,
                                --EmpBasic.BankNameFull, EmpBasic.BankAccNo,
                                '' BankName, '' BankNameFull, '' BankAccNo,
								(ISNULL(MMDSA.TotalPresent, 0) + ISNULL(MMDSA.TotalLate, 0)) PresentDays,
								ISNULL(MMDSA.AbsentDays, 0) AbsentDays, ISNULL(MMDSA.TotalHoliDay, 0) HoliDay, ISNULL(MMDSA.TotalWeekOff, 0) WeekOff,
								(ISNULL(MMDSA.TotalLv, 0) + ISNULL(MMDSA.TotalMLv, 0)) LeaveDays, EmpSlr.SlrProcChdSysID, EmpSlr.SlrProcMstSystemID, EmpSlr.SalaryProcID,
                                EmpSlr.PlantID, EmpSlr.FromDate, EmpSlr.ToDate, EmpSlr.MonthNo, EmpSlr.YearNo, EmpSlr.PayAbleShSystemID,
                                EmpSlr.SalaryHeadID, EmpSlr.EntryCurrencyID, EmpSlr.EntryAmount, EmpSlr.DefineCurrencyID, EmpSlr.DefineAmount,
                                EmpSlr.DisbusmentCurrencyID, EmpSlr.DisbusmentAmount, EmpSlr.AcltExcDisbSlrHDID, EmpSlr.AcltExcDisbSlrHDAmt,
                                EmpSlr.PlantWiseExchangeCR, EmpSlr.ExchangeRate, EmpSlr.AmtDefinitionCurrencyID, EmpSlr.AmtDefinitionCurrency,
                                EmpSlr.AmtDefinitionCurrencyRate, EmpSlr.IsNetPayEffect
                                ,EmpSlr.SalaryHead,EmpSlr.HeadCategory,EmpSlr.HeadType,EmpSlr.Sequence,IsCTCComponent,IsGrossComponent

                               

                            FROM
                                    (
									 SELECT E.SystemID, E.EmployeeCode, E.EmployeeName, E.DOJ, E.EmployeeStatus,
											DG.UserName DesignationGroupName, E.DesignationSystemID, DE.UserName DesignationName,GVDE.UserName GivenDesignationName,
											'' UserGroupSystemID, E.PlantID, F.UserName PlantName, E.UnitID,
											FU.UserName UnitName, E.DivisionID, DV.UserName DivisionName, E.DepartmentID, DP.UserName DepartmentName,
											E.SectionID, S.UserName SectionName, E.SubSectionID, SS.UserName SubSectionName, E.EmployeeCategorySystemID,
											EC.UserName EmpCategoryName--, BK.BankNameShort BankName, BK.BankNameFull, E.BankAccNo
                                            ,egdsgg.GivenDesignationGroup
                                     FROM EmployeeInformation E
												LEFT JOIN org.Plant F ON E.PlantID = F.Id
												LEFT JOIN hkp.DesignationGroup DG ON E.DesignationGroupId = DG.ID
												LEFT JOIN hkp.Designation DE ON E.GivenDesignationId = DE.Id
												LEFT JOIN hkp.Designation GVDE ON E.GivenDesignationId = GVDE.Id
												LEFT JOIN org.Unit FU ON E.UnitID = FU.Id
												LEFT JOIN org.Division DV ON E.DivisionID = DV.Id
												LEFT JOIN org.Department DP ON E.DepartmentID = DP.Id
												LEFT JOIN org.Section S ON E.SectionID = S.Id
												LEFT JOIN org.SubSection SS ON E.SubSectionID = SS.Id
												LEFT JOIN
                                                --hkp.EmployeeCategory EC ON E.EmployeeCategorySystemID = EC.Id
                                                (
                                                SELECT ECT.Id, ECT.UserName, DM.DesignationId FROM [HKP].[EmployeeCategory] ECT
												LEFT JOIN MST.DesignationMaster DM ON ECT.Id=DM.EmployeeCategoryId
												)EC ON EC.DesignationId=E.GivenDesignationId
												LEFT JOIN (SELECT dm.DesignationGroupId,dm.DesignationId,dm.EmployeeCategoryId
									            ,dg.UserName GivenDesignationGroup
									            FROM MST.DesignationMaster dm
									            LEFT JOIN HKP.DesignationGroup dg on dg.Id=dm.DesignationGroupId
									            ) egdsgg on egdsgg.DesignationId=e.GivenDesignationId
									            and egdsgg.EmployeeCategoryId=e.EmployeeCategorySystemID

									) EmpBasic
                                    INNER JOIN
											(
											 SELECT SPC.SystemID AS SlrProcChdSysID, SPC.SlrProcMstSystemID, SPM.SalaryProcID, SPM.FromDate, SPM.ToDate,
													SPC.EmpInfoSystemID, SPC.PlantID, SPM.UserGroupSystemID, SPM.MonthNo, SPM.YearNo, SPC.PayAbleShSystemID,
													SPC.SalaryHeadID, SPC.EntryCurrencyID, SPC.EntryAmount, SPC.DefineCurrencyID, SPC.DefineAmount,
													SPC.DisbusmentCurrencyID, SPC.DisbusmentAmount, SPC.AcltExcDisbSlrHDID, SPC.AcltExcDisbSlrHDAmt,
													CRE.Name AS PlantWiseExchangeCR, EXR.ToCurrencyBuying ExchangeRate, SPM.AmtDefinitionCurrencyID,
													CR.Name AS AmtDefinitionCurrency, SPM.AmtDefinitionCurrencyRate, SPC.IsNetPayEffect
                                                    ,sh.SalaryHead,sh.HeadCategory,sh.HeadType,isnull(psh.Sequence, 99) Sequence
                                                    ,sh.IsCTCComponent,sh.IsGrossComponent
											 FROM SalaryProcChild SPC
														INNER JOIN SalaryProcMaster SPM ON SPC.SlrProcMstSystemID = SPM.SystemID
																							AND SPM.SalaryProcID = '" + strSlrProcID + @"'

                                                        LEFT JOIN SalaryHead sh on sh.SalaryHeadID=spc.SalaryHeadID
														LEFT JOIN (select * from [MST].[PlantSalaryHeadSequence] where PlantId='" + sPlantID + @"' ) psh
																		on psh.SalaryHeadId=spc.SalaryHeadID

														LEFT JOIN scs.Currency CR ON SPM.AmtDefinitionCurrencyID = CR.Id
														LEFT JOIN (
																   SELECT * FROM ExchangerateDateWiseForHR
																   WHERE FromDate IN (
																					  SELECT MAX(FromDate) FromDate FROM ExchangerateDateWiseForHR
																						WHERE FromDate <= (
																										   SELECT MAX(FromDate) FromDate FROM SalaryProcMaster
																											WHERE SalaryProcID = '" + strSlrProcID + @"'
                                                                                                                  AND SystemID IN (
																																   SELECT SlrProcMstSystemID FROM SalaryProcChild
                                                                                                                                    WHERE PlantID = '" + sPlantID + @"'
                                                                                                                                  )
                                                                                                           )
                                                                                    )
																  ) EXR ON SPM.AmtDefinitionCurrencyID = EXR.FromCurrencyCode
																							AND SPC.PlantID = Exr.PlantID
														LEFT JOIN scs.Currency CRE ON EXR.FromCurrencyCode = CRE.Id
											) EmpSlr ON EmpBasic.SystemID = EmpSlr.EmpInfoSystemID AND EmpBasic.PlantID = EmpSlr.PlantID
                               

                                       
                                    LEFT JOIN
		                                    (
											 SELECT EmpSystemID, MonthNo, YearNo, TotalProcDate, TotalPresent, TotalLate,
													TotalAbsent AbsentDays, TotalLv, TotalMLv, TotalCompAssignLv, TotalWeekOff, TotalHoliDay,
													TotalWeekOffHoliDay, TotalOTHr, TotalNormalOTHr, TotalExtraOTHr
				                              FROM AttdnDataMonthlySummary
											) MMDSA ON EmpSlr.EmpInfoSystemID = MMDSA.EmpSystemID AND EmpSlr.MonthNo = MMDSA.MonthNo AND
						                               EmpSlr.YearNo = MMDSA.YearNo";

                if (sPlantID != "ALL")
                {
                    strSQL = strSQL + @" WHERE EmpBasic.PlantID = '" + sPlantID + @"'";
                }

                if (sEmpSysID != "")
                {
                    strSQL = strSQL + @" AND EmpSlr.EmpInfoSystemID IN (" + sEmpSysID + @")";
                }
                if (strStatus != "ALL")
                {
                    strSQL = strSQL + @" AND EmpBasic.EmployeeStatus = '" + strStatus + @"'";
                }

                strSQL = strSQL + @" ORDER BY EmpBasic.PlantID, EmpBasic.EmployeeCode, EmpSlr.EmpInfoSystemID, EmpSlr.SalaryHeadID";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function
        public void GetSalaryInfoSlrProcIDWiseSheet(ParamList para, out DataSet dsRef)
        {
            string strSQL;
            ConnectionManager.DAL.ConManager objCon;


            try
            {
                strSQL = @"SELECT EmpSlr.EmpInfoSystemID,convert(int, EmpBasic.EmployeeCode)EmployeeCode, EmpBasic.EmployeeName, Replace(Convert(varchar(11),EmpBasic.DOJ,106),' ','-') DOJ
                                , REPLACE(Convert(VARCHAR(11), EmpBasic.DOB, 106), ' ', '-') AS DOB,REPLACE(Convert(VARCHAR(11), EmpBasic.DOS, 106), ' ', '-') AS DOS,
                                EmpBasic.EmployeeStatus, EmpBasic.UnitID, EmpBasic.UnitName, EmpBasic.DivisionID, EmpBasic.DivisionName,
                                EmpBasic.DepartmentID, EmpBasic.DepartmentName, EmpBasic.SectionID, EmpBasic.SectionName, EmpBasic.SubSectionID,
                                EmpBasic.SubSectionName, EmpBasic.EmployeeCategorySystemID, EmpBasic.EmpCategoryName, EmpBasic.DesignationGroupName,
                                EmpBasic.DesignationSystemID, EmpBasic.DesignationName,EmpBasic.GivenDesignationName,EmpBasic.GivenDesignationGroup, EmpBasic.PlantName
							
                                ,esic.ESICNo,pf.UANNo,bb.BankAccNo,bb.BankName, '' BankNameFull,ISNULL(MMDSA.TotalLate, 0) TotalLate
								,(ISNULL(MMDSA.TotalPresent, 0) + ISNULL(MMDSA.TotalLate, 0)) PresentDays,PaymentMode,
								ISNULL(MMDSA.AbsentDays, 0) AbsentDays,  ISNULL(MMDSA.TotalHoliDay + MMDSA.TotalWeekOffHoliDay,0) HoliDay, ISNULL(MMDSA.TotalWeekOff, 0) WeekOff,
								(ISNULL(MMDSA.TotalLv, 0) + ISNULL(MMDSA.TotalMLv, 0)) LeaveDays,ISNULL(MMDSA.TotalLWP,0) LWP, EmpSlr.SlrProcChdSysID, EmpSlr.SlrProcMstSystemID, EmpSlr.SalaryProcID,
                                EmpSlr.PlantID, EmpSlr.FromDate, EmpSlr.ToDate, EmpSlr.MonthNo, EmpSlr.YearNo, EmpSlr.PayAbleShSystemID,
                                EmpSlr.SalaryHeadID, EmpSlr.EntryCurrencyID, EmpSlr.EntryAmount, EmpSlr.DefineCurrencyID, EmpSlr.DefineAmount,
                                EmpSlr.DisbusmentCurrencyID, EmpSlr.DisbusmentAmount, EmpSlr.AcltExcDisbSlrHDID, EmpSlr.AcltExcDisbSlrHDAmt,
                                EmpSlr.PlantWiseExchangeCR, EmpSlr.ExchangeRate, EmpSlr.AmtDefinitionCurrencyID, EmpSlr.AmtDefinitionCurrency,
                                EmpSlr.AmtDefinitionCurrencyRate, EmpSlr.IsNetPayEffect
                                ,EmpSlr.SalaryHead,EmpSlr.HeadCategory,EmpSlr.HeadType,EmpSlr.Sequence,EmpSlr.IsCTCComponent,EmpSlr.IsGrossComponent

                                , isnull(vpf.VoluntaryPFValue,0) VoluntaryPFValue
                                , isnull(BonusValue.Bonus,0) Bonus

								, BonusValue.SalaryHead B_SalaryHead
								, BonusValue.SalaryHeadID B_SalaryHeadID
								, BonusValue.IsCTCComponent B_IsCTCComponent
								, BonusValue.IsGrossComponent B_IsGrossComponent
								, BonusValue.HeadType B_HeadType
								--, BonusValue.HeadCategory B_HeadCategory

                                ,VPFhead.HeadCategory xHeadCategory,VPFhead.SalaryHeadID xSalaryHeadID
                                ,VPFhead.SalaryHead xSalaryHead,VPFhead.IsCTCComponent xIsCTCComponent
                                ,VPFhead.IsGrossComponent xIsGrossComponent,VPFhead.HeadType xHeadType
                                ,VPFhead.SalaryRuleMasterSystemID xSalaryRuleMasterSystemID
                                ,MW.Grade,CONVERT(DECIMAL(10, 2), ISNULL(MMDSA.TotalOTHr,0)/60) TotalOTHr
                                ,IntegerInDisb, DecimalNo
                            FROM
                                    (
									 SELECT E.SystemID, convert(int, E.EmployeeCode)EmployeeCode, E.EmployeeName, E.DOJ,E.DOB,E.DOS, E.EmployeeStatus,E.PaymentMode,
											DG.UserName DesignationGroupName, E.DesignationSystemID, DE.UserName DesignationName,GVDE.UserName GivenDesignationName,
											'' UserGroupSystemID, E.PlantID, F.UserName PlantName, E.UnitID,
											FU.UserName UnitName, E.DivisionID, DV.UserName DivisionName, E.DepartmentID, DP.UserName DepartmentName,
											E.SectionID, S.UserName SectionName, E.SubSectionID, SS.UserName SubSectionName, E.EmployeeCategorySystemID,
											EC.UserName EmpCategoryName--, BK.BankNameShort BankName, BK.BankNameFull, E.BankAccNo
                                            ,egdsgg.GivenDesignationGroup,e.SalaryRuleMasterSystemID
                                     FROM EmployeeInformation E
												LEFT JOIN org.Plant F ON E.PlantID = F.Id
												LEFT JOIN hkp.DesignationGroup DG ON E.DesignationGroupId = DG.ID
												LEFT JOIN hkp.Designation DE ON E.GivenDesignationId = DE.Id
												LEFT JOIN hkp.Designation GVDE ON E.GivenDesignationId = GVDE.Id
												LEFT JOIN org.Unit FU ON E.UnitID = FU.Id
												LEFT JOIN org.Division DV ON E.DivisionID = DV.Id
												LEFT JOIN org.Department DP ON E.DepartmentID = DP.Id
												LEFT JOIN org.Section S ON E.SectionID = S.Id
												LEFT JOIN org.SubSection SS ON E.SubSectionID = SS.Id
												LEFT JOIN
                                                --hkp.EmployeeCategory EC ON E.EmployeeCategorySystemID = EC.Id
                                                (
                                                SELECT ECT.Id, ECT.UserName, DM.DesignationId FROM [HKP].[EmployeeCategory] ECT
												LEFT JOIN MST.DesignationMaster DM ON ECT.Id=DM.EmployeeCategoryId
												)EC ON EC.DesignationId=E.GivenDesignationId
												LEFT JOIN (SELECT dm.DesignationGroupId,dm.DesignationId,dm.EmployeeCategoryId
									            ,dg.UserName GivenDesignationGroup
									            FROM MST.DesignationMaster dm
									            LEFT JOIN HKP.DesignationGroup dg on dg.Id=dm.DesignationGroupId
									            ) egdsgg on egdsgg.DesignationId=e.GivenDesignationId
									            and egdsgg.EmployeeCategoryId=e.EmployeeCategorySystemID

									) EmpBasic
                                    INNER JOIN
											(
											 SELECT SPC.SystemID AS SlrProcChdSysID, SPC.SlrProcMstSystemID, SPM.SalaryProcID, SPM.FromDate, SPM.ToDate,
													SPC.EmpInfoSystemID, SPC.PlantID, SPM.UserGroupSystemID, SPM.MonthNo, SPM.YearNo, SPC.PayAbleShSystemID,
													SPC.SalaryHeadID, SPC.EntryCurrencyID, SPC.EntryAmount, SPC.DefineCurrencyID, SPC.DefineAmount,
													SPC.DisbusmentCurrencyID, SPC.DisbusmentAmount, SPC.AcltExcDisbSlrHDID, SPC.AcltExcDisbSlrHDAmt,
													CRE.Name AS PlantWiseExchangeCR, EXR.ToCurrencyBuying ExchangeRate, SPM.AmtDefinitionCurrencyID,
													CR.Name AS AmtDefinitionCurrency, SPM.AmtDefinitionCurrencyRate, SPC.IsNetPayEffect
                                                    ,sh.SalaryHead,sh.HeadCategory,sh.HeadType,isnull(psh.Sequence, 99) Sequence
                                                    ,sh.IsCTCComponent,sh.IsGrossComponent
											 FROM SalaryProcChild SPC
														INNER JOIN SalaryProcMaster SPM ON SPC.SlrProcMstSystemID = SPM.SystemID
																							AND SPM.SalaryProcID = '" + para.SalaryProcessId + @"'

                                                        LEFT JOIN SalaryHead sh on sh.SalaryHeadID=spc.SalaryHeadID
														LEFT JOIN (select * from [MST].[PlantSalaryHeadSequence] where PlantId='" + para.PlantId + @"' ) psh
																		on psh.SalaryHeadId=spc.SalaryHeadID

														LEFT JOIN scs.Currency CR ON SPM.AmtDefinitionCurrencyID = CR.Id
														LEFT JOIN (
																   SELECT * FROM ExchangerateDateWiseForHR
																   WHERE FromDate IN (
																					  SELECT MAX(FromDate) FromDate FROM ExchangerateDateWiseForHR
																						WHERE FromDate <= (
																										   SELECT MAX(FromDate) FromDate FROM SalaryProcMaster
																											WHERE SalaryProcID = '" + para.SalaryProcessId + @"'
                                                                                                                  AND SystemID IN (
																																   SELECT SlrProcMstSystemID FROM SalaryProcChild
                                                                                                                                    WHERE PlantID = '" + para.PlantId + @"'
                                                                                                                                  )
                                                                                                           )
                                                                                    )
																  ) EXR ON SPM.AmtDefinitionCurrencyID = EXR.FromCurrencyCode
																							AND SPC.PlantID = Exr.PlantID
														LEFT JOIN scs.Currency CRE ON EXR.FromCurrencyCode = CRE.Id
											) EmpSlr ON EmpBasic.SystemID = EmpSlr.EmpInfoSystemID AND EmpBasic.PlantID = EmpSlr.PlantID
                                left join (
										
												  select EmpSystemId,MAX(EffectiveDate) EffectiveDate, VoluntaryPFValue from [PFEmployeeVoluntaryValue] 
												  Where EffectiveDate<='" + para.FromDate + @"'
												  Group By EmpSystemId,EffectiveDate,VoluntaryPFValue
										) VPF on EmpBasic.SystemId=vpf.EmpSystemId

										left join(
										SELECT SH.HeadCategory ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
										,SH.IsGrossComponent,SH.HeadType,sr.SalaryRuleMasterSystemID
											  FROM [dbo].[SalaryRulePF] SR
											  left join SalaryHead SH ON SH.SalaryHeadID=SR.SalaryHeadID
											  where SH.HeadCategory='PF Voluntary'
										) VPFhead on VPFhead.SalaryRuleMasterSystemID=EmpBasic.SalaryRuleMasterSystemID

                                        left join
										(
										select m.EmpSystemID,m.MonthNo,d.Value Bonus 
												--,SH.HeadCategory 
                                                ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
												,SH.IsGrossComponent,SH.HeadType
												from [BonusPolicyMonthlyRetainEmpWiseCalculation] m
												left join [BonusPolicyMonthlyRetainDistributionPmt] d on m.id=d.BnsPlyMntRetainID
												left join SalaryHead SH ON SH.SalaryHeadID=d.SalaryHeadID
												where m.MonthNo=DATEPART(Month,'" + para.FromDate + @"')  AND m.YearNo=DATEPART(YEAR,'" + para.FromDate + @"')  
                                                --and d.SalaryHeadID=(select SalaryHeadID from SalaryHead where HeadCategory='Festival Bonus')
										) BonusValue on EmpBasic.SystemId=BonusValue.EmpSystemID

                                    LEFT JOIN
		                                    (
											 SELECT EmpSystemID, MonthNo, YearNo, TotalProcDate, TotalPresent, TotalLate,
													TotalAbsent AbsentDays, TotalLv,TotalLWP, TotalMLv, TotalCompAssignLv, TotalWeekOff, TotalHoliDay,
													TotalWeekOffHoliDay, TotalOTHr, TotalNormalOTHr, TotalExtraOTHr
				                              FROM SalaryProceAttdnData
											) MMDSA ON EmpSlr.EmpInfoSystemID = MMDSA.EmpSystemID AND EmpSlr.MonthNo = MMDSA.MonthNo AND
						                               EmpSlr.YearNo = MMDSA.YearNo

                                    LEFT JOIN 
                                           		(
                                           		 SELECT E.SystemID, SUM(SV.SalaryHeadValue) SalaryHeadValue,LSG.UserName Grade
                                           			FROM EmployeeInformation E   
                                           					LEFT JOIN MST.ManpowerBudget b ON e.BudgetCode = b.Id
                                           					LEFT JOIN MST.LegalSalaryGradeDesignation GD ON GD.LegalDesignationId = E.LegalDesignationId 
                                                                                               AND E.PlantId = gd.PlantId
                                           					LEFT JOIN (
                                           								SELECT MAX(EffectiveDate)EffectiveDate, LegalSalaryGradeId, EmployeeLocationId 
                                           									FROM MST.LegalSalaryStructure 
                                           									WHERE EffectiveDate <= GETDATE()
                                           								GROUP BY LegalSalaryGradeId, EmployeeLocationId 
                                           							  ) S ON S.LegalSalaryGradeId = GD.LegalSalaryGradeId AND S.EmployeeLocationId = B.EmployeeLocationId
                                           					LEFT JOIN MST.LegalSalaryStructure SS ON SS.LegalSalaryGradeId = S.LegalSalaryGradeId 
                                                                                           AND SS.EmployeeLocationId = S.EmployeeLocationId 
                                                                                           AND SS.EffectiveDate = S.EffectiveDate
                                           					LEFT JOIN MST.LegalSalaryStructureValue SV ON SV.LegalSalaryStructureId = SS.Id 																							
                                           					left join  [SCS].[LegalSalaryGrade] LSG ON LSG.Id=S.LegalSalaryGradeId
                                           			GROUP BY E.SystemId,LSG.UserName 
                                           		) MW ON MW.SystemId = EmpBasic.SystemId

                                                left join (
                                                select bb.UserName BankName,b.BankAccNo,b.EmpSystemID from [dbo].[EmployeeBankInfo] b
                                                left join hkp.BankBranch bb on b.BankBranchId=bb.Id
                                                ) BB ON BB.EmpSystemID = EmpBasic.SystemId

                                                left join
												( select ed.DocNumber UANNo,ED.EmpSystemID from 
												EmployeeDocument ED 
												inner JOIN (select * from HKP.ComplianceDocument where ProfileType = 'PF') CD ON CD.Id = ED.ComplianceDocumentId 
												) pf on EmpBasic.SystemId = pf.EmpSystemID

												left join
												( select ed.DocNumber ESICNo,ED.EmpSystemID from 
												EmployeeDocument ED 
												inner JOIN (select * from HKP.ComplianceDocument where ProfileType = 'ESIC') CD ON CD.Id = ED.ComplianceDocumentId 
												) esic on EmpBasic.SystemId = esic.EmpSystemID
                                                        ";

                if (para.PlantId != "ALL")
                {
                    strSQL = strSQL + @" WHERE EmpBasic.PlantID = '" + para.PlantId + @"'";
                }


                if (para.EmployeeId != "")
                {
                    strSQL = strSQL + @" AND EmpSlr.EmpInfoSystemID IN (" + para.EmployeeId + @")";
                }
                if (para.EmpStatus != "ALL")
                {
                    strSQL = strSQL + @" AND EmpBasic.EmployeeStatus = '" + para.EmpStatus + @"'";
                }

                strSQL = strSQL + @" ORDER BY EmpBasic.PlantID, EmpBasic.EmployeeCode, EmpSlr.EmpInfoSystemID, EmpSlr.SalaryHeadID";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function
        public void GetSalaryInfoSlrProcIDWise(ParamList para, out DataSet dsRef)
        {
            string strSQL;
            ConnectionManager.DAL.ConManager objCon;


            //var _wcp = string.Empty;
            //if (para.PayGroup != "" && para.PayGroup != "ALL" )
            //{
            //    _wcp = " PayrollGroupId IN (" + para.PayGroup + @")";
            //}
            //else
            //{
            //    _wcp = "";
            //}

            try
            {
                strSQL = @"SELECT EmpSlr.EmpInfoSystemID,convert(int, EmpBasic.EmployeeCode)EmployeeCode, EmpBasic.EmployeeName, Replace(Convert(varchar(11),EmpBasic.DOJ,106),' ','-') DOJ
                                , REPLACE(Convert(VARCHAR(11), EmpBasic.DOB, 106), ' ', '-') AS DOB,REPLACE(Convert(VARCHAR(11), EmpBasic.DOS, 106), ' ', '-') AS DOS,
                                EmpBasic.EmployeeStatus, EmpBasic.UnitID, EmpBasic.UnitName, EmpBasic.DivisionID, EmpBasic.DivisionName,
                                EmpBasic.DepartmentID, EmpBasic.DepartmentName, EmpBasic.SectionID, EmpBasic.SectionName, EmpBasic.SubSectionID,
                                EmpBasic.SubSectionName, EmpBasic.EmployeeCategorySystemID, EmpBasic.EmpCategoryName, EmpBasic.DesignationGroupName,
                                EmpBasic.DesignationSystemID, EmpBasic.DesignationName,EmpBasic.GivenDesignationName,EmpBasic.GivenDesignationGroup, EmpBasic.PlantName
							
                                ,esic.ESICNo,pf.UANNo,bb.BankAccNo,bb.BankName, '' BankNameFull,ISNULL(MMDSA.TotalProcDate,0) TotalProcDate,ISNULL(MMDSA.TotalLate, 0) TotalLate
								,(ISNULL(MMDSA.TotalPresent, 0) + ISNULL(MMDSA.TotalLate, 0)) PresentDays,PaymentMode,
								ISNULL(MMDSA.AbsentDays, 0) AbsentDays,  ISNULL(MMDSA.TotalHoliDay + MMDSA.TotalWeekOffHoliDay,0) HoliDay, ISNULL(MMDSA.TotalWeekOff, 0) WeekOff,
								(ISNULL(MMDSA.TotalLv, 0) + ISNULL(MMDSA.TotalMLv, 0)) LeaveDays,ISNULL(MMDSA.TotalLWP,0) LWP, EmpSlr.SlrProcChdSysID, EmpSlr.SlrProcMstSystemID, EmpSlr.SalaryProcID,
                                EmpSlr.PlantID, EmpSlr.FromDate, EmpSlr.ToDate, EmpSlr.MonthNo, EmpSlr.YearNo, EmpSlr.PayAbleShSystemID,
                                EmpSlr.SalaryHeadID, EmpSlr.EntryCurrencyID, EmpSlr.EntryAmount, EmpSlr.DefineCurrencyID, EmpSlr.DefineAmount,
                                EmpSlr.DisbusmentCurrencyID, EmpSlr.DisbusmentAmount, EmpSlr.AcltExcDisbSlrHDID, EmpSlr.AcltExcDisbSlrHDAmt,
                                EmpSlr.PlantWiseExchangeCR, EmpSlr.ExchangeRate, EmpSlr.AmtDefinitionCurrencyID, EmpSlr.AmtDefinitionCurrency,
                                EmpSlr.AmtDefinitionCurrencyRate, EmpSlr.IsNetPayEffect
                                ,EmpSlr.SalaryHead,EmpSlr.HeadCategory,EmpSlr.HeadType,EmpSlr.Sequence,EmpSlr.IsCTCComponent,EmpSlr.IsGrossComponent

                                , isnull(vpf.VoluntaryPFValue,0) VoluntaryPFValue
                                , isnull(BonusValue.Bonus,0) Bonus

								, BonusValue.SalaryHead B_SalaryHead
								, BonusValue.SalaryHeadID B_SalaryHeadID
								, BonusValue.IsCTCComponent B_IsCTCComponent
								, BonusValue.IsGrossComponent B_IsGrossComponent
								, BonusValue.HeadType B_HeadType
								--, BonusValue.HeadCategory B_HeadCategory

                                ,VPFhead.HeadCategory xHeadCategory,VPFhead.SalaryHeadID xSalaryHeadID
                                ,VPFhead.SalaryHead xSalaryHead,VPFhead.IsCTCComponent xIsCTCComponent
                                ,VPFhead.IsGrossComponent xIsGrossComponent,VPFhead.HeadType xHeadType
                                ,VPFhead.SalaryRuleMasterSystemID xSalaryRuleMasterSystemID
                                ---,VPFhead.IntegerInDisb, VPFhead.DecimalNo,
                                ,MW.Grade,CONVERT(DECIMAL(10, 2), ISNULL(MMDSA.TotalOTHr,0)/60) TotalOTHr
                                ,EmpSlr.DecimalNo AS DecimalNo ,EmpSlr.IntegerInDisb AS IntegerInDisb,EmpSlr.IsDecimalInDisb AS IsDecimalInDisb
                                ,EmpBasic.Line,EmpBasic.LegalDesignation
                            FROM
                                    (
									 SELECT E.SystemID, convert(int, E.EmployeeCode)EmployeeCode, E.EmployeeName, E.DOJ,E.DOB,E.DOS, E.EmployeeStatus,E.PaymentMode,
											DG.UserName DesignationGroupName, E.DesignationSystemID, DE.UserName DesignationName,GVDE.UserName GivenDesignationName,
											'' UserGroupSystemID, E.PlantID, F.UserName PlantName, E.UnitID,
											FU.UserName UnitName, E.DivisionID, DV.UserName DivisionName, E.DepartmentID, DP.UserName DepartmentName,
											E.SectionID, S.UserName SectionName, E.SubSectionID, SS.UserName SubSectionName, E.EmployeeCategorySystemID,
											EC.UserName EmpCategoryName--, BK.BankNameShort BankName, BK.BankNameFull, E.BankAccNo
                                            ,egdsgg.GivenDesignationGroup,e.SalaryRuleMasterSystemID,L.UserName Line, LD.UserName LegalDesignation
                                     FROM EmployeeInformation E
												LEFT JOIN org.Plant F ON E.PlantID = F.Id
												LEFT JOIN hkp.DesignationGroup DG ON E.DesignationGroupId = DG.ID
												LEFT JOIN hkp.Designation DE ON E.GivenDesignationId = DE.Id
												LEFT JOIN hkp.Designation GVDE ON E.GivenDesignationId = GVDE.Id
												LEFT JOIN org.Unit FU ON E.UnitID = FU.Id
												LEFT JOIN org.Division DV ON E.DivisionID = DV.Id
												LEFT JOIN org.Department DP ON E.DepartmentID = DP.Id
												LEFT JOIN org.Section S ON E.SectionID = S.Id
												LEFT JOIN org.SubSection SS ON E.SubSectionID = SS.Id
                                                LEFT JOIN org.Line L ON L.Id = E.LineId
												LEFT JOIN HKP.LegalDesignation LD ON LD.Id=E.LegalDesignationId
												LEFT JOIN
                                                --hkp.EmployeeCategory EC ON E.EmployeeCategorySystemID = EC.Id
                                                (
                                                SELECT ECT.Id, ECT.UserName, DM.DesignationId FROM [HKP].[EmployeeCategory] ECT
												LEFT JOIN MST.DesignationMaster DM ON ECT.Id=DM.EmployeeCategoryId
												)EC ON EC.DesignationId=E.GivenDesignationId
												LEFT JOIN (SELECT dm.DesignationGroupId,dm.DesignationId,dm.EmployeeCategoryId
									            ,dg.UserName GivenDesignationGroup
									            FROM MST.DesignationMaster dm
									            LEFT JOIN HKP.DesignationGroup dg on dg.Id=dm.DesignationGroupId
									            ) egdsgg on egdsgg.DesignationId=e.GivenDesignationId
									            and egdsgg.EmployeeCategoryId=e.EmployeeCategorySystemID

									) EmpBasic
                                    INNER JOIN
											(
											 SELECT SPC.SystemID AS SlrProcChdSysID, SPC.SlrProcMstSystemID, SPM.SalaryProcID, SPM.FromDate, SPM.ToDate,
													SPC.EmpInfoSystemID, SPC.PlantID, SPM.UserGroupSystemID, SPM.MonthNo, SPM.YearNo, SPC.PayAbleShSystemID,
													SPC.SalaryHeadID, SPC.EntryCurrencyID, SPC.EntryAmount, SPC.DefineCurrencyID, SPC.DefineAmount,
													SPC.DisbusmentCurrencyID, SPC.DisbusmentAmount, SPC.AcltExcDisbSlrHDID, SPC.AcltExcDisbSlrHDAmt,
													CRE.Name AS PlantWiseExchangeCR, EXR.ToCurrencyBuying ExchangeRate, SPM.AmtDefinitionCurrencyID,
													CR.Name AS AmtDefinitionCurrency, SPM.AmtDefinitionCurrencyRate, SPC.IsNetPayEffect
                                                    ,sh.SalaryHead,sh.HeadCategory,sh.HeadType,isnull(psh.Sequence, 99) Sequence
                                                    ,sh.IsCTCComponent,sh.IsGrossComponent,dcm.DecimalNo,dcm.IntegerInDisb,dcm.IsDecimalInDisb
											 FROM SalaryProcChild SPC
														INNER JOIN SalaryProcMaster SPM ON SPC.SlrProcMstSystemID = SPM.SystemID
																							AND SPM.SalaryProcID = '" + para.SalaryProcessId + @"'

                                                        LEFT JOIN SalaryHead sh on sh.SalaryHeadID=spc.SalaryHeadID
														LEFT JOIN (select * from [MST].[PlantSalaryHeadSequence] where PlantId='" + para.PlantId + @"' ) psh
																		on psh.SalaryHeadId=spc.SalaryHeadID

														LEFT JOIN scs.Currency CR ON SPM.AmtDefinitionCurrencyID = CR.Id
														LEFT JOIN (
																   SELECT * FROM ExchangerateDateWiseForHR
																   WHERE FromDate IN (
																					  SELECT MAX(FromDate) FromDate FROM ExchangerateDateWiseForHR
																						WHERE FromDate <= (
																										   SELECT MAX(FromDate) FromDate FROM SalaryProcMaster
																											WHERE SalaryProcID = '" + para.SalaryProcessId + @"'
                                                                                                                  AND SystemID IN (
																																   SELECT SlrProcMstSystemID FROM SalaryProcChild
                                                                                                                                    WHERE PlantID = '" + para.PlantId + @"'
                                                                                                                                  )
                                                                                                           )
                                                                                    )
																  ) EXR ON SPM.AmtDefinitionCurrencyID = EXR.FromCurrencyCode
																							AND SPC.PlantID = Exr.PlantID
														LEFT JOIN scs.Currency CRE ON EXR.FromCurrencyCode = CRE.Id
                                                  ------    for decimal part       ---------
														 LEFT JOIN
                                               ( SELECT ssm.EmpInfoSystemID,crc.SalaryHeadID,crc.DecimalNo,crc.IntegerInDisb,crc.IsDecimalInDisb
												FROM SalaryInfoDefineMaster ssm
												left join SalaryRuleMaster srm on srm.SystemID=ssm.SalaryRuleMasterSystemID
												left join CurrencyRuleMaster crm on crm.SystemID=srm.CurrencyRuleSystemID
												left join CurrencyRuleChild crc on crc.MstSystemID=crm.SystemID) dcm on  dcm.SalaryHeadID=SPC.SalaryHeadID  and SPC.EmpInfoSystemID=dcm.EmpInfoSystemID
												      -------   end decimal part-------
											) EmpSlr ON EmpBasic.SystemID = EmpSlr.EmpInfoSystemID AND EmpBasic.PlantID = EmpSlr.PlantID
                                left join (
										
												  select EmpSystemId,MAX(EffectiveDate) EffectiveDate, VoluntaryPFValue from [PFEmployeeVoluntaryValue] 
												  Where EffectiveDate<='" + para.FromDate + @"'
												  Group By EmpSystemId,EffectiveDate,VoluntaryPFValue
										) VPF on EmpBasic.SystemId=vpf.EmpSystemId

										left join(
										SELECT SH.HeadCategory ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
										,SH.IsGrossComponent,SH.HeadType,sr.SalaryRuleMasterSystemID
											  FROM [dbo].[SalaryRulePF] SR
											  left join SalaryHead SH ON SH.SalaryHeadID=SR.SalaryHeadID
											  where SH.HeadCategory='PF Voluntary'
										) VPFhead on VPFhead.SalaryRuleMasterSystemID=EmpBasic.SalaryRuleMasterSystemID

                                        left join
										(
										select m.EmpSystemID,m.MonthNo,d.Value Bonus 
												--,SH.HeadCategory 
                                                ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
												,SH.IsGrossComponent,SH.HeadType
												from [BonusPolicyMonthlyRetainEmpWiseCalculation] m
												left join [BonusPolicyMonthlyRetainDistributionPmt] d on m.id=d.BnsPlyMntRetainID
												left join SalaryHead SH ON SH.SalaryHeadID=d.SalaryHeadID
												where m.MonthNo=DATEPART(Month,'" + para.FromDate + @"')  AND m.YearNo=DATEPART(YEAR,'" + para.FromDate + @"')  
                                                --and d.SalaryHeadID=(select SalaryHeadID from SalaryHead where HeadCategory='Festival Bonus')
										) BonusValue on EmpBasic.SystemId=BonusValue.EmpSystemID

                                    LEFT JOIN
		                                    (
											 SELECT EmpSystemID, MonthNo, YearNo, TotalProcDate, TotalPresent, TotalLate,
													TotalAbsent AbsentDays, TotalLv,TotalLWP, TotalMLv, TotalCompAssignLv, TotalWeekOff, TotalHoliDay,
													TotalWeekOffHoliDay, TotalOTHr, TotalNormalOTHr, TotalExtraOTHr
				                              FROM SalaryProceAttdnData
											) MMDSA ON EmpSlr.EmpInfoSystemID = MMDSA.EmpSystemID AND EmpSlr.MonthNo = MMDSA.MonthNo AND
						                               EmpSlr.YearNo = MMDSA.YearNo

                                    LEFT JOIN 
                                           		(
                                           		 SELECT E.SystemID, SUM(SV.SalaryHeadValue) SalaryHeadValue,LSG.UserName Grade
                                           			FROM EmployeeInformation E   
                                           					LEFT JOIN MST.ManpowerBudget b ON e.BudgetCode = b.Id
                                           					LEFT JOIN MST.LegalSalaryGradeDesignation GD ON GD.LegalDesignationId = E.LegalDesignationId 
                                                                                               AND E.PlantId = gd.PlantId
                                           					LEFT JOIN (
                                           								SELECT MAX(EffectiveDate)EffectiveDate, LegalSalaryGradeId, EmployeeLocationId 
                                           									FROM MST.LegalSalaryStructure 
                                           									WHERE EffectiveDate <= GETDATE()
                                           								GROUP BY LegalSalaryGradeId, EmployeeLocationId 
                                           							  ) S ON S.LegalSalaryGradeId = GD.LegalSalaryGradeId AND S.EmployeeLocationId = B.EmployeeLocationId
                                           					LEFT JOIN MST.LegalSalaryStructure SS ON SS.LegalSalaryGradeId = S.LegalSalaryGradeId 
                                                                                           AND SS.EmployeeLocationId = S.EmployeeLocationId 
                                                                                           AND SS.EffectiveDate = S.EffectiveDate
                                           					LEFT JOIN MST.LegalSalaryStructureValue SV ON SV.LegalSalaryStructureId = SS.Id 																							
                                           					left join  [SCS].[LegalSalaryGrade] LSG ON LSG.Id=S.LegalSalaryGradeId
                                           			GROUP BY E.SystemId,LSG.UserName 
                                           		) MW ON MW.SystemId = EmpBasic.SystemId

                                                left join (
                                                select bb.UserName BankName,b.BankAccNo,b.EmpSystemID from [dbo].[EmployeeBankInfo] b
                                                left join hkp.BankBranch bb on b.BankBranchId=bb.Id
                                                ) BB ON BB.EmpSystemID = EmpBasic.SystemId

                                                left join
												( select ed.DocNumber UANNo,ED.EmpSystemID from 
												EmployeeDocument ED 
												inner JOIN (select * from HKP.ComplianceDocument where ProfileType = 'PF') CD ON CD.Id = ED.ComplianceDocumentId 
												) pf on EmpBasic.SystemId = pf.EmpSystemID

												left join
												( select ed.DocNumber ESICNo,ED.EmpSystemID from 
												EmployeeDocument ED 
												inner JOIN (select * from HKP.ComplianceDocument where ProfileType = 'ESIC') CD ON CD.Id = ED.ComplianceDocumentId 
												) esic on EmpBasic.SystemId = esic.EmpSystemID";

                if (para.PlantId != "ALL")
                {
                    strSQL = strSQL + @" WHERE EmpBasic.PlantID = '" + para.PlantId + @"' AND (DOS IS NULL OR DOS>'" + para.FromDate + @"' OR EmployeeStatus='Active')
                                              AND (DOJ IS NULL OR DOJ<= '" + para.ToDate + @"')";
                }
                if (para.DepartmentId != "ALL" && para.DepartmentId != null)
                {
                    strSQL = strSQL + @" AND EmpBasic.DepartmentID = '" + para.DepartmentId + @"'";
                }

                if (para.EmployeeId != "")
                {
                    strSQL = strSQL + @" AND EmpSlr.EmpInfoSystemID IN (" + para.EmployeeId + @")";
                }
                #region--Pay Group--
                else
                {

                    if (para.PayGroup.ToUpper() != "NO GROUP")
                    {
                        strSQL = strSQL + @" AND EmpInfoSystemID  IN (
													 select employeeid from MST.PayrollGroupMaster where PayrollGroupId = '" + para.PayGroup + @"')";
                    }
                    if (para.PayGroup.ToUpper() == "NO GROUP")
                    {
                        strSQL = strSQL + @" AND EmpSlr.EmpInfoSystemID NOT IN (
													 select employeeid from MST.PayrollGroupMaster)";
                    }
                }
                #endregion--Pay Group--
                if (para.EmpStatus != "ALL")
                {
                    strSQL = strSQL + @" AND EmpBasic.EmployeeStatus = '" + para.EmpStatus + @"'";
                }



                strSQL = strSQL + @" ORDER BY EmpBasic.PlantID, EmpBasic.EmployeeCode, EmpSlr.EmpInfoSystemID, EmpSlr.SalaryHeadID";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function
        public void GetGrade(Dictionary<string, string> parameters, string sMth, string sYr, out DataSet dsRef)
        {
            string strSQL;
            ConnectionManager.DAL.ConManager objCon;
            var _wc = string.Empty;

            //    if (empid != "")
            //    {
            //        _wc = "  e.systemid IN (" + empid + @")";
            //    }
            //    else
            //    {
            //        if (pPayGrp.ToUpper() != "NO GROUP")
            //        {
            //            _wc = @" E.SystemId  IN (
            //select employeeid from MST.PayrollGroupMaster where PayrollGroupId = '" + pPayGrp + @"'
            //					 )";
            //        }
            //        if (pPayGrp.ToUpper() == "NO GROUP")
            //        {
            //            _wc = @" E.SystemId NOT IN (
            //					 select employeeid from MST.PayrollGroupMaster)";
            //        }

            //        //_wc = "  E.SystemId in (select EmployeeId from MST.PayrollGroupMaster where PayrollGroupId ='" + pPayGrp + @"')";
            //    }

            try
            {

                strSQL = @"SELECT E.SystemID, SUM(SV.SalaryHeadValue) SalaryHeadValue,LSG.ShortName Grade
                            FROM EmployeeInformation E   
                                    LEFT JOIN MST.ManpowerBudget b ON e.BudgetCode = b.Id
                                    left Join MST.PayrollGroupMaster PGM on PGM.EmployeeId = E.EmployeeId
                                    LEFT JOIN MST.LegalSalaryGradeDesignation GD ON GD.LegalDesignationId = E.LegalDesignationId 
                                                                        AND E.PlantId = gd.PlantId
                                    LEFT JOIN (
                                           		SELECT MAX(EffectiveDate)EffectiveDate, LegalSalaryGradeId, EmployeeLocationId 
                                           			FROM MST.LegalSalaryStructure 
                                           			WHERE EffectiveDate <= GETDATE()
                                           		GROUP BY LegalSalaryGradeId, EmployeeLocationId 
                                           		) S ON S.LegalSalaryGradeId = GD.LegalSalaryGradeId AND S.EmployeeLocationId = B.EmployeeLocationId
                                    LEFT JOIN MST.LegalSalaryStructure SS ON SS.LegalSalaryGradeId = S.LegalSalaryGradeId 
                                                                    AND SS.EmployeeLocationId = S.EmployeeLocationId 
                                                                    AND SS.EffectiveDate = S.EffectiveDate
                                    LEFT JOIN MST.LegalSalaryStructureValue SV ON SV.LegalSalaryStructureId = SS.Id 																							
                                    LEFT JOIN  [SCS].[LegalSalaryGrade] LSG ON LSG.Id =S.LegalSalaryGradeId 
                                    WHERE MONTH(DOJ) <= '" + sMth + @"' AND Year(DOJ) <= '" + sYr + @"'";

                if (parameters.Count > 0)
                {
                    if (parameters.Keys.ElementAt(0) != "")
                    {
                        //strSQL += @"and E.EmployeeCode IN(" + parameters["EmployeeCode"] + ")";
                        strSQL += @"and E.SystemID IN(" + parameters["EmpSystemId"] + ")";

                    }
                }
                strSQL += @"GROUP BY E.SystemId,LSG.ShortName";

                //if (pPayGrp != "ALL")
                //{
                //    strSQL = strSQL + @" WHERE EmpBasic.PlantID = '" + pPayGrp + @"'";
                //}

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }


        public void GetAdvanceAndTDS(ParamList para, out DataSet dsRef)
        {
            string strSQL;
            ConnectionManager.DAL.ConManager objCon;
            try
            {
                var EmpStatus = "";
                if (para.EmpStatus != "ALL")
                {
                    EmpStatus = @"AND E.EmployeeStatus='" + para.EmpStatus + "'";
                }

                var EmpSysId = "";
                if (!string.IsNullOrEmpty(para.EmployeeId))
                {
                    EmpSysId = @"AND E.SystemId IN(" + para.EmployeeId + ")";
                }

                strSQL = @"SELECT * FROM (SELECT E.SystemId,CONVERT(INT, E.EmployeeCode)EmployeeCode,E.EmployeeName, H.SalaryHead,H.HeadCategory,C.EntryAmount,C.DisbusmentAmount*(-1) DisbusmentAmount
                           ,''Loan,''LoanInt,''Bus,''Mobile FROM SalaryProcMaster S
                           LEFT JOIN SalaryProcChild C ON C.SlrProcMstSystemID=S.SystemID
                           LEFT JOIN EmployeeInformation E ON E.SystemId=C.EmpInfoSystemID
                           LEFT JOIN SalaryHead H ON H.SalaryHeadID=C.SalaryHeadID
                           WHERE E.GroupID='" + para.CompanyGroupId + @"' AND E.CompanyId='" + para.CompanyId + @"' AND S.FromDate between '" + para.FromDate + @"' and '" + para.ToDate + @"'
                           AND H.HeadCategory='Tax'  AND E.PlantId='" + para.PlantId + @"' " + EmpStatus + @" " + EmpSysId + @"
                            Union
                            SELECT E.SystemId,CONVERT(INT, E.EmployeeCode)EmployeeCode,E.EmployeeName, H.SalaryHead,H.HeadCategory,C.EntryAmount,C.DisbusmentAmount*(-1) DisbusmentAmount
                            ,''Loan,''LoanInt,''Bus,''Mobile FROM SalaryProcMaster S
                            LEFT JOIN SalaryProcChild C ON C.SlrProcMstSystemID=S.SystemID
                            LEFT JOIN EmployeeInformation E ON E.SystemId=C.EmpInfoSystemID
                            LEFT JOIN SalaryHead H ON H.SalaryHeadID=C.SalaryHeadID
                            WHERE E.GroupID='" + para.CompanyGroupId + @"' AND E.CompanyId='" + para.CompanyId + @"' AND S.FromDate between '" + para.FromDate + @"' and '" + para.ToDate + @"'
                            AND H.HeadCategory='Advance'  AND E.PlantId='" + para.PlantId + @"' " + EmpStatus + @" " + EmpSysId + @") A ORDER BY A.EmployeeCode
                            ";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

        public void GetBonus(string monthNo, string year, out DataSet dsRef)
        {
            string strSQL;
            ConnectionManager.DAL.ConManager objCon;
            try
            {
                strSQL = @"SELECT M.EmpSystemID, C.SalaryHeadID, C.Value Bonus, M.MonthNo, M.YearNo,sh.HeadCategory,sh.SalaryHead,sh.IsCTCComponent,sh.IsGrossComponent,sh.HeadType,sh.Sequence 
                           FROM BonusPolicyMonthlyRetainEmpWiseCalculation M
                           LEFT JOIN BonusPolicyMonthlyRetainDistributionPmt C ON M.ID = C.BnsPlyMntRetainID
                           LEFT JOIN SalaryHead sh on sh.SalaryHeadID=c.SalaryHeadID
                           WHERE M.MonthNo = '" + monthNo + @"' AND M.YearNo = '" + year + @"'
                           AND C.Value > 0";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

        public void XGetSalaryInfoSlrProcIDWise(ParamList para, out DataSet dsRef)
        {
            string strSQL;
            ConnectionManager.DAL.ConManager objCon;
            try
            {
                strSQL = @"SELECT EmpSlr.EmpInfoSystemID, EmpBasic.EmployeeCode, EmpBasic.EmployeeName, Replace(Convert(varchar(11),EmpBasic.DOJ,106),' ','-') DOJ,
                                EmpBasic.EmployeeStatus, EmpBasic.UnitID, EmpBasic.UnitName, EmpBasic.DivisionID, EmpBasic.DivisionName,
                                EmpBasic.DepartmentID, EmpBasic.DepartmentName, EmpBasic.SectionID, EmpBasic.SectionName, EmpBasic.SubSectionID,
                                EmpBasic.SubSectionName, EmpBasic.EmployeeCategorySystemID, EmpBasic.EmpCategoryName, EmpBasic.DesignationGroupName,
                                EmpBasic.DesignationSystemID, EmpBasic.DesignationName,EmpBasic.GivenDesignationName,EmpBasic.GivenDesignationGroup, EmpBasic.PlantName,
                                '' BankName, '' BankNameFull, '' BankAccNo,
								(ISNULL(MMDSA.TotalPresent, 0) + ISNULL(MMDSA.TotalLate, 0)) PresentDays,
								ISNULL(MMDSA.AbsentDays, 0) AbsentDays, ISNULL(MMDSA.TotalHoliDay, 0) HoliDay, ISNULL(MMDSA.TotalWeekOff, 0) WeekOff,
								(ISNULL(MMDSA.TotalLv, 0) + ISNULL(MMDSA.TotalMLv, 0)) LeaveDays, EmpSlr.SlrProcChdSysID, EmpSlr.SlrProcMstSystemID, EmpSlr.SalaryProcID,
                                EmpSlr.PlantID, EmpSlr.FromDate, EmpSlr.ToDate, EmpSlr.MonthNo, EmpSlr.YearNo, EmpSlr.PayAbleShSystemID,
                                EmpSlr.SalaryHeadID, EmpSlr.EntryCurrencyID, EmpSlr.EntryAmount, EmpSlr.DefineCurrencyID, EmpSlr.DefineAmount,
                                EmpSlr.DisbusmentCurrencyID, EmpSlr.DisbusmentAmount, EmpSlr.AcltExcDisbSlrHDID, EmpSlr.AcltExcDisbSlrHDAmt,
                                EmpSlr.PlantWiseExchangeCR, EmpSlr.ExchangeRate, EmpSlr.AmtDefinitionCurrencyID, EmpSlr.AmtDefinitionCurrency,
                                EmpSlr.AmtDefinitionCurrencyRate, EmpSlr.IsNetPayEffect,EmpSlr.SalaryHead, EmpSlr.HeadCategory, EmpSlr.HeadType, 
                                EmpSlr.Sequence, EmpSlr.IsCTCComponent, EmpSlr.IsGrossComponent, ISNULL(VPF.VoluntaryPFValue,0) VoluntaryPFValue
                                
                                ,VPFhead.HeadCategory xHeadCategory,VPFhead.SalaryHeadID xSalaryHeadID
                                ,VPFhead.SalaryHead xSalaryHead,VPFhead.IsCTCComponent xIsCTCComponent
                                ,VPFhead.IsGrossComponent xIsGrossComponent,VPFhead.HeadType xHeadType
                                ,VPFhead.SalaryRuleMasterSystemID xSalaryRuleMasterSystemID

                            FROM
                                    (
									 SELECT E.SystemID, E.EmployeeCode, E.EmployeeName, E.DOJ, E.EmployeeStatus,
											DG.UserName DesignationGroupName, E.DesignationSystemID, DE.UserName DesignationName,GVDE.UserName GivenDesignationName,
											'' UserGroupSystemID, E.PlantID, F.UserName PlantName, E.UnitID,
											FU.UserName UnitName, E.DivisionID, DV.UserName DivisionName, E.DepartmentID, DP.UserName DepartmentName,
											E.SectionID, S.UserName SectionName, E.SubSectionID, SS.UserName SubSectionName, E.EmployeeCategorySystemID,
											EC.UserName EmpCategoryName
                                            ,egdsgg.GivenDesignationGroup,e.SalaryRuleMasterSystemID
                                     FROM EmployeeInformation E
												LEFT JOIN org.Plant F ON E.PlantID = F.Id
												LEFT JOIN hkp.DesignationGroup DG ON E.DesignationGroupId = DG.ID
												LEFT JOIN hkp.Designation DE ON E.GivenDesignationId = DE.Id
												LEFT JOIN hkp.Designation GVDE ON E.GivenDesignationId = GVDE.Id
												LEFT JOIN org.Unit FU ON E.UnitID = FU.Id
												LEFT JOIN org.Division DV ON E.DivisionID = DV.Id
												LEFT JOIN org.Department DP ON E.DepartmentID = DP.Id
												LEFT JOIN org.Section S ON E.SectionID = S.Id
												LEFT JOIN org.SubSection SS ON E.SubSectionID = SS.Id
												LEFT JOIN
                                              
                                                (
                                                SELECT ECT.Id, ECT.UserName, DM.DesignationId FROM [HKP].[EmployeeCategory] ECT
												LEFT JOIN MST.DesignationMaster DM ON ECT.Id=DM.EmployeeCategoryId
												)EC ON EC.DesignationId=E.GivenDesignationId
												LEFT JOIN (SELECT dm.DesignationGroupId,dm.DesignationId,dm.EmployeeCategoryId
									            ,dg.UserName GivenDesignationGroup
									            FROM MST.DesignationMaster dm
									            LEFT JOIN HKP.DesignationGroup dg on dg.Id=dm.DesignationGroupId
									            ) egdsgg on egdsgg.DesignationId=e.GivenDesignationId
									            and egdsgg.EmployeeCategoryId=e.EmployeeCategorySystemID

									) EmpBasic
                                    INNER JOIN
											(
											 SELECT A.SlrProcChdSysID, A.SlrProcMstSystemID, A.SalaryProcID, A.FromDate, A.ToDate,
													A.EmpInfoSystemID, A.PlantID, A.UserGroupSystemID, A.MonthNo, A.YearNo, A.PayAbleShSystemID,
													A.SalaryHeadID, A.EntryCurrencyID, A.EntryAmount, A.DefineCurrencyID, A.DefineAmount,
													A.DisbusmentCurrencyID, A.DisbusmentAmount, A.AcltExcDisbSlrHDID, A.AcltExcDisbSlrHDAmt,
													CRE.Name AS PlantWiseExchangeCR, EXR.ToCurrencyBuying ExchangeRate, A.AmtDefinitionCurrencyID,
													CR.Name AS AmtDefinitionCurrency, A.AmtDefinitionCurrencyRate, A.IsNetPayEffect, SH.SalaryHead, 
                                                    SH.HeadCategory, SH.HeadType, ISNULL(PSH.Sequence, 99) Sequence, SH.IsCTCComponent, SH.IsGrossComponent
                                                    
											 FROM (
											       SELECT * FROM
																(
																  SELECT SPC.SystemID AS SlrProcChdSysID, SPC.SlrProcMstSystemID, SPM.SalaryProcID, SPM.FromDate, SPM.ToDate,
																										SPC.EmpInfoSystemID, SPC.PlantID, SPM.UserGroupSystemID, SPM.MonthNo, SPM.YearNo, SPC.PayAbleShSystemID,
																										SPC.SalaryHeadID, SPC.EntryCurrencyID, SPC.EntryAmount, SPC.DefineCurrencyID, SPC.DefineAmount,
																										SPC.DisbusmentCurrencyID, SPC.DisbusmentAmount, SPC.AcltExcDisbSlrHDID, SPC.AcltExcDisbSlrHDAmt,
																										SPM.AmtDefinitionCurrencyID, SPM.AmtDefinitionCurrencyRate, SPC.IsNetPayEffect
																								 FROM SalaryProcChild SPC
																											INNER JOIN SalaryProcMaster SPM ON SPC.SlrProcMstSystemID = SPM.SystemID
																																				AND SPM.SalaryProcID = '" + para.SalaryProcessId + @"'
																) A
																UNION 
																(
																 SELECT SPC.SystemID AS SlrProcChdSysID, SPC.SlrProcMstSystemID, SPC.SalaryProcID, SPC.FromDate, SPC.ToDate, 
																										M.EmpSystemID EmpInfoSystemID, SPC.PlantID, SPC.UserGroupSystemID, SPC.MonthNo, SPC.YearNo, SPC.PayAbleShSystemID,
																										D.SalaryHeadID, CRC.AmtEntryCurrency EntryCurrencyID, D.Value EntryAmount, CRC.AmtDefinitionCurrency DefineCurrencyID, D.Value DefineAmount, 
																										CRC.AmtDisbusmentCurrency DisbusmentCurrencyID, D.Value DisbusmentAmount, 
																										CRC.AccumulateExchangeSalaryHeadID AcltExcDisbSlrHDID, 0 AcltExcDisbSlrHDAmt, CRC.AmtDefinitionCurrency AmtDefinitionCurrencyID, 
																										1 AmtDefinitionCurrencyRate, 0 IsNetPayEffect
																 FROM [BonusPolicyMonthlyRetainEmpWiseCalculation] M
																			INNER JOIN [BonusPolicyMonthlyRetainDistributionPmt] D ON M.ID = D.BnsPlyMntRetainID
																			INNER JOIN (
																						SELECT SPC.*, SPM.SalaryProcID, SPM.FromDate, SPM.ToDate, SPM.UserGroupSystemID, 
																							   SPM.MonthNo, SPM.YearNo FROM SalaryProcChild SPC
																											INNER JOIN SalaryProcMaster SPM ON SPC.SlrProcMstSystemID = SPM.SystemID
																																				AND SPM.SalaryProcID = '" + para.SalaryProcessId + @"'
																					   ) SPC ON M.EmpSystemID = SPC.EmpInfoSystemID
																			INNER JOIN SalaryInfoDefineMaster MST ON M.EmpSystemID = MST.EmpInfoSystemID AND MST.IsApproved = 1
																			LEFT JOIN SalaryRuleMaster SRM ON SRM.SystemID = MST.SalaryRuleMasterSystemID
																			LEFT JOIN CurrencyRuleChild CRC ON CRC.MstSystemID = SRM.CurrencyRuleSystemID AND CRC.SalaryHeadID = D.SalaryHeadID
																 WHERE EOMONTH(DATEFROMPARTS(M.YearNo, M.MonthNo, 1)) IN (SELECT MAX(EOMONTH(DATEFROMPARTS(YearNo, MonthNo, 1))) 
																															FROM [BonusPolicyMonthlyRetainEmpWiseCalculation] 
																														  WHERE CONVERT(DATE, EOMONTH(DATEFROMPARTS(YearNo, MonthNo, 1))) <= CONVERT(DATE, '" + para.FromDate + @"'))
																)
														) A

                                                        LEFT JOIN SalaryHead sh on sh.SalaryHeadID=A.SalaryHeadID
														LEFT JOIN (select * from [MST].[PlantSalaryHeadSequence] where PlantId='" + para.PlantId + @"' ) psh
																		on psh.SalaryHeadId=A.SalaryHeadID

														LEFT JOIN scs.Currency CR ON A.AmtDefinitionCurrencyID = CR.Id
														LEFT JOIN (
																   SELECT * FROM ExchangerateDateWiseForHR
																   WHERE FromDate IN (
																					  SELECT MAX(FromDate) FromDate FROM ExchangerateDateWiseForHR
																						WHERE FromDate <= (
																										   SELECT MAX(FromDate) FromDate FROM SalaryProcMaster
																											WHERE SalaryProcID = '" + para.SalaryProcessId + @"'
                                                                                                                  AND SystemID IN (
																																   SELECT SlrProcMstSystemID FROM SalaryProcChild
                                                                                                                                    WHERE PlantID = '" + para.PlantId + @"'
                                                                                                                                  )
                                                                                                           )
                                                                                    )
																  ) EXR ON A.AmtDefinitionCurrencyID = EXR.FromCurrencyCode
																							AND A.PlantID = Exr.PlantID
														LEFT JOIN scs.Currency CRE ON EXR.FromCurrencyCode = CRE.Id
											) EmpSlr ON EmpBasic.SystemID = EmpSlr.EmpInfoSystemID AND EmpBasic.PlantID = EmpSlr.PlantID
                                left join (
										
												  select EmpSystemId,MAX(EffectiveDate) EffectiveDate, VoluntaryPFValue from [PFEmployeeVoluntaryValue] 
												  Where EffectiveDate<='" + para.FromDate + @"'
												  Group By EmpSystemId,EffectiveDate,VoluntaryPFValue
										) VPF on EmpBasic.SystemId=vpf.EmpSystemId

										left join(
										SELECT SH.HeadCategory ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
										,SH.IsGrossComponent,SH.HeadType,sr.SalaryRuleMasterSystemID
											  FROM [dbo].[SalaryRulePF] SR
											  left join SalaryHead SH ON SH.SalaryHeadID=SR.SalaryHeadID
											  where SH.HeadCategory='PF Voluntary'
										) VPFhead on VPFhead.SalaryRuleMasterSystemID=EmpBasic.SalaryRuleMasterSystemID

                                    LEFT JOIN
		                                    (
											 SELECT EmpSystemID, MonthNo, YearNo, TotalProcDate, TotalPresent, TotalLate,
													TotalAbsent AbsentDays, TotalLv, TotalMLv, TotalCompAssignLv, TotalWeekOff, TotalHoliDay,
													TotalWeekOffHoliDay, TotalOTHr, TotalNormalOTHr, TotalExtraOTHr
				                              FROM AttdnDataMonthlySummary
											) MMDSA ON EmpSlr.EmpInfoSystemID = MMDSA.EmpSystemID AND EmpSlr.MonthNo = MMDSA.MonthNo AND
						                               EmpSlr.YearNo = MMDSA.YearNo";

                if (para.PlantId != "ALL")
                {
                    strSQL = strSQL + @" WHERE EmpBasic.PlantID = '" + para.PlantId + @"'";
                }

                if (para.EmployeeId != "")
                {
                    strSQL = strSQL + @" AND EmpSlr.EmpInfoSystemID IN (" + para.EmployeeId + @")";
                }
                if (para.EmpStatus != "ALL")
                {
                    strSQL = strSQL + @" AND EmpBasic.EmployeeStatus = '" + para.EmpStatus + @"'";
                }

                strSQL = strSQL + @" ORDER BY EmpBasic.PlantID, EmpBasic.EmployeeCode, EmpSlr.EmpInfoSystemID, EmpSlr.SalaryHeadID";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function

        #region Bonus

        public void GetBonusInfoEffectiveDateWiseAfterProc(string sEffectiveDate, string sPlantID, out DataSet dsRef)
        {
            string strSQL;
            ConnectionManager.DAL.ConManager objCon;
            try
            {
                strSQL = @"SELECT EmpBnsAct.EmpSystemID, EmpBasic.EmployeeCode, EmpBasic.EmployeeName, Replace(Convert(varchar(11),EmpBasic.DOJ,106),' ','-') DOJ,
                                Replace(Convert(varchar(11),EmpBasic.DOC,106),' ','-') DOC, EmpBasic.EmployeeStatus, EmpBasic.UnitID, EmpBasic.UnitName, EmpBasic.DivisionID,
                                EmpBasic.DivisionName, EmpBasic.DepartmentID, EmpBasic.DepartmentName, EmpBasic.SectionID, EmpBasic.SectionName, EmpBasic.SubSectionID,

                                EmpBasic.SubSectionName, EmpBasic.EmployeeCategorySystemID, EmpBasic.EmpCategoryName, EmpBasic.DesignationGroupName,
                                EmpBasic.DesignationSystemID, EmpBasic.DesignationName, EmpBasic.PlantName
								--, EmpBasic.BankName, EmpBasic.BankNameFull,  EmpBasic.BankAccNo
								, EmpBnsAct.PlantID, SH.SalaryHead, EmpBnsAct.SalaryHeadID, EmpBnsAct.SalaryAmount,
								EmpBnsAct.BonusAmount, EmpBnsAct.ServiceLenght
                            FROM
                                (
								  SELECT E.SystemID, E.EmployeeCode, E.EmployeeName, E.DOJ, E.DOC, E.EmployeeStatus,
										DG.UserName DesignationGroupName, E.DesignationSystemID, DE.UserName DesignationName,
										'' UserGroupSystemID, E.PlantID, F.UserName PlantName, E.UnitID,
										FU.UserName UnitName, E.DivisionID, DV.UserName DivisionName, PR.DepartmentID, DP.UserName DepartmentName,
										PR.SectionID, S.UserName SectionName, PR.SubSectionID, SS.UserName SubSectionName,dm.EmployeeCategoryId EmployeeCategorySystemID,
										EC.UserName EmpCategoryName --, BK.BankNameShort BankName, BK.BankNameFull, E.BankAccNo
                                  FROM EmployeeInformation E
											 LEFT JOIN MST.ManpowerBudget PMB ON E.BudgetCode = PMB.Id
								   LEFT JOIN ORG.Position PR ON PMB.PositionId = PR.Id
									LEFT JOIN ORG.Entity En ON PMB.EntityId = En.Id
									LEFT JOIN HKP.LegalDesignation LGD ON LGD.Id = E.LegalDesignationId
                        LEFT join  [MST].[DesignationMasterLegalDesignation] dmld on dmld.LegalDesignationId=LGD.Id
                        left join [MST].[DesignationMaster] dm on dm.Id=dmld.DesignationMasterId

											LEFT JOIN ORG.Plant F ON E.PlantID = F.Id
											LEFT JOIN hkp.DesignationGroup DG ON E.DesignationGroupID = DG.Id
											LEFT JOIN hkp.Designation DE ON E.DesignationSystemID = DE.Id
											LEFT JOIN org.Unit FU ON En.UnitID = FU.Id
											LEFT JOIN org.Division DV ON En.DivisionID = DV.Id
											LEFT JOIN org.Department DP ON PR.DepartmentID = DP.Id
											LEFT JOIN org.Section S ON PR.SectionID = S.Id
											LEFT JOIN org.SubSection SS ON PR.SubSectionID = SS.Id
											LEFT JOIN hkp.EmployeeCategory EC ON dm.EmployeeCategoryId = EC.Id
											--LEFT JOIN BankNameInfo BK ON E.BankSystemID = Bk.SystemID
								) EmpBasic
                                        INNER JOIN
										        (
										        SELECT BPA.*, BPAM.SalaryHeadID, BPAM.PlantID FROM [dbo].[BonusPaymentActual] BPA
										        INNER JOIN BonusPaymentActualMaster BPAM ON BPA.BnsMstSystemID = BPAM.SystemID
										        WHERE EffectiveDate = '" + sEffectiveDate + @"' AND PlantID = '" + sPlantID + @"'
												        AND IsApproved = 0
										        ) EmpBnsAct ON EmpBasic.SystemID = EmpBnsAct.EmpSystemID  AND EmpBasic.PlantID = EmpBnsAct.PlantID
								        LEFT JOIN SalaryHead SH ON EmpBnsAct.SalaryHeadID = SH.SalaryHeadID";

                if (sPlantID != "ALL")
                {
                    strSQL = strSQL + @" WHERE EmpBasic.PlantID = '" + sPlantID + @"'";
                }

                strSQL = strSQL + @"
                                    ORDER BY EmpBasic.PlantID, EmpBasic.EmployeeCode, EmpBnsAct.EmpSystemID, EmpBnsAct.SalaryHeadID";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function

        #endregion Bonus

