        public void GetEmployeesShiftAndEffectiveDate(out Dictionary<string, DataRow> Data)
        {

            DataSet dsRef = new DataSet();
            string strSQL;
            ConnectionManager.DAL.ConManager objCon;
            try
            {
                strSQL = @"SELECT ES.FixSystemID, ES.EmpSystemId, FORMAT(MAX(ES.EffectiveDate),'dd-MMM-yyyy') EffectiveDate, ShiftName = CASE WHEN isnull(ES.FixSystemID, '') = '' THEN B.ShiftDefinationDescription ELSE A.ShiftDefinationDescription END, C.ShiftRosterDescription
	                            FROM EmployeeShiftAssign ES
	                            INNER JOIN (
		                            SELECT EmpSystemID, max(EffectiveDate) EffectiveDate
		                            FROM EmployeeShiftAssign
		                            WHERE EffectiveDate <= FORMAT(GETDATE(), 'dd-MMM-yyyy')
		                            GROUP BY EmpSystemID
		                            ) x ON x.EmpSystemID = es.EmpSystemID AND x.EffectiveDate = es.EffectiveDate
	                            LEFT JOIN [dbo].[ShiftDefination] A ON A.SystemID = ES.FixSystemID
	                            LEFT JOIN [dbo].[ShiftDefination] B ON B.SystemID = ES.RosterStartShiftID
	                            LEFT JOIN [dbo].[ShiftRosterMaster] C ON C.SystemID = ES.RosterSystemID
                                left join EmployeeInformation E on x.EmpSystemID=E.SystemId
	                             WHERE ES.EffectiveDate <= FORMAT(GETDATE(), 'dd-MMM-yyyy') AND e.EmployeeStatus='Active'
	                            GROUP BY FixSystemID, RosterStartShiftID, es.EmpSystemId, ES.FixSystemID, B.ShiftDefinationDescription, A.ShiftDefinationDescription, ShiftRosterDescription";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");

                Data = new Dictionary<string, DataRow>();
                for (int i = 0; i < dsRef.Tables[0].Rows.Count; i++)
                {
