        public void GetSalaryHead(string EmpInfoSystemID, out DataSet dsRef)
        {
            string strSQL;
            ConnectionManager.DAL.ConManager objCon;
            try
            {
                strSQL = @"select h.SalaryHead,d.DefineAmount Amount
                                ,ee.EmployeeName,ee.FirstName,isnull(ee.PresentAddress1,'') Address1
                                ,isnull(ee.PresentAddress2,'') Address2
                                ,j.JobLocation
                                ,Replace(Convert(varchar(11),ee.DOJ,106),' ','-') DOJ
                                , case when isnull(ee.DOCIsDay,0)=1 then isnull(ee.DOCDay,0)
                                else isnull(ee.DOCMonth,0)*30 end ProbationPeriod
                                ,dg.UserName Designation,sl.UserName Salutation
                                ,dept.UserName Department,sr.SalaryHeadID,h.HeadType,sr.IsGNRNetPayEffect
                                ,ct.UserName City,cn.UserName Country,cur.Name Currency,isnull(sq.Sequence,99) Seq
                                from
                               EmployeeInformation ee
                                left outer join (select * from [dbo].[SalaryInfoDefineMaster]
								where EffectiveDate=(select max(effectivedate) med from [dbo].[SalaryInfoDefineMaster] where EmpInfoSystemID in (" + EmpInfoSystemID + @"))
								)m on ee.SystemId=m.EmpInfoSystemID
                                left outer join  [dbo].[SalaryInfoDefine] d on d.SalaryID=m.SystemID
                                left outer join SalaryHead h on h.SalaryHeadID=d.SalaryHeadID

                                left outer join org.Company cc on cc.id=ee.CompanyId
								left outer join scs.Currency cur on cur.id=cc.BaseCurrencyId
                                left outer join scs.City ct on ct.id=ee.PresCityID
								left outer join scs.Country cn on cn.id=ee.PresCountryID
                                left outer join JobLocation j on j.SystemID=ee.JobLocationID
                                left outer join hkp.Designation dg on dg.id=ee.GivenDesignationId
                                left outer join hkp.Salutation sl on sl.id=ee.Salutation
                                left outer join org.Department dept on dept.id=ee.DepartmentId
                                left outer join mst.PlantSalaryHeadSequence sq on sq.SalaryHeadId=h.SalaryHeadID
                                left join (select gg.SalaryHeadID,MM.SystemID,gg.IsGNRNetPayEffect from SalaryRuleMaster mm
														left outer join SalaryRuleGeneral gg on gg.SalaryRuleMasterSystemID=mm.SystemID
												) SR on sr.SystemID=m.SalaryRuleMasterSystemID and sr.SalaryHeadID=d.SalaryHeadID

                                where  ee.SystemID in (" + EmpInfoSystemID + @")
                                --and isnull(d.DefineAmount,0)>0
                                order by HeadType desc
                                ";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function

