        public void GetPFCSV(out DataSet dsRef, int pmonth, string pyear, string salProcId)
        {
            string _date = "01-" + CultureInfo.CurrentCulture.DateTimeFormat.GetAbbreviatedMonthName(pmonth) + "-" + pyear;
            DateTime _lastdate = Convert.ToDateTime(_date).AddMonths(1).AddDays(-1);
            //var days = DateTime.DaysInMonth(Convert.ToInt32(year), monthName);//Number of Days in a month
            //string monthNameString = CultureInfo.CurrentCulture.DateTimeFormat.GetAbbreviatedMonthName(monthName);//Month Name from Month No
            //var date = days + "-" + monthNameString + "-" + year;
            string strSQL;

            ConnectionManager.DAL.ConManager objCon;
            try
            {
                strSQL = @"select ed.DocNumber UANNo
                                --,e.SystemId
                                --,e.EmployeeCode
                                ,e.EmployeeName
                                ,CONVERT(INT,gross.DisbusmentAmount) Gross
                                ,CONVERT(INT,[Basic].DisbusmentAmount) [Basic1]
                                ,CONVERT(INT,[Basic].DisbusmentAmount) [Basic2]
                                , Basic3=case  when [Basic].DisbusmentAmount>15000 then 15000 else CONVERT(INT,[Basic].DisbusmentAmount) end
                                --,[Basic].DisbusmentAmount [Basic32]
                                ,CONVERT(INT,spc.DisbusmentAmount*(-1)) EmployeeContribution
                                  ,CONVERT(INT,ISNULL(pension.DisbusmentAmount,0)) pension
                                ,CONVERT(INT,er.DisbusmentAmount) EmployerContribution
                                --,TotalPresent+TotalLv+TotalMLv+TotalCompAssignLv+TotalWeekOff+TotalHoliDay as PayDays
                               -- ,CONVERT(INT,ISNULL(AbsentDays,0)) PayDays
                                  , AbsentDays = case  when AbsentDays = floor(AbsentDays)
                               then convert(nvarchar,convert(int, AbsentDays)) -- change to int if no decimal part
                                else convert(nvarchar,convert(decimal(10, 1), AbsentDays)) -- else return one decimal
                                end
                                ,0 Advance
                                 FROM EmployeeInformation e 
                                INNER  JOIN EmployeeDocument ED ON E.SystemId = ED.EmpSystemID
                                INNER JOIN HKP.ComplianceDocument CD ON CD.Id = ED.ComplianceDocumentId  AND CD.ProfileType = 'PF'
                                 LEFT JOIN
	                                (
		                                SELECT EmpSystemID, MonthNo, YearNo, TotalProcDate, TotalPresent, TotalLate,
			                                TotalAbsent AbsentDays, TotalLv, TotalMLv, TotalCompAssignLv, TotalWeekOff, TotalHoliDay,
			                                TotalWeekOffHoliDay, TotalOTHr, TotalNormalOTHr, TotalExtraOTHr
		                                FROM AttdnDataMonthlySummary where MonthNo=" + pmonth + @" and YearNo='" + pyear + @"'
	                                ) MMDSA ON e.SystemID = MMDSA.EmpSystemID 
 
  				                                --gross
                                left join (select * from SalaryProcChild where SalaryHeadID in (SELECT SalaryHeadID from SalaryHead where HeadCategory in ('Gross'))
		                                  ) gross  ON gross.EmpInfoSystemID=e.SystemId
                                INNER JOIN (select * FROM SalaryProcMaster WHERE YearNo='" + pyear + @"' and MonthNo=" + pmonth + @" and SalaryProcID='" + salProcId + @"') SPMg on gross.SlrProcMstSystemID = SPMg.SystemID
 				                                --basic
                                left join (select * from SalaryProcChild where SalaryHeadID in (SELECT SalaryHeadID from SalaryHead where HeadCategory in ('Basic'))
		                                  ) Basic  ON Basic.EmpInfoSystemID=e.SystemId
                                INNER JOIN (select * FROM SalaryProcMaster WHERE  YearNo='" + pyear + @"' and MonthNo=" + pmonth + @" and SalaryProcID='" + salProcId + @"') SPMBasic on [Basic].SlrProcMstSystemID = SPMBasic.SystemID
				                                --ee
                                left join (select * from SalaryProcChild where SalaryHeadID in (SELECT SalaryHeadID from SalaryHead where HeadCategory in ('PF Employee Contribution'))
		                                  ) SPC  ON spc.EmpInfoSystemID=e.SystemId
                                INNER JOIN (select * FROM SalaryProcMaster WHERE  YearNo='" + pyear + @"' and MonthNo=" + pmonth + @" and SalaryProcID='" + salProcId + @"') SPMee on SPC.SlrProcMstSystemID = SPMee.SystemID
				                                --er
                                left join (select * from SalaryProcChild where SalaryHeadID in (SELECT SalaryHeadID from SalaryHead where HeadCategory in ('PF Employer Contribution'))
		                                  ) er  ON er.EmpInfoSystemID=e.SystemId
                                INNER JOIN (select * FROM SalaryProcMaster WHERE  YearNo='" + pyear + @"' and MonthNo=" + pmonth + @" and SalaryProcID='" + salProcId + @"') SPMer on er.SlrProcMstSystemID = SPMer.SystemID
				                                --pension
                                    LEFT JOIN (SELECT C.* FROM SalaryProcChild C
								 INNER JOIN (SELECT * FROM SalaryProcMaster WHERE   YearNo='" + pyear + @"' and MonthNo=" + pmonth + @" and SalaryProcID='" + salProcId + @"') SPMpension on C.SlrProcMstSystemID = SPMpension.SystemID
								where C.SalaryHeadID IN (SELECT SalaryHeadID from SalaryHead where HeadCategory in ('Pension'))
		                                  ) pension  ON pension.EmpInfoSystemID=e.SystemId
                               
                                where E.EmployeeStatus = 'Active' AND e.SystemId in 
			                                (
			                                SELECT 
				                                EmpSystemID
			                                FROM [dbo].[PFEligibleEmployee]
			                                where StartDate < '" + _lastdate + @"' and isActive = 1 and IsApproved = 1
			                                )";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//end function
        /// <summary>
        /// Provident Fund Excel Report SQL Query::Applicable in India
        /// </summary>
        /// <param name="dsRef"></param>
        /// <param name="monthName"></param>
        /// <param name="year"></param>
		public void GetPFEmpInfo(string SalaryProcessId, out DataSet dsRef, int monthName, string year)
        {
            string strSQL;
            var days = DateTime.DaysInMonth(Convert.ToInt32(year), monthName);//Number of Days in a month
            string monthNameString = CultureInfo.CurrentCulture.DateTimeFormat.GetAbbreviatedMonthName(monthName);//Month Name from Month No
            var date = days + "-" + monthNameString + "-" + year;


            ConnectionManager.DAL.ConManager objCon;
            try
            {
                strSQL = @"SELECT distinct EmpSlr.EmpInfoSystemID,EmpBasic.EmployeeCode,CONVERT(INT,EmpBasic.EmployeeCode) EmployeeCodes, EmpBasic.EmployeeName,DocNumber,EmpBasic.Age ,
                            REPLACE(Convert(VARCHAR(11), EmpBasic.DOB, 106), ' ', '-') AS DOB,
                            REPLACE(Convert(VARCHAR(11), EmpBasic.DOS, 106), ' ', '-') AS DOS,
                            REPLACE(Convert(VARCHAR(11), EmpBasic.DOJ, 106), ' ', '-') AS DOJ,

                    
								(ISNULL(MMDSA.TotalPresent, 0) + ISNULL(MMDSA.TotalLate, 0)) PresentDays,
								
								ISNULL(MMDSA.TotalHoliDay, 0) HoliDay, ISNULL(MMDSA.TotalWeekOff, 0) WeekOff,
								(ISNULL(MMDSA.TotalLv, 0) + ISNULL(MMDSA.TotalMLv, 0)) LeaveDays,
								(ISNULL(MMDSA.TotalPresent, 0) + ISNULL(MMDSA.TotalLate, 0)+ ISNULL(MMDSA.TotalWeekOff, 0)+ISNULL(MMDSA.TotalHoliDay, 0) + ISNULL(MMDSA.TotalLv, 0) + ISNULL(MMDSA.TotalMLv, 0)) workingDays
                                ,EmpSlr.PlantID, EmpSlr.FromDate, EmpSlr.ToDate, EmpSlr.MonthNo, EmpSlr.YearNo, EmpSlr.PayAbleShSystemID,
                                EmpSlr.SalaryHeadID, EmpSlr.EntryCurrencyID, EmpSlr.EntryAmount, EmpSlr.DefineCurrencyID, EmpSlr.DefineAmount,
                                EmpSlr.DisbusmentCurrencyID, EmpSlr.DisbusmentAmount, EmpSlr.AcltExcDisbSlrHDID, EmpSlr.AcltExcDisbSlrHDAmt,
                                EmpSlr.AmtDefinitionCurrencyID,
                                EmpSlr.AmtDefinitionCurrencyRate, EmpSlr.IsNetPayEffect
                                ,EMPSLR.cat,EmpSlr.SalaryHead,EmpSlr.HeadCategory,EmpSlr.HeadType,IsCTCComponent,IsGrossComponent
                                ,ISNULL(EmpSlr.IntegerInDisb,0) IntegerInDisb,ISNULL(EmpSlr.DecimalNo,0) DecimalNo
                            FROM
                                    (
										 SELECT E.SystemID, E.EmployeeCode, E.EmployeeName,E.DOB, E.DOJ,E.DOS, E.EmployeeStatus,ed.DocNumber,DATEDIFF(YY,E.DOB,'" + date + @"') As Age,
											DG.UserName DesignationGroupName, E.DesignationSystemID, DE.UserName DesignationName,GVDE.UserName GivenDesignationName,
											'' UserGroupSystemID, E.PlantID, F.UserName PlantName, E.UnitID,
											FU.UserName UnitName, E.DivisionID, DV.UserName DivisionName, E.DepartmentID, DP.UserName DepartmentName,
											E.SectionID, S.UserName SectionName, E.SubSectionID, SS.UserName SubSectionName, E.EmployeeCategorySystemID,
											EC.UserName EmpCategoryName--, BK.BankNameShort BankName, BK.BankNameFull, E.BankAccNo
                                            ,egdsgg.GivenDesignationGroup
                                     FROM EmployeeInformation E
												LEFT JOIN org.Plant F ON E.PlantID = F.Id
												LEFT JOIN hkp.DesignationGroup DG ON E.DesignationGroupId = DG.ID
												LEFT JOIN hkp.Designation DE ON E.GivenDesignationId = DE.Id
												LEFT JOIN hkp.Designation GVDE ON E.GivenDesignationId = GVDE.Id
												LEFT JOIN org.Unit FU ON E.UnitID = FU.Id
												LEFT JOIN org.Division DV ON E.DivisionID = DV.Id
												LEFT JOIN org.Department DP ON E.DepartmentID = DP.Id
												LEFT JOIN org.Section S ON E.SectionID = S.Id
												LEFT JOIN org.SubSection SS ON E.SubSectionID = SS.Id
												LEFT JOIN
                                                (
                                                SELECT ECT.Id, ECT.UserName, DM.DesignationId FROM [HKP].[EmployeeCategory] ECT
												LEFT JOIN MST.DesignationMaster DM ON ECT.Id=DM.EmployeeCategoryId
												)EC ON EC.DesignationId=E.GivenDesignationId
												LEFT JOIN (SELECT dm.DesignationGroupId,dm.DesignationId,dm.EmployeeCategoryId
									            ,dg.UserName GivenDesignationGroup
									            FROM MST.DesignationMaster dm
									            LEFT JOIN HKP.DesignationGroup dg ON dg.Id=dm.DesignationGroupId
									            ) egdsgg ON egdsgg.DesignationId=e.GivenDesignationId
									            AND egdsgg.EmployeeCategoryId=e.EmployeeCategorySystemID
												INNER JOIN EmployeeDocument ED ON E.SystemId = ED.EmpSystemID
												INNER JOIN HKP.ComplianceDocument CD ON CD.Id = ED.ComplianceDocumentId  AND CD.ProfileType = 'PF' 
												WHERE E.EmployeeStatus = 'Active'

									) EmpBasic
                                    INNER JOIN
											(
											 SELECT SPC.SystemID AS SlrProcChdSysID, SPC.SlrProcMstSystemID, SPM.SalaryProcID, SPM.FromDate, SPM.ToDate,
													SPC.EmpInfoSystemID, SPC.PlantID, SPM.UserGroupSystemID, SPM.MonthNo, SPM.YearNo, SPC.PayAbleShSystemID,
													SPC.SalaryHeadID, SPC.EntryCurrencyID, SPC.EntryAmount, SPC.DefineCurrencyID, SPC.DefineAmount,
													SPC.DisbusmentCurrencyID, SPC.DisbusmentAmount, SPC.AcltExcDisbSlrHDID, SPC.AcltExcDisbSlrHDAmt,
												    SPM.AmtDefinitionCurrencyID,
													SPM.AmtDefinitionCurrencyRate, SPC.IsNetPayEffect
                                                    ,sh.SalaryHead,sh.HeadCategory,sh.HeadType
                                                    ,sh.IsCTCComponent,sh.IsGrossComponent,sh.Cat
                                                    ,CRC.IntegerInDisb, CRC.DecimalNo
											 FROM SalaryProcChild SPC
														INNER JOIN SalaryProcMaster SPM ON SPC.SlrProcMstSystemID = SPM.SystemID
														 INNER JOIN (--0														
																			(SELECT *,'EE' Cat from SalaryHead where HeadCategory in ('PF Employee Contribution'))
																			UNION
																			(SELECT *,'ER' Cat from SalaryHead where HeadCategory in ('PF Employer Contribution'))
																			UNION
																		    (SELECT *,'B' Cat FROM SalaryHead where HeadCategory in ('Basic'))
																			UNION
																			(SELECT *,'P' Cat FROM SalaryHead where HeadCategory in ('Pension'))
																			UNION
																			(SELECT *,'VPF' Cat  FROM SalaryHead  WHERE HeadCategory in ('PF Voluntary'))
																			
																	)--0 
														SH ON SH.SalaryHeadID=SPC.SalaryHeadID
                                                                    LEFT JOIN SalaryInfoDefineMaster SDM ON SDM.SystemID = SPC.SalaryID
																	LEFT JOIN SalaryRuleMaster SRM ON SRM.SystemID = SDM.SalaryRuleMasterSystemID
																	LEFT JOIN CurrencyRuleMaster CRM ON CRM.SystemID = SRM.CurrencyRuleSystemID
										LEFT JOIN CurrencyRuleChild CRC ON CRC.MstSystemID = srm.CurrencyRuleSystemID AND CRC.SalaryHeadID = SH.SalaryHeadID

															WHERE SPM.SalaryProcID = '" + SalaryProcessId + @"'
											) EmpSlr ON EmpBasic.SystemID = EmpSlr.EmpInfoSystemID AND EmpBasic.PlantID = EmpSlr.PlantID
                                    LEFT JOIN
		                                    (
											 SELECT EmpSystemID, MonthNo, YearNo, TotalProcDate, TotalPresent, TotalLate,
													TotalAbsent AbsentDays, TotalLv, TotalMLv, TotalCompAssignLv, TotalWeekOff, TotalHoliDay,
													TotalWeekOffHoliDay, TotalOTHr, TotalNormalOTHr, TotalExtraOTHr
				                              FROM SalaryProceAttdnData  WHERE MonthNo = MONTH(CONVERT(DATE,'" + date + @"')) AND YearNo = YEAR(CONVERT(DATE,'" + date + @"'))
											) MMDSA ON EmpSlr.EmpInfoSystemID = MMDSA.EmpSystemID 											   
													   WHERE 
														
													EmpSlr.MonthNo = " + monthName + @" AND EmpBasic.SystemId in 
													(
													SELECT 
													  EmpSystemID
												  FROM [dbo].[PFEligibleEmployee]
												  WHERE StartDate < '" + date + @"' AND isActive = 1 and IsApproved = 1
													)                                       
                                                ORDER BY  EmployeeCodes";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//end function

        public void GetESICEmpInfo(out DataSet dsRef, int monthName, string year, string salaryProcessId)
        {
            string strSQL;
            var days = DateTime.DaysInMonth(Convert.ToInt32(year), monthName);//Number of Days in a month
            string monthNameString = CultureInfo.CurrentCulture.DateTimeFormat.GetAbbreviatedMonthName(monthName);//Month Name from Month No
            var date = days + "-" + monthNameString + "-" + year;


            ConnectionManager.DAL.ConManager objCon;
            try
            {
                strSQL = @"SELECT distinct EmpSlr.EmpInfoSystemID, EmpBasic.EmployeeCode,CONVERT(INT,EmpBasic.EmployeeCode) EmployeeCodeS, EmpBasic.EmployeeName,DocNumber,EmpBasic.Age ,
                       
								(ISNULL(MMDSA.TotalPresent, 0) + ISNULL(MMDSA.TotalLate, 0)) PresentDays,
								--ISNULL(MMDSA.AbsentDays, 0) AbsentDays
								ISNULL(MMDSA.TotalHoliDay, 0) HoliDay, ISNULL(MMDSA.TotalWeekOff, 0) WeekOff,
								(ISNULL(MMDSA.TotalLv, 0) + ISNULL(MMDSA.TotalMLv, 0)) LeaveDays,
								(ISNULL(MMDSA.TotalPresent, 0) + ISNULL(MMDSA.TotalLate, 0)+ ISNULL(MMDSA.TotalWeekOff, 0)+ISNULL(MMDSA.TotalHoliDay, 0) + ISNULL(MMDSA.TotalLv, 0) + ISNULL(MMDSA.TotalMLv, 0)) workingDays
								--, EmpSlr.SlrProcChdSysID, EmpSlr.SlrProcMstSystemID, EmpSlr.SalaryProcID,
                                ,EmpSlr.PlantID, EmpSlr.FromDate, EmpSlr.ToDate, EmpSlr.MonthNo, EmpSlr.YearNo, EmpSlr.PayAbleShSystemID,
                                EmpSlr.SalaryHeadID, EmpSlr.EntryCurrencyID, EmpSlr.EntryAmount, EmpSlr.DefineCurrencyID, EmpSlr.DefineAmount,
                                EmpSlr.DisbusmentCurrencyID, EmpSlr.DisbusmentAmount, EmpSlr.AcltExcDisbSlrHDID, EmpSlr.AcltExcDisbSlrHDAmt,
                                EmpSlr.AmtDefinitionCurrencyID,
                                EmpSlr.AmtDefinitionCurrencyRate, EmpSlr.IsNetPayEffect
                                ,empslr.cat,EmpSlr.SalaryHead,EmpSlr.HeadCategory,EmpSlr.HeadType,IsCTCComponent,IsGrossComponent
                                ,ISNULL(empslr.IsDecimalInDisb,0) IsDecimalInDisb,ISNULL(empslr.DecimalNo,0) DecimalNo,ISNULL(empslr.IntegerInDisb,0) IntegerInDisb
                            FROM
                                    (
										 SELECT E.SystemID, E.EmployeeCode, E.EmployeeName, E.DOJ, E.EmployeeStatus,ed.DocNumber,DATEDIFF(YY,E.DOB,'" + date + @"') As Age,
											DG.UserName DesignationGroupName, E.DesignationSystemID, DE.UserName DesignationName,GVDE.UserName GivenDesignationName,
											'' UserGroupSystemID, E.PlantID, F.UserName PlantName, E.UnitID,
											FU.UserName UnitName, E.DivisionID, DV.UserName DivisionName, E.DepartmentID, DP.UserName DepartmentName,
											E.SectionID, S.UserName SectionName, E.SubSectionID, SS.UserName SubSectionName, E.EmployeeCategorySystemID,
											EC.UserName EmpCategoryName--, BK.BankNameShort BankName, BK.BankNameFull, E.BankAccNo
                                            ,egdsgg.GivenDesignationGroup
                                     FROM EmployeeInformation E
												LEFT JOIN org.Plant F ON E.PlantID = F.Id
												LEFT JOIN hkp.DesignationGroup DG ON E.DesignationGroupId = DG.ID
												LEFT JOIN hkp.Designation DE ON E.GivenDesignationId = DE.Id
												LEFT JOIN hkp.Designation GVDE ON E.GivenDesignationId = GVDE.Id
												LEFT JOIN org.Unit FU ON E.UnitID = FU.Id
												LEFT JOIN org.Division DV ON E.DivisionID = DV.Id
												LEFT JOIN org.Department DP ON E.DepartmentID = DP.Id
												LEFT JOIN org.Section S ON E.SectionID = S.Id
												LEFT JOIN org.SubSection SS ON E.SubSectionID = SS.Id
												LEFT JOIN
                                                --hkp.EmployeeCategory EC ON E.EmployeeCategorySystemID = EC.Id
                                                (
                                                SELECT ECT.Id, ECT.UserName, DM.DesignationId FROM [HKP].[EmployeeCategory] ECT
												LEFT JOIN MST.DesignationMaster DM ON ECT.Id=DM.EmployeeCategoryId
												)EC ON EC.DesignationId=E.GivenDesignationId
												LEFT JOIN (SELECT dm.DesignationGroupId,dm.DesignationId,dm.EmployeeCategoryId
									            ,dg.UserName GivenDesignationGroup
									            FROM MST.DesignationMaster dm
									            LEFT JOIN HKP.DesignationGroup dg ON dg.Id=dm.DesignationGroupId
									            ) egdsgg ON egdsgg.DesignationId=e.GivenDesignationId
									            and egdsgg.EmployeeCategoryId=e.EmployeeCategorySystemID
												INNER  JOIN EmployeeDocument ED ON E.SystemId = ED.EmpSystemID
												INNER JOIN HKP.ComplianceDocument CD ON CD.Id = ED.ComplianceDocumentId  AND CD.ProfileType = 'ESIC' 
												where E.EmployeeStatus = 'Active'

									) EmpBasic
                                    INNER JOIN
											(
											 SELECT SPC.SystemID AS SlrProcChdSysID, SPC.SlrProcMstSystemID, SPM.SalaryProcID, SPM.FromDate, SPM.ToDate,
													SPC.EmpInfoSystemID, SPC.PlantID, SPM.UserGroupSystemID, SPM.MonthNo, SPM.YearNo, SPC.PayAbleShSystemID,
													SPC.SalaryHeadID, SPC.EntryCurrencyID, SPC.EntryAmount, SPC.DefineCurrencyID, SPC.DefineAmount,
													SPC.DisbusmentCurrencyID, SPC.DisbusmentAmount, SPC.AcltExcDisbSlrHDID, SPC.AcltExcDisbSlrHDAmt,
												    SPM.AmtDefinitionCurrencyID,
													SPM.AmtDefinitionCurrencyRate, SPC.IsNetPayEffect
                                                    ,sh.SalaryHead,sh.HeadCategory,sh.HeadType
                                                    ,sh.IsCTCComponent,sh.IsGrossComponent,sh.Cat,crc.IsDecimalInDisb,crc.DecimalNo,crc.IntegerInDisb
											 FROM SalaryProcChild SPC
														INNER JOIN SalaryProcMaster SPM ON SPC.SlrProcMstSystemID = SPM.SystemID
																 LEFT JOIN SalaryInfoDefineMaster SIDM on sidm.SystemID =spc.SalaryID
                                                                LEFT JOIN SalaryRuleMaster SRM ON SRM.SystemID = sidm.SalaryRuleMasterSystemID
                                                                LEFT JOIN CurrencyRuleMaster crm on crm.SystemID = sRM.CurrencyRuleSystemID
                                                                LEFT JOIN CurrencyRuleChild crc on crc.MstSystemID = CRM.SystemID						

                                                        INNER JOIN (--Salary Head
                                                                               (SELECT *,'B' Cat FROM SalaryHead where HeadCategory in ('Basic'))
																			    UNION														
																				SELECT *,'ESICER' FROM SalaryHead WHERE HeadCategory IN ('ESIC Employer Contribution')
																				UNION
																				SELECT *,'ESICEE' FROM SalaryHead WHERE HeadCategory IN ('ESIC Employee Contribution')
                                                                                UNION
                                                                                SELECT *,'GROSS' FROM SalaryHead WHERE HeadCategory = 'GROSS'																			
																	)--Salary Head 
														SH ON SH.SalaryHeadID=SPC.SalaryHeadID
                                                WHERE SPM.SalaryProcID = '" + salaryProcessId + @"'
														
											) EmpSlr ON EmpBasic.SystemID = EmpSlr.EmpInfoSystemID AND EmpBasic.PlantID = EmpSlr.PlantID
                                    LEFT JOIN
		                                    (
											 SELECT EmpSystemID, MonthNo, YearNo, TotalProcDate, TotalPresent, TotalLate,
													TotalAbsent AbsentDays, TotalLv, TotalMLv, TotalCompAssignLv, TotalWeekOff, TotalHoliDay,
													TotalWeekOffHoliDay, TotalOTHr, TotalNormalOTHr, TotalExtraOTHr
				                              FROM SalaryProceAttdnData
											  WHERE   MonthNo = MONTH(CONVERT(DATE,'" + date + @"')) AND
						                                YearNo = YEAR(CONVERT(DATE,'" + date + @"'))	

											) MMDSA ON EmpSlr.EmpInfoSystemID = MMDSA.EmpSystemID 											   
													   WHERE 
														
													EmpSlr.MonthNo = " + monthName + @" AND EmpBasic.SystemId in 
													(
													SELECT 
													  EmpSystemID
												  FROM [dbo].[ESICEligibleEmployee]
												  WHERE StartDate < '" + date + @"' and isActive = 1
													) ORDER BY EmployeeCodeS ";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//end function
        /// <summary>
        /// Bank Letter SQL Function
        /// </summary>
        /// <param name="dsRef"></param>
        /// <param name="companyGrpId"></param>
        /// <param name="companyId"></param>
        /// <param name="plantId"></param>
        /// <param name="bankId"></param>
        /// <param name="bankBranchId"></param>
        /// <param name="monthName"></param>
        /// <param name="year"></param>
        public void GetEmployeeSalaryBankAccountStatement(out DataSet dsRef, string paymentMode, string companyGrpId, string companyId, string plantId, string bankId, string bankBranchId, int monthName, string year, bool isActive, bool isSeperated, bool isMaternity)
        {
            string strSQL;
            var days = DateTime.DaysInMonth(Convert.ToInt32(year), monthName);//Number of Days in a month
            var monthNameString = CultureInfo.CurrentCulture.DateTimeFormat.GetAbbreviatedMonthName(monthName);//Month Name from Month No
            var date = days + "-" + monthNameString + "-" + year;
            ConnectionManager.DAL.ConManager objCon;

            string sqlBank = "SELECT* FROM EmployeeWiseBankCashAmount WHERE PlantId = '" + plantId + "' AND MonthNo = '" + monthName + @"' AND YearNo = '" + year + @"'";
            DataTable dtEmployeeWiseBankCashAmount = null;

            objCon = new ConnectionManager.DAL.ConManager("1");


            objCon.OpenDataSetThroughAdapter(sqlBank, out dsRef, false, "1");
            dtEmployeeWiseBankCashAmount = dsRef.Tables[0];
            dsRef = null;

            DataTable dtslProcId = null;


            string strSqlStruc = "";

            strSqlStruc = @"SELECT SystemID FROM SalaryProcMaster SPM
                                      WHERE SPM.SystemID IN (SELECT SlrProcMstSystemID FROM SalaryProcChild
                                                        WHERE PlantID = '" + plantId + @"' ) AND SPM.MonthNo = '" + monthName + @"' AND SPM.YearNo='" + year + @"' ";


            objCon = new ConnectionManager.DAL.ConManager("1");


            objCon.OpenDataSetThroughAdapter(strSqlStruc, out dsRef, false, "1");

            dtslProcId = dsRef.Tables[0];


            string inSalaryProcParam = "' '";

            for (int i = 0; i < dtslProcId.Rows.Count; i++)
            {
                inSalaryProcParam += ",'" + dtslProcId.Rows[i]["SystemID"].ToString() + "'";
            }


            try
            {
                string bankJoin = "";
                string bankWC = "";
                string bankNetPay = "";

                string empStatus = " Where (1=0 ";

                if (isActive == true && isSeperated == true && isMaternity == true)
                {
                    empStatus = " Where (1=1 ";
                }
                else
                {
                    if (isActive == true)
                    {
                        empStatus += " OR SalaryProcFlag ='Regular'";
                    }
                    if (isSeperated == true)
                    {
                        empStatus += " OR SalaryProcFlag ='SEPARATED'";
                    }
                    if (isMaternity == true)
                    {
                        empStatus += " OR SalaryProcFlag ='MLV_PRE'";

                    }
                }
                empStatus += ")";
                if (paymentMode.ToUpper() == "BANK")
                {
                    bankJoin = @"LEFT JOIN EmployeeBankInfo EBI ON EI.SystemId = EBI.EmpSystemID	
                                LEFT JOIN HKP.Bank Bank ON Bank.Id = EBI.BankSystemID
								LEFT JOIN HKP.BankBranch BankBr ON BankBr.Id = EBI.BankBranchId";
                    bankWC = @"AND EBI.BankSystemID ='" + bankId + @"'";
                    bankNetPay = @" ,(ISNULL(EBI.SalaryPercentage,0)*ISNULL(spc.DisbusmentAmount,0))/100 pBankSalary,EBi.BankSystemID,EBi.BankBranchId,EBI.BankAccNo BankAccountNo ,EBI.BankAccNo  IFSCCode, EBI.SalaryPercentage, Bank.UserName BankName,BankBr.UserName BankBranchName";
                }
                if (dtEmployeeWiseBankCashAmount.Rows.Count == 0)
                {

                    strSQL = @"SELECT * FROM (
                                SELECT   EI.PaymentMode,EI.GroupID,EI.CompanyId,EI.PlantId, EI.EmployeeCode,EI.EmployeeName
							   ,ISNULL(EI.EmployeeCodePreFix,'') EmployeeCodePreFix,ISNULL(EI.EmployeeCodeNumeric,0) EmployeeCodeNumeric	 
                               , ISNULL(SPC.DisbusmentAmount,0) NetSalary
							   " + bankNetPay + @"
							   ,sh.HeadType,SPC.EmpInfoSystemID,spm.MonthNo ,CRC.Code currCode,CRC.Id CurrencyId
                               , ISNULL(CURR.IntegerInDisb,0) IntegerInDisb, ISNULL(CURR.DecimalNo,0) DecimalNo 
                               , ISNULL(LGD.userName,'') Designation    
                               , Case when Isnull(SPM.SalaryProcFlag,'') = '' THen 'Regular' else SalaryProcFlag end SalaryProcFlag       
                                FROM SalaryProcChild SPC
							    INNER JOIN SalaryProcMaster SPM ON SPM.SystemID = SPC.SlrProcMstSystemID
								INNER JOIN SalaryHead SH ON SH.SalaryHeadID = SPC.SalaryHeadID 
								--LEFT JOIN CurrencyRuleChild CURR ON CURR.SalaryHeadID = sh.SalaryHeadID
								INNER JOIN EmployeeInformation EI ON EI.SystemId = SPC.EmpInfoSystemID 
                                LEFT JOIN SalaryRuleMaster SRM ON SRM.SystemID = EI.SalaryRuleMasterSystemID
								INNER JOIN CurrencyRuleChild CURR ON CURR.SalaryHeadID = sh.SalaryHeadID AND CURR.MstSystemID = srm.CurrencyRuleSystemID 
								" + bankJoin + @"
                                LEFT JOIN HKP.Designation DeG ON DeG.Id = EI.GivenDesignationId                                
                                LEFT JOIN HKP.LegalDesignation LGD ON LGD.Id = EI.LegalDesignationId
                                INNER JOIN SCS.Currency AS CRC ON CRC.Id = SPC.DisbusmentCurrencyID
								WHERE --SPM.MonthNo = '" + monthName + @"' AND SPM.YearNo='" + year + @"' 
                                --AND 
                                    SPM.SystemID IN  (" + inSalaryProcParam + @") 
								AND EI.GroupID = '" + companyGrpId + @"' AND EI.CompanyId = '" + companyId + @"' AND EI.PlantId ='" + plantId + @"' " + bankWC + @" --AND EBI. BankBranchId = '" + bankBranchId + @"'
                                AND SH.HeadCategory = 'Net Payable'  AND EI.PaymentMode = '" + paymentMode + @"') dd " + empStatus + @"
                                 ORDER BY EmployeeCodePreFix,EmployeeCodeNumeric
                                ";

                }
                else
                {
                    if (paymentMode.ToUpper() == "BANK")
                    {
                        bankJoin = @"INNER JOIN EmployeeWiseBankCashAmount EBCA ON EI.SystemId = EBCA.EmpSystemId and EBCA.PlantId = '" + plantId + @"' AND EBCA.MonthNo =  '" + monthName + @"'  AND EBCA.YearNo = '" + year + @"' 
                                LEFT JOIN EmployeeBankInfo EBI ON EI.SystemId = EBI.EmpSystemID	
                                LEFT JOIN HKP.Bank Bank ON Bank.Id = EBI.BankSystemID
								LEFT JOIN HKP.BankBranch BankBr ON BankBr.Id = EBI.BankBranchId";
                        bankWC = @"AND EBI.BankSystemID ='" + bankId + @"'";
                        bankNetPay = @" ,ISNULL(EBCA.BankAmount,0) pBankSalary ,EBi.BankSystemID,EBi.BankBranchId,EBI.BankAccNo BankAccountNo ,EBI.BankAccNo  IFSCCode, EBI.SalaryPercentage, Bank.UserName BankName,BankBr.UserName BankBranchName";
                    }
                    strSQL = @"SELECT * FROM (
                                SELECT   EI.PaymentMode,EI.GroupID,EI.CompanyId,EI.PlantId, EI.EmployeeCode,EI.EmployeeName
							   ,ISNULL(EI.EmployeeCodePreFix,'') EmployeeCodePreFix,ISNULL(EI.EmployeeCodeNumeric,0) EmployeeCodeNumeric	 
                               , ISNULL(SPC.DisbusmentAmount,0) NetSalary
							   " + bankNetPay + @"
							   ,sh.HeadType,SPC.EmpInfoSystemID,spm.MonthNo ,CRC.Code currCode,CRC.Id CurrencyId
                               , ISNULL(CURR.IntegerInDisb,0) IntegerInDisb, ISNULL(CURR.DecimalNo,0) DecimalNo 
                               , ISNULL(LGD.userName,'') Designation    
                            , Case when Isnull(SPM.SalaryProcFlag,'') = '' THen 'Regular' else SalaryProcFlag end SalaryProcFlag       
                                FROM SalaryProcChild SPC
							    INNER JOIN SalaryProcMaster SPM ON SPM.SystemID = SPC.SlrProcMstSystemID
								INNER JOIN SalaryHead SH ON SH.SalaryHeadID = SPC.SalaryHeadID 
								INNER JOIN EmployeeInformation EI ON EI.SystemId = SPC.EmpInfoSystemID 
                                LEFT JOIN SalaryRuleMaster SRM ON SRM.SystemID = EI.SalaryRuleMasterSystemID
								INNER JOIN CurrencyRuleChild CURR ON CURR.SalaryHeadID = sh.SalaryHeadID AND CURR.MstSystemID = srm.CurrencyRuleSystemID 
								
								" + bankJoin + @"
                                LEFT JOIN HKP.Designation DeG ON DeG.Id = EI.GivenDesignationId                                
                                LEFT JOIN HKP.LegalDesignation LGD ON LGD.Id = EI.LegalDesignationId
                                INNER JOIN SCS.Currency AS CRC ON CRC.Id = SPC.DisbusmentCurrencyID
								WHERE --SPM.MonthNo = '" + monthName + @"' AND SPM.YearNo='" + year + @"' 
                                --AND 
                                    SPM.SystemID IN  (" + inSalaryProcParam + @") 
								AND EI.GroupID = '" + companyGrpId + @"' AND EI.CompanyId = '" + companyId + @"' AND EI.PlantId ='" + plantId + @"' " + bankWC + @" --AND EBI. BankBranchId = '" + bankBranchId + @"'
                                AND SH.HeadCategory = 'Net Payable'  AND EI.PaymentMode = '" + paymentMode + @"') dd " + empStatus + @"
                            ORDER BY EmployeeCodePreFix,EmployeeCodeNumeric
                            ";
                }
                objCon = new ConnectionManager.DAL.ConManager("1");


                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//end function


