        public void GetEmployeeSalaryTransferStatement(out DataSet dsRef, string paymentMode, string companyGrpId, string companyId, string plantId, string bankId, string bankBranchId, int monthName, string year, string salaryProcId)
        {
            string strSQL;
            var days = DateTime.DaysInMonth(Convert.ToInt32(year), monthName);//Number of Days in a month
            var monthNameString = CultureInfo.CurrentCulture.DateTimeFormat.GetAbbreviatedMonthName(monthName);//Month Name from Month No
            var date = days + "-" + monthNameString + "-" + year;
            ConnectionManager.DAL.ConManager objCon;
            try
            {
                strSQL = @"SELECT SPMGross.PaymentMode,SPMGross.EmpInfoSystemID,CONVERT(INT,EmployeeCode) EmployeeCodeS,EmployeeCode,EmployeeName,ISNULL(SPMGross.BankAccNo,'') BankAccountNo, ISNULL(SPMGross.IFSCCode,'') IFSCCode
                            , SPMGross.BankName,SPMGross.BankBranchName
                            , SPMGross.SalaryPercentage,(SPMGross.GrossDisbusmentAmount + SPMExceptGross.WithoutGrossDisbusmentAmount) AS NetSalary
                            , SPMGross.SalaryPercentage*(SPMGross.GrossDisbusmentAmount + SPMExceptGross.WithoutGrossDisbusmentAmount) /100 pBankSalary,SPMGross.currCode
                            , SPMGross.GrossDisbusmentAmount,SPMExceptGross.WithoutGrossDisbusmentAmount
                            , ISNULL(SPMGross.DecimalNo,0) DecimalNo,ISNULL(SPMGross.IntegerInDisb,0) IntegerInDisb
                            
                            FROM(
							(SELECT DISTINCT EI.PaymentMode,EI.GroupID,EI.CompanyId,EI.PlantId, EI.EmployeeCode,EI.EmployeeName,EBI.BankAccNo ,BankBr.IFSCCode, EBI.SalaryPercentage
							   , Bank.UserName BankName,BankBr.UserName BankBranchName	
                               ,spc.DisbusmentAmount GrossDisbusmentAmount,sh.HeadType,SPC.EmpInfoSystemID,spm.MonthNo ,EBi.BankSystemID,EBi.BankBranchId,CRC.Code currCode
                               , ISNULL(CURR.DecimalNo,0) DecimalNo,ISNULL(CURR.IntegerInDisb,0) IntegerInDisb
                                FROM SalaryProcChild SPC
							    INNER JOIN SalaryProcMaster SPM ON SPM.SystemID = SPC.SlrProcMstSystemID
								INNER JOIN SalaryHead SH ON SH.SalaryHeadID = SPC.SalaryHeadID 
                                LEFT JOIN CurrencyRuleChild CURR ON CURR.SalaryHeadID = sh.SalaryHeadID
								INNER JOIN EmployeeInformation EI ON EI.SystemId = SPC.EmpInfoSystemID 
								LEFT JOIN EmployeeBankInfo EBI ON EI.SystemId = EBI.EmpSystemID	
                                LEFT JOIN HKP.Bank Bank ON Bank.Id = EBI.BankSystemID
								LEFT JOIN HKP.BankBranch BankBr ON BankBr.Id = EBI.BankBranchId
                                INNER JOIN SCS.Currency AS CRC ON CRC.Id = SPC.DisbusmentCurrencyID
								WHERE SPM.MonthNo = '" + monthName + @"' AND SPM.YearNo='" + year + @"'  AND SPM.SalaryProcID = '" + salaryProcId + "' AND SH.SalaryHead = 'GROSS' and (EI.EmployeeStatus = 'Active' OR Month( EI.DOS) = Month('" + date + @"'))
								AND EI.GroupID = '" + companyGrpId + @"' AND EI.CompanyId = '" + companyId + @"' AND EI.PlantId ='" + plantId + @"'-- AND EBI.BankSystemID ='" + bankId + @"' --AND EBI. BankBranchId = '" + bankBranchId + @"'
                                ) SPMGross 
								INNER JOIN 
								(SELECT SUM(spc.DisbusmentAmount) WithoutGrossDisbusmentAmount,sh.HeadType,SPC.EmpInfoSystemID,spm.MonthNo FROM SalaryProcChild SPC
								INNER JOIN SalaryProcMaster SPM ON SPM.SystemID = SPC.SlrProcMstSystemID
								INNER JOIN SalaryHead SH ON SH.SalaryHeadID = SPC.SalaryHeadID 
								INNER JOIN EmployeeInformation EI ON EI.SystemId = SPC.EmpInfoSystemID 
                                LEFT JOIN EmployeeBankInfo EBI ON EI.SystemId = EBI.EmpSystemID	
								WHERE SPM.MonthNo = '" + monthName + @"' AND SPM.YearNo='" + year + @"'  AND SPM.SalaryProcID = '" + salaryProcId + "' AND SH.HeadType = 'D' AND SH.SalaryHead != 'GROSS' and (EI.EmployeeStatus = 'Active' OR Month( EI.DOS) = Month('" + date + @"'))
								AND EI.GroupID = '" + companyGrpId + @"' AND EI.CompanyId = '" + companyId + @"' AND EI.PlantId ='" + plantId + @"' --AND EBI.BankSystemID ='" + bankId + @"' --AND EBI. BankBranchId = '" + bankBranchId + @"'
                                GROUP BY EmpInfoSystemID,HeadType,MonthNo
								) SPMExceptGross
								 ON SPMGross.EmpInfoSystemID = SPMExceptGross.EmpInfoSystemID)  WHERE PaymentMode = '" + paymentMode + @"' ORDER BY EmployeeCodeS";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//end function

        /// <summary>
        /// Cash Statement For each Month
        /// </summary>
        /// <param name="dsRef"></param>
        /// <param name="companyGrpId"></param>
        /// <param name="companyId"></param>
        /// <param name="plantId"></param>
        /// <param name="bankId"></param>
        /// <param name="bankBranchId"></param>
        /// <param name="monthName"></param>
        /// <param name="year"></param>
        public void GetEmployeeCashCheckStatement(out DataSet dsRef, string paymentMode, string companyGrpId, string companyId, string plantId, string bankId, string bankBranchId, int monthName, string year, string salaryProcId)
        {
            string strSQL;
            var days = DateTime.DaysInMonth(Convert.ToInt32(year), monthName);//Number of Days in a month
            var monthNameString = CultureInfo.CurrentCulture.DateTimeFormat.GetAbbreviatedMonthName(monthName);//Month Name from Month No
            var date = days + "-" + monthNameString + "-" + year;
            ConnectionManager.DAL.ConManager objCon;
            try
            {
                strSQL = @"SELECT SPMGross.PaymentMode,SPMGross.EmpInfoSystemID,CONVERT(INT,EmployeeCode) EmployeeCodeS,EmployeeCode,EmployeeName,FatherName
                            , Department, SPMGross.GivDesignation, SPMGross.workingDays,SPMGross.MonthNo,SPMGross.YearNo 
                           , (SPMGross.GrossDisbusmentAmount + SPMExceptGross.WithoutGrossDisbusmentAmount) AS NetSalary
                            --,SPMGross.SalaryPercentage*(SPMGross.GrossDisbusmentAmount + SPMExceptGross.WithoutGrossDisbusmentAmount) /100 pBankSalary,SPMGross.currCode
                            ,SPMGross.GrossDisbusmentAmount,SPMExceptGross.WithoutGrossDisbusmentAmount 
                            , ISNULL(SPMGross.DecimalNo,0) DecimalNo,ISNULL(SPMGross.IntegerInDisb,0) IntegerInDisb,SPMGross.Section
                            FROM(
							(SELECT DISTINCT  EI.PaymentMode,EI.GroupID,EI.CompanyId,EI.PlantId, EI.EmployeeCode,EI.EmployeeName,EI.FatherName,Dept.UserName Department--,EBI.BankAccNo , EBI.SalaryPercentage
								,spc.DisbusmentAmount GrossDisbusmentAmount,sh.HeadType,SPC.EmpInfoSystemID,spm.MonthNo,spm.YearNo --,EBi.BankSystemID,EBi.BankBranchId
								,CRC.Code currCode,egdsg.UserName GivDesignation,section.UserName Section
								,(ISNULL(ADMS.TotalPresent, 0) + ISNULL(ADMS.TotalLate, 0)+ ISNULL(ADMS.TotalWeekOff, 0)+ISNULL(ADMS.TotalHoliDay, 0) + ISNULL(ADMS.TotalLv, 0) + ISNULL(ADMS.TotalMLv, 0)) workingDays
								, CURR.IntegerInDisb, CURR.DecimalNo
                                FROM SalaryProcChild SPC
							    INNER JOIN SalaryProcMaster SPM ON SPM.SystemID = SPC.SlrProcMstSystemID
								INNER JOIN SalaryHead SH ON SH.SalaryHeadID = SPC.SalaryHeadID 
								INNER JOIN EmployeeInformation EI ON EI.SystemId = SPC.EmpInfoSystemID 
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = ei.BudgetCode
                            LEFT JOIN ORG.Position PR ON MB.PositionId=PR.Id
								LEFT JOIN CurrencyRuleChild CURR ON CURR.SalaryHeadID = sh.SalaryHeadID
								INNER JOIN ORG.Section section ON pr.SectionId = section.Id 

								INNER JOIN ORG.Department Dept ON pr.DepartmentId = Dept.Id 
                                INNER JOIN SCS.Currency AS CRC ON CRC.Id = SPC.DisbusmentCurrencyID
								INNER JOIN hkp.Designation egdsg on egdsg.id=EI.GivenDesignationId
								LEFT JOIN AttdnDataMonthlySummary AS ADMS ON ADMS.EmpSystemID = EI.SystemId 
								WHERE SPM.MonthNo = '" + monthName + @"' AND SPM.YearNo='" + year + @"'  AND SPM.SalaryProcID = '" + salaryProcId + @"' 
                                AND ADMS.MonthNo = '" + monthName + @"' AND ADMS.YearNo = '" + year + @"'
								AND SH.SalaryHead = 'GROSS' and (EI.EmployeeStatus = 'Active' OR MONTH( EI.DOS) = Month('" + date + @"'))
								AND EI.GroupID = '" + companyGrpId + @"' AND EI.CompanyId = '" + companyId + @"' AND EI.PlantId ='" + plantId + @"'
								AND PaymentMode = '" + paymentMode + @"'
                                ) SPMGross 
								INNER JOIN 
								(SELECT SUM(spc.DisbusmentAmount) WithoutGrossDisbusmentAmount,sh.HeadType,SPC.EmpInfoSystemID,spm.MonthNo FROM SalaryProcChild SPC
								INNER JOIN SalaryProcMaster SPM ON SPM.SystemID = SPC.SlrProcMstSystemID
								INNER JOIN SalaryHead SH ON SH.SalaryHeadID = SPC.SalaryHeadID 
								INNER JOIN EmployeeInformation EI ON EI.SystemId = SPC.EmpInfoSystemID 
                          	
								WHERE SPM.MonthNo = '" + monthName + @"' AND SPM.YearNo='" + year + @"' AND SPM.SalaryProcID = '" + salaryProcId + @"'  AND SH.HeadType = 'D' AND SH.SalaryHead != 'GROSS' and (EI.EmployeeStatus = 'Active' OR Month( EI.DOS) = Month('" + date + @"'))
								AND EI.GroupID = '" + companyGrpId + @"' AND EI.CompanyId = '" + companyId + @"' AND EI.PlantId ='" + plantId + @"'
								 AND PaymentMode = '" + paymentMode + @"'
                                GROUP BY EmpInfoSystemID,HeadType,MonthNo
								) SPMExceptGross
								 ON SPMGross.EmpInfoSystemID = SPMExceptGross.EmpInfoSystemID) 
							
								 ORDER BY EmployeeCodeS";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//end function



        public void GetEmpSalaryStructureRegisterAndPaySlipRpt(ParamList para, string paymentMode, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;
            clsStaticInfo obs = null;

            var _wc = string.Empty;

            if (para.EmployeeId != "" && para.EmployeeId != null)
            {
                _wc = " AND SystemID IN (" + para.EmployeeId + @")";
            }
            else
            {
                if (para.PayGroup.ToUpper() != "NOGROUP" && para.PayGroup != "null")
                {
                    _wc = @" AND EmpInfoSystemID IN (
							 select employeeid from MST.PayrollGroupMaster where PayrollGroupId = '" + para.PayGroup + @"'
													 )";
                }
                if (para.PayGroup.ToUpper() == "NO GROUP")
                {
                    _wc = @" AND EmpInfoSystemID NOT IN (
													 select employeeid from MST.PayrollGroupMaster)";
                }
                if (para.PayGroup.ToUpper() == "ALL")
                {
                    _wc = @"";
                }

            }
            try
            {
                obs = new clsStaticInfo();
                strSql = @"SELECT * FROM
                           (
                           SELECT E.SystemID
	                            , E.EmployeeCode
	                            , CONVERT(INT,E.EmployeeCode) EmployeeCodeS                                
	                            , E.EmployeeName
                                , ISNULL(E.EmployeeNameLocal,E.EmployeeName) EmployeeNameLocal
	                            , REPLACE(Convert(VARCHAR(11), E.DOB, 106), ' ', '-') AS DOB
	                            , E.FatherName
	                            , E.MotherName
	                            , E.EmpType EmployeeType
	                            , E.EmploymentType EmploymentNature
	                            , E.NationalID
	                            , E.GenderID GenderName
	                            , REPLACE(Convert(VARCHAR(11), E.DOJ, 106), ' ', '-') AS DOJ
	                            , REPLACE(Convert(VARCHAR(11), E.DOC, 106), ' ', '-') AS DOC
	                            , REPLACE(Convert(VARCHAR(11), E.DOS, 106), ' ', '-') AS DOS
                                    " + obs.EntityColumns() + @"
                                , E.PaymentMode
                                , Cm.UserName CompanyName
	                            , CAM.Address1
	                            , CAM.Address2
	                            , E.EmployeeStatus
	                            , P.UserName PlantName
	                            , (PAM.[Address1] + ', ' + PAM.[Address2] + ', ' + PAMC.UserName + ' - ' + PAM.Postcode) FactoryAddress
	                            , GC.UserName GroupName
	                            , (CGAM.[Address1] + ', ' + CGAM.[Address2] + ', ' + CT.UserName + ' - ' + CGAM.Postcode + ', Contact: ' + CGAM.Phone) GroupAddress
	                            , EmpSlr.SalaryHeadID
	                            , sh.SalaryHead
	                            , isnull(psh.Sequence, 99) Sequence
	                            , sh.HeadType
	                            , sh.HeadCategory
	                            , EmpSlr.EntryCurrencyID
	                            , EmpSlr.EntryAmount
	                            , EmpSlr.DefineCurrencyID
	                            , EmpSlr.DefineAmount
	                            , EmpSlr.AmtDefinitionCurrencyID AmtDefinationCurrencyID
	                            , EmpSlr.AmtDefinitionRate AmtDefinationRate
	                            , E.PlantID
	                            , BK.UserName BankNameShort
	                            , EBI.BankAccNo
                                ,sh.IsCTCComponent,sh.IsGrossComponent,mst.EmpInfoSystemID,mw.SalaryHeadValue

                                , isnull(vpf.VoluntaryPFValue,0) VoluntaryPFValue
                                , isnull(BonusValue.Bonus,0) Bonus

								, BonusValue.SalaryHead B_SalaryHead
								, BonusValue.SalaryHeadID B_SalaryHeadID
								, BonusValue.IsCTCComponent B_IsCTCComponent
								, BonusValue.IsGrossComponent B_IsGrossComponent
								, BonusValue.HeadType B_HeadType
								, BonusValue.HeadCategory B_HeadCategory

                                ,VPFhead.HeadCategory xHeadCategory,VPFhead.SalaryHeadID xSalaryHeadID
                                ,VPFhead.SalaryHead xSalaryHead,VPFhead.IsCTCComponent xIsCTCComponent
                                ,VPFhead.IsGrossComponent xIsGrossComponent,VPFhead.HeadType xHeadType
                                ,VPFhead.SalaryRuleMasterSystemID xSalaryRuleMasterSystemID
	                            ,CRC.IntegerInDisb,crc.DecimalNo
		                        ,OverTimePmtPolicyMasterID=CASE WHEN ISNULL(EOE.EmpSystemID,'')<>'' then (select id from OverTimePmtPolicyMaster where IsDefault=1)
											WHEN DMCT.IsOTEntitled=1 AND ISNULL(DMCT.OverTimePmtPolicyMasterID,'')<>'' then DMCT.OverTimePmtPolicyMasterID
											ELSE NULL END
								,OTD.FormulaDesID,OTD.FormulaDes
								,ISNULL(DMCT.IsOTEntitled,EOE.IsOTEntitle) IsOTEntitle
				            FROM EmployeeInformation AS E
LEFT OUTER JOIN MST.ManpowerBudget mpb on mpb.Id=e.BudgetCode
									LEFT OUTER JOIN ORG.Position PO ON mpb.PositionId=PO.Id
                                    LEFT OUTER JOIN ORG.Entity EN ON mpb.EntityId=EN.Id 
                                        " + obs.EntityTables() + @"
                              LEFT JOIN HKP.LocalLanguage LocLangLD ON LocLangLD.LegalDesignationId = E.LegalDesignationId AND LocLangLD.LanguageId = '" + para.LanguageId + @"'
                              LEFT JOIN HKP.LocalLanguage LocLangGD ON LocLangGD.DesignationId = E.GivenDesignationId AND LocLangGD.LanguageId = '" + para.LanguageId + @"'
                              --OT Entitlement and OT Calculation Rule              
				       LEFT JOIN EmployeeOTEntitle EOE ON EOE.EmpSystemID = E.SystemId and eoe.IsOTEntitle=1
												LEFT JOIN  MST.DesignationMaster DMOT ON DMOT.DesignationId = e.GivenDesignationId
												LEFT JOIN  SCS.DesignationMasterConfiguration DMCT ON DMCT.DesignationMasterId = DMOT.Id and DMCT.plantid='20181'
									left join (select * from OverTimePmtPolicyDetails where OverTimeDayType='Working Day') otd on otd.OverTimePmtPolicyID=DMCT.OverTimePmtPolicyMasterID
                                     ----------       
												LEFT JOIN EmployeeBankInfo EBI ON E.SystemId = EBI.EmpSystemID	
                                LEFT JOIN HKP.Bank Bank ON Bank.Id = EBI.BankSystemID
                                        left outer JOIN 
											(
												select e.systemid												
												,SUM(sv.SalaryHeadValue) SalaryHeadValue

												 FROM EmployeeInformation e   
												LEFT JOIN mst.ManpowerBudget b on e.BudgetCode=b.Id
												LEFT JOIN mst.LegalSalaryGradeDesignation gd on gd.LegalDesignationId=e.LegalDesignationId 
                                                                                                and e.PlantId=gd.PlantId
												LEFT JOIN (
												SELECT MAX(EffectiveDate)EffectiveDate
                                                                    ,LegalSalaryGradeId
                                                                    ,EmployeeLocationId 
												                    FROM MST.LegalSalaryStructure 
												                    WHERE EffectiveDate<='" + para.ToDate + @"'
                                                                     --EffectiveDate<='31-Aug-2018'
												                    group by LegalSalaryGradeId
                                                                            ,EmployeeLocationId 
												) S ON S.LegalSalaryGradeId=GD.LegalSalaryGradeId AND S.EmployeeLocationId=b.EmployeeLocationId
												LEFT JOIN MST.LegalSalaryStructure  SS ON SS.LegalSalaryGradeId=S.LegalSalaryGradeId 
                                                                                            AND SS.EmployeeLocationId=s.EmployeeLocationId 
                                                                                            AND SS.EffectiveDate=s.EffectiveDate
												LEFT JOIN MST.LegalSalaryStructureValue sv on sv.LegalSalaryStructureId=ss.Id 																							
												GROUP BY E.SystemId
											) MW ON MW.SystemId=E.SystemId

                                        LEFT OUTER JOIN
								                ORG.Plant AS p ON E.PlantId = p.Id
						                LEFT OUTER JOIN
								                ORG.Company AS Cm ON E.CompanyID = Cm.Id
						                left outer JOIN
								                ORG.CompanyGroup AS GC ON E.GroupID = GC.Id
										LEFT OUTER JOIN
												HKP.Bank AS BK ON E.BankSystemID = BK.Id
										LEFT OUTER JOIN
												MST.AddressMaster AS CAM ON Cm.AddressMasterId = CAM.Id
										LEFT OUTER JOIN
												MST.AddressMaster AS PAM ON P.AddressMasterId = PAM.Id
										LEFT OUTER JOIN
												MST.AddressMaster AS CGAM ON GC.AddressMasterId = CGAM.Id
										LEFT OUTER JOIN
												SCS.City AS PAMC ON PAM.CityId = PAMC.Id
										LEFT OUTER JOIN
												SCS.City AS CT ON CGAM.CityId = CT.Id
                                        LEFT OUTER JOIN (select * from SalaryInfoDefineMaster where IsApproved=1) mst ON E.SystemID= mst.EmpInfoSystemID
										LEFT OUTER  join SalaryInfoDefine EmpSlr on EmpSlr.SalaryID=mst.SystemID
	                                    LEFT OUTER join SalaryHead sh on sh.SalaryHeadID=EmpSlr.SalaryHeadID

										LEFT JOIN SalaryRuleMaster srm on srm.SystemID=mst.SalaryRuleMasterSystemID
										LEFT JOIN CurrencyRuleChild crc on crc.MstSystemID=srm.CurrencyRuleSystemID and crc.SalaryHeadID=sh.SalaryHeadID

                                        LEFT JOIN (
										
												  SELECT EmpSystemId,MAX(EffectiveDate) EffectiveDate, VoluntaryPFValue from [PFEmployeeVoluntaryValue] 
												  WHERE EffectiveDate<='" + para.ToDate + @"'
												  --Where EffectiveDate<='31-Aug-2018'
												  GROUP BY EmpSystemId,EffectiveDate,VoluntaryPFValue
										) VPF ON E.SystemId=vpf.EmpSystemId

										LEFT JOIN(
										SELECT SH.HeadCategory ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
										,SH.IsGrossComponent,SH.HeadType,sr.SalaryRuleMasterSystemID
											  FROM [dbo].[SalaryRulePF] SR
											  left join SalaryHead SH ON SH.SalaryHeadID=SR.SalaryHeadID
											  where SH.HeadCategory='PF Voluntary'
										) VPFhead on VPFhead.SalaryRuleMasterSystemID=mst.SalaryRuleMasterSystemID

                                        LEFT JOIN
										(
										SELECT m.EmpSystemID,m.MonthNo,d.Value Bonus 
												,SH.HeadCategory ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
												,SH.IsGrossComponent,SH.HeadType
												FROM [BonusPolicyMonthlyRetainEmpWiseCalculation] m
												LEFT JOIN [BonusPolicyMonthlyRetainDistributionPmt] d ON m.id=d.BnsPlyMntRetainID
												LEFT JOIN SalaryHead SH ON SH.SalaryHeadID=d.SalaryHeadID
												WHERE m.MonthNo=DATEPART(MONTH,'" + para.FromDate + @"') AND m.YearNo = DATEPART(YEAR,'" + para.FromDate + @"') 
                                           
                                        and d.SalaryHeadID=
												(select SalaryHeadID from SalaryHead where HeadCategory='Festival Bonus')
										) BonusValue on e.SystemId=BonusValue.EmpSystemID


										left outer join (select * from [MST].[PlantSalaryHeadSequence] where PlantId='" + para.PlantId + @"' ) psh
										on psh.SalaryHeadId=EmpSlr.SalaryHeadID
                         ) A  WHERE (EmployeeStatus != 'Separated' OR CONVERT(DATE,DOS) >= CONVERT(DATE,'" + para.FromDate + @"')) 
                            AND CONVERT(DATE,DOJ) <= CONVERT(DATE,'" + para.ToDate + @"')
                            --AND ISNULL(EmpInfoSystemID,'')<>'' 
                           --AND EmpInfoSystemID  IN (SELECT SystemId from EmployeeInformation where EmployeeCode = '100051') 
                             " + _wc + @"
                           AND PlantID = '" + para.PlantId + @"'";

                if (para.UnitId != "null" && para.UnitId != null && para.UnitId != "undefined" && para.UnitId != "")
                {
                    strSql = strSql + @" AND UnitID = '" + para.UnitId + "'";
                }
                if (para.DivisionId != "null" && para.DivisionId != null && para.DivisionId != "undefined" && para.DivisionId != "")
                {
                    strSql = strSql + @" AND DivisionID = '" + para.DivisionId + "'";
                }
                if (para.DepartmentId != "null" && para.DepartmentId != null && para.DepartmentId != "undefined" && para.DepartmentId != "")
                {
                    strSql = strSql + @" AND DepartmentID = '" + para.DepartmentId + "'";
                }
                if (para.SectionId != "null" && para.SectionId != null && para.SectionId != "undefined" && para.SectionId != "")
                {
                    strSql = strSql + @" AND SectionID = '" + para.SectionId + "'";
                }
                if (para.SubSectionId != "null" && para.SubSectionId != null && para.SubSectionId != "undefined" && para.SubSectionId != "All" && para.SubSectionId != "")
                {
                    strSql = strSql + @" AND SubSectionID = '" + para.SubSectionId + "'";
                }
                if (para.EmpCategorId != "null" && para.EmpCategorId != null && para.EmpCategorId != "undefined" && para.EmpCategorId != "All" && para.EmpCategorId != "")
                {
                    strSql = strSql + @" AND EmployeeCategorySystemID = '" + para.EmpCategorId + "'";
                }
                if (paymentMode != "null" && paymentMode != null && paymentMode != "undefined" && paymentMode != "All" && paymentMode != "")
                {
                    strSql = strSql + @" AND PaymentMode = '" + paymentMode + @"'";
                }
                strSql = strSql + @"
                        ORDER BY EmployeeCodeS";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function   

        /// <summary>
        /// Salary Certificate QUery For Saveral Month ()   
        /// </summary>
        /// <param name="empSystemId"></param>
        /// <param name="dsRef"></param>
        public void GetEmpSalaryInfoForFiscalYear(string plantId, string empSystemId, string fromDate, string toDate, out DataSet dsRef)
        {
            try
            {
                ConnectionManager.DAL.ConManager objCon;

                string strSql = @"SELECT EmpBasic.SystemId,EmpBasic.EmployeeName,EmpBasic.FatherName,EmpBasic.GenderID,EmpBasic.Salutation,
                                EmpSlr.SalaryHeadID, EmpSlr.EntryCurrencyID, Sum(EmpSlr.EntryAmount) EntryAmount, EmpSlr.DefineCurrencyID, Sum(EmpSlr.DefineAmount) DefineAmount,
                                EmpSlr.DisbusmentCurrencyID, SUM(EmpSlr.DisbusmentAmount) DisbusmentAmount,
							
                                EmpSlr.PlantWiseExchangeCR, EmpSlr.ExchangeRate, EmpSlr.AmtDefinitionCurrencyID, EmpSlr.AmtDefinitionCurrency,
                                EmpSlr.AmtDefinitionCurrencyRate,EmpCategoryName,EmpSlr.HeadType,EmpSlr.IsGrossComponent
                                ,EmpSlr.SalaryHead,EmpSlr.HeadCategory,EmpSlr.HeadType,ISNULL(psh.Sequence,'99')  Sequence,CRC.IntegerInDisb,CRC.DecimalNo,CRC.IsDecimalInDisb
                                , ISNULL(MW.SalaryHeadValue,0) MinimumWage,MW.Grade, EmpSlr.PartOfNetPay   
                            FROM
                                    (
									 SELECT E.SystemID, E.EmployeeCode, E.EmployeeName, E.EmployeeStatus,E.PaymentMode,E.FatherName,E.GenderID,sal.UserName Salutation,
											DG.UserName DesignationGroupName, E.DesignationSystemID, DE.UserName DesignationName,
											'' UserGroupSystemID, E.PlantID, F.UserName PlantName, E.UnitID,
											FU.UserName UnitName, E.DivisionID, DV.UserName DivisionName, E.DepartmentID, DP.UserName DepartmentName,
											E.SectionID, S.UserName SectionName, E.SubSectionID, SS.UserName SubSectionName, E.EmployeeCategorySystemID,
											EC.UserName EmpCategoryName--, BK.BankNameShort BankName, BK.BankNameFull, E.BankAccNo
                                            ,egdsgg.GivenDesignationGroup,e.SalaryRuleMasterSystemID,Format(E.DOJ,'dd-MMM-yyyy') DOJ,Format(E.DOS,'dd-MMM-yyyy') DOS,Format(E.DOB,'dd-MMM-yyyy') DOB
											,ISNULL(LDS.UserName,'') LegalDesignation,ISNULL(E.NationalID,'') NationalID
                                     FROM EmployeeInformation E
												LEFT JOIN ORG.Plant F ON E.PlantID = F.Id
												LEFT JOIN hkp.DesignationGroup DG ON E.DesignationGroupId = DG.ID
												LEFT JOIN hkp.Designation DE ON E.GivenDesignationId = DE.Id
												LEFT JOIN hkp.LegalDesignation LDS ON E.LegalDesignationId = LDS.Id
												Left join HKP.Salutation sal ON Sal.Id = e.Salutation

												LEFT JOIN org.Unit FU ON E.UnitID = FU.Id
												LEFT JOIN org.Division DV ON E.DivisionID = DV.Id
												LEFT JOIN org.Department DP ON E.DepartmentID = DP.Id
												LEFT JOIN org.Section S ON E.SectionID = S.Id
												LEFT JOIN org.SubSection SS ON E.SubSectionID = SS.Id
												LEFT JOIN
                                                --hkp.EmployeeCategory EC ON E.EmployeeCategorySystemID = EC.Id
                                                (
                                                SELECT ECT.Id, ECT.UserName, DM.DesignationId FROM [HKP].[EmployeeCategory] ECT
												LEFT JOIN MST.DesignationMaster DM ON ECT.Id=DM.EmployeeCategoryId
												)EC ON EC.DesignationId=E.GivenDesignationId
												LEFT JOIN (SELECT dm.DesignationGroupId,dm.DesignationId,dm.EmployeeCategoryId
									            ,dg.UserName GivenDesignationGroup
									            FROM MST.DesignationMaster dm
									            LEFT JOIN HKP.DesignationGroup dg on dg.Id=dm.DesignationGroupId
									            ) egdsgg on egdsgg.DesignationId=e.GivenDesignationId
									            and egdsgg.EmployeeCategoryId=e.EmployeeCategorySystemID

									) EmpBasic
                                    LEFT JOIN 
													(
													 SELECT E.SystemID EmpSystemId, SUM(SV.SalaryHeadValue) SalaryHeadValue,LSG.UserName Grade
														FROM EmployeeInformation E   
																LEFT JOIN MST.ManpowerBudget b ON e.BudgetCode = b.Id
																LEFT JOIN MST.LegalSalaryGradeDesignation GD ON GD.LegalDesignationId = E.LegalDesignationId 
                                                                                                AND E.PlantId = gd.PlantId
																LEFT JOIN (
																			SELECT MAX(EffectiveDate) EffectiveDate, LegalSalaryGradeId, EmployeeLocationId 
																				FROM MST.LegalSalaryStructure 
																				WHERE EffectiveDate <= '31-OCT-2019'
																			GROUP BY LegalSalaryGradeId, EmployeeLocationId 
																		  ) S ON S.LegalSalaryGradeId = GD.LegalSalaryGradeId AND S.EmployeeLocationId = B.EmployeeLocationId
																LEFT JOIN MST.LegalSalaryStructure SS ON SS.LegalSalaryGradeId = S.LegalSalaryGradeId 
                                                                                            AND SS.EmployeeLocationId = S.EmployeeLocationId 
                                                                                            AND SS.EffectiveDate = S.EffectiveDate
																LEFT JOIN MST.LegalSalaryStructureValue SV ON SV.LegalSalaryStructureId = SS.Id 	
                                                                left join  [SCS].[LegalSalaryGrade] LSG ON LSG.Id=S.LegalSalaryGradeId	
														GROUP BY E.SystemId,LSG.UserName
													) MW ON MW.EmpSystemId = EmpBasic.SystemId
                                    INNER JOIN
											(
											 SELECT SPC.SystemID AS SlrProcChdSysID, SPC.SlrProcMstSystemID, SPM.SalaryProcID, SPM.FromDate, SPM.ToDate,
													SPC.EmpInfoSystemID, SPC.PlantID, SPM.UserGroupSystemID, SPM.MonthNo, SPM.YearNo, SPC.PayAbleShSystemID,
													SPC.SalaryHeadID, SPC.EntryCurrencyID, SPC.EntryAmount, SPC.DefineCurrencyID, SPC.DefineAmount,
													SPC.DisbusmentCurrencyID, SPC.DisbusmentAmount, SPC.AcltExcDisbSlrHDID, SPC.AcltExcDisbSlrHDAmt,
													CRE.Name AS PlantWiseExchangeCR, EXR.ToCurrencyBuying ExchangeRate, SPM.AmtDefinitionCurrencyID,
													CR.Name AS AmtDefinitionCurrency, SPM.AmtDefinitionCurrencyRate, SPC.IsNetPayEffect,SH.IsCTCComponent,SH.IsGrossComponent
                                                    ,sh.SalaryHead,BSH.Name SalaryHeadLocal,sh.HeadCategory,sh.HeadType,SH.PartOfNetPay
                                                    
											 FROM SalaryProcChild SPC
																INNER JOIN SalaryProcMaster SPM ON SPC.SlrProcMstSystemID = SPM.SystemID
																							AND SPM.SystemID IN( SELECT SystemID FROM SalaryProcMaster
                                      WHERE SystemID IN(SELECT SlrProcMstSystemID FROM SalaryProcChild
                                                        WHERE PlantID = '" + plantId + @"' GROUP BY SlrProcMstSystemID)
                                         " + getMonthYear(fromDate, toDate, "YearNo", "MonthNo") + @"
										)
                                                        LEFT JOIN SalaryHead sh on sh.SalaryHeadID=spc.SalaryHeadID
														--LEFT JOIN (select * from [MST].[PlantSalaryHeadSequence] where PlantId='201816' ) psh
																		-- psh.SalaryHeadId=spc.SalaryHeadID

														LEFT JOIN scs.Currency CR ON SPM.AmtDefinitionCurrencyID = CR.Id
														LEFT JOIN (
																   SELECT * FROM ExchangerateDateWiseForHR
																   WHERE FromDate IN (   SELECT MAX(FromDate) FromDate FROM SalaryProcMaster
																															   
																											WHERE SystemID IN( SELECT SystemID FROM SalaryProcMaster
                                      WHERE SystemID IN(SELECT SlrProcMstSystemID FROM SalaryProcChild
                                                        WHERE PlantID = '" + plantId + @"' GROUP BY SlrProcMstSystemID)
                                          " + getMonthYear(fromDate, toDate, "YearNo", "MonthNo") + @"
										)
                                                                                    )
																  ) EXR ON SPM.AmtDefinitionCurrencyID = EXR.FromCurrencyCode
																							AND SPC.PlantID = Exr.PlantID
														LEFT JOIN SCS.Currency CRE ON EXR.FromCurrencyCode = CRE.Id
                                            LEFT JOIN (SELECT * FROM HKP.LocalLanguage WHERE SalaryHeadId IS NOT NULL AND LanguageId = '') AS BSH ON BSH.SalaryHeadId = sh.SalaryHeadID
											) EmpSlr ON EmpBasic.SystemID = EmpSlr.EmpInfoSystemID AND EmpBasic.PlantID = EmpSlr.PlantID
                             	LEFT JOIN SalaryRuleMaster SRM ON SRM.SystemID = EmpBasic.SalaryRuleMasterSystemID 
										--LEFT JOIN SalaryRuleGeneral SRG ON SRG.SalaryRuleMasterSystemID = SRM.SystemID	AND SRG.SalaryHeadID = EmpSlr.SalaryHeadID									
                                        LEFT JOIN (SELECT * FROM [MST].[PlantSalaryHeadSequence] WHERE PlantId='201816' ) PSH
																		ON PSH.SalaryHeadId=EmpSlr.SalaryHeadID
                                        LEFT JOIN CurrencyRuleChild CRC ON CRC.MstSystemID = srm.CurrencyRuleSystemID AND CRC.SalaryHeadID = EmpSlr.SalaryHeadID
                                        	 LEFT JOIN  
												( select ed.DocNumber UANNo,ED.EmpSystemID from 
												EmployeeDocument ED 
												inner JOIN (select * from HKP.ComplianceDocument where ProfileType = 'PF') CD ON CD.Id = ED.ComplianceDocumentId 
												) pf on EmpBasic.SystemId = pf.EmpSystemID

												left join
												( select ed.DocNumber ESICNo,ED.EmpSystemID from 
												EmployeeDocument ED 
												inner JOIN (select * from HKP.ComplianceDocument where ProfileType = 'ESIC') CD ON CD.Id = ED.ComplianceDocumentId 
												) esic on EmpBasic.SystemId = esic.EmpSystemID

                                    LEFT JOIN
		                                    (
											 SELECT EmpSystemID, MonthNo, YearNo, TotalProcDate, TotalPresent, TotalLate,TotalLWP,
													TotalAbsent AbsentDays, TotalLv, TotalMLv, TotalCompAssignLv, TotalWeekOff, TotalHoliDay,
													TotalWeekOffHoliDay, TotalOTHr, TotalNormalOTHr, TotalExtraOTHr
				                              FROM AttdnDataMonthlySummary
											) MMDSA ON EmpSlr.EmpInfoSystemID = MMDSA.EmpSystemID AND EmpSlr.MonthNo = MMDSA.MonthNo AND
						                               EmpSlr.YearNo = MMDSA.YearNo
                                        WHERE   EmpBasic.SystemID  IN('" + empSystemId + @"')

										GROUP BY 

									EmpSlr.SalaryHeadID, EmpSlr.EntryCurrencyID,  EmpSlr.DefineCurrencyID,
                                EmpSlr.DisbusmentCurrencyID,
							
                                EmpSlr.PlantWiseExchangeCR, EmpSlr.ExchangeRate, EmpSlr.AmtDefinitionCurrencyID, EmpSlr.AmtDefinitionCurrency,
                                EmpSlr.AmtDefinitionCurrencyRate,EmpCategoryName,EmpSlr.HeadType,EmpSlr.IsCTCComponent,EmpSlr.IsGrossComponent
                                ,EmpSlr.SalaryHead,EmpSlr.HeadCategory,EmpSlr.HeadType,psh.Sequence,CRC.IntegerInDisb,CRC.DecimalNo,CRC.IsDecimalInDisb
                                , MW.SalaryHeadValue ,MW.Grade, EmpSlr.PartOfNetPay ,EmpSlr.SalaryHeadLocal,EmpBasic.SystemId,EmpBasic.EmployeeName,EmpBasic.FatherName,EmpBasic.GenderID,EmpBasic.Salutation";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception)
            {

                throw;
            }
        }


