            {
                obs = new clsStaticInfo();
                strSql = @"
					SELECT 
	                        LTR.EmpSystemID,LT.Code,LT.LeaveType
	                        ,SUM(LTD.LeaveDuration) AvailedLeave
                             FROM LeaveTransaction LTR                              
                            Inner   JOIN LeaveType LT ON  LTR.LTSystemID = LT.Id 
