        public void GetEmployeeData(string year, string empId, string plantId, out DataSet dsRef)
        {
            string yearNo = year;
            ConnectionManager.DAL.ConManager objCon;
            var strSql = string.Empty;
            clsStaticInfo obs = null;
            try
            {
                obs = new clsStaticInfo();
                strSql = @"SELECT E.SystemId EmpSystemId,ISNULL(FORMAT(E.DOS,'dd-MMM-yyyy'),'') DOS,E.EmployeeName,E.FatherName,E.EmployeeCode,P.PayDays,ISNULL(S.BroughtForward,0) + ISNULL(CarryForwardOpeningBalance,0) BroughtForward
                        ,ISNULL(S.CurrentYearAllocationAsPerPolicy,0) CurrentYearAllocationAsPerPolicy,ISNULL(S.CurrentYearAvailedOpeningBalance,0) CurrentYearAvailedOpeningBalance
                        ,ISNULL(L.LeaveDays,0) LeaveDays,[MonthName],U.UserName Unit, Dv.UserName Division, SEC.UserName Section, SB.UserName SubSection
                        ,LG.UserName Designation, DPT.UserName Department, FORMAT(ISNULL(E.DOJ,''),'dd-MMM-yyyy') DOJ, ISNULL(Party.Id,'') ContractorId,ISNULL(Party.UserName,'') ContractorName
                         FROM EmployeeInformation E
                         LEFT JOIN (
                         SELECT PayDays = ISNULL(TotalPresent,0) + ISNULL(TotalLate,0), EmpSystemID, FORMAT(FromDate,'MMM') [MonthName],FromDate FROM [dbo].[SalaryProceAttdnData] WHERE EmpSystemID='" + empId + @"' and YearNo='" + yearNo + @"' 
                         ) P ON P.EmpSystemID=E.SystemId
                         LEFT JOIN (
                         select A.LeaveYearId CalanderYearID,0 IsExceptionAllowed,a.Id SystemID,A.LeaveTypeId LTSystemID,A.EmployeeId EmployeeID,lt.UserName LeaveName, lt.Description LeaveDescription,lt.LeaveType
 ,FORMAT(LY.FromDate,'dd-MMM-yyyy')FromDate,FORMAT(LY.ToDate,'dd-MMM-yyyy')ToDate,A.Opening BroughtForward,0 CurrentYearAllocationAsPerPolicy, 0 CurrentYearAvailedOpeningBalance,0 CarryForwardOpeningBalance
from dbo.AnnualLeaveDataCurrent A
left outer join dbo.LeaveType lt on lt.Id = A.LeaveTypeId AND LeaveType='Earn'
LEFT JOIN dbo.LeaveYearDefination LY  ON LY.Id=A.LeaveYearId
Where LY.FromDate between'01-JAN-" + year+ @"' AND  '31-DEC-" + year + @"' AND LY.ToDate between'01-JAN-" + year + @"' AND  '31-DEC-" + year + @"' AND A.EmployeeId='" + empId + @"'
                         ) S ON S.EmployeeId=E.SystemId 
                         LEFT JOIN (
                            SELECT ISNULL(Sum(Ld.LeaveDuration),0) LeaveDays
                            ,L.EmpSystemID,MONTH(ld.WorkDate) dd,Year(ld.WorkDate) yy FROM LeaveTransaction L
                         LEFT JOIN LeaveTransactionDetails LD ON L.SystemID=LD.LvTrnsSystemID
                          Where EmpSystemID='" + empId + @"' AND LTSystemID=(SELECT Id FROM LeaveType WHERE LeaveType='Earn') and l.IsApproved = 1
                          GROUP By EmpSystemID,MONTH(ld.WorkDate),Year(ld.WorkDate)
                         ) L ON L.EmpSystemID=E.SystemId and dd = month(p.FromDate) and yy =  Year(p.FromDate)
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = e.BudgetCode
                            LEFT JOIN ORG.Position PR ON MB.PositionId=PR.Id
                            LEFT JOIN ORG.Entity EN ON MB.EntityId=EN.Id
                            left join mst.DesignationMasterLegalDesignation m on m.LegalDesignationId=e.LegalDesignationId
                        left join mst.DesignationMaster dm on dm.id=m.DesignationMasterId
                        left join hkp.EmployeeCategory ec on ec.Id = dm.EmployeeCategoryId
                        left join hkp.LegalDesignation LG on LG.Id = e.LegalDesignationId
						 LEFT JOIN ORG.Department DPT ON DPT.Id=PR.DepartmentId
						 LEFT JOIN ORG.Unit U ON En.UnitID = U.Id
                         LEFT JOIN ORG.Division Dv ON PR.DivisionID = Dv.Id
						 LEFT JOIN ORG.Section SEC ON PR.SectionID = SEC.Id
						 LEFT JOIN ORG.SubSection SB ON PR.SubSectionID = SB.Id
		                    LEFT JOIN HKP.Party Party ON Party.Id = E.VendorId
                         WHERE E.SystemId='" + empId + @"' ORDER BY P.FromDate ASC";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function 

