        /// <summary>
        /// Full and Final Settlement Report Query for indidual Employees those who are LEAVING the compnay
        /// </summary>
        /// <param name="gratuityCalcDate"></param>
        /// <param name="companyGroupId"></param>
        /// <param name="comapnyId"></param>
        /// <param name="plantId"></param>
        /// <param name="dsRef"></param>
        public void GetEmpFinalDischargeVoucherInfo(string calculationDate, string companyGroupId, string comapnyId, string plantId, string empSystemId, out DataSet dsRef)
        {

            ConnectionManager.DAL.ConManager objCon;
            var strSql = string.Empty;
            clsStaticInfo obs = null;
            try
            {
                obs = new clsStaticInfo();
                strSql = @"SELECT  A.EmployeeCode,DOJ
	                       ,CAST(DATEDIFF(mm, A.DOJ, '" + calculationDate + @"') AS varchar(4))/12 totalYear
	                       ,CAST(DATEDIFF(mm, A.DOJ, '" + calculationDate + @"') AS varchar(4))-(CAST(DATEDIFF(mm, A.DOJ, '" + calculationDate + @"') AS varchar(4))/12)*12 totalMonthAfterYear,* FROM
                          (
                           SELECT E.SystemID EmpSystemID, E.EmployeeCode, E.EmployeeName, REPLACE(Convert(VARCHAR(11), E.DOB, 106), ' ', '-') AS DOB,
	                              E.FatherName, E.MotherName, E.EmpType EmployeeType, E.EmploymentType EmploymentNature, E.NationalID,
	                              E.GenderID GenderName, REPLACE(Convert(VARCHAR(11), E.DOJ, 106), ' ', '-') AS DOJ,REPLACE(Convert(VARCHAR(11), E.DOS, 106), ' ', '-') AS DOS
	                              , REPLACE(Convert(VARCHAR(11), E.DOC, 106), ' ', '-') AS DOC, DG.UserName DesignationGroup, D.UserName Designation,
								  GVD.UserName GivenDesignation, L.UserName Line, U.UserName Unit, Dv.UserName Division, Dp.UserName Department,
								  S.UserName Section, SB.UserName SubSection, EC.UserName AS EmpCategory, Cm.UserName CompanyName,Cm.Id CompanyId, CAM.Address1,
	                              CAM.Address2, E.EmployeeCategorySystemID, EN.UnitID, PR.DivisionID, PR.DepartmentID, DM.DesignationID,
	                              PR.SectionID, PR.SubSectionID, MB.LineID, DM.DesignationGroupID, E.SubSecStrucSystemID, E.EmployeeStatus,
	                              P.UserName PlantName, (PAM.[Address1] + ', ' + PAM.[Address2] + ', ' + PAMC.UserName + ' - ' + PAM.Postcode) FactoryAddress,
	                              GC.Id GroupID,GC.UserName GroupName, (CGAM.[Address1] + ', ' + CGAM.[Address2] + ', ' + CT.UserName + ' - ' + CGAM.Postcode + ', Contact: ' + CGAM.Phone) GroupAddress,
	                              E.PlantID, BK.UserName BankNameShort, E.BankAccNo, 
								  EmpSlr.SalaryHeadID, SH.SalaryHead, ISNULL(pSH.Sequence, 99) Sequence, SH.HeadType, SH.HeadCategory, EmpSlr.EntryCurrencyID, EmpSlr.EntryAmount,
	                              EmpSlr.DefineCurrencyID, EmpSlr.DefineAmount, EmpSlr.AmtDefinationCurrencyID, EmpSlr.AmtDefinationRate,
	                              SH.IsCTCComponent, SH.IsGrossComponent, EmpSlr.EmpInfoSystemID, MW.SalaryHeadValue

                                , ISNULL(vpf.VoluntaryPFValue,0) VoluntaryPFValue
                                ,VPFhead.HeadCategory xHeadCategory,VPFhead.SalaryHeadID xSalaryHeadID
                                ,VPFhead.SalaryHead xSalaryHead,VPFhead.IsCTCComponent xIsCTCComponent
                                ,VPFhead.IsGrossComponent xIsGrossComponent,VPFhead.HeadType xHeadType
                                ,VPFhead.SalaryRuleMasterSystemID xSalaryRuleMasterSystemID
	                            ,CRC.IntegerInDisb, CRC.DecimalNo, MW.Grade
				            FROM EmployeeInformation AS E
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = e.BudgetCode
                            LEFT JOIN ORG.Position PR ON MB.PositionId=PR.Id
                            LEFT JOIN ORG.Entity EN ON MB.EntityId=EN.Id
                                            LEFT JOIN ORG.Unit U ON EN.UnitID = U.Id
                                            LEFT JOIN ORG.Division Dv ON PR.DivisionID = Dv.Id
                                            LEFT JOIN ORG.Department Dp ON PR.DepartmentID = Dp.Id
                                            LEFT JOIN ORG.Section S ON PR.SectionID = S.Id
                                            LEFT JOIN ORG.SubSection SB ON PR.SubSectionID = SB.Id
                                            LEFT JOIN ORG.Line L ON E.LineID = L.Id
LEFT JOIN MST.DesignationMaster dm ON E.GivenDesignationId = dm.DesignationId
                                            LEFT JOIN HKP.DesignationGroup DG ON DM.DesignationGroupID = Dg.Id
                                            LEFT JOIN HKP.Designation GVD ON E.GivenDesignationId = GVD.Id
											LEFT JOIN ORG.Plant AS p ON E.PlantId = p.Id
											LEFT JOIN ORG.Company AS Cm ON E.CompanyID = Cm.Id
											LEFT JOIN ORG.CompanyGroup AS GC ON E.GroupID = GC.Id
											LEFT JOIN HKP.Bank AS BK ON E.BankSystemID = BK.Id
											LEFT JOIN MST.AddressMaster AS CAM ON Cm.AddressMasterId = CAM.Id
											LEFT JOIN MST.AddressMaster AS PAM ON P.AddressMasterId = PAM.Id
											LEFT JOIN MST.AddressMaster AS CGAM ON GC.AddressMasterId = CGAM.Id
											LEFT JOIN SCS.City AS PAMC ON PAM.CityId = PAMC.Id
											LEFT JOIN SCS.City AS CT ON CGAM.CityId = CT.Id
                                            LEFT JOIN
													(
													 SELECT ECT.Id, ECT.UserName, DM.DesignationId 
													  FROM [HKP].[EmployeeCategory] ECT
																	LEFT JOIN MST.DesignationMaster DM ON ECT.Id = DM.EmployeeCategoryId
													) EC ON EC.DesignationId = E.GivenDesignationId
											LEFT JOIN 
													(
													 SELECT E.SystemID, SUM(SV.SalaryHeadValue) SalaryHeadValue,LSG.UserName Grade
														FROM EmployeeInformation E   
																LEFT JOIN MST.ManpowerBudget b ON e.BudgetCode = b.Id
																LEFT JOIN MST.LegalSalaryGradeDesignation GD ON GD.LegalDesignationId = E.LegalDesignationId 
                                                                                                AND E.PlantId = gd.PlantId
																LEFT JOIN (
																			SELECT MAX(EffectiveDate)EffectiveDate, LegalSalaryGradeId, EmployeeLocationId 
																				FROM MST.LegalSalaryStructure 
																				WHERE EffectiveDate <= '" + calculationDate + @"'
																			GROUP BY LegalSalaryGradeId, EmployeeLocationId 
																		  ) S ON S.LegalSalaryGradeId = GD.LegalSalaryGradeId AND S.EmployeeLocationId = B.EmployeeLocationId
																LEFT JOIN MST.LegalSalaryStructure SS ON SS.LegalSalaryGradeId = S.LegalSalaryGradeId 
                                                                                            AND SS.EmployeeLocationId = S.EmployeeLocationId 
                                                                                            AND SS.EffectiveDate = S.EffectiveDate
																LEFT JOIN MST.LegalSalaryStructureValue SV ON SV.LegalSalaryStructureId = SS.Id 	
                                                                left join  [SCS].[LegalSalaryGrade] LSG ON LSG.Id=S.LegalSalaryGradeId	
														GROUP BY E.SystemId,LSG.UserName
													) MW ON MW.SystemId = E.SystemId

										LEFT JOIN (
													SELECT * FROM
																(
																 SELECT MST.EmpInfoSystemID, EmpSlr.SalaryHeadID, EmpSlr.EntryCurrencyID, EmpSlr.EntryAmount, EmpSlr.DefineCurrencyID, EmpSlr.DefineAmount, 
																		EmpSlr.AmtDefinitionCurrencyID AmtDefinationCurrencyID, EmpSlr.AmtDefinitionRate AmtDefinationRate, MST.SalaryRuleMasterSystemID
																 FROM SalaryInfoDefine EmpSlr
																		INNER JOIN SalaryInfoDefineMaster MST ON EmpSlr.SalaryID = MST.SystemID AND MST.IsApproved = 1
																) A
																UNION 
																(
																SELECT M.EmpSystemID EmpInfoSystemID, D.SalaryHeadID, CRC.AmtEntryCurrency EntryCurrencyID, D.Value EntryAmount,
																		CRC.AmtDefinitionCurrency DefineCurrencyID, D.Value DefineAmount, CRC.AmtDefinitionCurrency AmtDefinationCurrencyID,
																		1 AmtDefinationRate, MST.SalaryRuleMasterSystemID
																FROM [BonusPolicyMonthlyRetainStrcEmpWiseCalculation] M
																		INNER JOIN [BonusPolicyMonthlyRetainDistributionStrcPmt] D ON M.ID = D.BnsPlyMntRetainID
																		INNER JOIN SalaryInfoDefineMaster MST ON M.EmpSystemID = MST.EmpInfoSystemID AND MST.IsApproved = 1
																		LEFT JOIN SalaryRuleMaster SRM ON SRM.SystemID = MST.SalaryRuleMasterSystemID
																		LEFT JOIN CurrencyRuleChild CRC ON CRC.MstSystemID = SRM.CurrencyRuleSystemID AND CRC.SalaryHeadID = D.SalaryHeadID
															
                                                                                                                            --Dada
                                                                                                                            --WHERE EOMONTH(DATEFROMPARTS(M.YearNo, M.MonthNo, 1)) IN (SELECT MAX(EOMONTH(DATEFROMPARTS(YearNo, MonthNo, 1))) 
																															--FROM [BonusPolicyMonthlyRetainEmpWiseCalculation] 
																		WHERE M.MonthNo = DATEPART(MONTH,'" + calculationDate + @"') AND M.YearNo = DATEPART(YEAR,'" + calculationDate + @"')													--WHERE CONVERT(DATE, EOMONTH(DATEFROMPARTS(YearNo, MonthNo, 1))) <= CONVERT(DATE, '" + calculationDate + @"'))

																)
													) EmpSlr ON E.SystemID = EmpSlr.EmpInfoSystemID
										LEFT JOIN SalaryHead SH ON SH.SalaryHeadID = EmpSlr.SalaryHeadID
										LEFT JOIN (SELECT * FROM [MST].[PlantSalaryHeadSequence] WHERE PlantId='" + plantId + @"') PSH ON PSH.SalaryHeadId = EmpSlr.SalaryHeadID
										
										LEFT JOIN SalaryRuleMaster SRM ON SRM.SystemID = EmpSlr.SalaryRuleMasterSystemID
										LEFT JOIN CurrencyRuleChild CRC ON CRC.MstSystemID = srm.CurrencyRuleSystemID AND CRC.SalaryHeadID = SH.SalaryHeadID

                                        LEFT JOIN (
										 		   SELECT EmpSystemId,MAX(EffectiveDate) EffectiveDate, VoluntaryPFValue 
												     FROM [PFEmployeeVoluntaryValue] 
													 WHERE EffectiveDate<='" + calculationDate + @"'
												   GROUP BY EmpSystemId,EffectiveDate,VoluntaryPFValue
												  ) VPF ON E.SystemId = vpf.EmpSystemId
										LEFT JOIN(
										SELECT SH.HeadCategory, SH.SalaryHeadID, SH.SalaryHead, SH.IsCTCComponent, SH.IsGrossComponent, SH.HeadType, 
											   SR.SalaryRuleMasterSystemID
											  FROM [dbo].[SalaryRulePF] SR
											  LEFT JOIN SalaryHead SH ON SH.SalaryHeadID=SR.SalaryHeadID
											  WHERE SH.HeadCategory='PF Voluntary'
										) VPFhead ON VPFhead.SalaryRuleMasterSystemID = EmpSlr.SalaryRuleMasterSystemID

                                       
                                                 ) A  WHERE EmployeeStatus = 'Active' AND
                            ISNULL(EmpInfoSystemID,'')<>''  AND GroupID = '" + companyGroupId + @"' 
                            AND  CompanyId ='" + comapnyId + @"' AND PlantId ='" + plantId + @"'
	                        AND HeadCategory = 'Basic'	AND CAST(DATEDIFF(mm, A.DOJ, '" + calculationDate + @"') AS varchar(4))/12 >= 5
                                 AND EmpSystemID IN (" + empSystemId + @")
                                                ORDER BY A.EmployeeCode";
                strSql = strSql + @"";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function
        /// <summary>
        /// Leave Encashment Info
        /// </summary>
        /// <param name="calculationDate"></param>
        /// <param name="companyGroupId"></param>
        /// <param name="comapnyId"></param>
        /// <param name="plantId"></param>
        /// <param name="empSystemId"></param>
        /// <param name="dsRef"></param>
        public void GetEmpLeaveEncashmentInfo(string fromDate, string toDate, string companyGroupId, string comapnyId, string plantId, string empSystemId, out DataSet dsRef)
        {

            ConnectionManager.DAL.ConManager objCon;
            var strSql = string.Empty;
            clsStaticInfo obs = null;
            try
            {
                obs = new clsStaticInfo();
                strSql = @"SELECT
                                    ls.EmployeeId
		                            ,EI.EmployeeName
									,convert (int, EI.EmployeeCode) EmployeeCode 
									,EI.FatherName
									,REPLACE(Convert(VARCHAR(11), EI.DOB, 106), ' ', '-') AS  DOB
                                    ,REPLACE (Convert(VARCHAR(11), Ei.DOJ, 106), ' ', '-') AS  DOJ 
                                    ,SD.EntryAmount  
                                    ,ei.SystemId
		                            ,L.Code
		                            ,isnull (LS.DaysCanBeSanctioned ,0) DaysCanBeSanctioned	
		                            ,L.LeaveType	
		                            ,ls.LeaveTypeId
									,isnull (Btn.AVL,0)  availebal
									,(DaysCanBeSanctioned-isnull(Btn.AVL,0)) ELbalance
									,(SD.EntryAmount )/26*(DaysCanBeSanctioned-isnull (Btn.AVL,0)) Amount
									,LD.IsProrataPreviousyear
                                    ,LD.IsProratacurrentyear
                                    ,LD.IsAvailExceptionAllowedOnSpecialAppeal
                                    ,LS.CurrentYearAllocation
                                    ,LS.PreviousYearCarryForward PreviousYearCarryForward
                                    ,LS.AppliedDays
                  FROM TRN.EmployeeLeaveSummary LS
                  Left join EmployeeInformation EI ON EI.SystemId=ls.EmployeeId
                  LEFT JOIN LeaveType  L ON L.Id=LS.LeaveTypeId
				  left join  SalaryInfoDefineMaster sm ON  sm.EmpInfoSystemID=EI.SystemId
		          left join SalaryInfoDefine sd ON sd.SalaryID=sm.SystemID
		          left join SalaryHead sh ON sh.SalaryHeadID=sd.SalaryHeadID

                  left join (
				  SELECT m.DesignationId,d.LTSystemID,IsProrataPreviousyear,IsAvailExceptionAllowedOnSpecialAppeal,IsProratacurrentyear
				  FROM mst.DesignationMaster m
				  left join scs.DesignationMasterConfiguration c ON m.id=c.DesignationMasterId and c.PlantId='" + plantId + @"'
				  left join LeavePolicyDetail d ON d.LPMSystemID=c.LeavePolicyMasterId
				 ) LD ON  LD.LTSystemID=LS.LeaveTypeId and ld.DesignationId=ei.GivenDesignationId

		         -------------*************** availed between --------start----------		 
                  LEFT JOIN 
					(
						SELECT LT.EmpSystemID x,ls.LeaveTypeId LTSystemID,ls.EmployeeId EmpSystemID,ls.CurrentYearAvailedOpeningBalance
						,ISNULL(SUM(d.LeaveDuration),0)+ls.CurrentYearAvailedOpeningBalance AVL
						from  TRN.EmployeeLeaveSummary LS
						LEFT JOIN LeaveTransaction LT  ON LS.LeaveTypeId=LT.LTSystemID and ls.EmployeeId=lt.EmpSystemID
						LEFT JOIN (SELECT * FROM LeaveTransactionDetails WHERE WorkDate  BETWEEN CONVERT(DATE,'" + fromDate + @"') AND CONVERT(DATE,'" + toDate + @"') AND IsAvailed=1  ) D on D.LvTrnsSystemID=LT.SystemID


                        GROUP BY  LT.EmpSystemID,ls.LeaveTypeId,ls.EmployeeId ,ls.CurrentYearAvailedOpeningBalance
				    ) 
					  Btn ON Btn.EmpSystemID = ls.EmployeeId AND Btn.LTSystemID = ls.LeaveTypeId
                ------------ - ***************availed between-------- end----------
                left join

                  (SELECT LT.EmpSystemID, lt.LTSystemID, SUM(d.LeaveDuration) LAA FROM LeaveTransaction LT
                  LEFT JOIN LeaveTransactionDetails D ON D.LvTrnsSystemID= LT.SystemID
                  WHERE d.WorkDate > CONVERT(DATE,'" + toDate + @"') AND D.IsAvailed = 1
                  GROUP BY  LT.EmpSystemID,lt.LTSystemID) A ON A.EmpSystemID = ls.EmployeeId AND A.LTSystemID = ls.LeaveTypeId
                  WHERE EI.GroupID = '" + companyGroupId + @"'
                            AND EI.CompanyId = '" + comapnyId + @"' AND EI.PlantId = '" + plantId + @"'

                            AND ls.EmployeeId IN
                                        (SELECT lt.EmpSystemID
                                        FROM  LeaveTransaction LT

                                        LEFT JOIN LeaveTransactionDetails D on D.LvTrnsSystemID= LT.SystemID

                                        WHERE d.WorkDate BETWEEN CONVERT(DATE,'" + fromDate + @"') AND CONVERT(DATE,'" + toDate + @"') AND D.IsAvailed = 1
										)
                 AND SH.HeadCategory = 'Basic' AND L.LeaveType = 'Earn'
                 AND ls.EmployeeId IN(" + empSystemId + @")";
                strSql = strSql + @"";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function
        /// <summary>
        /// Employee Wise Bonus Informations
        /// </summary>
        /// <param name="fromDate"></param>
        /// <param name="toDate"></param>
        /// <param name="companyGroupId"></param>
        /// <param name="comapnyId"></param>
        /// <param name="plantId"></param>
        /// <param name="empSystemId"></param>
        /// <param name="dsRef"></param>
        public void GetEmpWiseBonusInfo(string calcDate, string companyGroupId, string comapnyId, string plantId, string empSystemId, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            var strSql = string.Empty;
            clsStaticInfo obs = null;
            try
            {
                obs = new clsStaticInfo();
                strSql = @"SELECT m.EmpSystemID,m.MonthNo,d.Value Bonus 
												 ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
												,SH.IsGrossComponent,SH.HeadType
												FROM [BonusPolicyMonthlyRetainEmpWiseCalculation] m
												LEFT JOIN [BonusPolicyMonthlyRetainDistributionPmt] d ON m.id=d.BnsPlyMntRetainID
												LEFT JOIN SalaryHead SH ON SH.SalaryHeadID=d.SalaryHeadID
												WHERE m.MonthNo=DATEPART(Month,'" + calcDate + "')  AND m.YearNo=DATEPART(YEAR,'" + calcDate + "')  and m.EmpSystemID =" + empSystemId + " ";
                strSql = strSql + @"";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function

        public void GetSalaryInfoSlrProcIDWiseForRegister(ParamList para, string paymentMode, string languageId, string sqlInStatement, string sortingParameters, bool isActive, bool isSeperated, bool isMaternity, out DataSet dsRef)
        {

            var salaryProcessSystemId = "";
            string wcEmpStatus = " (1=0 ";
            if (isActive == true && isSeperated == true && isMaternity == true)
            {
                wcEmpStatus = " (1=1 ";
            }
            else
            {
                if (isActive == true)
                {
                    wcEmpStatus += " OR SalaryProcFlag ='Regular' ";
                }
                if (isSeperated == true)
                {
                    wcEmpStatus += " OR SalaryProcFlag ='SEPARATED'";
                }
                if (isMaternity == true)
                {
                    wcEmpStatus += " OR SalaryProcFlag ='MLV_PRE'";

                }
            }
            wcEmpStatus += ") AND";
            if (!string.IsNullOrEmpty(para.SalaryProcessId) && para.SalaryProcessId != "undefined" && para.SalaryProcessId != "null")
            {
                salaryProcessSystemId = "SystemId IN ('" + para.SalaryProcessId + @"')";
            }
            else
            {
                //salaryProcessSystemId = @"SystemId IN( SELECT SystemID FROM SalaryProcMaster
                //                      WHERE SystemID IN(SELECT SlrProcMstSystemID FROM SalaryProcChild
                //                                        WHERE PlantID = '" + para.PlantId + @"' GROUP BY SlrProcMstSystemID)
                //                        AND MonthNo = Month('" + para.FromDate + "') AND YearNo = Year('" + para.FromDate + "')  and IsCompleteMonth = 1)";


                salaryProcessSystemId = "' '";

                DataTable dtSalPrcId = _sqlRepository.GetDataTable(@"SELECT SystemID FROM SalaryProcMaster
                                      WHERE SystemID IN(SELECT SlrProcMstSystemID FROM SalaryProcChild
                                                        WHERE PlantID = '" + para.PlantId + @"' GROUP BY SlrProcMstSystemID)
                                        AND MonthNo =  MONTH('" + para.FromDate + @"') AND YearNo =  YEAR('" + para.FromDate + @"') and IsCompleteMonth = 1 ");

                for (int si = 0; si < dtSalPrcId.Rows.Count; si++)
                {
                    salaryProcessSystemId += ",'" + dtSalPrcId.Rows[si]["SystemID"].ToString() + "'";
                }

            }
            string strSQL;
            ConnectionManager.DAL.ConManager objCon;

            var _wc = string.Empty;

            if (para.EmployeeId != "" && para.EmployeeId != null)
            {
                _wc = "  SYSTEMID IN (" + para.EmployeeId + @")";
            }
            else
            {
                if (para.PayGroup.ToUpper() != "NO GROUP" && para.PayGroup != "null")
                {
                    _wc = @"AND EmpInfoSystemID  IN (SELECT employeeid from MST.PayrollGroupMaster where PayrollGroupId = '" + para.PayGroup + @"')";
                }
                if (para.PayGroup.ToUpper() == "NO GROUP")
                {
                    _wc = @"AND EmpInfoSystemID NOT IN ( SELECT employeeid from MST.PayrollGroupMaster)";
                }
                if (para.PayGroup.ToUpper() == "ALL")
                {
                    _wc = @"";
                }

            }

            try
            {

                strSQL = @"SELECT EmpSlr.EmpInfoSystemID,convert(int, EmpBasic.EmployeeCode)EmployeeCode, EmpBasic.EmployeeName, ISNULL(EmpBasic.EmployeeNameLocal,EmpBasic.EmployeeName) EmployeeNameLocal,Replace(Convert(varchar(11),EmpBasic.DOJ,106),' ','-') DOJ
                                , REPLACE(Convert(VARCHAR(11), EmpBasic.DOB, 106), ' ', '-') AS DOB,REPLACE(Convert(VARCHAR(11), EmpBasic.DOS, 106), ' ', '-') AS DOS,
                                EmpBasic.EmployeeStatus, EmpBasic.UnitID, EmpBasic.UnitName, EmpBasic.DivisionID, EmpBasic.DivisionName,
                                EmpBasic.DepartmentID, EmpBasic.DepartmentName, EmpBasic.SectionID, EmpBasic.SectionName, EmpBasic.SubSectionID,EmpBasic.SubDivision,EmpBasic.SubdivisionID,
                                EmpBasic.SubSectionName, EmpBasic.EmployeeCategorySystemID, EmpBasic.EmpCategoryName, EmpBasic.DesignationGroupName,
                                EmpBasic.DesignationSystemID, EmpBasic.DesignationName,EmpBasic.GivenDesignationName,EmpBasic.GivenDesignationGroup
                                ,EmpBasic.PlantName,EmpBasic.EmployeeCodePreFix,EmpBasic.EmployeeCodeNumeric,EmpBasic.LDDesignationGD,EmpBasic.EmployeeCategorySequence
		                        ,ISNULL(EmpBasic.DesignationLocal, EmpBasic.LDDesignationGD) DesignationLocal,EmpBasic.GradeCode,EmpBasic.FatherName
                                ,esic.ESICNo,pf.UANNo,bb.BankAccNo,bb.BankName, '' BankNameFull,ISNULL(MMDSA.TotalProcDate,0) TotalProcDate,ISNULL(MMDSA.TotalLate, 0) TotalLate
								,(ISNULL(MMDSA.TotalPresent, 0) + ISNULL(MMDSA.TotalLate, 0)) PresentDays,PaymentMode,
								ISNULL(MMDSA.AbsentDays, 0) AbsentDays,  ISNULL(MMDSA.TotalHoliDay + MMDSA.TotalWeekOffHoliDay,0) HoliDay, ISNULL(MMDSA.TotalWeekOff, 0) WeekOff,
								(ISNULL(MMDSA.TotalLv, 0) + ISNULL(MMDSA.TotalMLv, 0)) LeaveDays,ISNULL(MMDSA.TotalLWP,0) LWP, EmpSlr.SlrProcChdSysID, EmpSlr.SlrProcMstSystemID, EmpSlr.SalaryProcID,
                                EmpSlr.PlantID, EmpSlr.FromDate, EmpSlr.ToDate, EmpSlr.MonthNo, EmpSlr.YearNo, EmpSlr.PayAbleShSystemID,
                                EmpSlr.SalaryHeadID, EmpSlr.EntryCurrencyID, EmpSlr.EntryAmount, EmpSlr.DefineCurrencyID, EmpSlr.DefineAmount,
                                EmpSlr.DisbusmentCurrencyID, EmpSlr.DisbusmentAmount, EmpSlr.AcltExcDisbSlrHDID, EmpSlr.AcltExcDisbSlrHDAmt,
                                EmpSlr.PlantWiseExchangeCR, EmpSlr.ExchangeRate, EmpSlr.AmtDefinitionCurrencyID, EmpSlr.AmtDefinitionCurrency,
                                EmpSlr.AmtDefinitionCurrencyRate, EmpSlr.IsNetPayEffect,EmpSlr.PartOfNetPay
                                ,EmpSlr.SalaryHead,ISNULL(EmpSlr.SalaryHeadBangla,EmpSlr.SalaryHead) SalaryHeadBangla,EmpSlr.HeadCategory,EmpSlr.HeadType,EmpSlr.Sequence,EmpSlr.IsCTCComponent,EmpSlr.IsGrossComponent

                                , ISNULL(vpf.VoluntaryPFValue,0) VoluntaryPFValue
                                , ISNULL(BonusValue.Bonus,0) Bonus

								, BonusValue.SalaryHead B_SalaryHead
								, BonusValue.SalaryHeadID B_SalaryHeadID
								, BonusValue.IsCTCComponent B_IsCTCComponent
								, BonusValue.IsGrossComponent B_IsGrossComponent
								, BonusValue.HeadType B_HeadType
								--, BonusValue.HeadCategory B_HeadCategory

                                ,VPFhead.HeadCategory xHeadCategory,VPFhead.SalaryHeadID xSalaryHeadID
                                ,VPFhead.SalaryHead xSalaryHead,VPFhead.IsCTCComponent xIsCTCComponent
                                ,VPFhead.IsGrossComponent xIsGrossComponent,VPFhead.HeadType xHeadType
                                ,VPFhead.SalaryRuleMasterSystemID xSalaryRuleMasterSystemID
                                ---,VPFhead.IntegerInDisb, VPFhead.DecimalNo,
                                ,MW.Grade,CONVERT(DECIMAL(10, 2), ISNULL(MMDSA.TotalOTHr,0)/60) TotalOTHr
                                ,EmpSlr.DecimalNo AS DecimalNo ,EmpSlr.IntegerInDisb AS IntegerInDisb,EmpSlr.IsDecimalInDisb AS IsDecimalInDisb
                                ,EmpBasic.Line,EmpBasic.LegalDesignation
                                ,EmpSlr.SalaryProcFlag
	                            ,EmpBasic.OverTimePmtPolicyMasterID
								,otd.FormulaDesID,otd.FormulaDes
								,ISNULL(EmpBasic.IsOTEntitle,0) IsOTEntitle
                              ,EmpBasic. LineId,EmpBasic.DesignationGroupId
                                ,EmpBasic.DesignationSequence,EmpBasic.PlantSequence,EmpBasic.UnitSequence,EmpBasic.DivisionSequence,EmpBasic.SubDivisionSequence,EmpBasic.DepartmentSequence
                                 ,SectionSequence,SubSectionSequence,EntitySequence,LineSequence
                                FROM
                                    (
									 SELECT E.SystemID,E.EmployeeCodePreFix,E.EmployeeCodeNumeric,CONVERT(INT, E.EmployeeCode)EmployeeCode, E.EmployeeName,E.EmployeeNameLocal,E.FatherName, E.DOJ,E.DOB,E.DOS, E.EmployeeStatus,E.PaymentMode,
											DG.UserName DesignationGroupName, E.DesignationSystemID, DE.UserName DesignationName,GVDE.UserName GivenDesignationName,GVDE.Sequence DesignationSequence,
											'' UserGroupSystemID, E.PlantID, F.UserName PlantName, F.Sequence PlantSequence, E.UnitID
											,FU.UserName UnitName,FU.Sequence UnitSequence, E.DivisionID, DV.UserName DivisionName,DV.Sequence DivisionSequence,E.SubdivisionID,subDV.UserName SubDivision,subDV.Sequence SubDivisionSequence, E.DepartmentID, DP.UserName DepartmentName,DP.Sequence DepartmentSequence,
											E.SectionID, S.UserName SectionName,S.Sequence SectionSequence, E.SubSectionID, SS.UserName SubSectionName,SS.Sequence SubSectionSequence, E.EmployeeCategorySystemID,
											EC.UserName EmpCategoryName,EC.Sequence EmployeeCategorySequence--, BK.BankNameShort BankName, BK.BankNameFull, E.BankAccNo
                                            ,ENT.UserName EntitySequence,egdsgg.GivenDesignationGroup,e.SalaryRuleMasterSystemID,L.UserName Line, LD.UserName LegalDesignation--,eoe.IsOTEntitle
											,IsOTEntitle = Case  when ISNULL(EOE.IsOTEntitle,0) =1 then EOE.IsOTEntitle else ISNULL(DMCT.IsOTEntitled,0) end
										 , ISNULL(LD.UserName,GVD.UserName) LDDesignationGD,LSalGr.Code GradeCode
		                                  , ISNULL(LocLangLD.Name,LocLangGD.Name) DesignationLocal
											,OverTimePmtPolicyMasterID=case when isnull(eoe.EmpSystemID,'')<>'' then (select id from OverTimePmtPolicyMaster where IsDefault=1)
											when DMCT.IsOTEntitled=1 and isnull(DMCT.OverTimePmtPolicyMasterID,'')<>'' then DMCT.OverTimePmtPolicyMasterID
											else null end,E.LineId,EGDSGG.DesignationGroupId,L.Sequence LineSequence
                                     
                                           FROM EmployeeInformation E
												LEFT JOIN org.Plant F ON E.PlantID = F.Id
												LEFT JOIN hkp.DesignationGroup DG ON E.DesignationGroupId = DG.ID
												LEFT JOIN hkp.Designation DE ON E.GivenDesignationId = DE.Id
												LEFT JOIN hkp.Designation GVDE ON E.GivenDesignationId = GVDE.Id
												LEFT JOIN org.Unit FU ON E.UnitID = FU.Id
												LEFT JOIN org.Division DV ON E.DivisionID = DV.Id
												LEFT JOIN org.Department DP ON E.DepartmentID = DP.Id
												LEFT JOIN org.Section S ON E.SectionID = S.Id
												LEFT JOIN org.SubSection SS ON E.SubSectionID = SS.Id
                                                LEFT JOIN org.Line L ON L.Id = E.LineId
                                                LEFT  JOIN [MST].[ManpowerBudget] AS MB  on MB.Id = E.BudgetCode
								                LEFT  JOIN ORG.Entity AS ENT ON ENT.Id = MB.EntityId
												LEFT JOIN HKP.LegalDesignation LD ON LD.Id=E.LegalDesignationId
												LEFT JOIN HKP.Designation GVD ON GVD.Id=E.GivenDesignationId
                                                LEFT JOIN MST.LegalSalaryGradeDesignation LSGD ON LSGD.LegalDesignationId = LD.Id
                                              LEFT JOIN SCS.LegalSalaryGrade LSalGr ON LSalGr.Id = LSGD.LegalSalaryGradeId
												LEFT JOIN org.SubDivision subDV ON E.SubdivisionID = subDV.Id
												LEFT JOIN
                                                --hkp.EmployeeCategory EC ON E.EmployeeCategorySystemID = EC.Id
                                                (
                                                SELECT ECT.Id, ECT.UserName,ECT.Sequence , DM.DesignationId FROM [HKP].[EmployeeCategory] ECT
												LEFT JOIN MST.DesignationMaster DM ON ECT.Id=DM.EmployeeCategoryId
												)EC ON EC.DesignationId=E.GivenDesignationId
												LEFT JOIN (SELECT dm.DesignationGroupId,dm.DesignationId,dm.EmployeeCategoryId
									            ,DG.UserName GivenDesignationGroup
									            FROM MST.DesignationMaster DM
									            LEFT JOIN HKP.DesignationGroup DG ON DG.Id=DM.DesignationGroupId
									            ) EGDSGG ON EGDSGG.DesignationId=e.GivenDesignationId
									            AND EGDSGG.EmployeeCategoryId=e.EmployeeCategorySystemID
                                               LEFT JOIN EmployeeOTEntitle EOE ON EOE.EmpSystemID = E.SystemId AND EOE.IsOTEntitle=1
												LEFT JOIN  MST.DesignationMaster DMOT ON DMOT.DesignationId = E.GivenDesignationId
												LEFT JOIN  SCS.DesignationMasterConfiguration DMCT ON DMCT.DesignationMasterId = DMOT.Id and DMCT.plantid='" + para.PlantId + @"'
												 LEFT JOIN HKP.LocalLanguage LocLangLD ON LocLangLD.LegalDesignationId = E.LegalDesignationId AND LocLangLD.LanguageId = '" + para.LanguageId + @"'
                                                LEFT JOIN HKP.LocalLanguage LocLangGD ON LocLangGD.DesignationId = E.GivenDesignationId AND LocLangGD.LanguageId = '" + para.LanguageId + @"'
                              
									) EmpBasic
									LEFT JOIN (select * from OverTimePmtPolicyDetails where OverTimeDayType='Working Day') otd on otd.OverTimePmtPolicyID=EmpBasic.OverTimePmtPolicyMasterID

                                    INNER JOIN
											(
											 SELECT SPC.SystemID AS SlrProcChdSysID, SPC.SlrProcMstSystemID, SPM.SalaryProcID, SPM.FromDate, SPM.ToDate,
													SPC.EmpInfoSystemID, SPC.PlantID, SPM.UserGroupSystemID, SPM.MonthNo, SPM.YearNo, SPC.PayAbleShSystemID,
													SPC.SalaryHeadID, SPC.EntryCurrencyID, SPC.EntryAmount, SPC.DefineCurrencyID, SPC.DefineAmount,
													SPC.DisbusmentCurrencyID, SPC.DisbusmentAmount, SPC.AcltExcDisbSlrHDID, SPC.AcltExcDisbSlrHDAmt,
													CRE.Name AS PlantWiseExchangeCR, EXR.ToCurrencyBuying ExchangeRate, SPM.AmtDefinitionCurrencyID,
													CR.Name AS AmtDefinitionCurrency, SPM.AmtDefinitionCurrencyRate, SPC.IsNetPayEffect,SH.PartOfNetPay
                                                    ,SH.SalaryHead,BSH.Name SalaryHeadBangla,sh.HeadCategory,sh.HeadType,isnull(psh.Sequence, 99) Sequence
                                                    ,SH.IsCTCComponent,sh.IsGrossComponent,dcm.DecimalNo,dcm.IntegerInDisb,dcm.IsDecimalInDisb
                                           , CASE WHEN ISNULL(SPM.SalaryProcFlag,'') = '' THen 'Regular' else SalaryProcFlag end SalaryProcFlag

											 FROM SalaryProcChild SPC
														INNER JOIN SalaryProcMaster SPM ON SPC.SlrProcMstSystemID = SPM.SystemID
																							AND SPM.SystemId IN (" + salaryProcessSystemId + @")

	                                                   INNER JOIN SalaryProcessLogDetail SPLD ON SPLD.SalaryProcessId  IN (" + salaryProcessSystemId + @")
                                                        and spld.EmpSystemId = spc.EmpInfoSystemID and spld.PlantId ='" + para.PlantId + @"'
                                                        LEFT JOIN SalaryHead sh on sh.SalaryHeadID=spc.SalaryHeadID
                                                        LEFT JOIN (SELECT * FROM HKP.LocalLanguage WHERE SalaryHeadId IS NOT NULL AND LanguageId = '" + languageId + @"') AS BSH ON BSH.SalaryHeadId = sh.SalaryHeadID --BanglaSalaryHead
														LEFT JOIN (SELECT * from [MST].[PlantSalaryHeadSequence] where PlantId='" + para.PlantId + @"' ) PSH
																		ON PSH.SalaryHeadId=spc.SalaryHeadID

														LEFT JOIN scs.Currency CR ON SPM.AmtDefinitionCurrencyID = CR.Id
														LEFT JOIN (
																   SELECT * FROM ExchangerateDateWiseForHR
																   WHERE FromDate IN (
																					  SELECT MAX(FromDate) FromDate FROM ExchangerateDateWiseForHR
																						WHERE FromDate <= (
																										   SELECT MAX(FromDate) FromDate FROM SalaryProcMaster
																											WHERE SystemId IN ( " + salaryProcessSystemId + @")
                                                                                                             
                                                                                                           )
                                                                                    )
																  ) EXR ON SPM.AmtDefinitionCurrencyID = EXR.FromCurrencyCode
																							AND SPC.PlantID = Exr.PlantID
														LEFT JOIN scs.Currency CRE ON EXR.FromCurrencyCode = CRE.Id
                                                  ------    for decimal part       ---------
														 LEFT JOIN
                                               ( SELECT SSM.EmpInfoSystemID,crc.SalaryHeadID,crc.DecimalNo,crc.IntegerInDisb,crc.IsDecimalInDisb
												FROM SalaryInfoDefineMaster SSM
												left join SalaryRuleMaster srm on srm.SystemID=SSM.SalaryRuleMasterSystemID
												left join CurrencyRuleMaster crm on crm.SystemID=srm.CurrencyRuleSystemID
												left join CurrencyRuleChild crc on crc.MstSystemID=crm.SystemID) dcm on  dcm.SalaryHeadID=SPC.SalaryHeadID  and SPC.EmpInfoSystemID=dcm.EmpInfoSystemID
												      -------   end decimal part-------
											) EmpSlr ON EmpBasic.SystemID = EmpSlr.EmpInfoSystemID AND EmpBasic.PlantID = EmpSlr.PlantID
                                LEFT JOIN (
										
												  SELECT EmpSystemId,MAX(EffectiveDate) EffectiveDate, VoluntaryPFValue from [PFEmployeeVoluntaryValue] 
												  Where EffectiveDate<='" + para.FromDate + @"'
												  Group By EmpSystemId,EffectiveDate,VoluntaryPFValue
										) VPF ON EmpBasic.SystemId=vpf.EmpSystemId

										LEFT JOIN(
										SELECT SH.HeadCategory ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
										,SH.IsGrossComponent,SH.HeadType,sr.SalaryRuleMasterSystemID
											  FROM [dbo].[SalaryRulePF] SR
											  LEFT JOIN SalaryHead SH ON SH.SalaryHeadID=SR.SalaryHeadID
											  WHERE SH.HeadCategory='PF Voluntary'
										) VPFhead ON VPFhead.SalaryRuleMasterSystemID=EmpBasic.SalaryRuleMasterSystemID

                                        LEFT JOIN
										(
										SELECT m.EmpSystemID,m.MonthNo,d.Value Bonus 
												--,SH.HeadCategory 
                                                ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
												,SH.IsGrossComponent,SH.HeadType
												FROM [BonusPolicyMonthlyRetainEmpWiseCalculation] m
												LEFT JOIN [BonusPolicyMonthlyRetainDistributionPmt] d on m.id=d.BnsPlyMntRetainID
												LEFT JOIN SalaryHead SH ON SH.SalaryHeadID=d.SalaryHeadID
												WHERE m.MonthNo=DATEPART(Month,'" + para.FromDate + @"')  AND m.YearNo=DATEPART(YEAR,'" + para.FromDate + @"')  
                                                --and d.SalaryHeadID=(select SalaryHeadID from SalaryHead where HeadCategory='Festival Bonus')
										) BonusValue ON EmpBasic.SystemId=BonusValue.EmpSystemID

                                    LEFT JOIN
		                                    (
											 SELECT EmpSystemID, MonthNo, YearNo, TotalProcDate, TotalPresent, TotalLate,
													TotalAbsent AbsentDays, TotalLv,TotalLWP, TotalMLv, TotalCompAssignLv, TotalWeekOff, TotalHoliDay,
													TotalWeekOffHoliDay, TotalOTHr, TotalNormalOTHr, TotalExtraOTHr
				                              FROM SalaryProceAttdnData
											) MMDSA ON EmpSlr.EmpInfoSystemID = MMDSA.EmpSystemID AND EmpSlr.MonthNo = MMDSA.MonthNo AND
						                               EmpSlr.YearNo = MMDSA.YearNo

                                    LEFT JOIN 
                                           		(
                                           		 SELECT E.SystemID, SUM(SV.SalaryHeadValue) SalaryHeadValue,LSG.UserName Grade
                                           			FROM EmployeeInformation E   
                                           					LEFT JOIN MST.ManpowerBudget b ON e.BudgetCode = b.Id
                                           					LEFT JOIN MST.LegalSalaryGradeDesignation GD ON GD.LegalDesignationId = E.LegalDesignationId 
                                                                                               AND E.PlantId = gd.PlantId
                                           					LEFT JOIN (
                                           								SELECT MAX(EffectiveDate)EffectiveDate, LegalSalaryGradeId, EmployeeLocationId 
                                           									FROM MST.LegalSalaryStructure 
                                           									WHERE EffectiveDate <= '" + para.FromDate + @"'
                                           								GROUP BY LegalSalaryGradeId, EmployeeLocationId 
                                           							  ) S ON S.LegalSalaryGradeId = GD.LegalSalaryGradeId AND S.EmployeeLocationId = B.EmployeeLocationId
                                           					LEFT JOIN MST.LegalSalaryStructure SS ON SS.LegalSalaryGradeId = S.LegalSalaryGradeId 
                                                                                           AND SS.EmployeeLocationId = S.EmployeeLocationId 
                                                                                           AND SS.EffectiveDate = S.EffectiveDate
                                           					LEFT JOIN MST.LegalSalaryStructureValue SV ON SV.LegalSalaryStructureId = SS.Id 																							
                                           					left join  [SCS].[LegalSalaryGrade] LSG ON LSG.Id=S.LegalSalaryGradeId
                                           			GROUP BY E.SystemId,LSG.UserName 
                                           		) MW ON MW.SystemId = EmpBasic.SystemId

                                                LEFT JOIN (
                                                SELECT bb.UserName BankName,b.BankAccNo,b.EmpSystemID FROM [dbo].[EmployeeBankInfo] b
                                                LEFT JOIN hkp.BankBranch bb ON b.BankBranchId=bb.Id
                                                ) BB ON BB.EmpSystemID = EmpBasic.SystemId

                                                LEFT JOIN
												( SELECT ed.DocNumber UANNo,ED.EmpSystemID FROM 
												EmployeeDocument ED 
												INNER JOIN (SELECT * FROM HKP.ComplianceDocument WHERE ProfileType = 'PF') CD ON CD.Id = ED.ComplianceDocumentId 
												) pf ON EmpBasic.SystemId = pf.EmpSystemID

												LEFT JOIN
												( SELECT ed.DocNumber ESICNo,ED.EmpSystemID FROM 
												EmployeeDocument ED 
												INNER JOIN (SELECT * FROM HKP.ComplianceDocument WHERE ProfileType = 'ESIC') CD ON CD.Id = ED.ComplianceDocumentId 
												) ESIC ON EmpBasic.SystemId = esic.EmpSystemID WHERE  " + wcEmpStatus + @"-- EmpBasic.DOJ <='" + para.ToDate + @"' 
                                                --AND (EmployeeStatus != 'Separated' OR CONVERT(DATE,DOS) >= CONVERT(DATE,'" + para.FromDate + @"'))
                                                 --EmpBasic.SystemId IN (select systemId from EmployeeInformation where EmployeeCode = '00094')                                              
                                                ";

                if (para.PlantId != "null" && para.PlantId != null && para.PlantId != "undefined" && para.PlantId != "")
                {
                    strSQL = strSQL + @" EmpBasic.PlantID = '" + para.PlantId + @"'  " + _wc + @"";
                }
                if (sqlInStatement != "null" && sqlInStatement != null && sqlInStatement != "undefined" && sqlInStatement != "")
                {
                    strSQL = strSQL + @" AND EmpBasic.SystemId " + sqlInStatement + @"";
                }
                if (para.UnitId != "null" && para.UnitId != null && para.UnitId != "undefined" && para.UnitId != "")
                {
                    strSQL = strSQL + @" AND UnitID = '" + para.UnitId + "'";
                }
                if (para.DivisionId != "null" && para.DivisionId != null && para.DivisionId != "undefined" && para.DivisionId != "")
                {
                    strSQL = strSQL + @" AND DivisionID = '" + para.DivisionId + "'";
                }
                if (para.DepartmentId != "null" && para.DepartmentId != null && para.DepartmentId != "undefined" && para.DepartmentId != "")
                {
                    strSQL = strSQL + @" AND DepartmentID = '" + para.DepartmentId + "'";
                }
                if (para.SectionId != "null" && para.SectionId != null && para.SectionId != "undefined" && para.SectionId != "")
                {
                    strSQL = strSQL + @" AND SectionID = '" + para.SectionId + "'";
                }
                if (para.SubSectionId != "null" && para.SubSectionId != null && para.SubSectionId != "undefined" && para.SubSectionId != "")
                {
                    strSQL = strSQL + @" AND SubSectionID = '" + para.SubSectionId + "'";
                }
                if (para.EmpCategorId != "null" && para.EmpCategorId != null && para.EmpCategorId != "undefined" && para.EmpCategorId != "")
                {
                    strSQL = strSQL + @" AND EmpBasic.EmployeeCategorySystemID = '" + para.EmpCategorId + "'";
                }
                if (paymentMode != "null" && paymentMode != null && paymentMode != "undefined" && paymentMode != "")
                {
                    strSQL = strSQL + @" AND EmpBasic.PaymentMode = '" + paymentMode + "'";
                }

                //strSQL = strSQL + @"ORDER BY  EmpBasic.EmployeeCode, EmpBasic.DivisionId,EmpBasic.SubdivisionID,EmpBasic.UnitId,EmpBasic.DepartmentId";
                strSQL = strSQL + @"" + sortingParameters + "--EmpBasic.DepartmentId,EmpBasic.SectionId,EmpBasic.SubSectionId,EmpBasic.LineId ,EmpBasic.DesignationGroupId,EmpBasic.EmployeeCode";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function



        public void GetSalaryInfoSlrProcIDWiseForRegisterPayRollGroup(ParamList para, string paymentMode, string languageId, string sqlInStatement, string sortingParameters, bool isActive, bool isSeperated, bool isMaternity, out DataSet dsRef)
        {

            var salaryProcessSystemId = "";
            string wcEmpStatus = " (1=0 ";
            if (isActive == true && isSeperated == true && isMaternity == true)
            {
                wcEmpStatus = " (1=1 ";
            }
            else
            {
                if (isActive == true)
                {
                    wcEmpStatus += " OR SalaryProcFlag ='Regular' ";
                }
                if (isSeperated == true)
                {
                    wcEmpStatus += " OR SalaryProcFlag ='SEPARATED'";
                }
                if (isMaternity == true)
                {
                    wcEmpStatus += " OR SalaryProcFlag ='MLV_PRE'";

                }
            }
            wcEmpStatus += ") AND";
            if (!string.IsNullOrEmpty(para.SalaryProcessId) && para.SalaryProcessId != "undefined" && para.SalaryProcessId != "null")
            {
                salaryProcessSystemId = "SystemId IN ('" + para.SalaryProcessId + @"')";
            }
            else
            {
                //salaryProcessSystemId = @"SystemId IN( SELECT SystemID FROM SalaryProcMaster
                //                      WHERE SystemID IN(SELECT SlrProcMstSystemID FROM SalaryProcChild
                //                                        WHERE PlantID = '" + para.PlantId + @"' GROUP BY SlrProcMstSystemID)
                //                        AND MonthNo = Month('" + para.FromDate + "') AND YearNo = Year('" + para.FromDate + "')  and IsCompleteMonth = 1)";


                salaryProcessSystemId = "' '";

                DataTable dtSalPrcId = _sqlRepository.GetDataTable(@"SELECT SystemID FROM SalaryProcMaster
                                      WHERE SystemID IN(SELECT SlrProcMstSystemID FROM SalaryProcChild
                                                        WHERE PlantID = '" + para.PlantId + @"' GROUP BY SlrProcMstSystemID)
                                        AND MonthNo =  MONTH('" + para.FromDate + @"') AND YearNo =  YEAR('" + para.FromDate + @"') and IsCompleteMonth = 1 ");

                for (int si = 0; si < dtSalPrcId.Rows.Count; si++)
                {
                    salaryProcessSystemId += ",'" + dtSalPrcId.Rows[si]["SystemID"].ToString() + "'";
                }

            }
            string strSQL;
            ConnectionManager.DAL.ConManager objCon;

            var _wc = string.Empty;

            if (para.EmployeeId != "" && para.EmployeeId != null)
            {
                _wc = "  SYSTEMID IN (" + para.EmployeeId + @")";
            }
            else
            {
                if (para.PayGroup.ToUpper() != "NO GROUP" && para.PayGroup != "null")
                {
                    _wc = @"AND EmpInfoSystemID  IN (SELECT employeeid from MST.PayrollGroupMaster where PayrollGroupId = '" + para.PayGroup + @"')";
                }
                if (para.PayGroup.ToUpper() == "NO GROUP")
                {
                    _wc = @"AND EmpInfoSystemID NOT IN ( SELECT employeeid from MST.PayrollGroupMaster)";
                }
                if (para.PayGroup.ToUpper() == "ALL")
                {
                    _wc = @"";
                }

            }

            try
            {

                strSQL = @"SELECT EmpSlr.EmpInfoSystemID,convert(int, EmpBasic.EmployeeCode)EmployeeCode, EmpBasic.EmployeeName, ISNULL(EmpBasic.EmployeeNameLocal,EmpBasic.EmployeeName) EmployeeNameLocal,Replace(Convert(varchar(11),EmpBasic.DOJ,106),' ','-') DOJ
                                , REPLACE(Convert(VARCHAR(11), EmpBasic.DOB, 106), ' ', '-') AS DOB,REPLACE(Convert(VARCHAR(11), EmpBasic.DOS, 106), ' ', '-') AS DOS,
                                EmpBasic.EmployeeStatus, EmpBasic.UnitID, EmpBasic.UnitName, EmpBasic.DivisionID, EmpBasic.DivisionName,
                                EmpBasic.DepartmentID, EmpBasic.DepartmentName, EmpBasic.SectionID, EmpBasic.SectionName, EmpBasic.SubSectionID,EmpBasic.SubDivision,EmpBasic.SubdivisionID,
                                EmpBasic.SubSectionName, EmpBasic.EmployeeCategorySystemID, EmpBasic.EmpCategoryName, EmpBasic.DesignationGroupName,
                                EmpBasic.DesignationSystemID, EmpBasic.DesignationName,EmpBasic.GivenDesignationName,EmpBasic.GivenDesignationGroup
                                ,EmpBasic.PlantName,EmpBasic.EmployeeCodePreFix,EmpBasic.EmployeeCodeNumeric,EmpBasic.LDDesignationGD,EmpBasic.EmployeeCategorySequence
		                        ,ISNULL(EmpBasic.DesignationLocal, EmpBasic.LDDesignationGD) DesignationLocal,EmpBasic.GradeCode,EmpBasic.FatherName
                                ,esic.ESICNo,pf.UANNo,bb.BankAccNo,bb.BankName, '' BankNameFull,ISNULL(MMDSA.TotalProcDate,0) TotalProcDate,ISNULL(MMDSA.TotalLate, 0) TotalLate
								,(ISNULL(MMDSA.TotalPresent, 0) + ISNULL(MMDSA.TotalLate, 0)) PresentDays,PaymentMode,
								ISNULL(MMDSA.AbsentDays, 0) AbsentDays,  ISNULL(MMDSA.TotalHoliDay + MMDSA.TotalWeekOffHoliDay,0) HoliDay, ISNULL(MMDSA.TotalWeekOff, 0) WeekOff,
								(ISNULL(MMDSA.TotalLv, 0) + ISNULL(MMDSA.TotalMLv, 0)) LeaveDays,ISNULL(MMDSA.TotalLWP,0) LWP, EmpSlr.SlrProcChdSysID, EmpSlr.SlrProcMstSystemID, EmpSlr.SalaryProcID,
                                EmpSlr.PlantID, EmpSlr.FromDate, EmpSlr.ToDate, EmpSlr.MonthNo, EmpSlr.YearNo, EmpSlr.PayAbleShSystemID,
                                EmpSlr.SalaryHeadID, EmpSlr.EntryCurrencyID, EmpSlr.EntryAmount, EmpSlr.DefineCurrencyID, EmpSlr.DefineAmount,
                                EmpSlr.DisbusmentCurrencyID, EmpSlr.DisbusmentAmount, EmpSlr.AcltExcDisbSlrHDID, EmpSlr.AcltExcDisbSlrHDAmt,
                                EmpSlr.PlantWiseExchangeCR, EmpSlr.ExchangeRate, EmpSlr.AmtDefinitionCurrencyID, EmpSlr.AmtDefinitionCurrency,
                                EmpSlr.AmtDefinitionCurrencyRate, EmpSlr.IsNetPayEffect,EmpSlr.PartOfNetPay
                                ,EmpSlr.SalaryHead,ISNULL(EmpSlr.SalaryHeadBangla,EmpSlr.SalaryHead) SalaryHeadBangla,EmpSlr.HeadCategory,EmpSlr.HeadType,EmpSlr.Sequence,EmpSlr.IsCTCComponent,EmpSlr.IsGrossComponent

                                , ISNULL(vpf.VoluntaryPFValue,0) VoluntaryPFValue
                                , ISNULL(BonusValue.Bonus,0) Bonus

								, BonusValue.SalaryHead B_SalaryHead
								, BonusValue.SalaryHeadID B_SalaryHeadID
								, BonusValue.IsCTCComponent B_IsCTCComponent
								, BonusValue.IsGrossComponent B_IsGrossComponent
								, BonusValue.HeadType B_HeadType
								--, BonusValue.HeadCategory B_HeadCategory

                                ,VPFhead.HeadCategory xHeadCategory,VPFhead.SalaryHeadID xSalaryHeadID
                                ,VPFhead.SalaryHead xSalaryHead,VPFhead.IsCTCComponent xIsCTCComponent
                                ,VPFhead.IsGrossComponent xIsGrossComponent,VPFhead.HeadType xHeadType
                                ,VPFhead.SalaryRuleMasterSystemID xSalaryRuleMasterSystemID
                                ---,VPFhead.IntegerInDisb, VPFhead.DecimalNo,
                                ,MW.Grade,CONVERT(DECIMAL(10, 2), ISNULL(MMDSA.TotalOTHr,0)/60) TotalOTHr
                                ,EmpSlr.DecimalNo AS DecimalNo ,EmpSlr.IntegerInDisb AS IntegerInDisb,EmpSlr.IsDecimalInDisb AS IsDecimalInDisb
                                ,EmpBasic.Line,EmpBasic.LegalDesignation
                                ,EmpSlr.SalaryProcFlag
	                            ,EmpBasic.OverTimePmtPolicyMasterID
								,otd.FormulaDesID,otd.FormulaDes
								,ISNULL(EmpBasic.IsOTEntitle,0) IsOTEntitle
                              ,EmpBasic. LineId,EmpBasic.DesignationGroupId
                                ,EmpBasic.DesignationSequence,EmpBasic.PlantSequence,EmpBasic.UnitSequence,EmpBasic.DivisionSequence,EmpBasic.SubDivisionSequence,EmpBasic.DepartmentSequence
                                 ,SectionSequence,SubSectionSequence,EntitySequence,LineSequence
                                FROM
                                    (
									 SELECT E.SystemID,E.EmployeeCodePreFix,E.EmployeeCodeNumeric,CONVERT(INT, E.EmployeeCode)EmployeeCode, E.EmployeeName,E.EmployeeNameLocal,E.FatherName, E.DOJ,E.DOB,E.DOS, E.EmployeeStatus,E.PaymentMode,
											DG.UserName DesignationGroupName, E.DesignationSystemID, DE.UserName DesignationName,GVDE.UserName GivenDesignationName,GVDE.Sequence DesignationSequence,
											'' UserGroupSystemID, E.PlantID, F.UserName PlantName, F.Sequence PlantSequence, E.UnitID
											,FU.UserName UnitName,FU.Sequence UnitSequence, E.DivisionID, DV.UserName DivisionName,DV.Sequence DivisionSequence,E.SubdivisionID,subDV.UserName SubDivision,subDV.Sequence SubDivisionSequence, E.DepartmentID, DP.UserName DepartmentName,DP.Sequence DepartmentSequence,
											E.SectionID, S.UserName SectionName,S.Sequence SectionSequence, E.SubSectionID, SS.UserName SubSectionName,SS.Sequence SubSectionSequence, E.EmployeeCategorySystemID,
											EC.UserName EmpCategoryName,EC.Sequence EmployeeCategorySequence--, BK.BankNameShort BankName, BK.BankNameFull, E.BankAccNo
                                            ,ENT.UserName EntitySequence,egdsgg.GivenDesignationGroup,e.SalaryRuleMasterSystemID,L.UserName Line, LD.UserName LegalDesignation--,eoe.IsOTEntitle
											,IsOTEntitle = Case  when ISNULL(EOE.IsOTEntitle,0) =1 then EOE.IsOTEntitle else ISNULL(DMCT.IsOTEntitled,0) end
										 , ISNULL(LD.UserName,GVD.UserName) LDDesignationGD,LSalGr.Code GradeCode
		                                  , ISNULL(LocLangLD.Name,LocLangGD.Name) DesignationLocal
											,OverTimePmtPolicyMasterID=case when isnull(eoe.EmpSystemID,'')<>'' then (select id from OverTimePmtPolicyMaster where IsDefault=1)
											when DMCT.IsOTEntitled=1 and isnull(DMCT.OverTimePmtPolicyMasterID,'')<>'' then DMCT.OverTimePmtPolicyMasterID
											else null end,E.LineId,EGDSGG.DesignationGroupId,L.Sequence LineSequence
                                     
                                           FROM EmployeeInformation E
												LEFT JOIN org.Plant F ON E.PlantID = F.Id
												LEFT JOIN hkp.DesignationGroup DG ON E.DesignationGroupId = DG.ID
												LEFT JOIN hkp.Designation DE ON E.GivenDesignationId = DE.Id
												LEFT JOIN hkp.Designation GVDE ON E.GivenDesignationId = GVDE.Id
												LEFT JOIN org.Unit FU ON E.UnitID = FU.Id
												LEFT JOIN org.Division DV ON E.DivisionID = DV.Id
												LEFT JOIN org.Department DP ON E.DepartmentID = DP.Id
												LEFT JOIN org.Section S ON E.SectionID = S.Id
												LEFT JOIN org.SubSection SS ON E.SubSectionID = SS.Id
                                                LEFT JOIN org.Line L ON L.Id = E.LineId
                                                LEFT  JOIN [MST].[ManpowerBudget] AS MB  on MB.Id = E.BudgetCode
								                LEFT  JOIN ORG.Entity AS ENT ON ENT.Id = MB.EntityId
												LEFT JOIN HKP.LegalDesignation LD ON LD.Id=E.LegalDesignationId
												LEFT JOIN HKP.Designation GVD ON GVD.Id=E.GivenDesignationId
                                                LEFT JOIN MST.LegalSalaryGradeDesignation LSGD ON LSGD.LegalDesignationId = LD.Id
                                              LEFT JOIN SCS.LegalSalaryGrade LSalGr ON LSalGr.Id = LSGD.LegalSalaryGradeId
												LEFT JOIN org.SubDivision subDV ON E.SubdivisionID = subDV.Id
												LEFT JOIN
                                                --hkp.EmployeeCategory EC ON E.EmployeeCategorySystemID = EC.Id
                                                (
                                                SELECT ECT.Id, ECT.UserName,ECT.Sequence , DM.DesignationId FROM [HKP].[EmployeeCategory] ECT
												LEFT JOIN MST.DesignationMaster DM ON ECT.Id=DM.EmployeeCategoryId
												)EC ON EC.DesignationId=E.GivenDesignationId
												LEFT JOIN (SELECT dm.DesignationGroupId,dm.DesignationId,dm.EmployeeCategoryId
									            ,DG.UserName GivenDesignationGroup
									            FROM MST.DesignationMaster DM
									            LEFT JOIN HKP.DesignationGroup DG ON DG.Id=DM.DesignationGroupId
									            ) EGDSGG ON EGDSGG.DesignationId=e.GivenDesignationId
									            AND EGDSGG.EmployeeCategoryId=e.EmployeeCategorySystemID
                                               LEFT JOIN EmployeeOTEntitle EOE ON EOE.EmpSystemID = E.SystemId AND EOE.IsOTEntitle=1
												LEFT JOIN  MST.DesignationMaster DMOT ON DMOT.DesignationId = E.GivenDesignationId
												LEFT JOIN  SCS.DesignationMasterConfiguration DMCT ON DMCT.DesignationMasterId = DMOT.Id and DMCT.plantid='" + para.PlantId + @"'
												 LEFT JOIN HKP.LocalLanguage LocLangLD ON LocLangLD.LegalDesignationId = E.LegalDesignationId AND LocLangLD.LanguageId = '" + para.LanguageId + @"'
                                                LEFT JOIN HKP.LocalLanguage LocLangGD ON LocLangGD.DesignationId = E.GivenDesignationId AND LocLangGD.LanguageId = '" + para.LanguageId + @"'
                              
									) EmpBasic
									LEFT JOIN (select * from OverTimePmtPolicyDetails where OverTimeDayType='Working Day') otd on otd.OverTimePmtPolicyID=EmpBasic.OverTimePmtPolicyMasterID

                                    INNER JOIN
											(
											 SELECT SPC.SystemID AS SlrProcChdSysID, SPC.SlrProcMstSystemID, SPM.SalaryProcID, SPM.FromDate, SPM.ToDate,
													SPC.EmpInfoSystemID, SPC.PlantID, SPM.UserGroupSystemID, SPM.MonthNo, SPM.YearNo, SPC.PayAbleShSystemID,
													SPC.SalaryHeadID, SPC.EntryCurrencyID, SPC.EntryAmount, SPC.DefineCurrencyID, SPC.DefineAmount,
													SPC.DisbusmentCurrencyID, SPC.DisbusmentAmount, SPC.AcltExcDisbSlrHDID, SPC.AcltExcDisbSlrHDAmt,
													CRE.Name AS PlantWiseExchangeCR, EXR.ToCurrencyBuying ExchangeRate, SPM.AmtDefinitionCurrencyID,
													CR.Name AS AmtDefinitionCurrency, SPM.AmtDefinitionCurrencyRate, SPC.IsNetPayEffect,SH.PartOfNetPay
                                                    ,SH.SalaryHead,BSH.Name SalaryHeadBangla,sh.HeadCategory,sh.HeadType,isnull(psh.Sequence, 99) Sequence
                                                    ,SH.IsCTCComponent,sh.IsGrossComponent,dcm.DecimalNo,dcm.IntegerInDisb,dcm.IsDecimalInDisb
                                           , CASE WHEN ISNULL(SPM.SalaryProcFlag,'') = '' THen 'Regular' else SalaryProcFlag end SalaryProcFlag

											 FROM SalaryProcChild SPC
														INNER JOIN SalaryProcMaster SPM ON SPC.SlrProcMstSystemID = SPM.SystemID
																							AND SPM.SystemId IN (" + salaryProcessSystemId + @")

	                                                   INNER JOIN SalaryProcessLogDetail SPLD ON SPLD.SalaryProcessId  IN (" + salaryProcessSystemId + @")
                                                        and spld.EmpSystemId = spc.EmpInfoSystemID and spld.PlantId ='" + para.PlantId + @"'
                                                        LEFT JOIN SalaryHead sh on sh.SalaryHeadID=spc.SalaryHeadID
                                                        LEFT JOIN (SELECT * FROM HKP.LocalLanguage WHERE SalaryHeadId IS NOT NULL AND LanguageId = '" + languageId + @"') AS BSH ON BSH.SalaryHeadId = sh.SalaryHeadID --BanglaSalaryHead
														LEFT JOIN (SELECT * from [MST].[PlantSalaryHeadSequence] where PlantId='" + para.PlantId + @"' ) PSH
																		ON PSH.SalaryHeadId=spc.SalaryHeadID

														LEFT JOIN scs.Currency CR ON SPM.AmtDefinitionCurrencyID = CR.Id
														LEFT JOIN (
																   SELECT * FROM ExchangerateDateWiseForHR
																   WHERE FromDate IN (
																					  SELECT MAX(FromDate) FromDate FROM ExchangerateDateWiseForHR
																						WHERE FromDate <= (
																										   SELECT MAX(FromDate) FromDate FROM SalaryProcMaster
																											WHERE SystemId IN ( " + salaryProcessSystemId + @")
                                                                                                             
                                                                                                           )
                                                                                    )
																  ) EXR ON SPM.AmtDefinitionCurrencyID = EXR.FromCurrencyCode
																							AND SPC.PlantID = Exr.PlantID
														LEFT JOIN scs.Currency CRE ON EXR.FromCurrencyCode = CRE.Id
                                                  ------    for decimal part       ---------
														 LEFT JOIN
                                               ( SELECT SSM.EmpInfoSystemID,crc.SalaryHeadID,crc.DecimalNo,crc.IntegerInDisb,crc.IsDecimalInDisb
												FROM SalaryInfoDefineMaster SSM
												left join SalaryRuleMaster srm on srm.SystemID=SSM.SalaryRuleMasterSystemID
												left join CurrencyRuleMaster crm on crm.SystemID=srm.CurrencyRuleSystemID
												left join CurrencyRuleChild crc on crc.MstSystemID=crm.SystemID) dcm on  dcm.SalaryHeadID=SPC.SalaryHeadID  and SPC.EmpInfoSystemID=dcm.EmpInfoSystemID
												      -------   end decimal part-------
											) EmpSlr ON EmpBasic.SystemID = EmpSlr.EmpInfoSystemID AND EmpBasic.PlantID = EmpSlr.PlantID
                                LEFT JOIN (
										
												  SELECT EmpSystemId,MAX(EffectiveDate) EffectiveDate, VoluntaryPFValue from [PFEmployeeVoluntaryValue] 
												  Where EffectiveDate<='" + para.FromDate + @"'
												  Group By EmpSystemId,EffectiveDate,VoluntaryPFValue
										) VPF ON EmpBasic.SystemId=vpf.EmpSystemId

										LEFT JOIN(
										SELECT SH.HeadCategory ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
										,SH.IsGrossComponent,SH.HeadType,sr.SalaryRuleMasterSystemID
											  FROM [dbo].[SalaryRulePF] SR
											  LEFT JOIN SalaryHead SH ON SH.SalaryHeadID=SR.SalaryHeadID
											  WHERE SH.HeadCategory='PF Voluntary'
										) VPFhead ON VPFhead.SalaryRuleMasterSystemID=EmpBasic.SalaryRuleMasterSystemID

                                        LEFT JOIN
										(
										SELECT m.EmpSystemID,m.MonthNo,d.Value Bonus 
												--,SH.HeadCategory 
                                                ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
												,SH.IsGrossComponent,SH.HeadType
												FROM [BonusPolicyMonthlyRetainEmpWiseCalculation] m
												LEFT JOIN [BonusPolicyMonthlyRetainDistributionPmt] d on m.id=d.BnsPlyMntRetainID
												LEFT JOIN SalaryHead SH ON SH.SalaryHeadID=d.SalaryHeadID
												WHERE m.MonthNo=DATEPART(Month,'" + para.FromDate + @"')  AND m.YearNo=DATEPART(YEAR,'" + para.FromDate + @"')  
                                                --and d.SalaryHeadID=(select SalaryHeadID from SalaryHead where HeadCategory='Festival Bonus')
										) BonusValue ON EmpBasic.SystemId=BonusValue.EmpSystemID

                                    LEFT JOIN
		                                    (
											 SELECT EmpSystemID, MonthNo, YearNo, TotalProcDate, TotalPresent, TotalLate,
													TotalAbsent AbsentDays, TotalLv,TotalLWP, TotalMLv, TotalCompAssignLv, TotalWeekOff, TotalHoliDay,
													TotalWeekOffHoliDay, TotalOTHr, TotalNormalOTHr, TotalExtraOTHr
				                              FROM SalaryProceAttdnData
											) MMDSA ON EmpSlr.EmpInfoSystemID = MMDSA.EmpSystemID AND EmpSlr.MonthNo = MMDSA.MonthNo AND
						                               EmpSlr.YearNo = MMDSA.YearNo

                                    LEFT JOIN 
                                           		(
                                           		 SELECT E.SystemID, SUM(SV.SalaryHeadValue) SalaryHeadValue,LSG.UserName Grade
                                           			FROM EmployeeInformation E   
                                           					LEFT JOIN MST.ManpowerBudget b ON e.BudgetCode = b.Id
                                           					LEFT JOIN MST.LegalSalaryGradeDesignation GD ON GD.LegalDesignationId = E.LegalDesignationId 
                                                                                               AND E.PlantId = gd.PlantId
                                           					LEFT JOIN (
                                           								SELECT MAX(EffectiveDate)EffectiveDate, LegalSalaryGradeId, EmployeeLocationId 
                                           									FROM MST.LegalSalaryStructure 
                                           									WHERE EffectiveDate <= '" + para.FromDate + @"'
                                           								GROUP BY LegalSalaryGradeId, EmployeeLocationId 
                                           							  ) S ON S.LegalSalaryGradeId = GD.LegalSalaryGradeId AND S.EmployeeLocationId = B.EmployeeLocationId
                                           					LEFT JOIN MST.LegalSalaryStructure SS ON SS.LegalSalaryGradeId = S.LegalSalaryGradeId 
                                                                                           AND SS.EmployeeLocationId = S.EmployeeLocationId 
                                                                                           AND SS.EffectiveDate = S.EffectiveDate
                                           					LEFT JOIN MST.LegalSalaryStructureValue SV ON SV.LegalSalaryStructureId = SS.Id 																							
                                           					left join  [SCS].[LegalSalaryGrade] LSG ON LSG.Id=S.LegalSalaryGradeId
                                           			GROUP BY E.SystemId,LSG.UserName 
                                           		) MW ON MW.SystemId = EmpBasic.SystemId

                                                LEFT JOIN (
                                                SELECT bb.UserName BankName,b.BankAccNo,b.EmpSystemID FROM [dbo].[EmployeeBankInfo] b
                                                LEFT JOIN hkp.BankBranch bb ON b.BankBranchId=bb.Id
                                                ) BB ON BB.EmpSystemID = EmpBasic.SystemId

                                                LEFT JOIN
												( SELECT ed.DocNumber UANNo,ED.EmpSystemID FROM 
												EmployeeDocument ED 
												INNER JOIN (SELECT * FROM HKP.ComplianceDocument WHERE ProfileType = 'PF') CD ON CD.Id = ED.ComplianceDocumentId 
												) pf ON EmpBasic.SystemId = pf.EmpSystemID

												LEFT JOIN
												( SELECT ed.DocNumber ESICNo,ED.EmpSystemID FROM 
												EmployeeDocument ED 
												INNER JOIN (SELECT * FROM HKP.ComplianceDocument WHERE ProfileType = 'ESIC') CD ON CD.Id = ED.ComplianceDocumentId 
												) ESIC ON EmpBasic.SystemId = esic.EmpSystemID WHERE  " + wcEmpStatus + @"-- EmpBasic.DOJ <='" + para.ToDate + @"' 
                                                --AND (EmployeeStatus != 'Separated' OR CONVERT(DATE,DOS) >= CONVERT(DATE,'" + para.FromDate + @"'))
                                                 --EmpBasic.SystemId IN (select systemId from EmployeeInformation where EmployeeCode = '00094')                                              
                                                ";

                if (para.PlantId != "null" && para.PlantId != null && para.PlantId != "undefined" && para.PlantId != "")
                {
                    strSQL = strSQL + @" EmpBasic.PlantID = '" + para.PlantId + @"'  " + _wc + @"";
                }
                if (sqlInStatement != "null" && sqlInStatement != null && sqlInStatement != "undefined" && sqlInStatement != "")
                {
                    strSQL = strSQL + @" AND EmpBasic.SystemId " + sqlInStatement + @"";
                }
                if (para.UnitId != "null" && para.UnitId != null && para.UnitId != "undefined" && para.UnitId != "")
                {
                    strSQL = strSQL + @" AND UnitID = '" + para.UnitId + "'";
                }
                if (para.DivisionId != "null" && para.DivisionId != null && para.DivisionId != "undefined" && para.DivisionId != "")
                {
                    strSQL = strSQL + @" AND DivisionID = '" + para.DivisionId + "'";
                }
                if (para.DepartmentId != "null" && para.DepartmentId != null && para.DepartmentId != "undefined" && para.DepartmentId != "")
                {
                    strSQL = strSQL + @" AND DepartmentID = '" + para.DepartmentId + "'";
                }
                if (para.SectionId != "null" && para.SectionId != null && para.SectionId != "undefined" && para.SectionId != "")
                {
                    strSQL = strSQL + @" AND SectionID = '" + para.SectionId + "'";
                }
                if (para.SubSectionId != "null" && para.SubSectionId != null && para.SubSectionId != "undefined" && para.SubSectionId != "")
                {
                    strSQL = strSQL + @" AND SubSectionID = '" + para.SubSectionId + "'";
                }
                if (para.EmpCategorId != "null" && para.EmpCategorId != null && para.EmpCategorId != "undefined" && para.EmpCategorId != "")
                {
                    strSQL = strSQL + @" AND EmpBasic.EmployeeCategorySystemID = '" + para.EmpCategorId + "'";
                }
                if (paymentMode != "null" && paymentMode != null && paymentMode != "undefined" && paymentMode != "")
                {
                    strSQL = strSQL + @" AND EmpBasic.PaymentMode = '" + paymentMode + "'";
                }

                //strSQL = strSQL + @"ORDER BY  EmpBasic.EmployeeCode, EmpBasic.DivisionId,EmpBasic.SubdivisionID,EmpBasic.UnitId,EmpBasic.DepartmentId";
                strSQL = strSQL + @"" + sortingParameters + "--EmpBasic.DepartmentId,EmpBasic.SectionId,EmpBasic.SubSectionId,EmpBasic.LineId ,EmpBasic.DesignationGroupId,EmpBasic.EmployeeCode";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function



        public void GetSalaryInfoSlrProcIDWiseForTopSheet(PayRegisterParamList para, out DataSet dsRef)
        {

            var salaryProcessSystemId = "";
            if (!string.IsNullOrEmpty(para.SalaryProcessId) && para.SalaryProcessId != "undefined" && para.SalaryProcessId != "null")
            {
                salaryProcessSystemId = "SystemId IN ('" + para.SalaryProcessId + @"')";
            }
            else
            {
                salaryProcessSystemId = @"SystemId IN( SELECT SystemID FROM SalaryProcMaster
                                      WHERE SystemID IN(SELECT SlrProcMstSystemID FROM SalaryProcChild
                                                        WHERE PlantID = '" + para.PlantId + @"' GROUP BY SlrProcMstSystemID)
                                        AND MonthNo = Month('" + para.FromDate + "') AND YearNo = Year('" + para.FromDate + "')  and IsCompleteMonth = 1)";
            }
            string strSQL;
            ConnectionManager.DAL.ConManager objCon;

            var _wc = string.Empty;

            //if (para.EmployeeId != "" && para.EmployeeId != null)
            //{
            //    _wc = "  SYSTEMID IN (" + para.EmployeeId + @")";
            //}
            //else
            //{
            //    if (para.PayGroup.ToUpper() != "NO GROUP" && para.PayGroup != "null" && para.PayGroup != null)
            //    {
            //        _wc = @"AND EmpInfoSystemID  IN (SELECT employeeid from MST.PayrollGroupMaster where PayrollGroupId = '" + para.PayGroup + @"')";
            //    }
            //    if (para.PayGroup.ToUpper() == "NO GROUP")
            //    {
            //        _wc = @"AND EmpInfoSystemID NOT IN ( SELECT employeeid from MST.PayrollGroupMaster)";
            //    }
            //    if (para.PayGroup.ToUpper() == "ALL")
            //    {
            //        _wc = @"";
            //    }

            //}

            try
            {

                strSQL = @"SELECT topSheet.EntityName,EntityId,topSheet.DepartmentName,topSheet.SubSectionName,COUNT(EmpInfoSystemID) TotalEmp,topSheet.SalaryHead,DepartmentSequence,SubSectionSequence,SalaryHeadID, SalaryHead,  HeadType, Sequence, HeadCategory, IsCTCComponent, IsGrossComponent, IntegerInDisb, DecimalNo
								,Sum(topSheet.DisbusmentAmount) DisbusmentAmount from (SELECT EmpSlr.EmpInfoSystemID,convert(int, EmpBasic.EmployeeCode)EmployeeCode, EmpBasic.EmployeeName, ISNULL(EmpBasic.EmployeeNameLocal,EmpBasic.EmployeeName) EmployeeNameLocal,Replace(Convert(varchar(11),EmpBasic.DOJ,106),' ','-') DOJ
                                , REPLACE(Convert(VARCHAR(11), EmpBasic.DOB, 106), ' ', '-') AS DOB,REPLACE(Convert(VARCHAR(11), EmpBasic.DOS, 106), ' ', '-') AS DOS,
                                EmpBasic.EmployeeStatus, EmpBasic.UnitID, EmpBasic.UnitName, EmpBasic.DivisionID, EmpBasic.DivisionName,
                                EmpBasic.DepartmentID, EmpBasic.DepartmentName, EmpBasic.SectionID, EmpBasic.SectionName, EmpBasic.SubSectionID,EmpBasic.SubDivision,EmpBasic.SubdivisionID,
                                EmpBasic.SubSectionName, EmpBasic.EmployeeCategorySystemID, EmpBasic.EmpCategoryName, EmpBasic.DesignationGroupName,
                                EmpBasic.DesignationSystemID, EmpBasic.DesignationName,EmpBasic.GivenDesignationName,EmpBasic.GivenDesignationGroup
                                , EmpBasic.PlantName
							     , EmpBasic.LDDesignationGD,EmpBasic.EmployeeCategorySequence
		                            ,  ISNULL(EmpBasic.DesignationLocal, EmpBasic.LDDesignationGD) DesignationLocal,EmpBasic.GradeCode,EmpBasic.FatherName
                                ,esic.ESICNo,pf.UANNo,bb.BankAccNo,bb.BankName, '' BankNameFull,ISNULL(MMDSA.TotalProcDate,0) TotalProcDate,ISNULL(MMDSA.TotalLate, 0) TotalLate
								,(ISNULL(MMDSA.TotalPresent, 0) + ISNULL(MMDSA.TotalLate, 0)) PresentDays,PaymentMode,
								ISNULL(MMDSA.AbsentDays, 0) AbsentDays,  ISNULL(MMDSA.TotalHoliDay + MMDSA.TotalWeekOffHoliDay,0) HoliDay, ISNULL(MMDSA.TotalWeekOff, 0) WeekOff,
								(ISNULL(MMDSA.TotalLv, 0) + ISNULL(MMDSA.TotalMLv, 0)) LeaveDays,ISNULL(MMDSA.TotalLWP,0) LWP, EmpSlr.SlrProcChdSysID, EmpSlr.SlrProcMstSystemID, EmpSlr.SalaryProcID,
                                EmpSlr.PlantID, EmpSlr.FromDate, EmpSlr.ToDate, EmpSlr.MonthNo, EmpSlr.YearNo, EmpSlr.PayAbleShSystemID,
                                EmpSlr.SalaryHeadID, EmpSlr.EntryCurrencyID, EmpSlr.EntryAmount, EmpSlr.DefineCurrencyID, EmpSlr.DefineAmount,
                                EmpSlr.DisbusmentCurrencyID, EmpSlr.DisbusmentAmount, EmpSlr.AcltExcDisbSlrHDID, EmpSlr.AcltExcDisbSlrHDAmt,
                                EmpSlr.PlantWiseExchangeCR, EmpSlr.ExchangeRate, EmpSlr.AmtDefinitionCurrencyID, EmpSlr.AmtDefinitionCurrency,
                                EmpSlr.AmtDefinitionCurrencyRate, EmpSlr.IsNetPayEffect
                                ,EmpSlr.SalaryHead,EmpSlr.HeadCategory,EmpSlr.HeadType,EmpSlr.Sequence,EmpSlr.IsCTCComponent,EmpSlr.IsGrossComponent

                                , isnull(vpf.VoluntaryPFValue,0) VoluntaryPFValue
                                , isnull(BonusValue.Bonus,0) Bonus

								, BonusValue.SalaryHead B_SalaryHead
								, BonusValue.SalaryHeadID B_SalaryHeadID
								, BonusValue.IsCTCComponent B_IsCTCComponent
								, BonusValue.IsGrossComponent B_IsGrossComponent
								, BonusValue.HeadType B_HeadType
								--, BonusValue.HeadCategory B_HeadCategory

                                ,VPFhead.HeadCategory xHeadCategory,VPFhead.SalaryHeadID xSalaryHeadID
                                ,VPFhead.SalaryHead xSalaryHead,VPFhead.IsCTCComponent xIsCTCComponent
                                ,VPFhead.IsGrossComponent xIsGrossComponent,VPFhead.HeadType xHeadType
                                ,VPFhead.SalaryRuleMasterSystemID xSalaryRuleMasterSystemID
                                ---,VPFhead.IntegerInDisb, VPFhead.DecimalNo,
                                ,MW.Grade,CONVERT(DECIMAL(10, 2), ISNULL(MMDSA.TotalOTHr,0)/60) TotalOTHr
                                ,EmpSlr.DecimalNo AS DecimalNo ,EmpSlr.IntegerInDisb AS IntegerInDisb,EmpSlr.IsDecimalInDisb AS IsDecimalInDisb
                                ,EmpBasic.Line,EmpBasic.LegalDesignation
	                            ,EmpBasic.OverTimePmtPolicyMasterID
								,otd.FormulaDesID,otd.FormulaDes
								,ISNULL(EmpBasic.IsOTEntitle,0) IsOTEntitle
                              ,EmpBasic. LineId,EmpBasic.DesignationGroupId
                                ,EmpBasic.DesignationSequence,EmpBasic.PlantSequence,EmpBasic.UnitSequence,EmpBasic.DivisionSequence,EmpBasic.SubDivisionSequence,EmpBasic.DepartmentSequence
                                 ,SectionSequence,SubSectionSequence,EntityName,LineSequence,EntityId
                                FROM
                                    (
									 SELECT E.SystemID, convert(int, E.EmployeeCode)EmployeeCode, E.EmployeeName,E.EmployeeNameLocal,E.FatherName, E.DOJ,E.DOB,E.DOS, E.EmployeeStatus,E.PaymentMode,
											DG.UserName DesignationGroupName, E.DesignationSystemID, DE.UserName DesignationName,GVDE.UserName GivenDesignationName,GVDE.Sequence DesignationSequence,
											'' UserGroupSystemID, E.PlantID, F.UserName PlantName, F.Sequence PlantSequence, E.UnitID
											,FU.UserName UnitName,FU.Sequence UnitSequence, E.DivisionID, DV.UserName DivisionName,DV.Sequence DivisionSequence,E.SubdivisionID,subDV.UserName SubDivision,subDV.Sequence SubDivisionSequence, E.DepartmentID, DP.UserName DepartmentName,DP.Sequence DepartmentSequence,
											E.SectionID, S.UserName SectionName,S.Sequence SectionSequence, E.SubSectionID, SS.UserName SubSectionName,SS.Sequence SubSectionSequence, E.EmployeeCategorySystemID,
											EC.UserName EmpCategoryName,EC.Sequence EmployeeCategorySequence--, BK.BankNameShort BankName, BK.BankNameFull, E.BankAccNo
                                            ,ENT.UserName EntityName,Ent.Id EntityId,egdsgg.GivenDesignationGroup,e.SalaryRuleMasterSystemID,L.UserName Line, LD.UserName LegalDesignation--,eoe.IsOTEntitle
											,IsOTEntitle = Case  when ISNULL(EOE.IsOTEntitle,0) =1 then EOE.IsOTEntitle else ISNULL(DMCT.IsOTEntitled,0) end
										 , ISNULL(LD.UserName,GVD.UserName) LDDesignationGD,LSalGr.Code GradeCode
		                                  , ISNULL(LocLangLD.Name,LocLangGD.Name) DesignationLocal
											,OverTimePmtPolicyMasterID=case when isnull(eoe.EmpSystemID,'')<>'' then (select id from OverTimePmtPolicyMaster where IsDefault=1)
											when DMCT.IsOTEntitled=1 and isnull(DMCT.OverTimePmtPolicyMasterID,'')<>'' then DMCT.OverTimePmtPolicyMasterID
											else null end,E.LineId,EGDSGG.DesignationGroupId,L.Sequence LineSequence
                                     
                                           FROM EmployeeInformation E
												LEFT JOIN org.Plant F ON E.PlantID = F.Id
												LEFT JOIN hkp.DesignationGroup DG ON E.DesignationGroupId = DG.ID
												LEFT JOIN hkp.Designation DE ON E.GivenDesignationId = DE.Id
												LEFT JOIN hkp.Designation GVDE ON E.GivenDesignationId = GVDE.Id
												LEFT JOIN org.Unit FU ON E.UnitID = FU.Id
												LEFT JOIN org.Division DV ON E.DivisionID = DV.Id
												LEFT JOIN org.Department DP ON E.DepartmentID = DP.Id
												LEFT JOIN org.Section S ON E.SectionID = S.Id
												LEFT JOIN org.SubSection SS ON E.SubSectionID = SS.Id
                                                LEFT JOIN org.Line L ON L.Id = E.LineId
                                                LEFT  JOIN [MST].[ManpowerBudget] AS MB  on MB.Id = E.BudgetCode
								                LEFT  JOIN ORG.Entity AS ENT ON ENT.Id = MB.EntityId
												LEFT JOIN HKP.LegalDesignation LD ON LD.Id=E.LegalDesignationId
												LEFT JOIN HKP.Designation GVD ON GVD.Id=E.GivenDesignationId
                                                LEFT JOIN MST.LegalSalaryGradeDesignation LSGD ON LSGD.LegalDesignationId = LD.Id
                                              LEFT JOIN SCS.LegalSalaryGrade LSalGr ON LSalGr.Id = LSGD.LegalSalaryGradeId
												LEFT JOIN org.SubDivision subDV ON E.SubdivisionID = subDV.Id
												LEFT JOIN
                                                --hkp.EmployeeCategory EC ON E.EmployeeCategorySystemID = EC.Id
                                                (
                                                SELECT ECT.Id, ECT.UserName,ECT.Sequence , DM.DesignationId FROM [HKP].[EmployeeCategory] ECT
												LEFT JOIN MST.DesignationMaster DM ON ECT.Id=DM.EmployeeCategoryId
												)EC ON EC.DesignationId=E.GivenDesignationId
												LEFT JOIN (SELECT dm.DesignationGroupId,dm.DesignationId,dm.EmployeeCategoryId
									            ,DG.UserName GivenDesignationGroup
									            FROM MST.DesignationMaster DM
									            LEFT JOIN HKP.DesignationGroup DG ON DG.Id=DM.DesignationGroupId
									            ) EGDSGG ON EGDSGG.DesignationId=e.GivenDesignationId
									            AND EGDSGG.EmployeeCategoryId=e.EmployeeCategorySystemID
                                               LEFT JOIN EmployeeOTEntitle EOE ON EOE.EmpSystemID = E.SystemId AND EOE.IsOTEntitle=1
												LEFT JOIN  MST.DesignationMaster DMOT ON DMOT.DesignationId = E.GivenDesignationId
												LEFT JOIN  SCS.DesignationMasterConfiguration DMCT ON DMCT.DesignationMasterId = DMOT.Id and DMCT.plantid='" + para.PlantId + @"'
												 LEFT JOIN HKP.LocalLanguage LocLangLD ON LocLangLD.LegalDesignationId = E.LegalDesignationId AND LocLangLD.LanguageId = '" + para.LanguageId + @"'
                                                LEFT JOIN HKP.LocalLanguage LocLangGD ON LocLangGD.DesignationId = E.GivenDesignationId AND LocLangGD.LanguageId = '" + para.LanguageId + @"'
                              
									) EmpBasic
									LEFT JOIN (select * from OverTimePmtPolicyDetails where OverTimeDayType='Working Day') otd on otd.OverTimePmtPolicyID=EmpBasic.OverTimePmtPolicyMasterID

                                    INNER JOIN
											(
											 SELECT SPC.SystemID AS SlrProcChdSysID, SPC.SlrProcMstSystemID, SPM.SalaryProcID, SPM.FromDate, SPM.ToDate,
													SPC.EmpInfoSystemID, SPC.PlantID, SPM.UserGroupSystemID, SPM.MonthNo, SPM.YearNo, SPC.PayAbleShSystemID,
													SPC.SalaryHeadID, SPC.EntryCurrencyID, SPC.EntryAmount, SPC.DefineCurrencyID, SPC.DefineAmount,
													SPC.DisbusmentCurrencyID, SPC.DisbusmentAmount, SPC.AcltExcDisbSlrHDID, SPC.AcltExcDisbSlrHDAmt,
													CRE.Name AS PlantWiseExchangeCR, EXR.ToCurrencyBuying ExchangeRate, SPM.AmtDefinitionCurrencyID,
													CR.Name AS AmtDefinitionCurrency, SPM.AmtDefinitionCurrencyRate, SPC.IsNetPayEffect
                                                    ,SH.SalaryHead,sh.HeadCategory,sh.HeadType,isnull(psh.Sequence, 99) Sequence
                                                    ,SH.IsCTCComponent,sh.IsGrossComponent,dcm.DecimalNo,dcm.IntegerInDisb,dcm.IsDecimalInDisb
											 FROM SalaryProcChild SPC
														INNER JOIN SalaryProcMaster SPM ON SPC.SlrProcMstSystemID = SPM.SystemID
																							AND SPM." + salaryProcessSystemId + @"

                                                        LEFT JOIN SalaryHead sh on sh.SalaryHeadID=spc.SalaryHeadID
														LEFT JOIN (SELECT * from [MST].[PlantSalaryHeadSequence] where PlantId='" + para.PlantId + @"' ) PSH
																		ON PSH.SalaryHeadId=spc.SalaryHeadID

														LEFT JOIN scs.Currency CR ON SPM.AmtDefinitionCurrencyID = CR.Id
														LEFT JOIN (
																   SELECT * FROM ExchangerateDateWiseForHR
																   WHERE FromDate IN (
																					  SELECT MAX(FromDate) FromDate FROM ExchangerateDateWiseForHR
																						WHERE FromDate <= (
																										   SELECT MAX(FromDate) FromDate FROM SalaryProcMaster
																											WHERE " + salaryProcessSystemId + @"
                                                                                                                 -- AND SystemID IN (
																													--			   SELECT SlrProcMstSystemID FROM SalaryProcChild
                                                                                                                      --              WHERE PlantID = '" + para.PlantId + @"'
                                                                                                                         --         )
                                                                                                           )
                                                                                    )
																  ) EXR ON SPM.AmtDefinitionCurrencyID = EXR.FromCurrencyCode
																							AND SPC.PlantID = Exr.PlantID
														LEFT JOIN scs.Currency CRE ON EXR.FromCurrencyCode = CRE.Id
                                                  ------    for decimal part       ---------
														 LEFT JOIN
                                               ( SELECT SSM.EmpInfoSystemID,crc.SalaryHeadID,crc.DecimalNo,crc.IntegerInDisb,crc.IsDecimalInDisb
												FROM SalaryInfoDefineMaster SSM
												left join SalaryRuleMaster srm on srm.SystemID=SSM.SalaryRuleMasterSystemID
												left join CurrencyRuleMaster crm on crm.SystemID=srm.CurrencyRuleSystemID
												left join CurrencyRuleChild crc on crc.MstSystemID=crm.SystemID) dcm on  dcm.SalaryHeadID=SPC.SalaryHeadID  and SPC.EmpInfoSystemID=dcm.EmpInfoSystemID
												      -------   end decimal part-------
											) EmpSlr ON EmpBasic.SystemID = EmpSlr.EmpInfoSystemID AND EmpBasic.PlantID = EmpSlr.PlantID
                                LEFT JOIN (
										
												  SELECT EmpSystemId,MAX(EffectiveDate) EffectiveDate, VoluntaryPFValue from [PFEmployeeVoluntaryValue] 
												  Where EffectiveDate<='" + para.FromDate + @"'
												  Group By EmpSystemId,EffectiveDate,VoluntaryPFValue
										) VPF ON EmpBasic.SystemId=vpf.EmpSystemId

										LEFT JOIN(
										SELECT SH.HeadCategory ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
										,SH.IsGrossComponent,SH.HeadType,sr.SalaryRuleMasterSystemID
											  FROM [dbo].[SalaryRulePF] SR
											  LEFT JOIN SalaryHead SH ON SH.SalaryHeadID=SR.SalaryHeadID
											  WHERE SH.HeadCategory='PF Voluntary'
										) VPFhead ON VPFhead.SalaryRuleMasterSystemID=EmpBasic.SalaryRuleMasterSystemID

                                        LEFT JOIN
										(
										SELECT m.EmpSystemID,m.MonthNo,d.Value Bonus 
												--,SH.HeadCategory 
                                                ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
												,SH.IsGrossComponent,SH.HeadType
												FROM [BonusPolicyMonthlyRetainEmpWiseCalculation] m
												LEFT JOIN [BonusPolicyMonthlyRetainDistributionPmt] d on m.id=d.BnsPlyMntRetainID
												LEFT JOIN SalaryHead SH ON SH.SalaryHeadID=d.SalaryHeadID
												WHERE m.MonthNo=DATEPART(Month,'" + para.FromDate + @"')  AND m.YearNo=DATEPART(YEAR,'" + para.FromDate + @"')  
                                                --and d.SalaryHeadID=(select SalaryHeadID from SalaryHead where HeadCategory='Festival Bonus')
										) BonusValue ON EmpBasic.SystemId=BonusValue.EmpSystemID

                                    LEFT JOIN
		                                    (
											 SELECT EmpSystemID, MonthNo, YearNo, TotalProcDate, TotalPresent, TotalLate,
													TotalAbsent AbsentDays, TotalLv,TotalLWP, TotalMLv, TotalCompAssignLv, TotalWeekOff, TotalHoliDay,
													TotalWeekOffHoliDay, TotalOTHr, TotalNormalOTHr, TotalExtraOTHr
				                              FROM SalaryProceAttdnData
											) MMDSA ON EmpSlr.EmpInfoSystemID = MMDSA.EmpSystemID AND EmpSlr.MonthNo = MMDSA.MonthNo AND
						                               EmpSlr.YearNo = MMDSA.YearNo

                                    LEFT JOIN 
                                           		(
                                           		 SELECT E.SystemID, SUM(SV.SalaryHeadValue) SalaryHeadValue,LSG.UserName Grade
                                           			FROM EmployeeInformation E   
                                           					LEFT JOIN MST.ManpowerBudget b ON e.BudgetCode = b.Id
                                           					LEFT JOIN MST.LegalSalaryGradeDesignation GD ON GD.LegalDesignationId = E.LegalDesignationId 
                                                                                               AND E.PlantId = gd.PlantId
                                           					LEFT JOIN (
                                           								SELECT MAX(EffectiveDate)EffectiveDate, LegalSalaryGradeId, EmployeeLocationId 
                                           									FROM MST.LegalSalaryStructure 
                                           									WHERE EffectiveDate <= '" + para.FromDate + @"'
                                           								GROUP BY LegalSalaryGradeId, EmployeeLocationId 
                                           							  ) S ON S.LegalSalaryGradeId = GD.LegalSalaryGradeId AND S.EmployeeLocationId = B.EmployeeLocationId
                                           					LEFT JOIN MST.LegalSalaryStructure SS ON SS.LegalSalaryGradeId = S.LegalSalaryGradeId 
                                                                                           AND SS.EmployeeLocationId = S.EmployeeLocationId 
                                                                                           AND SS.EffectiveDate = S.EffectiveDate
                                           					LEFT JOIN MST.LegalSalaryStructureValue SV ON SV.LegalSalaryStructureId = SS.Id 																							
                                           					left join  [SCS].[LegalSalaryGrade] LSG ON LSG.Id=S.LegalSalaryGradeId
                                           			GROUP BY E.SystemId,LSG.UserName 
                                           		) MW ON MW.SystemId = EmpBasic.SystemId

                                                LEFT JOIN (
                                                SELECT bb.UserName BankName,b.BankAccNo,b.EmpSystemID FROM [dbo].[EmployeeBankInfo] b
                                                LEFT JOIN hkp.BankBranch bb ON b.BankBranchId=bb.Id
                                                ) BB ON BB.EmpSystemID = EmpBasic.SystemId

                                                LEFT JOIN
												( SELECT ed.DocNumber UANNo,ED.EmpSystemID FROM 
												EmployeeDocument ED 
												INNER JOIN (SELECT * FROM HKP.ComplianceDocument WHERE ProfileType = 'PF') CD ON CD.Id = ED.ComplianceDocumentId 
												) pf ON EmpBasic.SystemId = pf.EmpSystemID

												LEFT JOIN
												( SELECT ed.DocNumber ESICNo,ED.EmpSystemID FROM 
												EmployeeDocument ED 
												INNER JOIN (SELECT * FROM HKP.ComplianceDocument WHERE ProfileType = 'ESIC') CD ON CD.Id = ED.ComplianceDocumentId 
												) ESIC ON EmpBasic.SystemId = esic.EmpSystemID WHERE -- EmpBasic.DOJ <='" + para.ToDate + @"' 
                                                --AND (EmployeeStatus != 'Separated' OR CONVERT(DATE,DOS) >= CONVERT(DATE,'" + para.FromDate + @"'))
                                                 --EmpBasic.SystemId IN (select systemId from EmployeeInformation where EmployeeCode = '00094')                                              
                                                ";

                if (para.PlantId != "null" && para.PlantId != null && para.PlantId != "undefined" && para.PlantId != "")
                {
                    strSQL = strSQL + @" EmpBasic.PlantID = '" + para.PlantId + @"'  " + _wc + @"";
                }
                //if (sqlInStatement != "null" && sqlInStatement != null && sqlInStatement != "undefined" && sqlInStatement != "")
                //{
                //    strSQL = strSQL + @" AND EmpBasic.SystemId " + sqlInStatement + @"";
                //}
                if (para.UnitId != "null" && para.UnitId != null && para.UnitId != "undefined" && para.UnitId != "")
                {
                    strSQL = strSQL + @" AND UnitID = '" + para.UnitId + "'";
                }
                if (para.DivisionId != "null" && para.DivisionId != null && para.DivisionId != "undefined" && para.DivisionId != "")
                {
                    strSQL = strSQL + @" AND DivisionID = '" + para.DivisionId + "'";
                }
                if (para.DepartmentId != "null" && para.DepartmentId != null && para.DepartmentId != "undefined" && para.DepartmentId != "")
                {
                    strSQL = strSQL + @" AND DepartmentID = '" + para.DepartmentId + "'";
                }
                if (para.SectionId != "null" && para.SectionId != null && para.SectionId != "undefined" && para.SectionId != "")
                {
                    strSQL = strSQL + @" AND SectionID = '" + para.SectionId + "'";
                }
                if (para.SubSectionId != "null" && para.SubSectionId != null && para.SubSectionId != "undefined" && para.SubSectionId != "")
                {
                    strSQL = strSQL + @" AND SubSectionID = '" + para.SubSectionId + "'";
                }
                if (para.EmpCategoryId != "null" && para.EmpCategoryId != null && para.EmpCategoryId != "undefined" && para.EmpCategoryId != "")
                {
                    strSQL = strSQL + @" AND EmpBasic.EmployeeCategorySystemID = '" + para.EmpCategoryId + "'";
                }
                if (para.PaymentMode != "null" && para.PaymentMode != null && para.PaymentMode != "undefined" && para.PaymentMode != "")
                {
                    strSQL = strSQL + @" AND EmpBasic.PaymentMode = '" + para.PaymentMode + "'";
                }
                strSQL = strSQL + @") topSheet  GROUP BY topSheet.EntityName,EntityId,topSheet.DepartmentName,topSheet.SubSectionName,topSheet.SalaryHead
												 ,DepartmentSequence,SubSectionSequence
												 ,SalaryHeadID,  HeadType, Sequence, HeadCategory, IsCTCComponent, IsGrossComponent, IntegerInDisb, DecimalNo
												 order by topSheet.EntityId
												 ,DepartmentSequence,SubSectionSequence,topSheet.SalaryHead";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function


        public void GetSalaryTopSheet(PayRegisterParamList para, string groupBy, string employeeStatus, string employeeCategoryId, out DataSet dsRef)
        {
            string groupBySelection = "";
            string selection = "";
            string groupByOrdered = "";
            string wcEmpStatus = ""; string wcEmployeeCategory = "";
            if (employeeStatus == "Active" || employeeStatus == "Separated")
            {
                wcEmpStatus = @"AND EmpBasic.EmployeeStatus = '" + employeeStatus + @"' ";

                if (employeeStatus == "Separated")
                {
                    //wcEmpStatus = @"AND EmpBasic.EmployeeStatus = '" + employeeStatus + @"' and Month(EmpBasic.DOS) = " + para.Month + " and YEAR(EmpBasic.Dos) =  " + para.Year + "";
                    wcEmpStatus = @"Where ISNULL(SPM.SalaryProcFlag,'') = 'Separated'";
                }
                if (employeeStatus == "Active")
                {
                    //wcEmpStatus = @"AND EmpBasic.EmployeeStatus = '" + employeeStatus + @"' OR( EmpBasic.DOS > '" + para.ToDate + "' and EmpBasic.DOJ <=  '" + para.ToDate + "')";
                    wcEmpStatus = @"Where ISNULL(SPM.SalaryProcFlag,'') = ''";
                }
            }
            if (employeeStatus == "Maternity")
            {
                //   wcEmpStatus = @"AND EmpBasic.SystemID IN (

                //                                    SELECT LTR.EmpSystemID from LeaveTransaction LTR

                //                                    LEFT JOIN LeaveType LT ON LT.Id = LTR.LTSystemID

                //                                     WHERE LT.LeaveType = 'Maternity' AND

                //                                   ((MONTH(Convert(date, (FromDate) - 1)) = '" + para.Month + @"' and YEar(Convert(date, (FromDate) - 1)) = '" + para.Year + @"')

                //                                    OR
                //                                    (MONTH(Convert(date, (ToDate) + 1)) = '" + para.Month + @"' and YEar(Convert(date, (ToDate) + 1)) = '" + para.Year + @"')
                //)
                //)";
                //wcEmpStatus = @"Where ISNULL(SPM.SalaryProcFlag,'') = 'MLV'";
                wcEmpStatus = @"Where ISNULL(SPM.SalaryProcFlag,'') = 'MLV_PRE'";


            }
            if (!string.IsNullOrEmpty(employeeCategoryId) && employeeCategoryId != "null")
            {
                wcEmployeeCategory = @"Where EmployeeCategorySystemID IN(" + employeeCategoryId + @")";
            }
            if (groupBy == "DepartmentSubSctionEmployeeCatagory")
            {
                groupBySelection = "topSheet.DepartmentName,topSheet.DepartmentID,topSheet.SubSectionName,topSheet.SubSectionID,topSheet.EmpCategoryName,topSheet.EmployeeCategorySystemID,DepartmentSequence,SubSectionSequence,EmployeeCategorySequence";
                groupByOrdered = "DepartmentSequence,SubSectionSequence,EmployeeCategorySequence";
            }
            if (groupBy == "DepartmentEmployeeCategory")
            {
                selection = "topSheet.UnitName EntityName,topSheet.UnitSequence ,topSheet.UnitID EntityId,topSheet.SectionName,topSheet.SectionId,topSheet.SectionSequence,topSheet.SubSectionName,topSheet.SubSectionId,topSheet.SubSectionSequence,topSheet.Line,topSheet.LineId,topSheet.LineSequence,topSheet.DepartmentName,topSheet.DepartmentID,topSheet.EmpCategoryName,topSheet.EmployeeCategorySystemID,DepartmentSequence,EmployeeCategorySequence,topSheet.SalaryHead";

                groupBySelection = "topSheet.UnitName ,topSheet.UnitSequence ,topSheet.UnitID ,topSheet.SectionName,topSheet.SectionId,topSheet.SectionSequence,topSheet.SubSectionName,topSheet.SubSectionId,topSheet.SubSectionSequence,topSheet.Line,topSheet.LineId,topSheet.LineSequence,topSheet.DepartmentName,topSheet.DepartmentID,topSheet.EmpCategoryName,topSheet.EmployeeCategorySystemID,DepartmentSequence,EmployeeCategorySequence,topSheet.SalaryHead";
                groupByOrdered = "UnitSequence , DepartmentSequence,SectionSequence,SubSectionSequence,LineSequence,EmployeeCategorySequence";
            }

            var salaryProcessSystemId = "";
            if (!string.IsNullOrEmpty(para.SalaryProcessId) && para.SalaryProcessId != "undefined" && para.SalaryProcessId != "null")
            {
                salaryProcessSystemId = "SystemId IN ('" + para.SalaryProcessId + @"')";
            }
            else
            {
                //salaryProcessSystemId = @"SystemId IN( SELECT SystemID FROM SalaryProcMaster
                //                      WHERE SystemID IN(SELECT SlrProcMstSystemID FROM SalaryProcChild
                //                                        WHERE PlantID = '" + para.PlantId + @"' GROUP BY SlrProcMstSystemID)
                //                        AND MonthNo = Month('" + para.FromDate + "') AND YearNo = Year('" + para.FromDate + "')  and IsCompleteMonth = 1)";

                salaryProcessSystemId = @"SystemId IN( SELECT SystemID FROM SalaryProcMaster
                                      WHERE SystemID IN(SELECT SlrProcMstSystemID FROM SalaryProcChild
                                                        WHERE PlantID = '" + para.PlantId + @"' GROUP BY SlrProcMstSystemID)
                                        AND MonthNo = Month('" + para.FromDate + "') AND YearNo = Year('" + para.FromDate + "'))";
            }
            string strSQL;
            ConnectionManager.DAL.ConManager objCon;

            var _wc = string.Empty;

            try
            {

                strSQL = @"SELECT " + selection + @",COUNT(EmpInfoSystemID) TotalEmp,topSheet.SalaryHead,SalaryHeadID, SalaryHead,  HeadType, Sequence, HeadCategory, IsCTCComponent, IsGrossComponent, IntegerInDisb, DecimalNo
								,Sum(topSheet.DisbusmentAmount) DisbusmentAmount from (SELECT EmpSlr.EmpInfoSystemID,convert(int, EmpBasic.EmployeeCode)EmployeeCode, EmpBasic.EmployeeName, ISNULL(EmpBasic.EmployeeNameLocal,EmpBasic.EmployeeName) EmployeeNameLocal,Replace(Convert(varchar(11),EmpBasic.DOJ,106),' ','-') DOJ
                                , REPLACE(Convert(VARCHAR(11), EmpBasic.DOB, 106), ' ', '-') AS DOB,REPLACE(Convert(VARCHAR(11), EmpBasic.DOS, 106), ' ', '-') AS DOS,
                                EmpBasic.EmployeeStatus, EmpBasic.UnitID, EmpBasic.UnitName, EmpBasic.DivisionID, EmpBasic.DivisionName,
                                EmpBasic.DepartmentID, EmpBasic.DepartmentName, EmpBasic.SectionID, EmpBasic.SectionName, EmpBasic.SubSectionID,EmpBasic.SubDivision,EmpBasic.SubdivisionID,
                                EmpBasic.SubSectionName, EmpBasic.EmployeeCategorySystemID, EmpBasic.EmpCategoryName, EmpBasic.DesignationGroupName,
                                EmpBasic.DesignationSystemID, EmpBasic.DesignationName,EmpBasic.GivenDesignationName,EmpBasic.GivenDesignationGroup
                                , EmpBasic.PlantName
							     , EmpBasic.LDDesignationGD,EmpBasic.EmployeeCategorySequence
		                            ,  ISNULL(EmpBasic.DesignationLocal, EmpBasic.LDDesignationGD) DesignationLocal,EmpBasic.GradeCode,EmpBasic.FatherName
                                ,esic.ESICNo,pf.UANNo,bb.BankAccNo,bb.BankName, '' BankNameFull,ISNULL(MMDSA.TotalProcDate,0) TotalProcDate,ISNULL(MMDSA.TotalLate, 0) TotalLate
								,(ISNULL(MMDSA.TotalPresent, 0) + ISNULL(MMDSA.TotalLate, 0)) PresentDays,PaymentMode,
								ISNULL(MMDSA.AbsentDays, 0) AbsentDays,  ISNULL(MMDSA.TotalHoliDay + MMDSA.TotalWeekOffHoliDay,0) HoliDay, ISNULL(MMDSA.TotalWeekOff, 0) WeekOff,
								(ISNULL(MMDSA.TotalLv, 0) + ISNULL(MMDSA.TotalMLv, 0)) LeaveDays,ISNULL(MMDSA.TotalLWP,0) LWP, EmpSlr.SlrProcChdSysID, EmpSlr.SlrProcMstSystemID, EmpSlr.SalaryProcID,
                                EmpSlr.PlantID, EmpSlr.FromDate, EmpSlr.ToDate, EmpSlr.MonthNo, EmpSlr.YearNo, EmpSlr.PayAbleShSystemID,
                                EmpSlr.SalaryHeadID, EmpSlr.EntryCurrencyID, EmpSlr.EntryAmount, EmpSlr.DefineCurrencyID, EmpSlr.DefineAmount,
                                EmpSlr.DisbusmentCurrencyID, EmpSlr.DisbusmentAmount, EmpSlr.AcltExcDisbSlrHDID, EmpSlr.AcltExcDisbSlrHDAmt,
                                EmpSlr.PlantWiseExchangeCR, EmpSlr.ExchangeRate, EmpSlr.AmtDefinitionCurrencyID, EmpSlr.AmtDefinitionCurrency,
                                EmpSlr.AmtDefinitionCurrencyRate, EmpSlr.IsNetPayEffect
                                ,EmpSlr.SalaryHead,EmpSlr.HeadCategory,EmpSlr.HeadType,EmpSlr.Sequence,EmpSlr.IsCTCComponent,EmpSlr.IsGrossComponent

                                , isnull(vpf.VoluntaryPFValue,0) VoluntaryPFValue
                                , isnull(BonusValue.Bonus,0) Bonus

								, BonusValue.SalaryHead B_SalaryHead
								, BonusValue.SalaryHeadID B_SalaryHeadID
								, BonusValue.IsCTCComponent B_IsCTCComponent
								, BonusValue.IsGrossComponent B_IsGrossComponent
								, BonusValue.HeadType B_HeadType
								--, BonusValue.HeadCategory B_HeadCategory

                                ,VPFhead.HeadCategory xHeadCategory,VPFhead.SalaryHeadID xSalaryHeadID
                                ,VPFhead.SalaryHead xSalaryHead,VPFhead.IsCTCComponent xIsCTCComponent
                                ,VPFhead.IsGrossComponent xIsGrossComponent,VPFhead.HeadType xHeadType
                                ,VPFhead.SalaryRuleMasterSystemID xSalaryRuleMasterSystemID
                                ---,VPFhead.IntegerInDisb, VPFhead.DecimalNo,
                                ,CONVERT(DECIMAL(10, 2), ISNULL(MMDSA.TotalOTHr,0)/60) TotalOTHr
                                ,EmpSlr.DecimalNo AS DecimalNo ,EmpSlr.IntegerInDisb AS IntegerInDisb,EmpSlr.IsDecimalInDisb AS IsDecimalInDisb
                                ,EmpBasic.Line,EmpBasic.LegalDesignation
	                            ,EmpBasic.OverTimePmtPolicyMasterID
								,otd.FormulaDesID,otd.FormulaDes
								,ISNULL(EmpBasic.IsOTEntitle,0) IsOTEntitle
                              ,EmpBasic. LineId,EmpBasic.DesignationGroupId
                                ,EmpBasic.DesignationSequence,EmpBasic.PlantSequence,EmpBasic.UnitSequence,EmpBasic.DivisionSequence,EmpBasic.SubDivisionSequence,EmpBasic.DepartmentSequence
                                 ,SectionSequence,SubSectionSequence,EntityName,LineSequence,EntityId
                                FROM
                                    (
									 SELECT E.SystemID, convert(int, E.EmployeeCode)EmployeeCode, E.EmployeeName,E.EmployeeNameLocal,E.FatherName, E.DOJ,E.DOB,E.DOS, E.EmployeeStatus,E.PaymentMode,
											DG.UserName DesignationGroupName, E.DesignationSystemID, DE.UserName DesignationName,GVDE.UserName GivenDesignationName,GVDE.Sequence DesignationSequence,
											'' UserGroupSystemID, E.PlantID, F.UserName PlantName, F.Sequence PlantSequence, E.UnitID
											,FU.UserName UnitName,FU.Sequence UnitSequence, E.DivisionID, DV.UserName DivisionName,DV.Sequence DivisionSequence,E.SubdivisionID,subDV.UserName SubDivision,subDV.Sequence SubDivisionSequence, E.DepartmentID, DP.UserName DepartmentName,DP.Sequence DepartmentSequence,
											E.SectionID, S.UserName SectionName,S.Sequence SectionSequence, E.SubSectionID, SS.UserName SubSectionName,SS.Sequence SubSectionSequence, EC.Id EmployeeCategorySystemID,
											EC.UserName EmpCategoryName,EC.Sequence EmployeeCategorySequence--, BK.BankNameShort BankName, BK.BankNameFull, E.BankAccNo
                                            ,ENT.UserName EntityName,Ent.Id EntityId,egdsgg.GivenDesignationGroup,e.SalaryRuleMasterSystemID,L.UserName Line, LD.UserName LegalDesignation--,eoe.IsOTEntitle
											,IsOTEntitle = Case  when ISNULL(EOE.IsOTEntitle,0) =1 then EOE.IsOTEntitle else ISNULL(DMCT.IsOTEntitled,0) end
										 , ISNULL(LD.UserName,GVD.UserName) LDDesignationGD,LSalGr.Code GradeCode
		                                  , ISNULL(LocLangLD.Name,LocLangGD.Name) DesignationLocal
											,OverTimePmtPolicyMasterID=case when isnull(eoe.EmpSystemID,'')<>'' then (select id from OverTimePmtPolicyMaster where IsDefault=1)
											when DMCT.IsOTEntitled=1 and isnull(DMCT.OverTimePmtPolicyMasterID,'')<>'' then DMCT.OverTimePmtPolicyMasterID
											else null end,E.LineId,EGDSGG.DesignationGroupId,L.Sequence LineSequence
                                      ,E.CompanyId
                                           FROM EmployeeInformation E
												LEFT JOIN org.Plant F ON E.PlantID = F.Id
												LEFT JOIN hkp.DesignationGroup DG ON E.DesignationGroupId = DG.ID
												LEFT JOIN hkp.Designation DE ON E.GivenDesignationId = DE.Id
												LEFT JOIN hkp.Designation GVDE ON E.GivenDesignationId = GVDE.Id
												LEFT JOIN org.Unit FU ON E.UnitID = FU.Id
												LEFT JOIN org.Division DV ON E.DivisionID = DV.Id
												LEFT JOIN org.Department DP ON E.DepartmentID = DP.Id
												LEFT JOIN org.Section S ON E.SectionID = S.Id
												LEFT JOIN org.SubSection SS ON E.SubSectionID = SS.Id
                                                LEFT JOIN org.Line L ON L.Id = E.LineId
                                                LEFT  JOIN [MST].[ManpowerBudget] AS MB  on MB.Id = E.BudgetCode
								                LEFT  JOIN ORG.Entity AS ENT ON ENT.Id = MB.EntityId
												LEFT JOIN HKP.LegalDesignation LD ON LD.Id=E.LegalDesignationId
												LEFT JOIN HKP.Designation GVD ON GVD.Id=E.GivenDesignationId
                                                LEFT JOIN MST.LegalSalaryGradeDesignation LSGD ON LSGD.LegalDesignationId = LD.Id AND LSGD.PlantId = '" + para.PlantId + @"'
                                              LEFT JOIN SCS.LegalSalaryGrade LSalGr ON LSalGr.Id = LSGD.LegalSalaryGradeId and LSalGr.PlantId = '" + para.PlantId + @"'
												LEFT JOIN org.SubDivision subDV ON E.SubdivisionID = subDV.Id
												LEFT JOIN
                                                --hkp.EmployeeCategory EC ON E.EmployeeCategorySystemID = EC.Id
                                                (
                                                SELECT ECT.Id, ECT.UserName,ECT.Sequence , DM.DesignationId FROM [HKP].[EmployeeCategory] ECT
												LEFT JOIN MST.DesignationMaster DM ON ECT.Id=DM.EmployeeCategoryId
												)EC ON EC.DesignationId=E.GivenDesignationId
												LEFT JOIN (SELECT dm.DesignationGroupId,dm.DesignationId,dm.EmployeeCategoryId
									            ,DG.UserName GivenDesignationGroup
									            FROM MST.DesignationMaster DM
									            LEFT JOIN HKP.DesignationGroup DG ON DG.Id=DM.DesignationGroupId
									            ) EGDSGG ON EGDSGG.DesignationId=e.GivenDesignationId
									            AND EGDSGG.EmployeeCategoryId=e.EmployeeCategorySystemID
                                               LEFT JOIN EmployeeOTEntitle EOE ON EOE.EmpSystemID = E.SystemId AND EOE.IsOTEntitle=1
												LEFT JOIN  MST.DesignationMaster DMOT ON DMOT.DesignationId = E.GivenDesignationId
												LEFT JOIN  SCS.DesignationMasterConfiguration DMCT ON DMCT.DesignationMasterId = DMOT.Id and DMCT.plantid='" + para.PlantId + @"'
												 LEFT JOIN HKP.LocalLanguage LocLangLD ON LocLangLD.LegalDesignationId = E.LegalDesignationId AND LocLangLD.LanguageId = '" + para.LanguageId + @"'
                                                LEFT JOIN HKP.LocalLanguage LocLangGD ON LocLangGD.DesignationId = E.GivenDesignationId AND LocLangGD.LanguageId = '" + para.LanguageId + @"'
                              
									) EmpBasic
									LEFT JOIN (select * from OverTimePmtPolicyDetails where OverTimeDayType='Working Day') otd on otd.OverTimePmtPolicyID=EmpBasic.OverTimePmtPolicyMasterID

                                    INNER JOIN
											(
											 SELECT SPC.SystemID AS SlrProcChdSysID, SPC.SlrProcMstSystemID, SPM.SalaryProcID, SPM.FromDate, SPM.ToDate,
													SPC.EmpInfoSystemID, SPC.PlantID, SPM.UserGroupSystemID, SPM.MonthNo, SPM.YearNo, SPC.PayAbleShSystemID,
													SPC.SalaryHeadID, SPC.EntryCurrencyID, SPC.EntryAmount, SPC.DefineCurrencyID, SPC.DefineAmount,
													SPC.DisbusmentCurrencyID, SPC.DisbusmentAmount, SPC.AcltExcDisbSlrHDID, SPC.AcltExcDisbSlrHDAmt,
													CRE.Name AS PlantWiseExchangeCR, EXR.ToCurrencyBuying ExchangeRate, SPM.AmtDefinitionCurrencyID,
													CR.Name AS AmtDefinitionCurrency, SPM.AmtDefinitionCurrencyRate, SPC.IsNetPayEffect
                                                    ,SH.SalaryHead,sh.HeadCategory,sh.HeadType,isnull(psh.Sequence, 99) Sequence
                                                    ,SH.IsCTCComponent,sh.IsGrossComponent,dcm.DecimalNo,dcm.IntegerInDisb,dcm.IsDecimalInDisb
											 FROM SalaryProcChild SPC
														INNER JOIN SalaryProcMaster SPM ON SPC.SlrProcMstSystemID = SPM.SystemID
																							AND SPM." + salaryProcessSystemId + @"
                                                                                            
                                                        LEFT JOIN SalaryHead sh on sh.SalaryHeadID=spc.SalaryHeadID
														LEFT JOIN (SELECT * from [MST].[PlantSalaryHeadSequence] where PlantId='" + para.PlantId + @"' ) PSH
																		ON PSH.SalaryHeadId=spc.SalaryHeadID

														LEFT JOIN scs.Currency CR ON SPM.AmtDefinitionCurrencyID = CR.Id
														LEFT JOIN (
																   SELECT * FROM ExchangerateDateWiseForHR
																   WHERE FromDate IN (
																					  SELECT MAX(FromDate) FromDate FROM ExchangerateDateWiseForHR
																						WHERE FromDate <= (
																										   SELECT MAX(FromDate) FromDate FROM SalaryProcMaster
																											WHERE " + salaryProcessSystemId + @"
                                                                                                                 -- AND SystemID IN (
																													--			   SELECT SlrProcMstSystemID FROM SalaryProcChild
                                                                                                                      --              WHERE PlantID = '" + para.PlantId + @"'
                                                                                                                         --         )
                                                                                                           )
                                                                                    )
																  ) EXR ON SPM.AmtDefinitionCurrencyID = EXR.FromCurrencyCode
																							AND SPC.PlantID = Exr.PlantID
														LEFT JOIN scs.Currency CRE ON EXR.FromCurrencyCode = CRE.Id
                                                  ------    for decimal part       ---------
														 LEFT JOIN
                                               ( SELECT SSM.EmpInfoSystemID,crc.SalaryHeadID,crc.DecimalNo,crc.IntegerInDisb,crc.IsDecimalInDisb
												FROM SalaryInfoDefineMaster SSM
												left join SalaryRuleMaster srm on srm.SystemID=SSM.SalaryRuleMasterSystemID
												left join CurrencyRuleMaster crm on crm.SystemID=srm.CurrencyRuleSystemID
												left join CurrencyRuleChild crc on crc.MstSystemID=crm.SystemID) dcm on  dcm.SalaryHeadID=SPC.SalaryHeadID  and SPC.EmpInfoSystemID=dcm.EmpInfoSystemID
												      -------   end decimal part-------

                                             " + wcEmpStatus + @"
											) EmpSlr ON EmpBasic.SystemID = EmpSlr.EmpInfoSystemID AND EmpBasic.PlantID = EmpSlr.PlantID
                                LEFT JOIN (
										
												  SELECT EmpSystemId,MAX(EffectiveDate) EffectiveDate, VoluntaryPFValue from [PFEmployeeVoluntaryValue] 
												  Where EffectiveDate<='" + para.FromDate + @"'
												  Group By EmpSystemId,EffectiveDate,VoluntaryPFValue
										) VPF ON EmpBasic.SystemId=vpf.EmpSystemId

										LEFT JOIN(
										SELECT SH.HeadCategory ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
										,SH.IsGrossComponent,SH.HeadType,sr.SalaryRuleMasterSystemID
											  FROM [dbo].[SalaryRulePF] SR
											  LEFT JOIN SalaryHead SH ON SH.SalaryHeadID=SR.SalaryHeadID
											  WHERE SH.HeadCategory='PF Voluntary'
										) VPFhead ON VPFhead.SalaryRuleMasterSystemID=EmpBasic.SalaryRuleMasterSystemID

                                        LEFT JOIN
										(
										SELECT m.EmpSystemID,m.MonthNo,d.Value Bonus 
												--,SH.HeadCategory 
                                                ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
												,SH.IsGrossComponent,SH.HeadType
												FROM [BonusPolicyMonthlyRetainEmpWiseCalculation] m
												LEFT JOIN [BonusPolicyMonthlyRetainDistributionPmt] d on m.id=d.BnsPlyMntRetainID
												LEFT JOIN SalaryHead SH ON SH.SalaryHeadID=d.SalaryHeadID
												WHERE m.MonthNo=DATEPART(Month,'" + para.FromDate + @"')  AND m.YearNo=DATEPART(YEAR,'" + para.FromDate + @"')  
                                                --and d.SalaryHeadID=(select SalaryHeadID from SalaryHead where HeadCategory='Festival Bonus')
										) BonusValue ON EmpBasic.SystemId=BonusValue.EmpSystemID

                                    LEFT JOIN
		                                    (
											 SELECT EmpSystemID, MonthNo, YearNo, TotalProcDate, TotalPresent, TotalLate,
													TotalAbsent AbsentDays, TotalLv,TotalLWP, TotalMLv, TotalCompAssignLv, TotalWeekOff, TotalHoliDay,
													TotalWeekOffHoliDay, TotalOTHr, TotalNormalOTHr, TotalExtraOTHr
				                              FROM SalaryProceAttdnData
											) MMDSA ON EmpSlr.EmpInfoSystemID = MMDSA.EmpSystemID AND EmpSlr.MonthNo = MMDSA.MonthNo AND
						                               EmpSlr.YearNo = MMDSA.YearNo

                                 

                                                LEFT JOIN (
                                                SELECT bb.UserName BankName,b.BankAccNo,b.EmpSystemID FROM [dbo].[EmployeeBankInfo] b
                                                LEFT JOIN hkp.BankBranch bb ON b.BankBranchId=bb.Id
                                                ) BB ON BB.EmpSystemID = EmpBasic.SystemId

                                                LEFT JOIN
												( SELECT ed.DocNumber UANNo,ED.EmpSystemID FROM 
												EmployeeDocument ED 
												INNER JOIN (SELECT * FROM HKP.ComplianceDocument WHERE ProfileType = 'PF') CD ON CD.Id = ED.ComplianceDocumentId 
												) pf ON EmpBasic.SystemId = pf.EmpSystemID

												LEFT JOIN
												( SELECT ed.DocNumber ESICNo,ED.EmpSystemID FROM 
												EmployeeDocument ED 
												INNER JOIN (SELECT * FROM HKP.ComplianceDocument WHERE ProfileType = 'ESIC') CD ON CD.Id = ED.ComplianceDocumentId 
												) ESIC ON EmpBasic.SystemId = esic.EmpSystemID WHERE ";

                if (para.PlantId != "null" && para.PlantId != null && para.PlantId != "undefined" && para.PlantId != "")
                {
                    strSQL = strSQL + @"EmpBasic.CompanyId = '" + para.CompanyId + @"' and EmpBasic.PlantID = '" + para.PlantId + @"'  " + _wc + @"";
                }

                strSQL = strSQL + @") topSheet " + wcEmployeeCategory + @"  GROUP BY " + groupBySelection + @",topSheet.SalaryHead
												 
												 ,SalaryHeadID,  HeadType, Sequence, HeadCategory, IsCTCComponent, IsGrossComponent, IntegerInDisb, DecimalNo
												 order by 
												 " + groupByOrdered + @",topSheet.SalaryHead";


                ConnectionManager.clsConnectionManager con = new clsConnectionManager(600);
                con.getDataSet(strSQL, out dsRef);
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function


        public void GetSalaryInfoSlrProcIDWiseCombined(ParamList para, out DataSet dsRef)
        {
            string strSQL;
            ConnectionManager.DAL.ConManager objCon;
            var _wc = string.Empty;

            if (para.EmployeeId != "")
            {
                _wc = "  SYSTEMID IN (" + para.EmployeeId + @")";
            }
            else
            {
                if (para.PayGroup.ToUpper() != "NOGROUP")
                {
                    _wc = @" EmpInfoSystemID  IN (SELECT employeeid from MST.PayrollGroupMaster where PayrollGroupId = '" + para.PayGroup + @"')";
                }
                if (para.PayGroup.ToUpper() == "NOGROUP")
                {
                    _wc = @" EmpInfoSystemID NOT IN ( SELECT employeeid from MST.PayrollGroupMaster)";
                }

            }
            try
            {
                strSQL = @"SELECT EmpSlr.EmpInfoSystemID, EmpBasic.EmployeeCode, EmpBasic.EmployeeName, Replace(Convert(varchar(11),EmpBasic.DOJ,106),' ','-') DOJ,
                                EmpBasic.EmployeeStatus, EmpBasic.UnitID, EmpBasic.UnitName, EmpBasic.DivisionID, EmpBasic.DivisionName,
                                EmpBasic.DepartmentID, EmpBasic.DepartmentName, EmpBasic.SectionID, EmpBasic.SectionName, EmpBasic.SubSectionID,
                                EmpBasic.SubSectionName, EmpBasic.EmployeeCategorySystemID, EmpBasic.EmpCategoryName, EmpBasic.DesignationGroupName,
                                EmpBasic.DesignationSystemID, EmpBasic.DesignationName,EmpBasic.GivenDesignationName,EmpBasic.GivenDesignationGroup, EmpBasic.PlantName,
								--EmpBasic.BankName,
                                --EmpBasic.BankNameFull, EmpBasic.BankAccNo,
                                '' BankName, '' BankNameFull, '' BankAccNo,
								(ISNULL(MMDSA.TotalPresent, 0) + ISNULL(MMDSA.TotalLate, 0))  PresentDays,
								ISNULL(MMDSA.AbsentDays, 0) AbsentDays, ISNULL(MMDSA.TotalHoliDay, 0) HoliDay, ISNULL(MMDSA.TotalWeekOff, 0) WeekOff,
								(ISNULL(MMDSA.TotalLv, 0) + ISNULL(MMDSA.TotalMLv, 0)) LeaveDays, EmpSlr.SlrProcChdSysID, EmpSlr.SlrProcMstSystemID, EmpSlr.SalaryProcID,
                                EmpSlr.PlantID, EmpSlr.FromDate, EmpSlr.ToDate, EmpSlr.MonthNo, EmpSlr.YearNo, EmpSlr.PayAbleShSystemID,
                                EmpSlr.SalaryHeadID, EmpSlr.EntryCurrencyID, EmpSlr.EntryAmount, EmpSlr.DefineCurrencyID, EmpSlr.DefineAmount,
                                EmpSlr.DisbusmentCurrencyID, EmpSlr.DisbusmentAmount, EmpSlr.AcltExcDisbSlrHDID, EmpSlr.AcltExcDisbSlrHDAmt,
                                EmpSlr.PlantWiseExchangeCR, EmpSlr.ExchangeRate, EmpSlr.AmtDefinitionCurrencyID, EmpSlr.AmtDefinitionCurrency,
                                EmpSlr.AmtDefinitionCurrencyRate, EmpSlr.IsNetPayEffect
                                ,EmpSlr.SalaryHead,EmpSlr.HeadCategory,EmpSlr.HeadType,EmpSlr.Sequence,EmpSlr.IsCTCComponent,EmpSlr.IsGrossComponent

                                , isnull(vpf.VoluntaryPFValue,0) VoluntaryPFValue
                                , isnull(BonusValue.Bonus,0) Bonus

								, BonusValue.SalaryHead B_SalaryHead
								, BonusValue.SalaryHeadID B_SalaryHeadID
								, BonusValue.IsCTCComponent B_IsCTCComponent
								, BonusValue.IsGrossComponent B_IsGrossComponent
								, BonusValue.HeadType B_HeadType
								--, BonusValue.HeadCategory B_HeadCategory

                                ,VPFhead.HeadCategory xHeadCategory,VPFhead.SalaryHeadID xSalaryHeadID
                                ,VPFhead.SalaryHead xSalaryHead,VPFhead.IsCTCComponent xIsCTCComponent
                                ,VPFhead.IsGrossComponent xIsGrossComponent,VPFhead.HeadType xHeadType
                                ,VPFhead.SalaryRuleMasterSystemID xSalaryRuleMasterSystemID

                            FROM
                                    (
									 SELECT E.SystemID, E.EmployeeCode, E.EmployeeName, E.DOJ, E.EmployeeStatus,
											DG.UserName DesignationGroupName, E.DesignationSystemID, DE.UserName DesignationName,GVDE.UserName GivenDesignationName,
											'' UserGroupSystemID, E.PlantID, F.UserName PlantName, E.UnitID,
											FU.UserName UnitName, E.DivisionID, DV.UserName DivisionName, E.DepartmentID, DP.UserName DepartmentName,
											E.SectionID, S.UserName SectionName, E.SubSectionID, SS.UserName SubSectionName, E.EmployeeCategorySystemID,
											EC.UserName EmpCategoryName--, BK.BankNameShort BankName, BK.BankNameFull, E.BankAccNo
                                            ,egdsgg.GivenDesignationGroup,e.SalaryRuleMasterSystemID
                                     FROM EmployeeInformation E
												LEFT JOIN org.Plant F ON E.PlantID = F.Id
												LEFT JOIN hkp.DesignationGroup DG ON E.DesignationGroupId = DG.ID
												LEFT JOIN hkp.Designation DE ON E.GivenDesignationId = DE.Id
												LEFT JOIN hkp.Designation GVDE ON E.GivenDesignationId = GVDE.Id
												LEFT JOIN org.Unit FU ON E.UnitID = FU.Id
												LEFT JOIN org.Division DV ON E.DivisionID = DV.Id
												LEFT JOIN org.Department DP ON E.DepartmentID = DP.Id
												LEFT JOIN org.Section S ON E.SectionID = S.Id
												LEFT JOIN org.SubSection SS ON E.SubSectionID = SS.Id
												LEFT JOIN
                                                --hkp.EmployeeCategory EC ON E.EmployeeCategorySystemID = EC.Id
                                                (
                                                SELECT ECT.Id, ECT.UserName, DM.DesignationId FROM [HKP].[EmployeeCategory] ECT
												LEFT JOIN MST.DesignationMaster DM ON ECT.Id=DM.EmployeeCategoryId
												)EC ON EC.DesignationId=E.GivenDesignationId
												LEFT JOIN (SELECT dm.DesignationGroupId,dm.DesignationId,dm.EmployeeCategoryId
									            ,dg.UserName GivenDesignationGroup
									            FROM MST.DesignationMaster dm
									            LEFT JOIN HKP.DesignationGroup dg on dg.Id=dm.DesignationGroupId
									            ) egdsgg on egdsgg.DesignationId=e.GivenDesignationId
									            and egdsgg.EmployeeCategoryId=e.EmployeeCategorySystemID

									) EmpBasic
                                    INNER JOIN
											(
											 SELECT SPC.SystemID AS SlrProcChdSysID, SPC.SlrProcMstSystemID, SPM.SalaryProcID, SPM.FromDate, SPM.ToDate,
													SPC.EmpInfoSystemID, SPC.PlantID, SPM.UserGroupSystemID, SPM.MonthNo, SPM.YearNo, SPC.PayAbleShSystemID,
													SPC.SalaryHeadID, SPC.EntryCurrencyID, SPC.EntryAmount, SPC.DefineCurrencyID, SPC.DefineAmount,
													SPC.DisbusmentCurrencyID, SPC.DisbusmentAmount, SPC.AcltExcDisbSlrHDID, SPC.AcltExcDisbSlrHDAmt,
													CRE.Name AS PlantWiseExchangeCR, EXR.ToCurrencyBuying ExchangeRate, SPM.AmtDefinitionCurrencyID,
													CR.Name AS AmtDefinitionCurrency, SPM.AmtDefinitionCurrencyRate, SPC.IsNetPayEffect
                                                    ,sh.SalaryHead,sh.HeadCategory,sh.HeadType,isnull(psh.Sequence, 99) Sequence
                                                    ,sh.IsCTCComponent,sh.IsGrossComponent
											 FROM SalaryProcChild SPC
														INNER JOIN SalaryProcMaster SPM ON SPC.SlrProcMstSystemID = SPM.SystemID
																							AND SPM.SalaryProcID = '" + para.SalaryProcessId + @"'

                                                        LEFT JOIN SalaryHead sh on sh.SalaryHeadID=spc.SalaryHeadID
														LEFT JOIN (select * from [MST].[PlantSalaryHeadSequence] where PlantId='" + para.PlantId + @"' ) psh
																		on psh.SalaryHeadId=spc.SalaryHeadID

														LEFT JOIN scs.Currency CR ON SPM.AmtDefinitionCurrencyID = CR.Id
														LEFT JOIN (
																   SELECT * FROM ExchangerateDateWiseForHR
																   WHERE FromDate IN (
																					  SELECT MAX(FromDate) FromDate FROM ExchangerateDateWiseForHR
																						WHERE FromDate <= (
																										   SELECT MAX(FromDate) FromDate FROM SalaryProcMaster
																											WHERE SalaryProcID = '" + para.SalaryProcessId + @"'
                                                                                                                  AND SystemID IN (
																																   SELECT SlrProcMstSystemID FROM SalaryProcChild
                                                                                                                                    WHERE PlantID = '" + para.PlantId + @"'
                                                                                                                                  )
                                                                                                           )
                                                                                    )
																  ) EXR ON SPM.AmtDefinitionCurrencyID = EXR.FromCurrencyCode
																							AND SPC.PlantID = Exr.PlantID
														LEFT JOIN scs.Currency CRE ON EXR.FromCurrencyCode = CRE.Id
											) EmpSlr ON EmpBasic.SystemID = EmpSlr.EmpInfoSystemID AND EmpBasic.PlantID = EmpSlr.PlantID
                                left join (
										
												  select EmpSystemId,MAX(EffectiveDate) EffectiveDate, VoluntaryPFValue from [PFEmployeeVoluntaryValue] 
												  Where EffectiveDate<='" + para.ToDate + @"'
												  Group By EmpSystemId,EffectiveDate,VoluntaryPFValue
										) VPF on EmpBasic.SystemId=vpf.EmpSystemId

										left join(
										SELECT SH.HeadCategory ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
										,SH.IsGrossComponent,SH.HeadType,sr.SalaryRuleMasterSystemID
											  FROM [dbo].[SalaryRulePF] SR
											  left join SalaryHead SH ON SH.SalaryHeadID=SR.SalaryHeadID
											  where SH.HeadCategory='PF Voluntary'
										) VPFhead on VPFhead.SalaryRuleMasterSystemID=EmpBasic.SalaryRuleMasterSystemID

                                        left join
										(
										select m.EmpSystemID,m.MonthNo,d.Value Bonus 
												 ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
												,SH.IsGrossComponent,SH.HeadType
												from [BonusPolicyMonthlyRetainEmpWiseCalculation] m
												left join [BonusPolicyMonthlyRetainDistributionPmt] d on m.id=d.BnsPlyMntRetainID
												left join SalaryHead SH ON SH.SalaryHeadID=d.SalaryHeadID
												where m.MonthNo=DATEPART(Month,'" + para.FromDate + @"')  AND m.YearNo=DATEPART(YEAR,'" + para.FromDate + @"')  
                                                 --and d.SalaryHeadID=(select SalaryHeadID from SalaryHead where HeadCategory='Festival Bonus')
										) BonusValue on EmpBasic.SystemId=BonusValue.EmpSystemID

                                    LEFT JOIN
		                                    (
											 SELECT EmpSystemID, MonthNo, YearNo, TotalProcDate, TotalPresent, TotalLate,
													TotalAbsent AbsentDays, TotalLv, TotalMLv, TotalCompAssignLv, TotalWeekOff, TotalHoliDay,
													TotalWeekOffHoliDay, TotalOTHr, TotalNormalOTHr, TotalExtraOTHr
				                              FROM AttdnDataMonthlySummary
											) MMDSA ON EmpSlr.EmpInfoSystemID = MMDSA.EmpSystemID AND EmpSlr.MonthNo = MMDSA.MonthNo AND
						                               EmpSlr.YearNo = MMDSA.YearNo";

                if (para.PlantId != "ALL")
                {
                    strSQL = strSQL + @" WHERE EmpBasic.PlantID = '" + para.PlantId + @"' AND " + _wc + @"";
                }



                //strSQL = strSQL + @"ORDER BY EmpBasic.DivisionId,EmpBasic.SubdivisionID,EmpBasic.UnitId,EmpBasic.DepartmentId, EmpBasic.EmployeeCode";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function

        public void GetSalaryStructActual(ParamList para, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;
            clsStaticInfo obs = null;
            try
            {
                obs = new clsStaticInfo();
                strSql = @"SELECT * FROM
                           (
                           SELECT E.SystemID
	                            , E.EmployeeCode
	                            , E.EmployeeName
	                            , REPLACE(Convert(VARCHAR(11), E.DOB, 106), ' ', '-') AS DOB
	                            , E.FatherName
	                            , E.MotherName
	                            , E.EmpType EmployeeType
	                            , E.EmploymentType EmploymentNature
	                            , E.NationalID
	                            , E.GenderID GenderName
	                            , REPLACE(Convert(VARCHAR(11), E.DOJ, 106), ' ', '-') AS DOJ
	                            , REPLACE(Convert(VARCHAR(11), E.DOC, 106), ' ', '-') AS DOC
                                    " + obs.EntityColumns() + @"

                                   --U.UserName AS Unit, Dv.UserName AS Division, De.UserName AS Department, Se.UserName AS Section,
                                   --SuS.UserName SubSection, Dsg.UserName AS Designation, EC.UserName EmpCategoryName

                                , Cm.UserName CompanyName
	                            , CAM.Address1
	                            , CAM.Address2
	                            , E.EmployeeCategorySystemID
	                            , E.UnitID
	                            , E.DivisionID
	                            , E.DepartmentID
	                            , E.DesignationSystemID
	                            , E.SectionID
	                            , E.SubSectionID
	                            , E.LineID
	                            , E.DesignationGroupID
	                            , E.SubSecStrucSystemID
	                            , E.EmployeeStatus
	                            , P.UserName PlantName
	                            , (PAM.[Address1] + ', ' + PAM.[Address2] + ', ' + PAMC.UserName + ' - ' + PAM.Postcode) FactoryAddress
	                            , GC.UserName GroupName
	                            , (CGAM.[Address1] + ', ' + CGAM.[Address2] + ', ' + CT.UserName + ' - ' + CGAM.Postcode + ', Contact: ' + CGAM.Phone) GroupAddress
	                            , EmpSlr.SalaryHeadID
	                            , sh.SalaryHead
	                            , isnull(psh.Sequence, 99) Sequence
	                            , sh.HeadType
	                            , sh.HeadCategory
	                            , EmpSlr.EntryCurrencyID
	                            , EmpSlr.EntryAmount
	                            , EmpSlr.DefineCurrencyID
	                            , EmpSlr.DefineAmount
	                            , EmpSlr.AmtDefinitionCurrencyID AmtDefinationCurrencyID
	                            , EmpSlr.AmtDefinitionRate AmtDefinationRate
	                            , E.PlantID
	                            , BK.UserName BankNameShort
	                            , E.BankAccNo
                                ,sh.IsCTCComponent,sh.IsGrossComponent,mst.EmpInfoSystemID,mw.SalaryHeadValue

                                , isnull(vpf.VoluntaryPFValue,0) VoluntaryPFValue
                                , isnull(BonusValue.Bonus,0) Bonus

								, BonusValue.SalaryHead B_SalaryHead
								, BonusValue.SalaryHeadID B_SalaryHeadID
								, BonusValue.IsCTCComponent B_IsCTCComponent
								, BonusValue.IsGrossComponent B_IsGrossComponent
								, BonusValue.HeadType B_HeadType
								, BonusValue.HeadCategory B_HeadCategory

                                ,VPFhead.HeadCategory xHeadCategory,VPFhead.SalaryHeadID xSalaryHeadID
                                ,VPFhead.SalaryHead xSalaryHead,VPFhead.IsCTCComponent xIsCTCComponent
                                ,VPFhead.IsGrossComponent xIsGrossComponent,VPFhead.HeadType xHeadType
                                ,VPFhead.SalaryRuleMasterSystemID xSalaryRuleMasterSystemID
	                            ,crc.IntegerInDisb,crc.DecimalNo
				            FROM EmployeeInformation AS E
LEFT OUTER JOIN MST.ManpowerBudget mpb on mpb.Id=e.BudgetCode
									LEFT OUTER JOIN ORG.Position PO ON mpb.PositionId=PO.Id
                                    LEFT OUTER JOIN ORG.Entity EN ON mpb.EntityId=EN.Id 
                                        " + obs.EntityTables() + @"
                                        left outer JOIN 
											(
												select e.systemid												
												,sum(sv.SalaryHeadValue) SalaryHeadValue

												 from EmployeeInformation e   
												left join mst.ManpowerBudget b on e.BudgetCode=b.Id
												left join mst.LegalSalaryGradeDesignation gd on gd.LegalDesignationId=e.LegalDesignationId 
                                                                                                and e.PlantId=gd.PlantId
												left join (
												select max(EffectiveDate)EffectiveDate
                                                                    ,LegalSalaryGradeId
                                                                    ,EmployeeLocationId 
												                    from mst.LegalSalaryStructure 
												                    WHERE EffectiveDate<='" + para.FromDate + @"'
                                                                     --EffectiveDate<='31-Aug-2018'
												                    group by LegalSalaryGradeId
                                                                            ,EmployeeLocationId 
												) s on s.LegalSalaryGradeId=gd.LegalSalaryGradeId and s.EmployeeLocationId=b.EmployeeLocationId
												left join mst.LegalSalaryStructure  ss on ss.LegalSalaryGradeId=s.LegalSalaryGradeId 
                                                                                            and ss.EmployeeLocationId=s.EmployeeLocationId 
                                                                                            and ss.EffectiveDate=s.EffectiveDate
												left join mst.LegalSalaryStructureValue sv on sv.LegalSalaryStructureId=ss.Id 																							
												group by e.SystemId
											) MW on mw.SystemId=e.SystemId

                                        left outer JOIN
								                ORG.Plant AS p ON E.PlantId = p.Id
						                left outer JOIN
								                ORG.Company AS Cm ON E.CompanyID = Cm.Id
						                left outer JOIN
								                ORG.CompanyGroup AS GC ON E.GroupID = GC.Id
										left outer JOIN
												HKP.Bank AS BK ON E.BankSystemID = BK.Id
										left outer JOIN
												MST.AddressMaster AS CAM ON Cm.AddressMasterId = CAM.Id
										left outer JOIN
												MST.AddressMaster AS PAM ON P.AddressMasterId = PAM.Id
										left outer JOIN
												MST.AddressMaster AS CGAM ON GC.AddressMasterId = CGAM.Id
										left outer JOIN
												SCS.City AS PAMC ON PAM.CityId = PAMC.Id
										left outer JOIN
												SCS.City AS CT ON CGAM.CityId = CT.Id
                                        left outer JOIN (select * from SalaryInfoDefineMaster where IsApproved=1) mst ON E.SystemID= mst.EmpInfoSystemID
										left outer  join SalaryInfoDefine EmpSlr on EmpSlr.SalaryID=mst.SystemID
	                                    left outer join SalaryHead sh on sh.SalaryHeadID=EmpSlr.SalaryHeadID

										left join SalaryRuleMaster srm on srm.SystemID=mst.SalaryRuleMasterSystemID
										left join CurrencyRuleChild crc on crc.MstSystemID=srm.CurrencyRuleSystemID and crc.SalaryHeadID=sh.SalaryHeadID

                                        left join (
										
												  select EmpSystemId,MAX(EffectiveDate) EffectiveDate, VoluntaryPFValue from [PFEmployeeVoluntaryValue] 
												  Where EffectiveDate<='" + para.FromDate + @"'
												  --Where EffectiveDate<='31-Aug-2018'
												  Group By EmpSystemId,EffectiveDate,VoluntaryPFValue
										) VPF on e.SystemId=vpf.EmpSystemId

										left join(
										SELECT SH.HeadCategory ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
										,SH.IsGrossComponent,SH.HeadType,sr.SalaryRuleMasterSystemID
											  FROM [dbo].[SalaryRulePF] SR
											  left join SalaryHead SH ON SH.SalaryHeadID=SR.SalaryHeadID
											  where SH.HeadCategory='PF Voluntary'
										) VPFhead on VPFhead.SalaryRuleMasterSystemID=mst.SalaryRuleMasterSystemID

                                        left join
										(
										select m.EmpSystemID,m.MonthNo,d.Value Bonus 
												,SH.HeadCategory ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
												,SH.IsGrossComponent,SH.HeadType
												from [BonusPolicyMonthlyRetainEmpWiseCalculation] m
												left join [BonusPolicyMonthlyRetainDistributionPmt] d on m.id=d.BnsPlyMntRetainID
												left join SalaryHead SH ON SH.SalaryHeadID=d.SalaryHeadID
												where m.MonthNo=DATEPART(Month,'" + para.FromDate + @"') 
                                                --m.MonthNo=DATEPART(Month,'31-Aug-2018')
                                        and d.SalaryHeadID=
												(select SalaryHeadID from SalaryHead where HeadCategory='Festival Bonus')
										) BonusValue on e.SystemId=BonusValue.EmpSystemID


										left outer join (select * from [MST].[PlantSalaryHeadSequence] where PlantId='" + para.PlantId + @"' ) psh
										on psh.SalaryHeadId=EmpSlr.SalaryHeadID
                         ) A  WHERE --EmployeeStatus = 'Active' and
                        ISNULL(EmpInfoSystemID,'')<>'' AND PlantID = '" + para.PlantId + @"'";


                if (para.EmployeeId != "")
                {
                    strSql = strSql + @" AND SystemID IN (" + para.EmployeeId + ")";
                }

                strSql = strSql + @"
                        ORDER BY DivisionId,UnitId,DepartmentId, EmployeeCode";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function 

        public void GetEmpMinWageInfo(ParamList para, out DataSet dsRef)
        {
            var paraDate = Convert.ToDateTime(para.FromDate);

            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;
            clsStaticInfo obs = null;
            try
            {
                obs = new clsStaticInfo();
                strSql = @"SELECT E.SystemID empSystemId, ISNULL(SUM(SV.SalaryHeadValue),0) SalaryHeadValue
	                 FROM EmployeeInformation E   
			LEFT JOIN MST.ManpowerBudget b ON e.BudgetCode = b.Id
			LEFT JOIN MST.LegalSalaryGradeDesignation GD ON GD.LegalDesignationId = E.LegalDesignationId 
                                                                                   AND E.PlantId = gd.PlantId
			LEFT JOIN (
						SELECT MAX(EffectiveDate)EffectiveDate, LegalSalaryGradeId, EmployeeLocationId 
							FROM MST.LegalSalaryStructure 
							WHERE EffectiveDate <= '" + para.FromDate + @"'
						GROUP BY LegalSalaryGradeId, EmployeeLocationId 
					  ) S ON S.LegalSalaryGradeId = GD.LegalSalaryGradeId AND S.EmployeeLocationId = B.EmployeeLocationId
			LEFT JOIN MST.LegalSalaryStructure SS ON SS.LegalSalaryGradeId = S.LegalSalaryGradeId 
                                                                               AND SS.EmployeeLocationId = S.EmployeeLocationId 
                                                                               AND SS.EffectiveDate = S.EffectiveDate
			LEFT JOIN MST.LegalSalaryStructureValue SV ON SV.LegalSalaryStructureId = SS.Id 		
			
			where E.SystemId IN ( " + para.EmployeeId + @"	)																				
	 GROUP BY E.SystemId";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function  

        public void GetEmpSalaryStructureSql(ParamList para, string sUnitID, string sDivID, string sDepID, string sSecID, string sSubSecID, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;
            clsStaticInfo obs = null;

            var _wc = string.Empty;

            if (para.EmployeeId != "")
            {
                _wc = "  SYSTEMID IN (" + para.EmployeeId + @")";
            }
            else
            {
                if (para.PayGroup.ToUpper() != "NO GROUP")
                {
                    _wc = @" EmpInfoSystemID  IN (SELECT employeeid from MST.PayrollGroupMaster where PayrollGroupId = '" + para.PayGroup + @"')";
                }
                if (para.PayGroup.ToUpper() == "NO GROUP")
                {
                    _wc = @" EmpInfoSystemID NOT IN ( SELECT employeeid from MST.PayrollGroupMaster)";
                }

            }

            try
            {
                obs = new clsStaticInfo();
                strSql = @"SELECT * FROM
                          (
                           SELECT E.SystemID, E.EmployeeCode,CONVERT(INT,E.EmployeeCode) EmployeeCodes, E.EmployeeName, REPLACE(Convert(VARCHAR(11), E.DOB, 106), ' ', '-') AS DOB,
	                              E.FatherName, E.MotherName, E.EmpType EmployeeType, E.EmploymentType EmploymentNature, E.NationalID,
	                              E.GenderID GenderName, REPLACE(Convert(VARCHAR(11), E.DOJ, 106), ' ', '-') AS DOJ,REPLACE(Convert(VARCHAR(11), E.DOS, 106), ' ', '-') AS DOS,
	                              REPLACE(Convert(VARCHAR(11), E.DOC, 106), ' ', '-') AS DOC, DG.UserName DesignationGroup, D.UserName Designation,
								  GVD.UserName GivenDesignation, L.UserName Line, U.UserName Unit, Dv.UserName Division, Dp.UserName Department,
								  S.UserName Section, SB.UserName SubSection, EC.UserName AS EmpCategory, Cm.UserName CompanyName, CAM.Address1,
	                              CAM.Address2, E.EmployeeCategorySystemID, E.UnitID, E.DivisionID, E.DepartmentID, E.DesignationSystemID,
	                              E.SectionID, E.SubSectionID, E.LineID, E.DesignationGroupID, E.SubSecStrucSystemID, E.EmployeeStatus,
	                              P.UserName PlantName, (PAM.[Address1] + ', ' + PAM.[Address2] + ', ' + PAMC.UserName + ' - ' + PAM.Postcode) FactoryAddress,
	                              GC.UserName GroupName, (CGAM.[Address1] + ', ' + CGAM.[Address2] + ', ' + CT.UserName + ' - ' + CGAM.Postcode + ', Contact: ' + CGAM.Phone) GroupAddress,
	                              E.PlantID, BK.UserName BankNameShort, E.BankAccNo, 
								  EmpSlr.SalaryHeadID, SH.SalaryHead, ISNULL(pSH.Sequence, 99) Sequence, SH.HeadType, SH.HeadCategory, EmpSlr.EntryCurrencyID, EmpSlr.EntryAmount,
	                              EmpSlr.DefineCurrencyID, EmpSlr.DefineAmount, EmpSlr.AmtDefinationCurrencyID, EmpSlr.AmtDefinationRate,
	                              SH.IsCTCComponent, SH.IsGrossComponent, EmpSlr.EmpInfoSystemID, MW.SalaryHeadValue,EC.UserName StaffCategory

                                , ISNULL(vpf.VoluntaryPFValue,0) VoluntaryPFValue
                                ,VPFhead.HeadCategory xHeadCategory,VPFhead.SalaryHeadID xSalaryHeadID
                                ,VPFhead.SalaryHead xSalaryHead,VPFhead.IsCTCComponent xIsCTCComponent
                                ,VPFhead.IsGrossComponent xIsGrossComponent,VPFhead.HeadType xHeadType
                                ,VPFhead.SalaryRuleMasterSystemID xSalaryRuleMasterSystemID
	                            ,CRC.IntegerInDisb, CRC.DecimalNo, MW.Grade, PGM.PayrollGroupId PayGroupID
				            FROM EmployeeInformation AS E

                                            LEFT JOIN ORG.Unit U ON E.UnitID = U.Id
                                            LEFT JOIN ORG.Division Dv ON E.DivisionID = Dv.Id
                                            LEFT JOIN ORG.Department Dp ON E.DepartmentID = Dp.Id
                                            LEFT JOIN ORG.Section S ON E.SectionID = S.Id
                                            LEFT JOIN ORG.SubSection SB ON E.SubSectionID = SB.Id
                                            LEFT JOIN ORG.Line L ON E.LineID = L.Id
                                            LEFT JOIN HKP.DesignationGroup DG ON E.DesignationGroupID = Dg.Id
                                            LEFT JOIN HKP.Designation D ON E.DesignationSystemID = D.Id
                                            LEFT JOIN HKP.Designation GVD ON E.GivenDesignationId = GVD.Id
											LEFT JOIN ORG.Plant AS p ON E.PlantId = p.Id
                                            LEFT JOIN MST.PayrollGroupMaster PGM on PGM.EmployeeId = E.SystemId
											LEFT JOIN ORG.Company AS Cm ON E.CompanyID = Cm.Id
											LEFT JOIN ORG.CompanyGroup AS GC ON E.GroupID = GC.Id
											LEFT JOIN HKP.Bank AS BK ON E.BankSystemID = BK.Id
											LEFT JOIN MST.AddressMaster AS CAM ON Cm.AddressMasterId = CAM.Id
											LEFT JOIN MST.AddressMaster AS PAM ON P.AddressMasterId = PAM.Id
											LEFT JOIN MST.AddressMaster AS CGAM ON GC.AddressMasterId = CGAM.Id
											LEFT JOIN SCS.City AS PAMC ON PAM.CityId = PAMC.Id
											LEFT JOIN SCS.City AS CT ON CGAM.CityId = CT.Id
                                            LEFT JOIN
													(
													 SELECT ECT.Id, ECT.UserName, DM.DesignationId 
													  FROM [HKP].[EmployeeCategory] ECT
																	LEFT JOIN MST.DesignationMaster DM ON ECT.Id = DM.EmployeeCategoryId
													) EC ON EC.DesignationId = E.GivenDesignationId
											LEFT JOIN 
													(
													 SELECT E.SystemID, SUM(SV.SalaryHeadValue) SalaryHeadValue,LSG.UserName Grade
														FROM EmployeeInformation E   
																LEFT JOIN MST.ManpowerBudget b ON e.BudgetCode = b.Id
																LEFT JOIN MST.LegalSalaryGradeDesignation GD ON GD.LegalDesignationId = E.LegalDesignationId 
                                                                                                AND E.PlantId = gd.PlantId
																LEFT JOIN (
																			SELECT MAX(EffectiveDate) EffectiveDate, LegalSalaryGradeId, EmployeeLocationId 
																				FROM MST.LegalSalaryStructure 
																				WHERE EffectiveDate <= '" + para.ToDate + @"'
																			GROUP BY LegalSalaryGradeId, EmployeeLocationId 
																		  ) S ON S.LegalSalaryGradeId = GD.LegalSalaryGradeId AND S.EmployeeLocationId = B.EmployeeLocationId
																LEFT JOIN MST.LegalSalaryStructure SS ON SS.LegalSalaryGradeId = S.LegalSalaryGradeId 
                                                                                            AND SS.EmployeeLocationId = S.EmployeeLocationId 
                                                                                            AND SS.EffectiveDate = S.EffectiveDate
																LEFT JOIN MST.LegalSalaryStructureValue SV ON SV.LegalSalaryStructureId = SS.Id 	
                                                                left join  [SCS].[LegalSalaryGrade] LSG ON LSG.Id=S.LegalSalaryGradeId	
														GROUP BY E.SystemId,LSG.UserName
													) MW ON MW.SystemId = E.SystemId

										LEFT JOIN (
													SELECT * FROM
																(
																 SELECT MST.EmpInfoSystemID, EmpSlr.SalaryHeadID, EmpSlr.EntryCurrencyID, EmpSlr.EntryAmount, EmpSlr.DefineCurrencyID, EmpSlr.DefineAmount, 
																		EmpSlr.AmtDefinitionCurrencyID AmtDefinationCurrencyID, EmpSlr.AmtDefinitionRate AmtDefinationRate, MST.SalaryRuleMasterSystemID
																 FROM SalaryInfoDefine EmpSlr
																		INNER JOIN SalaryInfoDefineMaster MST ON EmpSlr.SalaryID = MST.SystemID 
                                                                  -----------------------AND MST.IsApproved = 1---------------------
																) A
																UNION 
																(
																SELECT M.EmpSystemID EmpInfoSystemID, D.SalaryHeadID, CRC.AmtEntryCurrency EntryCurrencyID, D.Value EntryAmount,
																		CRC.AmtDefinitionCurrency DefineCurrencyID, D.Value DefineAmount, CRC.AmtDefinitionCurrency AmtDefinationCurrencyID,
																		1 AmtDefinationRate, MST.SalaryRuleMasterSystemID
																FROM [BonusPolicyMonthlyRetainStrcEmpWiseCalculation] M
																		INNER JOIN [BonusPolicyMonthlyRetainDistributionStrcPmt] D ON M.ID = D.BnsPlyMntRetainID
																		INNER JOIN SalaryInfoDefineMaster MST ON M.EmpSystemID = MST.EmpInfoSystemID 
                                                                         ----------------AND MST.IsApproved = 1-------------
																		LEFT JOIN SalaryRuleMaster SRM ON SRM.SystemID = MST.SalaryRuleMasterSystemID
																		LEFT JOIN CurrencyRuleChild CRC ON CRC.MstSystemID = SRM.CurrencyRuleSystemID AND CRC.SalaryHeadID = D.SalaryHeadID
															
                                                                                                                            --Dada
                                                                                                                            --WHERE EOMONTH(DATEFROMPARTS(M.YearNo, M.MonthNo, 1)) IN (SELECT MAX(EOMONTH(DATEFROMPARTS(YearNo, MonthNo, 1))) 
																															--FROM [BonusPolicyMonthlyRetainEmpWiseCalculation] 
																		WHERE M.MonthNo = DATEPART(MONTH,'" + para.FromDate + @"') AND M.YearNo = DATEPART(YEAR,'" + para.FromDate + @"')													--WHERE CONVERT(DATE, EOMONTH(DATEFROMPARTS(YearNo, MonthNo, 1))) <= CONVERT(DATE, '" + para.FromDate + @"'))

																)
													) EmpSlr ON E.SystemID = EmpSlr.EmpInfoSystemID
										LEFT JOIN SalaryHead SH ON SH.SalaryHeadID = EmpSlr.SalaryHeadID
										LEFT JOIN (SELECT * FROM [MST].[PlantSalaryHeadSequence] WHERE PlantId='" + para.PlantId + @"') PSH ON PSH.SalaryHeadId = EmpSlr.SalaryHeadID
										
										LEFT JOIN SalaryRuleMaster SRM ON SRM.SystemID = EmpSlr.SalaryRuleMasterSystemID
										LEFT JOIN CurrencyRuleChild CRC ON CRC.MstSystemID = srm.CurrencyRuleSystemID AND CRC.SalaryHeadID = SH.SalaryHeadID

                                        LEFT JOIN (
										 		   SELECT EmpSystemId,MAX(EffectiveDate) EffectiveDate, VoluntaryPFValue 
												     FROM [PFEmployeeVoluntaryValue] 
													 WHERE EffectiveDate<='" + para.ToDate + @"'
												   GROUP BY EmpSystemId,EffectiveDate,VoluntaryPFValue
												  ) VPF ON E.SystemId = vpf.EmpSystemId
										LEFT JOIN(
										SELECT SH.HeadCategory, SH.SalaryHeadID, SH.SalaryHead, SH.IsCTCComponent, SH.IsGrossComponent, SH.HeadType, 
											   SR.SalaryRuleMasterSystemID
											  FROM [dbo].[SalaryRulePF] SR
											  LEFT JOIN SalaryHead SH ON SH.SalaryHeadID = SR.SalaryHeadID
											  WHERE SH.HeadCategory='PF Voluntary'
										) VPFhead ON VPFhead.SalaryRuleMasterSystemID = EmpSlr.SalaryRuleMasterSystemID

                                       
                         ) A  WHERE
                         ISNULL(EmpInfoSystemID,'')<>'' AND PlantID = '" + para.PlantId + @"' AND " + _wc + @"
                           AND (EmployeeStatus = 'Active' OR COnvert(date,DOS) >= Convert(Date,'" + para.FromDate + "'))";


                //if (para.EmployeeId != "")
                //{
                //    strSql = strSql + @" AND SystemID IN (" + para.EmployeeId + ")";
                //}

                if (sUnitID != "ALL")
                {
                    strSql = strSql + @" AND UnitID = '" + sUnitID + "'";
                }
                if (sDivID != "ALL")
                {
                    strSql = strSql + @" AND DivisionID = '" + sDivID + "'";
                }
                if (sDepID != "ALL")
                {
                    strSql = strSql + @" AND DepartmentID = '" + sDepID + "'";
                }
                if (sSecID != "ALL")
                {
                    strSql = strSql + @" AND SectionID = '" + sSecID + "'";
                }
                if (sSubSecID != "ALL")
                {
                    strSql = strSql + @" AND SubSectionID = '" + sSubSecID + "'";
                }
                //  #region--xPay Group--
                //  if (para.PayGroup != null)
                //  {

                //      if (para.PayGroup.ToUpper() != "NO GROUP")
                //      {
                //          strSql = strSql + @" AND EmpInfoSystemID  IN (
                //select employeeid from MST.PayrollGroupMaster where PayrollGroupId = '" + para.PayGroup + @"')";
                //      }
                //      if (para.PayGroup.ToUpper() == "NO GROUP")
                //      {
                //          strSql = strSql + @" AND EmpInfoSystemID NOT IN (
                //select employeeid from MST.PayrollGroupMaster)";
                //      }
                //  }
                //  #endregion--xPay Group--

                strSql = strSql + @"ORDER BY EmployeeCodeS";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function GetEmpSalaryStructureSql()

        public void GetAttendanceSummarySql(ParamList para, string workDate, string sUnitID, string sDivID, string sDepID, string sSecID, string sSubSecID, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;
            clsStaticInfo obs = null;
            try
            {
                obs = new clsStaticInfo();
                string wc = string.Empty;
                //if (para.JobLocationId != "ALL")
                //{
                //    wc = " and JobLocationID='" + para.JobLocationId + "' ";
                //}
                if (sUnitID != "ALL")
                {
                    wc = wc + @" AND UnitId = '" + sUnitID + "'";
                }
                if (sDivID != "ALL")
                {
                    wc = wc + @" AND DivisionId = '" + sDivID + "'";
                }
                if (sDepID != "ALL")
                {
                    wc = wc + @" AND DepartmentId = '" + sDepID + "'";
                }
                if (sSecID != "ALL")
                {
                    wc = wc + @" AND SectionId = '" + sSecID + "'";
                }
                if (sSubSecID != "ALL")
                {
                    wc = wc + @" AND SubSectionId = '" + sSubSecID + "'";
                }
                obs = new clsStaticInfo();
                strSql = @"SELECT distinct OnRoleEmployee.CompanyId CompanyId,OnRoleEmployee.CompanyName ColumnName,OnRoleEmployee.GroupName GroupName,OnRoleEmployee.CompanyGroupId CompanyGroupId
                             ,OnRoleEmployee.EmpCategory,OnRoleEmployee.Department, OnRoleEmployee.DesignationGroup,OnRoleEmployee.Section
							 ,OnRoleEmployee.catgSeq,OnRoleEmployee.DesGrpSeq,OnRoleEmployee.DeptSeq,OnRoleEmployee.SecSeq
								,ISNULL(OnRoleEmployee.totalEmployee,0) OnRoleEmployee
								,ISNULL(PresentEmployee.totalPresentEmployee,0) totalPresentEmployee
								,ISNULL(AbsentEmployee.totalAbsentEmployee,0) totalAbsentEmployee
								,ISNULL(LateEmployee.totalLateEmployee,0) totalLateEmployee
								,ISNULL(LeaveEmployee.totalLeaveEmployee,0) totalLeaveEmployee
								,ISNULL(WeekOffEmployee.totalWeekoffEmployee,0)totalWeekoffEmployee
						
					     FROM
						   (SELECT
						   EmpC.UserName EmpCategory,  EmpC.Id EmpCategoryId,
						   DesGrp.UserName DesignationGroup,DesGrp.Id DesigGrpId,Dept.UserName Department, Dept.Id DepartmentId,Sec.UserName Section,Sec.Id SectionId,
						   COUNT(E.SystemId) totalEmployee,
						   C.UserName,cg.Id CompanyGroupId,c.Id CompanyId,c.UserName CompanyName,cg.UserName GroupName 
	                        	,Empc.Sequence catgSeq,DesGrp.Sequence DesGrpSeq,Sec.Sequence SecSeq,Dept.Sequence DeptSeq
						    	FROM  ORG.CompanyGroup CG
											LEFT OUTER JOIN ORG.Company C ON CG.Id = c.CompanyGroupId
											LEFT OUTER JOIN EmployeeInformation 
											E ON e.GroupID = CG.Id and c.Id=E.CompanyId
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = e.BudgetCode
                            LEFT JOIN ORG.Position PR ON MB.PositionId=PR.Id
								   INNER JOIN  ORG.Department AS Dept ON Dept.Id = PR.DepartmentId
								   INNER JOIN  ORG.Section AS Sec ON SEC.Id = PR.SectionId
								   INNER JOIN  ORG.SubSection AS SubSec ON SubSEC.Id = PR.SubSectionId
									LEFT JOIN [HKP].Designation GDes ON GDes.Id = E.GivenDesignationId
								    LEFT JOIN [MST].DesignationMaster DesM ON DesM.DesignationId = E.GivenDesignationId
									INNER JOIN [HKP].DesignationGroup DesGrp ON DesGrp.Id = DesM.DesignationGroupId
								    LEFT JOIN [HKP].EmployeeCategory EmpC ON EmpC.Id = DesM.EmployeeCategoryId
											WHERE
												  PlantId = '" + para.PlantId + @"'    AND (E.EmployeeStatus != 'Separated' OR ISNULL(E.DOS,'') = '' OR ISNULL(E.DOS,'')>CONVERT(DATE,'" + workDate + @"'))
                                                   AND CONVERT(DATE,E.DOJ) <= CONVERT(DATE,'" + workDate + @"')  " + wc + @"
												GROUP BY C.UserName,cg.Id,c.Id,c.UserName,cg.UserName
												,EmpC.Username,EmpC.Id
												,DesGrp.UserName,DesGrp.Id,Sec.UserName,Sec.Id,Dept.UserName,Dept.Id 
											,Empc.Sequence ,DesGrp.Sequence ,Sec.Sequence,Dept.Sequence
										
												) OnRoleEmployee
												LEFT OUTER JOIN
								  ( SELECT EmpC.UserName EmpCategory,  EmpC.Id EmpCategoryId,DesGrp.UserName DesignationGroup,DesGrp.Id DesigGrpId,Dept.UserName Department,
						               Dept.Id DepartmentId,Sec.UserName Section,Sec.Id SectionId
								  ,COUNT(E.SystemId) totalPresentEmployee,cg.Id CompanyGroupId,cg.UserName GroupName,
									C.Id AS CompanyId,C.UserName CompanyName

									FROM  ORG.CompanyGroup CG
									LEFT OUTER JOIN ORG.Company C ON CG.Id = c.CompanyGroupId

									LEFT OUTER JOIN  (--*
								SELECT * FROM EmployeeInformation
								WHERE SystemId IN (--**
								SELECT DISTINCT EmpSystemID FROM AttdnProcessData  APD
									LEFT JOIN DayType DT ON APD.DayStatus = DT.DayType
									WHERE DT.Category = 'Present' AND  CONVERT(DATE,WorkDate) = CONVERT(DATE,'" + workDate + @"')
								)--**
                                " + wc + @"
								)--*
								E ON e.GroupID = CG.Id and c.Id = E.CompanyId
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = e.BudgetCode
                            LEFT JOIN ORG.Position PR ON MB.PositionId=PR.Id
								   INNER JOIN  ORG.Department AS Dept ON Dept.Id = PR.DepartmentId
								   INNER JOIN  ORG.Section AS Sec ON SEC.Id = PR.SectionId
								   INNER JOIN  ORG.SubSection AS SubSec ON SubSEC.Id = PR.SubSectionId
									 	LEFT JOIN [HKP].Designation GDes ON GDes.Id = E.GivenDesignationId
								    LEFT JOIN [MST].DesignationMaster DesM ON DesM.DesignationId = E.GivenDesignationId
								    LEFT JOIN [HKP].EmployeeCategory EmpC ON EmpC.Id = DesM.EmployeeCategoryId
									INNER JOIN [HKP].DesignationGroup DesGrp ON DesGrp.Id = DesM.DesignationGroupId				

									WHERE
									   PlantId = '" + para.PlantId + @"'  
									GROUP BY C.UserName,cg.Id,c.Id,c.UserName,cg.UserName
												,EmpC.Username,EmpC.Id
												,DesGrp.UserName,DesGrp.Id,Sec.UserName,Sec.Id,Dept.UserName,Dept.Id 							
									)
									PresentEmployee
									ON OnRoleEmployee.CompanyGroupId = PresentEmployee.CompanyGroupId AND OnRoleEmployee.CompanyId = PresentEmployee.CompanyId
									AND OnRoleEmployee.EmpCategoryId = PresentEmployee.EmpCategoryId AND OnRoleEmployee.DesigGrpId = PresentEmployee.DesigGrpId
									AND OnRoleEmployee.DepartmentId = PresentEmployee.DepartmentId AND OnRoleEmployee.SectionId = PresentEmployee.SectionId 

									LEFT OUTER JOIN
									----------------------------
									 (SELECT EmpC.UserName EmpCategory,  EmpC.Id EmpCategoryId,DesGrp.UserName DesignationGroup,DesGrp.Id DesigGrpId,Dept.UserName Department,
						               Dept.Id DepartmentId,Sec.UserName Section,Sec.Id SectionId
									 ,COUNT(E.SystemId) totalAbsentEmployee,cg.Id CompanyGroupId,cg.UserName GroupName,
									C.Id AS CompanyId,C.UserName CompanyName

									FROM  ORG.CompanyGroup CG
									LEFT OUTER JOIN ORG.Company C ON CG.Id = c.CompanyGroupId

									LEFT OUTER JOIN  (--*
								SELECT * FROM EmployeeInformation
								WHERE SystemId IN (--**
								SELECT DISTINCT EmpSystemID FROM AttdnProcessData  APD
									LEFT JOIN DayType DT ON APD.DayStatus = DT.DayType
									WHERE DT.Category = 'Absent' AND  CONVERT(DATE,WorkDate) = CONVERT(DATE,'" + workDate + @"')
								)--**
                                " + wc + @"
								)--*
								E ON e.GroupID = CG.Id and c.Id = E.CompanyId
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = e.BudgetCode
                            LEFT JOIN ORG.Position PR ON MB.PositionId=PR.Id
								INNER JOIN  ORG.Department AS Dept ON Dept.Id = PR.DepartmentId
								   INNER JOIN  ORG.Section AS Sec ON SEC.Id = PR.SectionId
								   INNER JOIN  ORG.SubSection AS SubSec ON SubSEC.Id = PR.SubSectionId
									 	LEFT JOIN [HKP].Designation GDes ON GDes.Id = E.GivenDesignationId
								    LEFT JOIN [MST].DesignationMaster DesM ON DesM.DesignationId = E.GivenDesignationId
								    LEFT JOIN [HKP].EmployeeCategory EmpC ON EmpC.Id = DesM.EmployeeCategoryId
									INNER JOIN [HKP].DesignationGroup DesGrp ON DesGrp.Id = DesM.DesignationGroupId				

									WHERE
									   PlantId = '" + para.PlantId + @"'   
									GROUP BY C.UserName,cg.Id,c.Id,c.UserName,cg.UserName,EmpC.Username,EmpC.Id
											,DesGrp.UserName,DesGrp.Id,Sec.UserName,Sec.Id,Dept.UserName,Dept.Id 
									)
									AbsentEmployee ON 
										 OnRoleEmployee.CompanyGroupId = AbsentEmployee.CompanyGroupId AND OnRoleEmployee.CompanyId = AbsentEmployee.CompanyId
									AND OnRoleEmployee.EmpCategoryId = AbsentEmployee.EmpCategoryId AND OnRoleEmployee.DesigGrpId = AbsentEmployee.DesigGrpId
									AND OnRoleEmployee.DepartmentId = AbsentEmployee.DepartmentId AND OnRoleEmployee.SectionId = AbsentEmployee.SectionId 

									LEFT OUTER JOIN
									(SELECT EmpC.UserName EmpCategory,  EmpC.Id EmpCategoryId,DesGrp.UserName DesignationGroup,DesGrp.Id DesigGrpId,Dept.UserName Department,
						               Dept.Id DepartmentId,Sec.UserName Section,Sec.Id SectionId
									,COUNT(E.SystemId) totalLateEmployee,cg.Id CompanyGroupId,cg.UserName GroupName,
									C.Id AS CompanyId,C.UserName CompanyName

									FROM  ORG.CompanyGroup CG
									LEFT OUTER JOIN ORG.Company C ON CG.Id = c.CompanyGroupId

									LEFT OUTER JOIN  (--*
								SELECT * FROM EmployeeInformation
								WHERE SystemId IN (--**
								SELECT DISTINCT EmpSystemID FROM AttdnProcessData  APD
									LEFT JOIN DayType DT ON APD.DayStatus = DT.DayType
									WHERE DT.Category = 'Late' AND  CONVERT(DATE,WorkDate) = CONVERT(DATE,'" + workDate + @"')
								)--**
                                " + wc + @"
								)--*
								E ON e.GroupID = CG.Id and c.Id = E.CompanyId
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = e.BudgetCode
                            LEFT JOIN ORG.Position PR ON MB.PositionId=PR.Id
								INNER JOIN  ORG.Department AS Dept ON Dept.Id = PR.DepartmentId
								   INNER JOIN  ORG.Section AS Sec ON SEC.Id = PR.SectionId
								   INNER JOIN  ORG.SubSection AS SubSec ON SubSEC.Id = PR.SubSectionId
									 	LEFT JOIN [HKP].Designation GDes ON GDes.Id = E.GivenDesignationId
								    LEFT JOIN [MST].DesignationMaster DesM ON DesM.DesignationId = E.GivenDesignationId
								    LEFT JOIN [HKP].EmployeeCategory EmpC ON EmpC.Id = DesM.EmployeeCategoryId
									INNER JOIN [HKP].DesignationGroup DesGrp ON DesGrp.Id = DesM.DesignationGroupId				

									WHERE
									    PlantId = '" + para.PlantId + @"'  
									GROUP BY C.UserName,cg.Id,c.Id,c.UserName,cg.UserName,EmpC.Username,EmpC.Id
											,DesGrp.UserName,DesGrp.Id,Sec.UserName,Sec.Id,Dept.UserName,Dept.Id 
									)
									LateEmployee on
											 OnRoleEmployee.CompanyGroupId = LateEmployee.CompanyGroupId AND OnRoleEmployee.CompanyId = LateEmployee.CompanyId
									AND OnRoleEmployee.EmpCategoryId = LateEmployee.EmpCategoryId AND OnRoleEmployee.DesigGrpId = LateEmployee.DesigGrpId
									AND OnRoleEmployee.DepartmentId = LateEmployee.DepartmentId AND OnRoleEmployee.SectionId = LateEmployee.SectionId 
										LEFT OUTER JOIN
									(SELECT EmpC.UserName EmpCategory,  EmpC.Id EmpCategoryId,DesGrp.UserName DesignationGroup,DesGrp.Id DesigGrpId,Dept.UserName Department,
						               Dept.Id DepartmentId,Sec.UserName Section,Sec.Id SectionId
									,COUNT(E.SystemId) totalWeekoffEmployee,cg.Id CompanyGroupId,cg.UserName GroupName,
									C.Id AS CompanyId,C.UserName CompanyName

									FROM  ORG.CompanyGroup CG
									LEFT OUTER JOIN ORG.Company C ON CG.Id = c.CompanyGroupId

									LEFT OUTER JOIN  (--*
								SELECT * FROM EmployeeInformation
								WHERE SystemId IN (--**
								SELECT DISTINCT EmpSystemID FROM AttdnProcessData  APD
									LEFT JOIN DayType DT ON APD.DayStatus = DT.DayType
									WHERE DT.Category IN('Holiday', 'Weekend') AND  CONVERT(DATE,WorkDate) = CONVERT(DATE,'" + workDate + @"')
								)--**
                                " + wc + @"
								)--*
								E ON e.GroupID = CG.Id and c.Id = E.CompanyId
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = e.BudgetCode
                            LEFT JOIN ORG.Position PR ON MB.PositionId=PR.Id
								INNER JOIN  ORG.Department AS Dept ON Dept.Id = PR.DepartmentId
								   INNER JOIN  ORG.Section AS Sec ON SEC.Id = PR.SectionId
								   INNER JOIN  ORG.SubSection AS SubSec ON SubSEC.Id = PR.SubSectionId
									 	LEFT JOIN [HKP].Designation GDes ON GDes.Id = E.GivenDesignationId
								    LEFT JOIN [MST].DesignationMaster DesM ON DesM.DesignationId = E.GivenDesignationId
								    LEFT JOIN [HKP].EmployeeCategory EmpC ON EmpC.Id = DesM.EmployeeCategoryId
									INNER JOIN [HKP].DesignationGroup DesGrp ON DesGrp.Id = DesM.DesignationGroupId				

									WHERE
									    PlantId = '" + para.PlantId + @"'   
									GROUP BY C.UserName,cg.Id,c.Id,c.UserName,cg.UserName,EmpC.Username,EmpC.Id
											,DesGrp.UserName,DesGrp.Id,Sec.UserName,Sec.Id,Dept.UserName,Dept.Id 	
									)
									WeekOffEmployee ON 
									
										 OnRoleEmployee.CompanyGroupId = WeekOffEmployee.CompanyGroupId AND OnRoleEmployee.CompanyId = WeekOffEmployee.CompanyId
									AND OnRoleEmployee.EmpCategoryId = WeekOffEmployee.EmpCategoryId AND OnRoleEmployee.DesigGrpId = WeekOffEmployee.DesigGrpId
									AND OnRoleEmployee.DepartmentId = WeekOffEmployee.DepartmentId AND OnRoleEmployee.SectionId = WeekOffEmployee.SectionId 
									
                                             LEFT OUTER JOIN
    
									(SELECT EmpC.UserName EmpCategory,  EmpC.Id EmpCategoryId,DesGrp.UserName DesignationGroup,DesGrp.Id DesigGrpId,Dept.UserName Department,
						               Dept.Id DepartmentId,Sec.UserName Section,Sec.Id SectionId
									,COUNT(E.SystemId) totalLeaveEmployee,cg.Id CompanyGroupId,cg.UserName GroupName,
									C.Id AS CompanyId,C.UserName CompanyName

									FROM  ORG.CompanyGroup CG
									LEFT OUTER JOIN ORG.Company C ON CG.Id = c.CompanyGroupId

									LEFT OUTER JOIN  (--*
								SELECT * FROM EmployeeInformation
								WHERE SystemId IN (--**
								SELECT DISTINCT EmpSystemID FROM AttdnProcessData  APD
									LEFT JOIN DayType DT ON APD.DayStatus = DT.DayType
									WHERE DT.Category = 'Leave' AND  CONVERT(DATE,WorkDate) = CONVERT(DATE,'" + workDate + @"')
								)--**
                                " + wc + @"
								)--*
								E ON e.GroupID = CG.Id and c.Id = E.CompanyId
LEFT JOIN MST.ManpowerBudget mb ON mb.Id = e.BudgetCode
                            LEFT JOIN ORG.Position PR ON MB.PositionId=PR.Id
								INNER JOIN  ORG.Department AS Dept ON Dept.Id = PR.DepartmentId

								   INNER JOIN  ORG.Section AS Sec ON SEC.Id = PR.SectionId
								   INNER JOIN  ORG.SubSection AS SubSec ON SubSEC.Id = PR.SubSectionId
									 	LEFT JOIN [HKP].Designation GDes ON GDes.Id = E.GivenDesignationId
								    LEFT JOIN [MST].DesignationMaster DesM ON DesM.DesignationId = E.GivenDesignationId
								    LEFT JOIN [HKP].EmployeeCategory EmpC ON EmpC.Id = DesM.EmployeeCategoryId
									INNER JOIN [HKP].DesignationGroup DesGrp ON DesGrp.Id = DesM.DesignationGroupId				

									WHERE
									   PlantId = '" + para.PlantId + @"' ";

                strSql += @"GROUP BY C.UserName,cg.Id,c.Id,c.UserName,cg.UserName,EmpC.Username,EmpC.Id
											,DesGrp.UserName,DesGrp.Id,Sec.UserName,Sec.Id,Dept.UserName,Dept.Id
									)
								LeaveEmployee ON

                                    OnRoleEmployee.CompanyGroupId = LeaveEmployee.CompanyGroupId AND OnRoleEmployee.CompanyId = LeaveEmployee.CompanyId

                                    AND OnRoleEmployee.EmpCategoryId = LeaveEmployee.EmpCategoryId AND OnRoleEmployee.DesigGrpId = LeaveEmployee.DesigGrpId

                                    AND OnRoleEmployee.DepartmentId = LeaveEmployee.DepartmentId  AND OnRoleEmployee.SectionId = LeaveEmployee.SectionId 

                                    ORDER BY OnRoleEmployee.catgSeq,OnRoleEmployee.DeptSeq,OnRoleEmployee.SecSeq,OnRoleEmployee.DesGrpSeq";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function GetEmpSalaryStructureSql()

        public void GetFiscalMonthListSql(string fromDate, string toDate, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;
            clsStaticInfo obs = null;
            try
            {
                obs = new clsStaticInfo();
                strSql = @"DECLARE @start DATE = CONVERT(DATE,'" + fromDate + @"')
                            DECLARE @end DATE = CONVERT(DATE,'" + toDate + @"')

                            ;WITH months (date)
                            AS
                            (
                                SELECT @start
                                UNION ALL
                                SELECT DATEADD(month,1,date)
                                from months
                                where DATEADD(month,1,date) < @end
                            )
                            SELECT     [MonthName]    = DATENAME(mm ,Date)  
                                        ,[MonthNumber]  = DATEPART(mm ,Date)  
                                        ,[LastDayOfMonth]  = DATEPART(dd,EOMONTH(Date))
                                        ,[MonthYear]    = DATEPART(yy ,Date) 
                            FROM months";

                //if (para.EmployeeId != "")
                //{
                //    strSql = strSql + @" AND SystemID IN (" + para.EmployeeId + ")";
                //}

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function GetEmpSalaryStructureSql()

        public void GetOperationListSql(out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;
            clsStaticInfo obs = null;
            try
            {
                obs = new clsStaticInfo();
                strSql = @"      SELECT Distinct
	                    OA.Code OperationActivityCode
	                    ,OA.UserName OperationActivity
	                   
                    FROM MST.OperationMaster OM
                    LEFT JOIN [HKP].[OperationActivity] OA ON OA.Id = OM.OperationActivityId
                    LEFT JOIN [HKP].[OperationCategory] OC ON OC.Id = OM.OperationCategoryId
                    LEFT JOIN [HKP].[OperationType] OT ON OT.Id = OM.OperationTypeId
                    LEFT JOIN MST.MachineMaster MM ON MM.Id = OM.MachineMasterId
                    LEFT JOIN [HKP].[Skill] SKO ON SKO.Id = OM.SkillId
                    LEFT JOIN [HKP].[Skill] SKM ON SKM.Id = MM.SkillId
                    LEFT JOIN [HKP].[SkillProcess] SP ON SP.SkillId = SKO.Id
                    LEFT JOIN [HKP].[Process] P ON P.Id = SP.ProcessId
                    LEFT JOIN SCS.SkillGrouping SKG ON SKG.Id = OM.SkillGroupId
                    LEFT JOIN HKP.LegalDesignation OLDG ON OLDG.Id = OM.LegalDesignationId
                    LEFT JOIN [HKP].[Process] PR ON PR.Id = OM.ProcessId
                    LEFT JOIN [MST].OperationPositionMPBudget OMB ON OMB.OperationMasterId = OM.Id
                    LEFT JOIN [ORG].[Entity] EN ON EN.ID= OMB.EntityId
                    LEFT JOIN [ORG].[Line] Li ON Li.ID = EN.LineId
                    LEFT JOIN [ORG].[Position] PO ON PO.Id = OMB.PositionId";

                //if (para.EmployeeId != "")
                //{
                //    strSql = strSql + @" AND SystemID IN (" + para.EmployeeId + ")";
                //}

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function GetEmpSalaryStructureSql()

        public void GetSalaryProcessId(string companyGrpId, string companyId, string plantId, string calcDate, out System.Data.DataSet dsRef)
        {
            var monthNo = string.Empty;
            monthNo = Convert.ToDateTime(calcDate).ToString("MM");
            var mNo = Convert.ToInt16(monthNo);
            var yearNo = string.Empty;
            yearNo = Convert.ToDateTime(calcDate).ToString("yyyy");
            string strSQL;
            ConnectionManager.DAL.ConManager objCon;
            try
            {
                strSQL = @"SELECT DISTINCT TOP (1) SystemID,SalaryProcID,SalaryProcDate FROM SalaryProcMaster 
                                  WHERE MonthNo = " + mNo.ToString() + @" AND  YearNo = " + yearNo + @"
                                                        ORDER BY SalaryProcDate DESC ";
                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function
        public void GetEmpSalaryStructureSqlPayGrp(ParamList para, string sUnitID, string sDivID, string sDepID, string sSecID, string sSubSecID, string sMth, string sYr, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;
            clsStaticInfo obs = null;
            //var _wcp = string.Empty;
            //if (para.DepartmentId != "ALL")
            //{
            //    _wcp = " PayrollGroupId IN (" + para.PayGrp + @")";
            //}
            //else
            //{
            //    _wcp = "";
            //}
            try
            {
                obs = new clsStaticInfo();
                strSql = @"SELECT * FROM
                          (
                           SELECT E.SystemID, E.EmployeeCode,CONVERT(INT,E.EmployeeCode) EmployeeCodes, E.EmployeeName, REPLACE(Convert(VARCHAR(11), E.DOB, 106), ' ', '-') AS DOB,
	                              E.FatherName, E.MotherName, E.EmpType EmployeeType, E.EmploymentType EmploymentNature, E.NationalID,
	                              E.GenderID GenderName, REPLACE(Convert(VARCHAR(11), E.DOJ, 106), ' ', '-') AS DOJ,E.DOS,
	                              REPLACE(Convert(VARCHAR(11), E.DOC, 106), ' ', '-') AS DOC, DG.UserName DesignationGroup, D.UserName Designation,
								  GVD.UserName GivenDesignation, L.UserName Line, U.UserName Unit, Dv.UserName Division, Dp.UserName Department,
								  S.UserName Section, SB.UserName SubSection, EC.UserName AS EmpCategory, Cm.UserName CompanyName, CAM.Address1,
	                              CAM.Address2, E.EmployeeCategorySystemID, E.UnitID, E.DivisionID, E.DepartmentID, E.DesignationSystemID,
	                              E.SectionID, E.SubSectionID, E.LineID, E.DesignationGroupID, E.SubSecStrucSystemID, E.EmployeeStatus,
	                              P.UserName PlantName, (PAM.[Address1] + ', ' + PAM.[Address2] + ', ' + PAMC.UserName + ' - ' + PAM.Postcode) FactoryAddress,
	                              GC.UserName GroupName, (CGAM.[Address1] + ', ' + CGAM.[Address2] + ', ' + CT.UserName + ' - ' + CGAM.Postcode + ', Contact: ' + CGAM.Phone) GroupAddress,
	                              E.PlantID, BK.UserName BankNameShort, E.BankAccNo, 
								  EmpSlr.SalaryHeadID, SH.SalaryHead, ISNULL(pSH.Sequence, 99) Sequence, SH.HeadType, SH.HeadCategory, EmpSlr.EntryCurrencyID, EmpSlr.EntryAmount,
	                              EmpSlr.DefineCurrencyID, EmpSlr.DefineAmount, EmpSlr.AmtDefinationCurrencyID, EmpSlr.AmtDefinationRate,
	                              SH.IsCTCComponent, SH.IsGrossComponent, EmpSlr.EmpInfoSystemID, MW.SalaryHeadValue

                                , ISNULL(vpf.VoluntaryPFValue,0) VoluntaryPFValue
                                ,VPFhead.HeadCategory xHeadCategory,VPFhead.SalaryHeadID xSalaryHeadID
                                ,VPFhead.SalaryHead xSalaryHead,VPFhead.IsCTCComponent xIsCTCComponent
                                ,VPFhead.IsGrossComponent xIsGrossComponent,VPFhead.HeadType xHeadType
                                ,VPFhead.SalaryRuleMasterSystemID xSalaryRuleMasterSystemID
	                            ,CRC.IntegerInDisb, CRC.DecimalNo,CRC.IsDecimalInDisb isDecimal, MW.Grade, PGM.PayrollGroupId PayGroupID
				            FROM EmployeeInformation AS E

                                            LEFT JOIN ORG.Unit U ON E.UnitID = U.Id
                                            LEFT JOIN ORG.Division Dv ON E.DivisionID = Dv.Id
                                            LEFT JOIN ORG.Department Dp ON E.DepartmentID = Dp.Id
                                            LEFT JOIN ORG.Section S ON E.SectionID = S.Id
                                            LEFT JOIN ORG.SubSection SB ON E.SubSectionID = SB.Id
                                            LEFT JOIN ORG.Line L ON E.LineID = L.Id
                                            LEFT JOIN HKP.DesignationGroup DG ON E.DesignationGroupID = Dg.Id
                                            LEFT JOIN HKP.Designation D ON E.DesignationSystemID = D.Id
                                            LEFT JOIN HKP.Designation GVD ON E.GivenDesignationId = GVD.Id
											LEFT JOIN ORG.Plant AS p ON E.PlantId = p.Id
                                            LEFT JOIN MST.PayrollGroupMaster PGM on PGM.EmployeeId = E.SystemId
											LEFT JOIN ORG.Company AS Cm ON E.CompanyID = Cm.Id
											LEFT JOIN ORG.CompanyGroup AS GC ON E.GroupID = GC.Id
											LEFT JOIN HKP.Bank AS BK ON E.BankSystemID = BK.Id
											LEFT JOIN MST.AddressMaster AS CAM ON Cm.AddressMasterId = CAM.Id
											LEFT JOIN MST.AddressMaster AS PAM ON P.AddressMasterId = PAM.Id
											LEFT JOIN MST.AddressMaster AS CGAM ON GC.AddressMasterId = CGAM.Id
											LEFT JOIN SCS.City AS PAMC ON PAM.CityId = PAMC.Id
											LEFT JOIN SCS.City AS CT ON CGAM.CityId = CT.Id
                                            LEFT JOIN
													(
													 SELECT ECT.Id, ECT.UserName, DM.DesignationId 
													  FROM [HKP].[EmployeeCategory] ECT
																	LEFT JOIN MST.DesignationMaster DM ON ECT.Id = DM.EmployeeCategoryId
													) EC ON EC.DesignationId = E.GivenDesignationId
											LEFT JOIN 
													(
													 SELECT E.SystemID, SUM(SV.SalaryHeadValue) SalaryHeadValue,LSG.UserName Grade
														FROM EmployeeInformation E   
																LEFT JOIN MST.ManpowerBudget b ON e.BudgetCode = b.Id
																LEFT JOIN MST.LegalSalaryGradeDesignation GD ON GD.LegalDesignationId = E.LegalDesignationId 
                                                                                                AND E.PlantId = gd.PlantId
																LEFT JOIN (
																			SELECT MAX(EffectiveDate) EffectiveDate, LegalSalaryGradeId, EmployeeLocationId 
																				FROM MST.LegalSalaryStructure 
																				WHERE EffectiveDate <= '" + para.ToDate + @"'
																			GROUP BY LegalSalaryGradeId, EmployeeLocationId 
																		  ) S ON S.LegalSalaryGradeId = GD.LegalSalaryGradeId AND S.EmployeeLocationId = B.EmployeeLocationId
																LEFT JOIN MST.LegalSalaryStructure SS ON SS.LegalSalaryGradeId = S.LegalSalaryGradeId 
                                                                                            AND SS.EmployeeLocationId = S.EmployeeLocationId 
                                                                                            AND SS.EffectiveDate = S.EffectiveDate
																LEFT JOIN MST.LegalSalaryStructureValue SV ON SV.LegalSalaryStructureId = SS.Id 	
                                                                left join  [SCS].[LegalSalaryGrade] LSG ON LSG.Id=S.LegalSalaryGradeId	
														GROUP BY E.SystemId,LSG.UserName
													) MW ON MW.SystemId = E.SystemId

										LEFT JOIN (
													SELECT * FROM
																(
																 SELECT MST.EmpInfoSystemID, EmpSlr.SalaryHeadID, EmpSlr.EntryCurrencyID, EmpSlr.EntryAmount, EmpSlr.DefineCurrencyID, EmpSlr.DefineAmount, 
																		EmpSlr.AmtDefinitionCurrencyID AmtDefinationCurrencyID, EmpSlr.AmtDefinitionRate AmtDefinationRate, MST.SalaryRuleMasterSystemID
																 FROM SalaryInfoDefine EmpSlr
																		INNER JOIN SalaryInfoDefineMaster MST ON EmpSlr.SalaryID = MST.SystemID 
                                                                  -----------------------AND MST.IsApproved = 1---------------------
																) A
																UNION 
																(
																SELECT M.EmpSystemID EmpInfoSystemID, D.SalaryHeadID, CRC.AmtEntryCurrency EntryCurrencyID, D.Value EntryAmount,
																		CRC.AmtDefinitionCurrency DefineCurrencyID, D.Value DefineAmount, CRC.AmtDefinitionCurrency AmtDefinationCurrencyID,
																		1 AmtDefinationRate, MST.SalaryRuleMasterSystemID
																FROM [BonusPolicyMonthlyRetainStrcEmpWiseCalculation] M
																		INNER JOIN [BonusPolicyMonthlyRetainDistributionStrcPmt] D ON M.ID = D.BnsPlyMntRetainID
																		INNER JOIN SalaryInfoDefineMaster MST ON M.EmpSystemID = MST.EmpInfoSystemID 
                                                                         ----------------AND MST.IsApproved = 1-------------
																		LEFT JOIN SalaryRuleMaster SRM ON SRM.SystemID = MST.SalaryRuleMasterSystemID
																		LEFT JOIN CurrencyRuleChild CRC ON CRC.MstSystemID = SRM.CurrencyRuleSystemID AND CRC.SalaryHeadID = D.SalaryHeadID
															
                                                                                                                            --Dada
                                                                                                                            --WHERE EOMONTH(DATEFROMPARTS(M.YearNo, M.MonthNo, 1)) IN (SELECT MAX(EOMONTH(DATEFROMPARTS(YearNo, MonthNo, 1))) 
																															--FROM [BonusPolicyMonthlyRetainEmpWiseCalculation] 
																		WHERE M.MonthNo = DATEPART(MONTH,'" + para.FromDate + @"') AND M.YearNo = DATEPART(YEAR,'" + para.FromDate + @"')													--WHERE CONVERT(DATE, EOMONTH(DATEFROMPARTS(YearNo, MonthNo, 1))) <= CONVERT(DATE, '" + para.FromDate + @"'))

																)
													) EmpSlr ON E.SystemID = EmpSlr.EmpInfoSystemID
										LEFT JOIN SalaryHead SH ON SH.SalaryHeadID = EmpSlr.SalaryHeadID
										LEFT JOIN (SELECT * FROM [MST].[PlantSalaryHeadSequence] WHERE PlantId='" + para.PlantId + @"') PSH ON PSH.SalaryHeadId = EmpSlr.SalaryHeadID
										
										LEFT JOIN SalaryRuleMaster SRM ON SRM.SystemID = EmpSlr.SalaryRuleMasterSystemID
										LEFT JOIN CurrencyRuleChild CRC ON CRC.MstSystemID = srm.CurrencyRuleSystemID AND CRC.SalaryHeadID = SH.SalaryHeadID

                                        LEFT JOIN (
										 		   SELECT EmpSystemId,MAX(EffectiveDate) EffectiveDate, VoluntaryPFValue 
												     FROM [PFEmployeeVoluntaryValue] 
													 WHERE EffectiveDate<='" + para.ToDate + @"'
												   GROUP BY EmpSystemId,EffectiveDate,VoluntaryPFValue
												  ) VPF ON E.SystemId = vpf.EmpSystemId
										LEFT JOIN(
										SELECT SH.HeadCategory, SH.SalaryHeadID, SH.SalaryHead, SH.IsCTCComponent, SH.IsGrossComponent, SH.HeadType, 
											   SR.SalaryRuleMasterSystemID
											  FROM [dbo].[SalaryRulePF] SR
											  LEFT JOIN SalaryHead SH ON SH.SalaryHeadID = SR.SalaryHeadID
											  WHERE SH.HeadCategory='PF Voluntary'
										) VPFhead ON VPFhead.SalaryRuleMasterSystemID = EmpSlr.SalaryRuleMasterSystemID

                                       
                         ) A  WHERE --EmployeeStatus = 'Active' and
                       --  ISNULL(EmpInfoSystemID,'')<>''AND 
                PlantID = '" + para.PlantId + @"'  AND DOJ <= '" + para.ToDate + @"'
                           AND (EmployeeStatus != 'Separated' OR ISNULL(DOS,'') = '' OR CONVERT(DATE,DOS) >= Convert(Date,'" + para.FromDate + "'))";

                //if (para.PayGroup.ToUpper() != "NO GROUP")
                //{
                //    strSql = strSql + @" AND EmpInfoSystemID IN (
                //select employeeid from MST.PayrollGroupMaster where PayrollGroupId = '" + para.PayGroup + @"'
                //)";
                //}
                //if (para.PayGroup.ToUpper() == "NO GROUP")
                //{
                //    strSql = strSql + @" AND EmpInfoSystemID NOT IN (
                //select employeeid from MST.PayrollGroupMaster )";
                //}
                //if (para.EmployeeId != "")
                //{
                //    strSql = strSql + @" AND SystemID IN (" + para.EmployeeId + ")";
                //}

                //if (sUnitID != "ALL")
                //{
                //    strSql = strSql + @" AND UnitID = '" + sUnitID + "'";
                //}
                //if (sDivID != "ALL")
                //{
                //    strSql = strSql + @" AND DivisionID = '" + sDivID + "'";
                //}
                if (para.EmployeeId != "")
                {
                    strSql = strSql + @" AND EmpInfoSystemID IN (" + para.EmployeeId + @")";
                }
                if (para.EmpStatus != "ALL")
                {
                    strSql = strSql + @" AND EmpBasic.EmployeeStatus = '" + para.EmpStatus + @"'";
                }
                if (para.DepartmentId != "ALL")
                {
                    strSql = strSql + @" AND DepartmentID = '" + para.DepartmentId + "'";
                }
                //if (sSecID != "ALL")
                //{
                //    strSql = strSql + @" AND SectionID = '" + sSecID + "'";
                //}
                //if (sSubSecID != "ALL")
                //{
                //    strSql = strSql + @" AND SubSectionID = '" + sSubSecID + "'";
                //}
                #region--Pay Group--
                if (para.PayGroup.ToUpper() == "ALL".ToUpper())
                {

                    if (para.SystemAdmin.ToUpper() == "TRUE" || para.ControlAdmin.ToUpper() == "TRUE")
                    {
                        strSql = strSql + "";
                    }
                    else
                    {
                        strSql = strSql + @" AND EmpInfoSystemID  =''";
                        throw new Exception("Please Select a Pay Group");

                    }

                }
                else if (para.PayGroup.ToUpper() != "NO GROUP")
                {
                    strSql = strSql + @" AND EmpInfoSystemID  IN (
													 select employeeid from MST.PayrollGroupMaster where PayrollGroupId = '" + para.PayGroup + @"')";
                }
                if (para.PayGroup.ToUpper() == "NO GROUP")
                {
                    strSql = strSql + @" AND EmpInfoSystemID NOT IN (
													 select employeeid from MST.PayrollGroupMaster)";
                }
                #endregion--Pay Group--
                strSql = strSql + @"ORDER BY EmployeeCodeS";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function

        public void GetSalaryInfoSlrProcIDWisePayGrp(ParamList para, out DataSet dsRef)
        {
            string strSQL;
            ConnectionManager.DAL.ConManager objCon;
            try
            {
                strSQL = @"SELECT EmpSlr.EmpInfoSystemID,convert(int, EmpBasic.EmployeeCode)EmployeeCode, EmpBasic.EmployeeName, Replace(Convert(varchar(11),EmpBasic.DOJ,106),' ','-') DOJ
                                , REPLACE(Convert(VARCHAR(11), EmpBasic.DOB, 106), ' ', '-') AS DOB,REPLACE(Convert(VARCHAR(11), EmpBasic.DOS, 106), ' ', '-') AS DOS,
                                EmpBasic.EmployeeStatus, EmpBasic.UnitID, EmpBasic.UnitName, EmpBasic.DivisionID, EmpBasic.DivisionName,
                                EmpBasic.DepartmentID, EmpBasic.DepartmentName, EmpBasic.SectionID, EmpBasic.SectionName, EmpBasic.SubSectionID,
                                EmpBasic.SubSectionName, EmpBasic.EmployeeCategorySystemID, EmpBasic.EmpCategoryName, EmpBasic.DesignationGroupName,
                                EmpBasic.DesignationSystemID, EmpBasic.DesignationName,EmpBasic.GivenDesignationName,ISNULL(EmpBasic.LegalDesignation,'')LegalDesignation,EmpBasic.GivenDesignationGroup, EmpBasic.PlantName
							
                                ,esic.ESICNo,pf.UANNo,bb.BankAccNo,bb.BankName, '' BankNameFull,ISNULL(MMDSA.TotalLate, 0) TotalLate
								,(ISNULL(MMDSA.TotalPresent, 0) + ISNULL(MMDSA.TotalLate, 0)) PresentDays,PaymentMode,
								ISNULL(MMDSA.AbsentDays, 0) AbsentDays,  ISNULL(MMDSA.TotalHoliDay + MMDSA.TotalWeekOffHoliDay,0) HoliDay, ISNULL(MMDSA.TotalWeekOff, 0) WeekOff,
								(ISNULL(MMDSA.TotalLv, 0) + ISNULL(MMDSA.TotalMLv, 0)) LeaveDays,ISNULL(MMDSA.TotalLWP,0) LWP, EmpSlr.SlrProcChdSysID, EmpSlr.SlrProcMstSystemID, EmpSlr.SalaryProcID,
                                EmpSlr.PlantID, EmpSlr.FromDate, EmpSlr.ToDate, EmpSlr.MonthNo, EmpSlr.YearNo, EmpSlr.PayAbleShSystemID,
                                EmpSlr.SalaryHeadID, EmpSlr.EntryCurrencyID, EmpSlr.EntryAmount, EmpSlr.DefineCurrencyID, EmpSlr.DefineAmount,
                                EmpSlr.DisbusmentCurrencyID, EmpSlr.DisbusmentAmount, EmpSlr.AcltExcDisbSlrHDID, EmpSlr.AcltExcDisbSlrHDAmt,
                                EmpSlr.PlantWiseExchangeCR, EmpSlr.ExchangeRate, EmpSlr.AmtDefinitionCurrencyID, EmpSlr.AmtDefinitionCurrency,
                                EmpSlr.AmtDefinitionCurrencyRate, EmpSlr.IsNetPayEffect
                                ,EmpSlr.SalaryHead,EmpSlr.HeadCategory,EmpSlr.HeadType,EmpSlr.Sequence,EmpSlr.IsCTCComponent,EmpSlr.IsGrossComponent,empslr.SalaryHeadBangla

                                , isnull(vpf.VoluntaryPFValue,0) VoluntaryPFValue
                                , isnull(BonusValue.Bonus,0) Bonus

								, BonusValue.SalaryHead B_SalaryHead
								, BonusValue.SalaryHeadID B_SalaryHeadID
								, BonusValue.IsCTCComponent B_IsCTCComponent
								, BonusValue.IsGrossComponent B_IsGrossComponent
								, BonusValue.HeadType B_HeadType
								--, BonusValue.HeadCategory B_HeadCategory

                                ,VPFhead.HeadCategory xHeadCategory,VPFhead.SalaryHeadID xSalaryHeadID
                                ,VPFhead.SalaryHead xSalaryHead,VPFhead.IsCTCComponent xIsCTCComponent
                                ,VPFhead.IsGrossComponent xIsGrossComponent,VPFhead.HeadType xHeadType
                                ,VPFhead.SalaryRuleMasterSystemID xSalaryRuleMasterSystemID
                                ,MW.Grade,CONVERT(DECIMAL(10, 2), ISNULL(MMDSA.TotalOTHr,0)/60) TotalOTHr
                            FROM
                                    (
									 SELECT E.SystemID, convert(int, E.EmployeeCode)EmployeeCode, E.EmployeeName, E.DOJ,E.DOB,E.DOS, E.EmployeeStatus,E.PaymentMode,
											DG.UserName DesignationGroupName, E.DesignationSystemID, DE.UserName DesignationName,GVDE.UserName GivenDesignationName,LG.UserName LegalDesignation,
											'' UserGroupSystemID, E.PlantID, F.UserName PlantName, E.UnitID,
											FU.UserName UnitName, E.DivisionID, DV.UserName DivisionName, E.DepartmentID, DP.UserName DepartmentName,
											E.SectionID, S.UserName SectionName, E.SubSectionID, SS.UserName SubSectionName, E.EmployeeCategorySystemID,
											EC.UserName EmpCategoryName--, BK.BankNameShort BankName, BK.BankNameFull, E.BankAccNo
                                            ,egdsgg.GivenDesignationGroup,e.SalaryRuleMasterSystemID
                                     FROM EmployeeInformation E
												LEFT JOIN org.Plant F ON E.PlantID = F.Id
												LEFT JOIN hkp.DesignationGroup DG ON E.DesignationGroupId = DG.ID
												LEFT JOIN hkp.Designation DE ON E.GivenDesignationId = DE.Id
												LEFT JOIN hkp.Designation GVDE ON E.GivenDesignationId = GVDE.Id
                                                LEFT JOIN HKP.LegalDesignation LG ON E.LegalDesignationId = LG.Id
												LEFT JOIN org.Unit FU ON E.UnitID = FU.Id
												LEFT JOIN org.Division DV ON E.DivisionID = DV.Id
												LEFT JOIN org.Department DP ON E.DepartmentID = DP.Id
												LEFT JOIN org.Section S ON E.SectionID = S.Id
												LEFT JOIN org.SubSection SS ON E.SubSectionID = SS.Id
												LEFT JOIN
                                                --hkp.EmployeeCategory EC ON E.EmployeeCategorySystemID = EC.Id
                                                (
                                                SELECT ECT.Id, ECT.UserName, DM.DesignationId FROM [HKP].[EmployeeCategory] ECT
												LEFT JOIN MST.DesignationMaster DM ON ECT.Id=DM.EmployeeCategoryId
												)EC ON EC.DesignationId=E.GivenDesignationId
												LEFT JOIN (SELECT dm.DesignationGroupId,dm.DesignationId,dm.EmployeeCategoryId
									            ,dg.UserName GivenDesignationGroup
									            FROM MST.DesignationMaster dm
									            LEFT JOIN HKP.DesignationGroup dg on dg.Id=dm.DesignationGroupId
									            ) egdsgg on egdsgg.DesignationId=e.GivenDesignationId
									            and egdsgg.EmployeeCategoryId=e.EmployeeCategorySystemID

									) EmpBasic
                                    INNER JOIN
											(
											 SELECT SPC.SystemID AS SlrProcChdSysID, SPC.SlrProcMstSystemID, SPM.SalaryProcID, SPM.FromDate, SPM.ToDate,
													SPC.EmpInfoSystemID, SPC.PlantID, SPM.UserGroupSystemID, SPM.MonthNo, SPM.YearNo, SPC.PayAbleShSystemID,
													SPC.SalaryHeadID, SPC.EntryCurrencyID, SPC.EntryAmount, SPC.DefineCurrencyID, SPC.DefineAmount,
													SPC.DisbusmentCurrencyID, SPC.DisbusmentAmount, SPC.AcltExcDisbSlrHDID, SPC.AcltExcDisbSlrHDAmt,
													CRE.Name AS PlantWiseExchangeCR, EXR.ToCurrencyBuying ExchangeRate, SPM.AmtDefinitionCurrencyID,
													CR.Name AS AmtDefinitionCurrency, SPM.AmtDefinitionCurrencyRate, SPC.IsNetPayEffect
                                                    ,sh.SalaryHead,sh.HeadCategory,sh.HeadType,isnull(psh.Sequence, 99) Sequence
                                                    ,sh.IsCTCComponent,sh.IsGrossComponent,BSH.Name SalaryHeadBangla
											 FROM SalaryProcChild SPC
														INNER JOIN SalaryProcMaster SPM ON SPC.SlrProcMstSystemID = SPM.SystemID
																							AND SPM.SalaryProcID = '" + para.SalaryProcessId + @"'

                                                        LEFT JOIN SalaryHead sh on sh.SalaryHeadID=spc.SalaryHeadID
LEFT JOIN (SELECT * FROM HKP.LocalLanguage WHERE SalaryHeadId IS NOT NULL) AS BSH ON BSH.SalaryHeadId = sh.SalaryHeadID --BanglaSalaryHead
														LEFT JOIN (select * from [MST].[PlantSalaryHeadSequence] where PlantId='" + para.PlantId + @"' ) psh
																		on psh.SalaryHeadId=spc.SalaryHeadID

														LEFT JOIN scs.Currency CR ON SPM.AmtDefinitionCurrencyID = CR.Id
														LEFT JOIN (
																   SELECT * FROM ExchangerateDateWiseForHR
																   WHERE FromDate IN (
																					  SELECT MAX(FromDate) FromDate FROM ExchangerateDateWiseForHR
																						WHERE FromDate <= (
																										   SELECT MAX(FromDate) FromDate FROM SalaryProcMaster
																											WHERE SalaryProcID = '" + para.SalaryProcessId + @"'
                                                                                                                  AND SystemID IN (
																																   SELECT SlrProcMstSystemID FROM SalaryProcChild
                                                                                                                                    WHERE PlantID = '" + para.PlantId + @"'
                                                                                                                                  )
                                                                                                           )
                                                                                    )
																  ) EXR ON SPM.AmtDefinitionCurrencyID = EXR.FromCurrencyCode
																							AND SPC.PlantID = Exr.PlantID
														LEFT JOIN scs.Currency CRE ON EXR.FromCurrencyCode = CRE.Id
											) EmpSlr ON EmpBasic.SystemID = EmpSlr.EmpInfoSystemID AND EmpBasic.PlantID = EmpSlr.PlantID
                                left join (
										
												  select EmpSystemId,MAX(EffectiveDate) EffectiveDate, VoluntaryPFValue from [PFEmployeeVoluntaryValue] 
												  Where EffectiveDate<='" + para.FromDate + @"'
												  Group By EmpSystemId,EffectiveDate,VoluntaryPFValue
										) VPF on EmpBasic.SystemId=vpf.EmpSystemId

										left join(
										SELECT SH.HeadCategory ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
										,SH.IsGrossComponent,SH.HeadType,sr.SalaryRuleMasterSystemID
											  FROM [dbo].[SalaryRulePF] SR
											  left join SalaryHead SH ON SH.SalaryHeadID=SR.SalaryHeadID
											  where SH.HeadCategory='PF Voluntary'
										) VPFhead on VPFhead.SalaryRuleMasterSystemID=EmpBasic.SalaryRuleMasterSystemID

                                        left join
										(
										select m.EmpSystemID,m.MonthNo,d.Value Bonus 
												--,SH.HeadCategory 
                                                ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
												,SH.IsGrossComponent,SH.HeadType
												from [BonusPolicyMonthlyRetainEmpWiseCalculation] m
												left join [BonusPolicyMonthlyRetainDistributionPmt] d on m.id=d.BnsPlyMntRetainID
												left join SalaryHead SH ON SH.SalaryHeadID=d.SalaryHeadID
												where m.MonthNo=DATEPART(Month,'" + para.FromDate + @"')  AND m.YearNo=DATEPART(YEAR,'" + para.FromDate + @"')  
                                                --and d.SalaryHeadID=(select SalaryHeadID from SalaryHead where HeadCategory='Festival Bonus')
										) BonusValue on EmpBasic.SystemId=BonusValue.EmpSystemID

                                    LEFT JOIN
		                                    (
											 SELECT EmpSystemID, MonthNo, YearNo, TotalProcDate, TotalPresent, TotalLate,
													TotalAbsent AbsentDays, TotalLv,TotalLWP, TotalMLv, TotalCompAssignLv, TotalWeekOff, TotalHoliDay,
													TotalWeekOffHoliDay, TotalOTHr, TotalNormalOTHr, TotalExtraOTHr
				                              FROM SalaryProceAttdnData
											) MMDSA ON EmpSlr.EmpInfoSystemID = MMDSA.EmpSystemID AND EmpSlr.MonthNo = MMDSA.MonthNo AND
						                               EmpSlr.YearNo = MMDSA.YearNo

                                    LEFT JOIN 
                                           		(
                                           		 SELECT E.SystemID, SUM(SV.SalaryHeadValue) SalaryHeadValue,LSG.UserName Grade
                                           			FROM EmployeeInformation E   
                                           					LEFT JOIN MST.ManpowerBudget b ON e.BudgetCode = b.Id
                                           					LEFT JOIN MST.LegalSalaryGradeDesignation GD ON GD.LegalDesignationId = E.LegalDesignationId 
                                                                                               AND E.PlantId = gd.PlantId
                                           					LEFT JOIN (
                                           								SELECT MAX(EffectiveDate)EffectiveDate, LegalSalaryGradeId, EmployeeLocationId 
                                           									FROM MST.LegalSalaryStructure 
                                           									WHERE EffectiveDate <= GETDATE()
                                           								GROUP BY LegalSalaryGradeId, EmployeeLocationId 
                                           							  ) S ON S.LegalSalaryGradeId = GD.LegalSalaryGradeId AND S.EmployeeLocationId = B.EmployeeLocationId
                                           					LEFT JOIN MST.LegalSalaryStructure SS ON SS.LegalSalaryGradeId = S.LegalSalaryGradeId 
                                                                                           AND SS.EmployeeLocationId = S.EmployeeLocationId 
                                                                                           AND SS.EffectiveDate = S.EffectiveDate
                                           					LEFT JOIN MST.LegalSalaryStructureValue SV ON SV.LegalSalaryStructureId = SS.Id 																							
                                           					left join  [SCS].[LegalSalaryGrade] LSG ON LSG.Id=S.LegalSalaryGradeId
                                           			GROUP BY E.SystemId,LSG.UserName 
                                           		) MW ON MW.SystemId = EmpBasic.SystemId

                                                left join (
                                                select bb.UserName BankName,b.BankAccNo,b.EmpSystemID from [dbo].[EmployeeBankInfo] b
                                                left join hkp.BankBranch bb on b.BankBranchId=bb.Id
                                                ) BB ON BB.EmpSystemID = EmpBasic.SystemId

                                                left join
												( select ed.DocNumber UANNo,ED.EmpSystemID from 
												EmployeeDocument ED 
												inner JOIN (select * from HKP.ComplianceDocument where ProfileType = 'PF') CD ON CD.Id = ED.ComplianceDocumentId 
												) pf on EmpBasic.SystemId = pf.EmpSystemID

												left join
												( select ed.DocNumber ESICNo,ED.EmpSystemID from 
												EmployeeDocument ED 
												inner JOIN (select * from HKP.ComplianceDocument where ProfileType = 'ESIC') CD ON CD.Id = ED.ComplianceDocumentId 
												) esic on EmpBasic.SystemId = esic.EmpSystemID
                                                        ";

                if (para.PlantId != "ALL")
                {
                    strSQL = strSQL + @" WHERE EmpBasic.PlantID = '" + para.PlantId + @"'";
                }
                if (para.PayGroup.ToUpper() != "NO GROUP")
                {
                    strSQL = strSQL + @" AND EmpSlr.EmpInfoSystemID IN (
													 select employeeid from MST.PayrollGroupMaster where PayrollGroupId = '" + para.PayGroup + @"'
													 )";
                }
                if (para.PayGroup.ToUpper() == "NO GROUP")
                {
                    strSQL = strSQL + @" AND EmpSlr.EmpInfoSystemID NOT IN (
													 select employeeid from MST.PayrollGroupMaster)";
                }

                if (para.EmployeeId != "")
                {
                    strSQL = strSQL + @" AND EmpSlr.EmpInfoSystemID IN (" + para.EmployeeId + @")";
                }
                if (para.EmpStatus != "ALL")
                {
                    strSQL = strSQL + @" AND EmpBasic.EmployeeStatus = '" + para.EmpStatus + @"'";
                }

                strSQL = strSQL + @" ORDER BY EmpBasic.PlantID, EmpBasic.EmployeeCode, EmpSlr.EmpInfoSystemID, EmpSlr.SalaryHeadID";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function
        public void GetWeeklyAbsentismAssignment(string ePlant, string eCode, string eFrmDate, string eToDate, out DataSet dsWeeklyAbsnt)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = string.Empty;

            try
            {
                strSql = @"SELECT  REPLACE(CONVERT(VARCHAR(11),WorkingDate,106),' ','-') WorkingDate,EmpSystemID,EmployeeCode
                                            FROM [SCS].[WeeklyAbsentismAssignment] S
                                            LEFT JOIN EmployeeInformation EI on EI.SystemId = S.EmpSystemID
                                            where WorkingDate BETWEEN '" + eFrmDate + @"' AND '" + eToDate + @"'  AND S.plantid= '" + ePlant + @"' AND EmpSystemID in( " + eCode + ")";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsWeeklyAbsnt, false, false, "", "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function
        public void GetSalaryInfoSlrProcIDWiseIndia(ParamList para, string sMth, string sYr, out DataSet dsRef)
        {
            string strSQL;
            ConnectionManager.DAL.ConManager objCon;


            try
            {
                strSQL = @"SELECT EmpSlr.EmpInfoSystemID,convert(int, EmpBasic.EmployeeCode)EmployeeCode, EmpBasic.EmployeeName, Replace(Convert(varchar(11),EmpBasic.DOJ,106),' ','-') DOJ
                                , REPLACE(Convert(VARCHAR(11), EmpBasic.DOB, 106), ' ', '-') AS DOB,REPLACE(Convert(VARCHAR(11), EmpBasic.DOS, 106), ' ', '-') AS DOS,
                                EmpBasic.EmployeeStatus, EmpBasic.UnitID, EmpBasic.UnitName, EmpBasic.DivisionID, EmpBasic.DivisionName,
                                EmpBasic.DepartmentID, EmpBasic.DepartmentName, EmpBasic.SectionID, EmpBasic.SectionName, EmpBasic.SubSectionID,
                                EmpBasic.SubSectionName, EmpBasic.EmployeeCategorySystemID, EmpBasic.EmpCategoryName, EmpBasic.DesignationGroupName,
                                EmpBasic.DesignationSystemID, EmpBasic.DesignationName,EmpBasic.GivenDesignationName,EmpBasic.GivenDesignationGroup, EmpBasic.PlantName
							
                                ,esic.ESICNo,pf.UANNo,bb.BankAccNo,bb.BankName, '' BankNameFull,ISNULL(MMDSA.TotalProcDate, 0) TotalProcDate,ISNULL(MMDSA.TotalLate, 0) TotalLate
								,(ISNULL(MMDSA.TotalPresent, 0) + ISNULL(MMDSA.TotalLate, 0)) PresentDays,PaymentMode, (ISNULL(MMDSA.TotalLWP, 0)) TotalLWP
								,ISNULL(MMDSA.AbsentDays, 0) AbsentDays,  ISNULL(MMDSA.TotalHoliDay + MMDSA.TotalWeekOffHoliDay,0) HoliDay, ISNULL(MMDSA.TotalWeekOff, 0) WeekOff,
								(ISNULL(MMDSA.TotalLv, 0) + ISNULL(MMDSA.TotalMLv, 0)) LeaveDays,ISNULL(MMDSA.TotalLWP,0) LWP, EmpSlr.SlrProcChdSysID, EmpSlr.SlrProcMstSystemID, EmpSlr.SalaryProcID,
                                EmpSlr.PlantID, EmpSlr.FromDate, EmpSlr.ToDate, EmpSlr.MonthNo, EmpSlr.YearNo, EmpSlr.PayAbleShSystemID,
                                EmpSlr.SalaryHeadID, EmpSlr.EntryCurrencyID, EmpSlr.EntryAmount, EmpSlr.DefineCurrencyID, EmpSlr.DefineAmount,
                                EmpSlr.DisbusmentCurrencyID, EmpSlr.DisbusmentAmount, EmpSlr.AcltExcDisbSlrHDID, EmpSlr.AcltExcDisbSlrHDAmt,
                                EmpSlr.PlantWiseExchangeCR, EmpSlr.ExchangeRate, EmpSlr.AmtDefinitionCurrencyID, EmpSlr.AmtDefinitionCurrency,
                                EmpSlr.AmtDefinitionCurrencyRate, EmpSlr.IsNetPayEffect
                                ,EmpSlr.SalaryHead,EmpSlr.HeadCategory,EmpSlr.HeadType,EmpSlr.Sequence,EmpSlr.IsCTCComponent,EmpSlr.IsGrossComponent

                                , isnull(vpf.VoluntaryPFValue,0) VoluntaryPFValue
                                , isnull(BonusValue.Bonus,0) Bonus

								, BonusValue.SalaryHead B_SalaryHead
								, BonusValue.SalaryHeadID B_SalaryHeadID
								, BonusValue.IsCTCComponent B_IsCTCComponent
								, BonusValue.IsGrossComponent B_IsGrossComponent
								, BonusValue.HeadType B_HeadType
								--, BonusValue.HeadCategory B_HeadCategory

                                ,VPFhead.HeadCategory xHeadCategory,VPFhead.SalaryHeadID xSalaryHeadID
                                ,VPFhead.SalaryHead xSalaryHead,VPFhead.IsCTCComponent xIsCTCComponent
                                ,VPFhead.IsGrossComponent xIsGrossComponent,VPFhead.HeadType xHeadType
                                ,VPFhead.SalaryRuleMasterSystemID xSalaryRuleMasterSystemID
                                ---,VPFhead.IntegerInDisb, VPFhead.DecimalNo,
                                ,MW.Grade,CONVERT(DECIMAL(10, 2), ISNULL(MMDSA.TotalOTHr,0)/60) TotalOTHr
                                ,EmpSlr.DecimalNo AS DecimalNo ,EmpSlr.IntegerInDisb AS IntegerInDisb,EmpSlr.IsDecimalInDisb AS IsDecimalInDisb
                            FROM
                                    (
									 SELECT E.SystemID, convert(int, E.EmployeeCode)EmployeeCode, E.EmployeeName, E.DOJ,E.DOB,E.DOS, E.EmployeeStatus,E.PaymentMode,
											DG.UserName DesignationGroupName, E.DesignationSystemID, DE.UserName DesignationName,GVDE.UserName GivenDesignationName,
											'' UserGroupSystemID, E.PlantID, F.UserName PlantName, E.UnitID,
											FU.UserName UnitName, E.DivisionID, DV.UserName DivisionName, E.DepartmentID, DP.UserName DepartmentName,
											E.SectionID, S.UserName SectionName, E.SubSectionID, SS.UserName SubSectionName, E.EmployeeCategorySystemID,
											EC.UserName EmpCategoryName--, BK.BankNameShort BankName, BK.BankNameFull, E.BankAccNo
                                            ,egdsgg.GivenDesignationGroup,e.SalaryRuleMasterSystemID
                                     FROM EmployeeInformation E
												LEFT JOIN org.Plant F ON E.PlantID = F.Id
												LEFT JOIN hkp.DesignationGroup DG ON E.DesignationGroupId = DG.ID
												LEFT JOIN hkp.Designation DE ON E.GivenDesignationId = DE.Id
												LEFT JOIN hkp.Designation GVDE ON E.GivenDesignationId = GVDE.Id
												LEFT JOIN org.Unit FU ON E.UnitID = FU.Id
												LEFT JOIN org.Division DV ON E.DivisionID = DV.Id
												LEFT JOIN org.Department DP ON E.DepartmentID = DP.Id
												LEFT JOIN org.Section S ON E.SectionID = S.Id
												LEFT JOIN org.SubSection SS ON E.SubSectionID = SS.Id
												LEFT JOIN
                                                --hkp.EmployeeCategory EC ON E.EmployeeCategorySystemID = EC.Id
                                                (
                                                SELECT ECT.Id, ECT.UserName, DM.DesignationId FROM [HKP].[EmployeeCategory] ECT
												LEFT JOIN MST.DesignationMaster DM ON ECT.Id=DM.EmployeeCategoryId
												)EC ON EC.DesignationId=E.GivenDesignationId
												LEFT JOIN (SELECT dm.DesignationGroupId,dm.DesignationId,dm.EmployeeCategoryId
									            ,dg.UserName GivenDesignationGroup
									            FROM MST.DesignationMaster dm
									            LEFT JOIN HKP.DesignationGroup dg on dg.Id=dm.DesignationGroupId
									            ) egdsgg on egdsgg.DesignationId=e.GivenDesignationId
									            and egdsgg.EmployeeCategoryId=e.EmployeeCategorySystemID

									) EmpBasic
                                    INNER JOIN
											(
											 SELECT SPC.SystemID AS SlrProcChdSysID, SPC.SlrProcMstSystemID, SPM.SalaryProcID, SPM.FromDate, SPM.ToDate,
													SPC.EmpInfoSystemID, SPC.PlantID, SPM.UserGroupSystemID, SPM.MonthNo, SPM.YearNo, SPC.PayAbleShSystemID,
													SPC.SalaryHeadID, SPC.EntryCurrencyID, SPC.EntryAmount, SPC.DefineCurrencyID, SPC.DefineAmount,
													SPC.DisbusmentCurrencyID, SPC.DisbusmentAmount, SPC.AcltExcDisbSlrHDID, SPC.AcltExcDisbSlrHDAmt,
													CRE.Name AS PlantWiseExchangeCR, EXR.ToCurrencyBuying ExchangeRate, SPM.AmtDefinitionCurrencyID,
													CR.Name AS AmtDefinitionCurrency, SPM.AmtDefinitionCurrencyRate, SPC.IsNetPayEffect
                                                    ,sh.SalaryHead,sh.HeadCategory,sh.HeadType,isnull(psh.Sequence, 99) Sequence
                                                    ,sh.IsCTCComponent,sh.IsGrossComponent,dcm.DecimalNo,dcm.IntegerInDisb,dcm.IsDecimalInDisb
											 FROM SalaryProcChild SPC
														INNER JOIN SalaryProcMaster SPM ON SPC.SlrProcMstSystemID = SPM.SystemID
																							AND SPM.SalaryProcID = '" + para.SalaryProcessId + @"'

                                                        LEFT JOIN SalaryHead sh on sh.SalaryHeadID=spc.SalaryHeadID
														LEFT JOIN (select * from [MST].[PlantSalaryHeadSequence] where PlantId='" + para.PlantId + @"' ) psh
																		on psh.SalaryHeadId=spc.SalaryHeadID

														LEFT JOIN scs.Currency CR ON SPM.AmtDefinitionCurrencyID = CR.Id
														LEFT JOIN (
																   SELECT * FROM ExchangerateDateWiseForHR
																   WHERE FromDate IN (
																					  SELECT MAX(FromDate) FromDate FROM ExchangerateDateWiseForHR
																						WHERE FromDate <= (
																										   SELECT MAX(FromDate) FromDate FROM SalaryProcMaster
																											WHERE SalaryProcID = '" + para.SalaryProcessId + @"'
                                                                                                                  AND SystemID IN (
																																   SELECT SlrProcMstSystemID FROM SalaryProcChild
                                                                                                                                    WHERE PlantID = '" + para.PlantId + @"'
                                                                                                                                  )
                                                                                                           )
                                                                                    )
																  ) EXR ON SPM.AmtDefinitionCurrencyID = EXR.FromCurrencyCode
																							AND SPC.PlantID = Exr.PlantID
														LEFT JOIN scs.Currency CRE ON EXR.FromCurrencyCode = CRE.Id
                                                  ------    for decimal part       ---------
														 LEFT JOIN
                                               ( SELECT ssm.EmpInfoSystemID,crc.SalaryHeadID,crc.DecimalNo,crc.IntegerInDisb,crc.IsDecimalInDisb
												FROM SalaryInfoDefineMaster ssm
												left join SalaryRuleMaster srm on srm.SystemID=ssm.SalaryRuleMasterSystemID
												left join CurrencyRuleMaster crm on crm.SystemID=srm.CurrencyRuleSystemID
												left join CurrencyRuleChild crc on crc.MstSystemID=crm.SystemID) dcm on  dcm.SalaryHeadID=SPC.SalaryHeadID  and SPC.EmpInfoSystemID=dcm.EmpInfoSystemID
												      -------   end decimal part-------
											) EmpSlr ON EmpBasic.SystemID = EmpSlr.EmpInfoSystemID AND EmpBasic.PlantID = EmpSlr.PlantID
                                left join (
										
												  select EmpSystemId,MAX(EffectiveDate) EffectiveDate, VoluntaryPFValue from [PFEmployeeVoluntaryValue] 
												  Where EffectiveDate<='" + para.FromDate + @"'
												  Group By EmpSystemId,EffectiveDate,VoluntaryPFValue
										) VPF on EmpBasic.SystemId=vpf.EmpSystemId

										left join(
										SELECT SH.HeadCategory ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
										,SH.IsGrossComponent,SH.HeadType,sr.SalaryRuleMasterSystemID
											  FROM [dbo].[SalaryRulePF] SR
											  left join SalaryHead SH ON SH.SalaryHeadID=SR.SalaryHeadID
											  where SH.HeadCategory='PF Voluntary'
										) VPFhead on VPFhead.SalaryRuleMasterSystemID=EmpBasic.SalaryRuleMasterSystemID

                                        left join
										(
										select m.EmpSystemID,m.MonthNo,d.Value Bonus 
												--,SH.HeadCategory 
                                                ,SH.SalaryHeadID,SH.SalaryHead,SH.IsCTCComponent
												,SH.IsGrossComponent,SH.HeadType
												from [BonusPolicyMonthlyRetainEmpWiseCalculation] m
												left join [BonusPolicyMonthlyRetainDistributionPmt] d on m.id=d.BnsPlyMntRetainID
												left join SalaryHead SH ON SH.SalaryHeadID=d.SalaryHeadID
												where m.MonthNo=DATEPART(Month,'" + para.FromDate + @"')  AND m.YearNo=DATEPART(YEAR,'" + para.FromDate + @"')  
                                                --and d.SalaryHeadID=(select SalaryHeadID from SalaryHead where HeadCategory='Festival Bonus')
										) BonusValue on EmpBasic.SystemId=BonusValue.EmpSystemID

                                    LEFT JOIN
		                                    (
											 SELECT EmpSystemID, MonthNo, YearNo, TotalProcDate, TotalPresent, TotalLate,
													TotalAbsent AbsentDays, TotalLv,TotalLWP, TotalMLv, TotalCompAssignLv, TotalWeekOff, TotalHoliDay,
													TotalWeekOffHoliDay, TotalOTHr, TotalNormalOTHr, TotalExtraOTHr
				                              FROM SalaryProceAttdnData
											) MMDSA ON EmpSlr.EmpInfoSystemID = MMDSA.EmpSystemID AND EmpSlr.MonthNo = MMDSA.MonthNo AND
						                               EmpSlr.YearNo = MMDSA.YearNo

                                    LEFT JOIN 
                                           		(
                                           		 SELECT E.SystemID, SUM(SV.SalaryHeadValue) SalaryHeadValue,LSG.UserName Grade
                                           			FROM EmployeeInformation E   
                                           					LEFT JOIN MST.ManpowerBudget b ON e.BudgetCode = b.Id
                                           					LEFT JOIN MST.LegalSalaryGradeDesignation GD ON GD.LegalDesignationId = E.LegalDesignationId 
                                                                                               AND E.PlantId = gd.PlantId
                                           					LEFT JOIN (
                                           								SELECT MAX(EffectiveDate)EffectiveDate, LegalSalaryGradeId, EmployeeLocationId 
                                           									FROM MST.LegalSalaryStructure 
                                           									WHERE EffectiveDate <= GETDATE()
                                           								GROUP BY LegalSalaryGradeId, EmployeeLocationId 
                                           							  ) S ON S.LegalSalaryGradeId = GD.LegalSalaryGradeId AND S.EmployeeLocationId = B.EmployeeLocationId
                                           					LEFT JOIN MST.LegalSalaryStructure SS ON SS.LegalSalaryGradeId = S.LegalSalaryGradeId 
                                                                                           AND SS.EmployeeLocationId = S.EmployeeLocationId 
                                                                                           AND SS.EffectiveDate = S.EffectiveDate
                                           					LEFT JOIN MST.LegalSalaryStructureValue SV ON SV.LegalSalaryStructureId = SS.Id 																							
                                           					left join  [SCS].[LegalSalaryGrade] LSG ON LSG.Id=S.LegalSalaryGradeId
                                           			GROUP BY E.SystemId,LSG.UserName 
                                           		) MW ON MW.SystemId = EmpBasic.SystemId

                                                left join (
                                                select bb.UserName BankName,b.BankAccNo,b.EmpSystemID from [dbo].[EmployeeBankInfo] b
                                                left join hkp.BankBranch bb on b.BankBranchId=bb.Id
                                                ) BB ON BB.EmpSystemID = EmpBasic.SystemId

                                                left join
												( select ed.DocNumber UANNo,ED.EmpSystemID from 
												EmployeeDocument ED 
												inner JOIN (select * from HKP.ComplianceDocument where ProfileType = 'PF') CD ON CD.Id = ED.ComplianceDocumentId 
												) pf on EmpBasic.SystemId = pf.EmpSystemID

												left join
												( select ed.DocNumber ESICNo,ED.EmpSystemID from 
												EmployeeDocument ED 
												inner JOIN (select * from HKP.ComplianceDocument where ProfileType = 'ESIC') CD ON CD.Id = ED.ComplianceDocumentId 
												) esic on EmpBasic.SystemId = esic.EmpSystemID 
                                                        ";

                if (para.PlantId != "ALL")
                {
                    strSQL = strSQL + @" WHERE EmpBasic.PlantID = '" + para.PlantId + @"' AND   ((MONTH(DOS) >= " + sMth + @" AND Year(DOS) >= " + sYr + @") OR  EmpBasic.EmployeeStatus = 'Active') AND (MONTH(DOJ) <= " + sMth + @" OR Year(DOJ) <= " + sYr + @") ";
                }
                if (para.DepartmentId != "ALL")
                {
                    strSQL = strSQL + @" AND EmpBasic.DepartmentID = '" + para.DepartmentId + @"' ";
                }
                #region--Pay Group--
                if (para.PayGroup.ToUpper() != "NO GROUP")
                {
                    strSQL = strSQL + @" AND EmpInfoSystemID  IN (
													 select employeeid from MST.PayrollGroupMaster where PayrollGroupId = '" + para.PayGroup + @"'
													 )";
                }
                if (para.PayGroup.ToUpper() == "NO GROUP")
                {
                    strSQL = strSQL + @" AND EmpInfoSystemID NOT IN (
													 select employeeid from MST.PayrollGroupMaster)";
                }
                #endregion--Pay Group--
                if (para.EmployeeId != "")
                {
                    strSQL = strSQL + @" AND EmpSlr.EmpInfoSystemID IN (" + para.EmployeeId + @")";
                }
                if (para.EmpStatus != "ALL")
                {
                    strSQL = strSQL + @" AND EmpBasic.EmployeeStatus = '" + para.EmpStatus + @"'";
                }

                strSQL = strSQL + @" ORDER BY EmpBasic.PlantID, EmpBasic.EmployeeCode, EmpSlr.EmpInfoSystemID, EmpSlr.SalaryHeadID";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function
        public void GetEmpGratuityInfo(string gratuityCalcDate, string companyGroupId, string comapnyId, string plantId, string payGrp, string employeeId, string SystemAdmin, string ControlAdmin, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            var strSql = string.Empty;
            clsStaticInfo obs = null;
            try
            {
                obs = new clsStaticInfo();
                strSql = @"SELECT  A.EmployeeCode,A.EmployeeCode EmployeeCodeS ,DOJ,A.EmpSystemID
	                       ,Convert(decimal(18,2),CAST(DATEDIFF(mm, A.DOJ, '" + gratuityCalcDate + @"') AS varchar(4)))/12 totalYear
	                       ,Convert(decimal(18,2),CAST(DATEDIFF(mm, A.DOJ, '" + gratuityCalcDate + @"') AS varchar(4)))-(Convert(decimal(18,2),CAST(DATEDIFF(mm, A.DOJ, '" + gratuityCalcDate + @"') AS varchar(4)))/12)*12 totalMonthAfterYear,* FROM
                    
                       (
                           SELECT E.SystemID EmpSystemID, E.EmployeeCode, E.EmployeeName, REPLACE(Convert(VARCHAR(11), E.DOB, 106), ' ', '-') AS DOB,
	                              E.FatherName, E.MotherName, E.EmpType EmployeeType, E.EmploymentType EmploymentNature, E.NationalID,
	                              E.GenderID GenderName, REPLACE(Convert(VARCHAR(11), E.DOJ, 106), ' ', '-') AS DOJ,
	                              REPLACE(Convert(VARCHAR(11), E.DOC, 106), ' ', '-') AS DOC, eact.IsOutSider,
							
								 EC.UserName AS EmpCategory, Cm.UserName CompanyName,Cm.Id CompanyId, CAM.Address1,
	                              CAM.Address2, E.EmployeeCategorySystemID, E.UnitID, E.DivisionID, E.DepartmentID, E.DesignationSystemID,
	                              E.SectionID, E.SubSectionID, E.LineID, E.DesignationGroupID, E.SubSecStrucSystemID, E.EmployeeStatus,
	                              P.UserName PlantName, (PAM.[Address1] + ', ' + PAM.[Address2] + ', ' + PAMC.UserName + ' - ' + PAM.Postcode) FactoryAddress,
	                              GC.Id GroupID,GC.UserName GroupName, (CGAM.[Address1] + ', ' + CGAM.[Address2] + ', ' + CT.UserName + ' - ' + CGAM.Postcode + ', Contact: ' + CGAM.Phone) GroupAddress,
	                              E.PlantID, BK.UserName BankNameShort, E.BankAccNo, 
								  EmpSlr.SalaryHeadID, SH.SalaryHead, --SNULL(pSH.Sequence, 99) Sequence,
                                SH.HeadType, SH.HeadCategory, EmpSlr.EntryCurrencyID, EmpSlr.EntryAmount,
	                              EmpSlr.DefineCurrencyID, EmpSlr.DefineAmount, EmpSlr.AmtDefinationCurrencyID, EmpSlr.AmtDefinationRate,
	                              SH.IsCTCComponent, SH.IsGrossComponent, EmpSlr.EmpInfoSystemID, MW.SalaryHeadValue                                
	                            ,ISNULL(CRC.IntegerInDisb,1) IntegerInDisb, ISNULL(CRC.DecimalNo,0) DecimalNo, MW.Grade
				            FROM EmployeeInformation AS E
											LEFT JOIN ORG.Plant AS p ON E.PlantId = p.Id
											LEFT JOIN ORG.Company AS Cm ON E.CompanyID = Cm.Id
											LEFT JOIN ORG.CompanyGroup AS GC ON E.GroupID = GC.Id
											LEFT JOIN HKP.Bank AS BK ON E.BankSystemID = BK.Id
											LEFT JOIN MST.AddressMaster AS CAM ON Cm.AddressMasterId = CAM.Id
											LEFT JOIN MST.AddressMaster AS PAM ON P.AddressMasterId = PAM.Id
											LEFT JOIN MST.AddressMaster AS CGAM ON GC.AddressMasterId = CGAM.Id
											LEFT JOIN SCS.City AS PAMC ON PAM.CityId = PAMC.Id
											LEFT JOIN SCS.City AS CT ON CGAM.CityId = CT.Id
                                            LEFT JOIN
													(
													 SELECT ECT.Id, ECT.UserName, DM.DesignationId 
													  FROM [HKP].[EmployeeCategory] ECT
																	LEFT JOIN MST.DesignationMaster DM ON ECT.Id = DM.EmployeeCategoryId
													) EC ON EC.DesignationId = E.GivenDesignationId
											LEFT JOIN 
													(
													 SELECT E.SystemID, SUM(SV.SalaryHeadValue) SalaryHeadValue,LSG.UserName Grade
														FROM EmployeeInformation E   
																LEFT JOIN MST.ManpowerBudget b ON e.BudgetCode = b.Id
																LEFT JOIN MST.LegalSalaryGradeDesignation GD ON GD.LegalDesignationId = E.LegalDesignationId 
                                                                                                AND E.PlantId = gd.PlantId
																LEFT JOIN (
																			SELECT MAX(EffectiveDate)EffectiveDate, LegalSalaryGradeId, EmployeeLocationId 
																				FROM MST.LegalSalaryStructure 
																				WHERE EffectiveDate <= '" + gratuityCalcDate + @"'
																			GROUP BY LegalSalaryGradeId, EmployeeLocationId 
																		  ) S ON S.LegalSalaryGradeId = GD.LegalSalaryGradeId AND S.EmployeeLocationId = B.EmployeeLocationId
																LEFT JOIN MST.LegalSalaryStructure SS ON SS.LegalSalaryGradeId = S.LegalSalaryGradeId 
                                                                                            AND SS.EmployeeLocationId = S.EmployeeLocationId 
                                                                                            AND SS.EffectiveDate = S.EffectiveDate
																LEFT JOIN MST.LegalSalaryStructureValue SV ON SV.LegalSalaryStructureId = SS.Id 	
                                                                left join  [SCS].[LegalSalaryGrade] LSG ON LSG.Id=S.LegalSalaryGradeId	
														GROUP BY E.SystemId,LSG.UserName
													) MW ON MW.SystemId = E.SystemId

										LEFT JOIN (
													SELECT * FROM
																(
																 SELECT MST.EmpInfoSystemID, EmpSlr.SalaryHeadID, EmpSlr.EntryCurrencyID, EmpSlr.EntryAmount, EmpSlr.DefineCurrencyID, EmpSlr.DefineAmount, 
																		EmpSlr.AmtDefinitionCurrencyID AmtDefinationCurrencyID, EmpSlr.AmtDefinitionRate AmtDefinationRate, MST.SalaryRuleMasterSystemID
																 FROM SalaryInfoDefine EmpSlr
																		INNER JOIN SalaryInfoDefineMaster MST ON EmpSlr.SalaryID = MST.SystemID AND MST.IsApproved = 1
																) A
																UNION 
																(
																SELECT M.EmpSystemID EmpInfoSystemID, D.SalaryHeadID, CRC.AmtEntryCurrency EntryCurrencyID, D.Value EntryAmount,
																		CRC.AmtDefinitionCurrency DefineCurrencyID, D.Value DefineAmount, CRC.AmtDefinitionCurrency AmtDefinationCurrencyID,
																		1 AmtDefinationRate, MST.SalaryRuleMasterSystemID
																FROM [BonusPolicyMonthlyRetainStrcEmpWiseCalculation] M
																		INNER JOIN [BonusPolicyMonthlyRetainDistributionStrcPmt] D ON M.ID = D.BnsPlyMntRetainID
																		INNER JOIN SalaryInfoDefineMaster MST ON M.EmpSystemID = MST.EmpInfoSystemID AND MST.IsApproved = 1
																		LEFT JOIN SalaryRuleMaster SRM ON SRM.SystemID = MST.SalaryRuleMasterSystemID
																		LEFT JOIN CurrencyRuleChild CRC ON CRC.MstSystemID = SRM.CurrencyRuleSystemID AND CRC.SalaryHeadID = D.SalaryHeadID
															
                                                                                                                            --Dada
                                                                                                                            --WHERE EOMONTH(DATEFROMPARTS(M.YearNo, M.MonthNo, 1)) IN (SELECT MAX(EOMONTH(DATEFROMPARTS(YearNo, MonthNo, 1))) 
																															--FROM [BonusPolicyMonthlyRetainEmpWiseCalculation] 
																		WHERE M.MonthNo = DATEPART(MONTH,'" + gratuityCalcDate + @"') AND M.YearNo = DATEPART(YEAR,'" + gratuityCalcDate + @"')													--WHERE CONVERT(DATE, EOMONTH(DATEFROMPARTS(YearNo, MonthNo, 1))) <= CONVERT(DATE, '" + gratuityCalcDate + @"'))

																)
													) EmpSlr ON E.SystemID = EmpSlr.EmpInfoSystemID
										LEFT JOIN SalaryHead SH ON SH.SalaryHeadID = EmpSlr.SalaryHeadID
										--LEFT JOIN (SELECT * FROM [MST].[PlantSalaryHeadSequence] WHERE PlantId='" + plantId + @"') PSH ON PSH.SalaryHeadId = EmpSlr.SalaryHeadID
										
										LEFT JOIN SalaryRuleMaster SRM ON SRM.SystemID = EmpSlr.SalaryRuleMasterSystemID
										LEFT JOIN CurrencyRuleChild CRC ON CRC.MstSystemID = srm.CurrencyRuleSystemID AND CRC.SalaryHeadID = SH.SalaryHeadID
                                            left join [dbo].[EmployeeCodeType] eact on eact.Id=e.EmployeeCodeTypeId
                                                 ) A  WHERE EmployeeStatus = 'Active' and a.IsOutSider=0 and
                            isnull(EmpInfoSystemID,'')<>''  AND GroupID = '" + companyGroupId + @"' AND  CompanyId ='" + comapnyId + @"' AND PlantId ='" + plantId + @"'
	                        AND HeadCategory = 'Basic'	
                    AND Convert(decimal(18,2),CAST(DATEDIFF(mm, A.DOJ, '" + gratuityCalcDate + @"') AS varchar(4)))/12 between 
							(
							 SELECT Min(Convert(decimal(18,2),Convert(decimal(18,2),GPD.MaturityFromYear))) FROM GratuityPolicyMaster GPM 
                                left join ORG.Plant pp on pp.Id=GPM.plantId
			                    LEFT JOIN GratuityPolicyDetails GPD ON GPM.Id = GPD.GratuityPolicyMasterId
			                    WHERE GPD.PlantId ='" + plantId + @"'
							)
							AND
							(
							 SELECT Max(Convert(decimal(18,2),Convert(decimal(18,2),GPD.MaturityToYear))) FROM GratuityPolicyMaster GPM
                                left join ORG.Plant ppp on ppp.Id=GPM.plantId
			                    LEFT JOIN GratuityPolicyDetails GPD ON GPM.Id = GPD.GratuityPolicyMasterId
			                    WHERE GPD.PlantId ='" + plantId + @"'
							)
                            ";

                if (!string.IsNullOrEmpty(employeeId))
                {
                    strSql = strSql + @" AND EmpSystemID IN (" + employeeId + ")";
                }
                #region--Pay Group--

                if (payGrp.ToUpper() == "ALL".ToUpper())
                {

                    if (SystemAdmin.ToUpper() == "TRUE" || ControlAdmin.ToUpper() == "TRUE")
                    {
                        strSql = strSql + "";
                    }
                    else
                    {
                        strSql = strSql + @" AND EmpSystemID  =''";
                        throw new Exception("Please Select a Pay Group");

                    }

                }
                else if (payGrp.ToUpper().Trim() != "NOGROUP")
                {
                    strSql = strSql + @" AND EmpSystemID  IN (
													 select employeeid from MST.PayrollGroupMaster where PayrollGroupId = '" + payGrp + @"')";
                }
                if (payGrp.ToUpper().Trim() == "NOGROUP")
                {
                    strSql = strSql + @" AND EmpSystemID NOT IN (
													 select employeeid from MST.PayrollGroupMaster)";
                }
                #endregion--Pay Group--
                strSql = strSql + @"
                        ORDER BY EmployeeCodeS";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, false, "", "1");
                int i = dsRef.Tables[0].Rows.Count;
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//End Function
        public void SelectedPlantWiseCompany(string sPlantID, out DataSet dsRef)
        {
            ConnectionManager.DAL.ConManager objCon;
            string strSql = "";

            try
            {
                strSql = @"SELECT p.UserName PlantName,c.UserName CompanyName ,ISNULL(a.Address1,'')+','+ ISNULL(a.Address2,'') Address1, a.Phone,a.Email
                                ,cm.Address1 cAddress1 ,cm.Address2 cAddress2,c.[Image] CompanyImage
                                FROM org.Plant p
							LEFT OUTER JOIN org.Company c on c.Id=p.CompanyId
							LEFT OUTER JOIN mst.AddressMaster a on a.Id=p.AddressMasterId
							LEFT OUTER JOIN mst.AddressMaster cm on cm.Id=c.AddressMasterId
							WHERE p.Id='" + sPlantID + "'";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSql, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//end of function
        public DataTable SelectedPlantWiseCompanyDT(string sPlantID)
        {
            string strSql = "";
            try
            {
                strSql = @"SELECT p.UserName PlantName,c.UserName CompanyName ,ISNULL(a.Address1,'')+','+ ISNULL(a.Address2,'') Address1, a.Phone,a.Email
                                  ,cm.Address1 cAddress1 ,cm.Address2 cAddress2
                                  FROM org.Plant p
         LEFT OUTER JOIN org.Company c on c.Id=p.CompanyId
         LEFT OUTER JOIN mst.AddressMaster a on a.Id=p.AddressMasterId
         LEFT OUTER JOIN mst.AddressMaster cm on cm.Id=c.AddressMasterId
         WHERE p.Id='" + sPlantID + "'";
                return _sqlRepository.GetDataTable(strSql);
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
            }
        }//end of function

        public DataTable SelectedCompanyDT(string companyId)
        {
            string strSql = "";
            try
            {
                strSql = @"SELECT c.UserName CompanyName ,ISNULL(cm.Address1,'')+','+ ISNULL(cm.Address2,'') Address1
                               
                                FROM org.Company c
							
							
							LEFT OUTER JOIN mst.AddressMaster cm on cm.Id=c.AddressMasterId
							WHERE c.Id='" + companyId + "'";
                return _sqlRepository.GetDataTable(strSql);
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
            }
        }//end of function
        public void GetShortLeave(ParaMontlyAttendance objm, Dictionary<string, string> empParameters, out DataSet dsRef)
        {
            string strSQL;

            ConnectionManager.DAL.ConManager objCon;
            try
            {
                strSQL = @"SELECT	 A.SystemId EmployeeSystemId
                                ,A.EmployeeCode
                            	,A.EmployeeName	
                            	,REPLACE(CONVERT(VARCHAR(11), A.PDate, 113), ' ', '-') PDate
                            	,A.DayStatus
                                ,A.ShortLeave
                            FROM(
                                SELECT E.SystemId
                                    ,E.EmployeeCode
                                    , E.EmployeeName
                                    , AR.WorkDate PDate
                                    , AR.DayStatus
                                    , AR.CountedShortLeave ShortLeave

                                FROM dbo.EmployeeInformation E
                                INNER JOIN dbo.AttdnProcessData AR ON E.SystemID = AR.EmpSystemID
                                left join EmpDateWiseShiftAssign es on es.EmpSystemID = E.SystemId
                                AND AR.WorkDate = ES.WorkDate

                                WHERE 
                                     AR.WorkDate BETWEEN '" + objm.FDate + @"'
                                        AND '" + objm.TDate + @"' AND (EmployeeStatus = 'Active' OR Convert(date,DOS) >= Convert(Date,'" + objm.FDate + @"')) and AR.CountedShortLeave >= 1
                                ";
                try
                {
                    if (empParameters.Count > 0)
                    {
                        if (empParameters.Keys.ElementAt(0) != "")
                        {
                            strSQL += @" AND E.SystemId IN(" + empParameters["EmpSystemId"] + ")";
                        }
                    }
                }
                catch (Exception)
                {
                }
                strSQL = strSQL + @") A
                            GROUP BY A.SystemId 
                                ,A.EmployeeCode
                            	,A.EmployeeName                       	
                            	,PDate
                            	,A.DayStatus 
                                ,a.ShortLeave
                            ORDER BY A.EmployeeCode
                            	,A.PDate";

                objCon = new ConnectionManager.DAL.ConManager("1");
                objCon.OpenDataSetThroughAdapter(strSQL, out dsRef, false, "1");
            }
            catch (Exception ex)
            {
                throw (ex);
            }
            finally
            {
                objCon = null;
            }
        }//end function
