        public string GetSortingParameters(string companyGroupId, string companyId, string plantId, string groupBy)
        {
            List<SalaryRegisterSorting> listdsSlrREGSorting = new List<SalaryRegisterSorting>();//SalarySheetReport

            listdsSlrREGSorting = GetPlantWiseSalaryRegisterSortingParameters(companyGroupId, companyId, plantId);
            string stringSalaryRegSorting = "ORDER BY ";
            string strSequence = "Sequence,";
            string defaultSort = " ISNULL(EmpBasic.EmployeeCodePreFix,'') ASC, ISNULL(EmpBasic.EmployeeCodeNumeric,0) ASC,EmpBasic.EmployeeName ";
            if (!string.IsNullOrEmpty(groupBy))
            {
                stringSalaryRegSorting += groupBy + strSequence;
            }
            if (listdsSlrREGSorting.Count() > 0)
            {
                for (int i = 0; i < listdsSlrREGSorting.Count(); i++)
                {
                    if (listdsSlrREGSorting[i].Parameter == groupBy)
                    {
                        continue;
                    }
                    if (listdsSlrREGSorting[i].Parameter.Contains("EmployeeCode"))
                    {
                        stringSalaryRegSorting += "ISNULL(EmpBasic.EmployeeCodePreFix,'') ASC, ISNULL(EmpBasic.EmployeeCodeNumeric,0) ASC,";
                        defaultSort = "";
                    }
                    else if (listdsSlrREGSorting[i].Parameter.Contains("EmployeeName"))
                    {
                        stringSalaryRegSorting += "EmpBasic.EmployeeName,";
                        defaultSort = "";
                    }
                    else
                    {
                        stringSalaryRegSorting += listdsSlrREGSorting[i].Parameter + strSequence;

                    }
                }
                stringSalaryRegSorting += defaultSort;
            }
            else
            {
                stringSalaryRegSorting += " ISNULL(EmpBasic.EmployeeCodePreFix,'') ASC, ISNULL(EmpBasic.EmployeeCodeNumeric,0) ASC,EmpBasic.EmployeeName,";
            }
            return stringSalaryRegSorting.Remove(stringSalaryRegSorting.Length - 1, 1);
        }

